INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000001', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-001', 'conjugation', 'Be Verb: Identitas, Sifat & Lokasi (am / is / are)', '[Subject] + am / is / are + [Noun / Adjective / Place]', 'Menghubungkan subjek dengan profesi, sifat, atau lokasi saat tidak ada kata kerja aksi.', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"I''m a software engineer based in Seattle.","reading":"/aɪm ə ˈsɔːftwɛr ˌɛndʒɪˈnɪr beɪst ɪn siˈætəl/","id":"Saya seorang insinyur perangkat lunak yang berbasis di Seattle."},{"jp":"The meeting room is on the third floor.","reading":"/ðə ˈmiːtɪŋ ruːm ɪz ɑːn ðə θɜːrd flɔːr/","id":"Ruang rapatnya ada di lantai tiga."}]'::jsonb, 'I am (/aɪm/) • He/She/It is (/ɪz/) • You/We/They are (/ɑːr/)', '{"analogy":"Dalam Bahasa Indonesia kita bisa langsung bilang ''Saya lapar'' atau ''Rina di kantor'' tanpa kata penghubung. Dalam Bahasa Inggris, kalimat wajib punya ''mesin'' kata kerja. Kalau tidak ada aksi fisik, ''am / is / are'' bertugas menjadi jembatan wajib antara subjek dan keterangannya.","when_to_use":["Memperkenalkan nama, profesi, kewarganegaraan, atau peran di kampus/kantor","Mendeskripsikan kondisi, sifat, atau perasaan saat ini (misal: ''busy'', ''ready'', ''excited'')","Menunjukkan posisi atau lokasi seseorang/benda (misal: ''at the airport'', ''in Boston'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku / Topik"},{"role":"verb","text":"am / is / are","label":"Be Verb (Jembatan)"},{"role":"predicate","text":"Noun / Adj / Place","label":"Identitas / Sifat / Lokasi"}],"steps":["Tentukan subjek kalimat: gunakan ''am'' khusus untuk ''I'', ''is'' untuk tunggal (''he/she/it''), dan ''are'' untuk ''you/we/they''.","Dalam percakapan Amerika sehari-hari, singkat menjadi kontraksi alami: I''m, she''s, you''re, we''re, they''re.","Untuk kalimat tanya, tukar posisi Be Verb ke depan subjek (''Are you ready?''), dan untuk negatif tambahkan ''not'' (''isn''t / aren''t'')."],"breakdowns":[{"tokens":[{"jp":"She","reading":"/ʃiː/","meaning":"dia (perempuan)","role":"subject"},{"jp":"is","reading":"/ɪz/","meaning":"adalah (be tunggal)","role":"verb"},{"jp":"our product manager","reading":"/ˈaʊər ˈprɑːdʌkt ˈmænɪdʒər/","meaning":"manajer produk kami","role":"noun"}],"translation":"Dia adalah manajer produk kami."},{"tokens":[{"jp":"Are","reading":"/ɑːr/","meaning":"apakah (be tanya)","role":"verb"},{"jp":"you","reading":"/juː/","meaning":"kamu / Anda","role":"subject"},{"jp":"free","reading":"/friː/","meaning":"luang","role":"adjective"},{"jp":"this afternoon?","reading":"/ðɪs ˌæftərˈnuːn/","meaning":"siang ini?","role":"time"}],"translation":"Apakah Anda luang siang ini?"}],"forms":[{"label":"Positif (Kontraksi US)","jp":"They''re ready for the pitch.","reading":"/ðɛr ˈrɛdi fɔːr ðə pɪtʃ/","id":"Mereka siap untuk presentasi bisnis."},{"label":"Negatif","jp":"He isn''t in the office today.","reading":"/hiː ˈɪzənt ɪn ði ˈɔːfɪs təˈdeɪ/","id":"Dia sedang tidak di kantor hari ini."},{"label":"Tanya (Yes/No)","jp":"Is the Wi-Fi connection stable?","reading":"/ɪz ðə ˈwaɪfaɪ kəˈnɛkʃən ˈsteɪbəl/","id":"Apakah koneksi Wi-Fi-nya stabil?"}],"mistakes":[{"wrong":"I very busy today.","right":"I''m very busy today.","why":"Kata sifat ''busy'' bukan kata kerja; Bahasa Inggris wajib menyertakan ''am'' setelah ''I''."},{"wrong":"She is work at a bank.","right":"She works at a bank. / She is a banker.","why":"Jangan menggabungkan ''am/is/are'' langsung dengan kata kerja dasar (''work''); pilih kata kerja murni atau kata benda profesi."}],"quiz":[{"question":"Lengkapi perkenalan profesional berikut: ''Hi, I ___ Dimas, and these ___ my colleagues from Jakarta.''","options":["am / is","am / are","is / are","are / am"],"answer":1,"why":"''I'' berpasangan dengan ''am'', sedangkan ''these (my colleagues)'' bersifat jamak sehingga memakai ''are''."},{"question":"Manakah kalimat tanya yang benar secara tata bahasa?","options":["Do you are hungry?","You are from Indonesia?","Are you ready for the interview?","Is they in the lobby?"],"answer":2,"why":"Kalimat dengan kata sifat ''ready'' menggunakan inversi Be Verb ''Are you...'', bukan ''Do you are''."},{"question":"Pilih bentuk negatif alami dalam Bahasa Inggris Amerika untuk subjek tunggal ''The café'':","options":["The café not open yet.","The café aren''t open yet.","The café doesn''t open yet.","The café isn''t open yet."],"answer":3,"why":"''Open'' di sini berfungsi sebagai kata sifat kondisi (''buka''), sehingga subjek tunggal memakai ''isn''t''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000002', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-002', 'tense', 'Present Simple: Fakta & Rutinitas (I work / She works)', '[Subject] + V1 (+ -s/-es untuk He/She/It) + [Object]', 'Menyatakan kebiasaan rutin, jadwal tetap, dan fakta umum yang selalu benar.', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"Our team reviews code every morning at nine.","reading":"/ˈaʊər tiːm rɪˈvjuːz koʊd ˈɛvri ˈmɔːrnɪŋ æt naɪn/","id":"Tim kami meninjau kode setiap pagi pukul sembilan."},{"jp":"She doesn''t drink coffee after 3 p.m.","reading":"/ʃiː ˈdʌzənt drɪŋk ˈkɔːfi ˈæftər θriː ˌpiːˈɛm/","id":"Dia tidak minum kopi setelah jam 3 sore."}]'::jsonb, 'I/You/We/They work (/wɜːrk/) • He/She/It works (/wɜːrks/) • don''t / doesn''t + V1', '{"analogy":"Bayangkan Present Simple seperti ''setelan pabrik'' atau jadwal otomatis di kalender HP-mu: bukan cuma soal detik ini, melainkan hal yang berulang terus atau fakta permanen. Khusus subjek tunggal orang ketiga (he/she/it), kata kerjanya memakai ''sabuk pengaman -s'' di kalimat positif.","when_to_use":["Menceritakan rutinitas harian, kebiasaan kerja, atau alur operasional kantor","Menyatakan fakta ilmiah, kebenaran umum, atau profil perusahaan","Menyebutkan jadwal transportasi, kelas kampus, atau agenda resmi yang sudah terjadwal"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"V1 / V1+s","label":"Aksi Rutin"},{"role":"object","text":"Object","label":"Sasaran"},{"role":"time","text":"every day / usually","label":"Penanda Frekuensi"}],"steps":["Gunakan kata kerja dasar (V1) untuk I, you, we, they; tambahkan -s/-es/-ies jika subjeknya tunggal (he, she, it, my boss, the system).","Untuk kalimat negatif, panggil kata bantu ''don''t'' atau ''doesn''t'' lalu kembalikan kata kerja ke bentuk dasar murni tanpa -s!","Untuk kalimat tanya, letakkan ''Do'' atau ''Does'' di depan subjek diikuti V1 murni."],"breakdowns":[{"tokens":[{"jp":"Nadia","reading":"/ˈnɑːdiə/","meaning":"Nadia (subjek tunggal)","role":"subject"},{"jp":"teaches","reading":"/ˈtiːtʃɪz/","meaning":"mengajar (teach + es)","role":"verb"},{"jp":"data analytics","reading":"/ˈdeɪtə ˌænəˈlɪtɪks/","meaning":"analitik data","role":"object"},{"jp":"on Fridays.","reading":"/ɑːn ˈfraɪdeɪz/","meaning":"setiap hari Jumat.","role":"time"}],"translation":"Nadia mengajar analitik data setiap hari Jumat."},{"tokens":[{"jp":"Does","reading":"/dʌz/","meaning":"apakah (tunggal)","role":"particle"},{"jp":"this shuttle","reading":"/ðɪs ˈʃʌtəl/","meaning":"bus antar-jemput ini","role":"subject"},{"jp":"stop","reading":"/stɑːp/","meaning":"berhenti (V1 murni)","role":"verb"},{"jp":"near downtown?","reading":"/nɪr ˈdaʊntaʊn/","meaning":"di dekat pusat kota?","role":"place"}],"translation":"Apakah bus antar-jemput ini berhenti di dekat pusat kota?"}],"forms":[{"label":"Positif (Orang ke-3)","jp":"He manages three client accounts.","reading":"/hiː ˈmænɪdʒɪz θriː ˈklaɪənt əˈkaʊnts/","id":"Dia mengelola tiga akun klien."},{"label":"Negatif","jp":"He doesn''t work on weekends.","reading":"/hiː ˈdʌzənt wɜːrk ɑːn ˈwiːkɛndz/","id":"Dia tidak bekerja di akhir pekan."},{"label":"Tanya","jp":"Does he commute by subway?","reading":"/dʌz hiː kəˈmjuːt baɪ ˈsʌbweɪ/","id":"Apakah dia pulang-pergi naik kereta bawah tanah?"}],"mistakes":[{"wrong":"She doesn''t likes spicy food.","right":"She doesn''t like spicy food.","why":"Akhiran ''-s'' sudah diambil alih oleh ''doesn''t'', jadi kata kerja utamanya wajib kembali ke V1 (''like'')."},{"wrong":"Our company have 200 employees.","right":"Our company has 200 employees.","why":"''Our company'' adalah satu entitas tunggal (''it''), sehingga bentuk orang ketiga dari ''have'' adalah ''has''."}],"quiz":[{"question":"Pilih bentuk yang tepat: ''The campus library ___ at 8 a.m. every weekday.''","options":["open","opens","is openning","opening"],"answer":1,"why":"Jadwal rutin dengan subjek tunggal (''The campus library'' = it) memakai Present Simple berakhiran ''-s'' (''opens'')."},{"question":"Manakah kalimat negatif yang bebas dari kesalahan grammar?","options":["My laptop don''t charge properly.","My laptop not charges properly.","My laptop doesn''t charge properly.","My laptop doesn''t charges properly."],"answer":2,"why":"Subjek tunggal ''My laptop'' memakai ''doesn''t'' + kata kerja dasar ''charge'' tanpa ''-s''."},{"question":"Lengkapi pertanyaan wawancara berikut: ''How often ___ your team deploy updates?''","options":["do","does","is","are"],"answer":1,"why":"Dalam American English standar, kata benda kolektif tunggal ''your team'' dianggap ''it'' sehingga memakai ''does''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000003', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-003', 'particle', 'Pronouns & Possessives: Kata Ganti & Milik (I / me / my / mine)', '[Subject Pronoun] + Verb + [Object Pronoun] | [Possessive Adj + Noun] vs [Possessive Pronoun]', 'Membedakan bentuk kata ganti berdasarkan posisinya sebagai pelaku, sasaran, atau pemilik benda.', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"Could you send me your updated resume?","reading":"/kʊd juː sɛnd miː jʊr ʌpˈdeɪtɪd ˈrɛzəmeɪ/","id":"Bisakah Anda mengirimkan CV terbaru Anda kepada saya?"},{"jp":"This charger is mine, and the white one is hers.","reading":"/ðɪs ˈtʃɑːrdʒər ɪz maɪn ænd ðə waɪt wʌn ɪz hɜːrz/","id":"Pengisi daya ini milik saya, dan yang putih itu milik dia."}]'::jsonb, 'I → me → my (+N) → mine • they → them → their (+N) → theirs', '{"analogy":"Dalam Bahasa Indonesia, kata ''saya'' tidak pernah ganti baju: ''Saya melihat dia'', ''Dia melihat saya'', ''Buku saya''. Dalam Bahasa Inggris, kata ganti wajib ganti seragam sesuai posisinya di lapangan: kapten di depan (''I''), penerima bola di belakang (''me''), label nama di depan benda (''my book''), atau berdiri mandiri (''mine'').","when_to_use":["Menggantikan nama orang/benda agar kalimat tidak mengulang kata yang sama terus-menerus","Menunjukkan kepemilikan dokumen, perangkat kerja, atau ide dalam percakapan profesional","Membedakan pelaku tindakan vs penerima tindakan setelah kata kerja atau preposisi (''for me'', ''with them'')"],"formula_parts":[{"role":"subject","text":"I / she / they","label":"Sebelum Kata Kerja"},{"role":"verb","text":"Verb / Prep","label":"Aksi / Preposisi"},{"role":"object","text":"me / her / them","label":"Sasaran Objek"},{"role":"noun","text":"my badge / mine","label":"Kepemilikan"}],"steps":["Sebelum kata kerja utama, selalu gunakan Subject Pronoun: I, you, he, she, it, we, they.","Setelah kata kerja atau preposisi (to, for, with, between), wajib ubah ke Object Pronoun: me, you, him, her, it, us, them.","Gunakan my/your/his/her/its/our/their tepat DI DEPAN kata benda, atau mine/yours/his/hers/ours/theirs TANPA kata benda sesudahnya."],"breakdowns":[{"tokens":[{"jp":"She","reading":"/ʃiː/","meaning":"dia (subjek)","role":"subject"},{"jp":"shared","reading":"/ʃɛrd/","meaning":"membagikan","role":"verb"},{"jp":"her notes","reading":"/hɜːr noʊts/","meaning":"catatannya (poss. adj + benda)","role":"object"},{"jp":"with us.","reading":"/wɪð ʌs/","meaning":"dengan kami (objek preposisi).","role":"particle"}],"translation":"Dia membagikan catatannya kepada kami."},{"tokens":[{"jp":"Our seats","reading":"/ˈaʊər siːts/","meaning":"kursi kami","role":"subject"},{"jp":"are","reading":"/ɑːr/","meaning":"berada","role":"verb"},{"jp":"here,","reading":"/hɪr/","meaning":"di sini,","role":"place"},{"jp":"and","reading":"/ænd/","meaning":"dan","role":"connector"},{"jp":"theirs","reading":"/ðɛrz/","meaning":"milik mereka (tanpa benda)","role":"noun"},{"jp":"are upfront.","reading":"/ɑːr ˌʌpˈfrʌnt/","meaning":"ada di bagian depan.","role":"place"}],"translation":"Kursi kami di sini, dan milik mereka ada di bagian depan."}],"forms":[{"label":"Subjek + Objek","jp":"They invited us to the workshop.","reading":"/ðeɪ ɪnˈvaɪtɪd ʌs tə ðə ˈwɜːrkʃɑːp/","id":"Mereka mengundang kami ke lokakarya."},{"label":"Possessive Adjective","jp":"Please check their portfolio.","reading":"/pliːz tʃɛk ðɛr pɔːrtˈfoʊlioʊ/","id":"Silakan periksa portofolio mereka."},{"label":"Possessive Pronoun","jp":"The final decision is yours.","reading":"/ðə ˈfaɪnəl dɪˈsɪʒən ɪz jʊrz/","id":"Keputusan akhir ada di tangan Anda (milik Anda)."}],"mistakes":[{"wrong":"Between you and I, this project is tough.","right":"Between you and me, this project is tough.","why":"Setelah preposisi ''between'', semua kata ganti wajib berbentuk objek (''you and me''), bukan subjek ''I''."},{"wrong":"The startup updated it''s website.","right":"The startup updated its website.","why":"''It''s'' dengan apostrof selalu berarti ''it is'' atau ''it has''; bentuk kepemilikan dari ''it'' adalah ''its'' tanpa apostrof!"}],"quiz":[{"question":"Pilih kata ganti yang tepat: ''Mr. Carter asked Raka and ___ to present the quarterly report.''","options":["I","me","my","mine"],"answer":1,"why":"Posisi setelah kata kerja ''asked'' adalah objek langsung, sehingga wajib memakai ''me''."},{"question":"Lengkapi kalimat berikut: ''I forgot my umbrella, so Maya lent me ___.''","options":["her","she","hers","herself"],"answer":2,"why":"Karena kata benda ''umbrella'' tidak diulang lagi di akhir kalimat, gunakan Possessive Pronoun mandiri ''hers'' (= her umbrella)."},{"question":"Manakah penulisan yang benar untuk kalimat akademik/TOEFL?","options":["Each university has it''s own admission criteria.","Each university has its own admission criteria.","Each university has their''s admission criteria.","Each university has it own admission criteria."],"answer":1,"why":"''Its'' (tanpa apostrof) adalah kata sifat kepemilikan tunggal yang tepat untuk ''each university''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000004', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-004', 'particle', 'Articles: Kata Sandang Umum vs Spesifik (a / an / the)', 'a (+ bunyi konsonan) / an (+ bunyi vokal) / the (+ benda spesifik) / Ø (+ jamak/abstrak umum)', 'Menandai apakah suatu kata benda baru disebut pertama kali secara umum atau sudah spesifik diketahui bersama.', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"We waited for an hour to meet the dean.","reading":"/wiː ˈweɪtɪd fɔːr ən ˈaʊər tə miːt ðə diːn/","id":"Kami menunggu selama satu jam untuk menemui dekan tersebut."},{"jp":"She bought a laptop, and the laptop runs smoothly.","reading":"/ʃiː bɔːt ə ˈlæptɑːp ænd ðə ˈlæptɑːp rʌnz ˈsmuːðli/","id":"Dia membeli sebuah laptop, dan laptop tersebut berjalan lancar."}]'::jsonb, 'a user (/ə ˈjuːzər/) • an hour (/ən ˈaʊər/) • the report (/ðə rɪˈpɔːrt/)', '{"analogy":"Anggap ''a/an'' seperti mengambil satu apel acak dari keranjang (''sebuah apel mana saja''), sedangkan ''the'' seperti menunjuk langsung pakai jari (''apel yang ITU lho, yang kita maksud bareng!''). Penentuan ''a'' vs ''an'' murni mengikuti BUNYI ucapan awal, bukan huruf tulisannya.","when_to_use":["Pakai ''a/an'' untuk benda tunggal dapat dihitung saat pertama kali disebut atau menyebut profesi (''an architect'', ''a university'')","Pakai ''the'' saat pendengar sudah tahu persis benda mana yang dimaksud, benda unik (''the internet'', ''the sun''), atau superlatif","Tanpa artikel (zero article) saat membahas konsep umum dalam bentuk jamak atau tak terhitung (''Technology changes lives'')"],"formula_parts":[{"role":"particle","text":"a / an","label":"1 Benda Umum (Bunyi)"},{"role":"particle","text":"the","label":"Benda Spesifik / Unik"},{"role":"noun","text":"Noun","label":"Kata Benda"}],"steps":["Cek apakah bendanya tunggal dan dapat dihitung: dalam Bahasa Inggris, kata benda tunggal terhitung hampir tidak pernah berdiri telanjang tanpa penentu!","Dengarkan bunyi awalnya: bunyi konsonan memakai ''a'' (''a university'' /juː/), bunyi vokal memakai ''an'' (''an MBA'' /ɛm/, ''an honest answer'' /ɑː/).","Ubah menjadi ''the'' ketika benda itu disebut untuk kedua kalinya atau hanya ada satu di konteks percakapan (''Can you close the door?'')."],"breakdowns":[{"tokens":[{"jp":"He","reading":"/hiː/","meaning":"dia","role":"subject"},{"jp":"graduated from","reading":"/ˈɡrædʒueɪtɪd frʌm/","meaning":"lulus dari","role":"verb"},{"jp":"a","reading":"/ə/","meaning":"sebuah (bunyi /j/ konsonan)","role":"particle"},{"jp":"university","reading":"/ˌjuːnɪˈvɜːrsəti/","meaning":"universitas","role":"noun"},{"jp":"in","reading":"/ɪn/","meaning":"di","role":"particle"},{"jp":"the United States.","reading":"/ðə juˈnaɪtɪd steɪts/","meaning":"Amerika Serikat (negara serikat pakai ''the'').","role":"place"}],"translation":"Dia lulus dari sebuah universitas di Amerika Serikat."},{"tokens":[{"jp":"Could you","reading":"/kʊd juː/","meaning":"bisakah Anda","role":"verb"},{"jp":"share","reading":"/ʃɛr/","meaning":"membagikan","role":"verb"},{"jp":"the link","reading":"/ðə lɪŋk/","meaning":"tautan itu (spesifik rapat ini)","role":"object"},{"jp":"in the chat?","reading":"/ɪn ðə tʃæt/","meaning":"di kolom obrolan?","role":"place"}],"translation":"Bisakah Anda membagikan tautannya di kolom obrolan?"}],"forms":[{"label":"Bunyi Vokal (an)","jp":"She earned an MBA scholarship.","reading":"/ʃiː ɜːrnd ən ˌɛmbiːˈeɪ ˈskɑːlərʃɪp/","id":"Dia meraih beasiswa MBA (huruf M berbunyi /ɛm/)."},{"label":"Bunyi Konsonan (a)","jp":"It is a European startup.","reading":"/ɪt ɪz ə ˌjʊrəˈpiːən ˈstɑːrtʌp/","id":"Itu adalah perusahaan rintisan Eropa (berbunyi /jʊr/)."},{"label":"Umum Tanpa Artikel","jp":"Clean water is essential for health.","reading":"/kliːn ˈwɔːtər ɪz ɪˈsɛnʃəl fɔːr hɛlθ/","id":"Air bersih sangat penting bagi kesehatan."}],"mistakes":[{"wrong":"I need an university recommendation letter.","right":"I need a university recommendation letter.","why":"Meski diawali huruf vokal ''u'', kata ''university'' diucapkan dengan bunyi konsonan /juː/, sehingga wajib memakai ''a''."},{"wrong":"The life in Jakarta is very fast-paced.","right":"Life in Jakarta is very fast-paced.","why":"Kata benda abstrak umum seperti ''life'', ''education'', atau ''music'' tidak memakai ''the'' kecuali dibatasi secara spesifik (''the life of Einstein'')."}],"quiz":[{"question":"Pilih artikel yang tepat: ''It is ___ honor to speak at ___ annual conference today.''","options":["a / a","an / the","a / the","an / a"],"answer":1,"why":"''Honor'' memiliki huruf ''h'' bisu (/ˈɑːnər/) sehingga memakai ''an'', dan konferensi spesifik hari ini memakai ''the''."},{"question":"Manakah kalimat yang benar saat menyebutkan pekerjaan seseorang?","options":["My sister is data scientist.","My sister is the data scientist.","My sister is a data scientist.","My sister is an data scientist."],"answer":2,"why":"Menyebutkan profesi tunggal dalam Bahasa Inggris wajib memakai ''a/an'' (''a data scientist'')."},{"question":"Mengapa frasa ''an NDA (Non-Disclosure Agreement)'' memakai ''an''?","options":["Karena NDA kata benda jamak","Karena huruf ''N'' saat dieja diawali bunyi vokal /ɛn/","Karena singkatan selalu memakai ''an''","Karena NDA tidak bisa dihitung"],"answer":1,"why":"Huruf ''N'' dibaca /ɛn/ (bunyi vokal di awal), sehingga memakai ''an NDA''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000005', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-005', 'sentence_pattern', 'Existential Clauses: Menyatakan Keberadaan (There is / There are)', 'There + is (+ Singular / Uncountable Noun) | There + are (+ Plural Noun) + [Place/Time]', 'Memperkenalkan keberadaan sesuatu atau seseorang di suatu tempat atau situasi (setara kata ''Ada'' di awal kalimat).', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"There is a coffee shop right across the street.","reading":"/ðɛr ɪz ə ˈkɔːfi ʃɑːp raɪt əˈkrɔːs ðə striːt/","id":"Ada kedai kopi tepat di seberang jalan."},{"jp":"There are three open positions in our engineering team.","reading":"/ðɛr ɑːr θriː ˈoʊpən pəˈzɪʃənz ɪn ˈaʊər ˌɛndʒɪˈnɪrɪŋ tiːm/","id":"Ada tiga posisi lowongan di tim teknik kami."}]'::jsonb, 'There''s (/ðɛrz/) a bug • There are (/ðɛr ɑːr/) two options', '{"analogy":"Orang Indonesia sering menerjemahkan ''Ada masalah'' menjadi ''Have a problem'' tanpa subjek. Padahal ''have'' artinya ''memiliki'' dan butuh pemilik! Untuk bilang ''Ada...'' di awal kalimat, Bahasa Inggris memakai panggung pembuka ''There is / There are''—di mana ''there'' bukan berarti ''di sana'', melainkan penanda keberadaan.","when_to_use":["Memberi tahu adanya fasilitas, toko, atau ruangan di suatu area","Melaporkan adanya masalah, peluang, pertanyaan, atau pembaruan dalam rapat","Menyebutkan jumlah peserta, item, atau agenda yang tersedia"],"formula_parts":[{"role":"particle","text":"There","label":"Pembuka ''Ada''"},{"role":"verb","text":"is / are","label":"Ikuti Jumlah Benda"},{"role":"subject","text":"Noun Phrase","label":"Benda yang Ada"},{"role":"place","text":"Place / Time","label":"Lokasi / Waktu"}],"steps":["Lihat kata benda yang muncul SETELAH ''be'': jika tunggal atau tak terhitung (''milk'', ''traffic''), gunakan ''There is'' (''There''s'').","Jika kata bendanya jamak (''two emails'', ''many students''), gunakan ''There are''.","Untuk kalimat tanya, balik menjadi ''Is there...?'' atau ''Are there...?'', dan untuk negatif gunakan ''There isn''t any...'' / ''There aren''t any...''."],"breakdowns":[{"tokens":[{"jp":"There''s","reading":"/ðɛrz/","meaning":"ada (tunggal/uncountable)","role":"verb"},{"jp":"heavy traffic","reading":"/ˈhɛvi ˈtræfɪk/","meaning":"kemacetan padat","role":"subject"},{"jp":"on the highway","reading":"/ɑːn ðə ˈhaɪweɪ/","meaning":"di jalan raya","role":"place"},{"jp":"this morning.","reading":"/ðɪs ˈmɔːrnɪŋ/","meaning":"pagi ini.","role":"time"}],"translation":"Ada kemacetan padat di jalan raya pagi ini."},{"tokens":[{"jp":"Are there","reading":"/ɑːr ðɛr/","meaning":"apakah ada (jamak)","role":"verb"},{"jp":"any questions","reading":"/ˈɛni ˈkwɛstʃənz/","meaning":"pertanyaan apa pun","role":"subject"},{"jp":"about the budget?","reading":"/əˈbaʊt ðə ˈbʌdʒɪt/","meaning":"tentang anggarannya?","role":"object"}],"translation":"Apakah ada pertanyaan tentang anggarannya?"}],"forms":[{"label":"Tunggal / Tak Terhitung","jp":"There is enough time to rehearse.","reading":"/ðɛr ɪz ɪˈnʌf taɪm tə rɪˈhɜːrs/","id":"Ada cukup waktu untuk berlatih."},{"label":"Jamak","jp":"There aren''t any seats left.","reading":"/ðɛr ˈɑːrənt ˈɛni siːts lɛft/","id":"Tidak ada kursi yang tersisa."},{"label":"Pertanyaan","jp":"Is there an ATM nearby?","reading":"/ɪz ðɛr ən ˌeɪtiːˈɛm ˈnɪrbaɪ/","id":"Apakah ada ATM di sekitar sini?"}],"mistakes":[{"wrong":"Have many startups in Austin.","right":"There are many startups in Austin.","why":"Jangan gunakan ''Have'' tanpa subjek untuk menerjemahkan ''Ada''; gunakan ''There are'' untuk kata benda jamak."},{"wrong":"There are a lot of information on this page.","right":"There is a lot of information on this page.","why":"''Information'' adalah kata benda tak terhitung (uncountable) sehingga selalu dianggap tunggal (''There is'')."}],"quiz":[{"question":"Pilih bentuk yang tepat: ''___ several errors in the final spreadsheet.''","options":["There is","There are","It has","Have"],"answer":1,"why":"''Several errors'' berbentuk jamak, sehingga wajib didahului ''There are''."},{"question":"Lengkapi pertanyaan sopan di hotel: ''Excuse me, ___ free shuttle service to the airport?''","options":["are there a","is there a","does there have","has there"],"answer":1,"why":"''A free shuttle service'' adalah benda tunggal, sehingga bentuk tanyanya ''is there a...''."},{"question":"Dalam daftar benda gabungan ''___ a projector and two whiteboards in Room B'', bentuk formal standar yang paling tepat adalah:","options":["There is","There are","They are","It is"],"answer":0,"why":"Ketika menyebutkan deretan benda dengan ''There be'', kata kerja menyesuaikan dengan kata benda pertama yang paling dekat (''a projector'' = tunggal → ''There is'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000006', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-006', 'particle', 'Prepositions of Time & Place: Waktu & Lokasi (in / on / at)', 'IN (Area luas / Bulan-Tahun) • ON (Permukaan / Hari-Tanggal) • AT (Titik spesifik / Jam)', 'Menentukan tingkat presisi waktu dan lokasi menggunakan piramida besar-ke-kecil: in, on, dan at.', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"Our flight leaves at 6:30 a.m. on Tuesday.","reading":"/ˈaʊər flaɪt liːvz æt sɪks ˈθɜːrti ˌeɪˈɛm ɑːn ˈtuːzdeɪ/","id":"Penerbangan kita berangkat pukul 06.30 pagi pada hari Selasa."},{"jp":"He lives in Chicago, and his office is on Michigan Avenue.","reading":"/hiː lɪvz ɪn ʃɪˈkɑːɡoʊ ænd hɪz ˈɔːfɪs ɪz ɑːn ˈmɪʃɪɡən ˈævənuː/","id":"Dia tinggal di Chicago, dan kantornya berada di Michigan Avenue."}]'::jsonb, 'in July / in Manhattan • on Monday / on 5th Ave • at 9 a.m. / at the desk', '{"analogy":"Bayangkan segitiga terbalik dari luas ke tajam seperti fitur Zoom di Google Maps: ''IN'' itu zoom jauh melihat kota/negara atau rentang bulan/tahun; ''ON'' itu zoom menengah menyentuh permukaan jalan/lantai atau satu kotak hari/tanggal di kalender; ''AT'' itu pin merah tajam di satu titik alamat/lokasi atau jarum jam spesifik!","when_to_use":["IN: abad, tahun, bulan, musim, bagian hari (''in the morning''), kota, negara, ruangan tertutup","ON: hari (''on Friday''), tanggal lengkap (''on May 12th''), nama jalan tanpa nomor, lantai gedung (''on the 2nd floor''), layar/platform digital (''on Zoom'')","AT: jam tepat (''at noon'', ''at 4 p.m.''), titik pertemuan spesifik (''at the entrance'', ''at the airport''), alamat bernomor lengkap"],"formula_parts":[{"role":"particle","text":"in","label":"Bulan/Tahun & Kota/Ruang"},{"role":"particle","text":"on","label":"Hari/Tanggal & Jalan/Layar"},{"role":"particle","text":"at","label":"Jam Tepat & Titik Lokasi"}],"steps":["Cek skala waktunya: jam → ''at'', hari atau tanggal (meski ada nama bulannya, misal ''on July 4th'') → ''on'', bulan/musim/tahun saja → ''in''.","Cek skala tempatnya: negara/kota/ruang → ''in'', nama jalan/lantai/kendaraan besar/layar digital → ''on'', titik kumpul/alamat nomor → ''at''.","Hati-hati pengecualian wajib: jangan pakai preposisi in/on/at di depan ''today'', ''tomorrow'', ''yesterday'', ''this/next/last/every''!"],"breakdowns":[{"tokens":[{"jp":"Let''s meet","reading":"/lɛts miːt/","meaning":"mari bertemu","role":"verb"},{"jp":"at the lobby","reading":"/æt ðə ˈlɑːbi/","meaning":"di titik lobi","role":"place"},{"jp":"at 2 p.m.","reading":"/æt tuː ˌpiːˈɛm/","meaning":"pukul 2 siang","role":"time"},{"jp":"on Monday.","reading":"/ɑːn ˈmʌndeɪ/","meaning":"pada hari Senin.","role":"time"}],"translation":"Mari bertemu di lobi pukul 2 siang pada hari Senin."},{"tokens":[{"jp":"The summit","reading":"/ðə ˈsʌmɪt/","meaning":"konferensi tingkat tinggi itu","role":"subject"},{"jp":"takes place","reading":"/teɪks pleɪs/","meaning":"berlangsung","role":"verb"},{"jp":"in Boston","reading":"/ɪn ˈbɔːstən/","meaning":"di kota Boston","role":"place"},{"jp":"in October.","reading":"/ɪn ɑːkˈtoʊbər/","meaning":"pada bulan Oktober.","role":"time"}],"translation":"Konferensi tersebut berlangsung di Boston pada bulan Oktober."}],"forms":[{"label":"Platform Digital (on)","jp":"I saw your post on LinkedIn.","reading":"/aɪ sɔː jʊr poʊst ɑːn ˈlɪŋktɪn/","id":"Saya melihat unggahan Anda di LinkedIn."},{"label":"Tanggal Spesifik (on)","jp":"Classes start on September 3rd.","reading":"/ˈklæsɪz stɑːrt ɑːn sɛpˈtɛmbər θɜːrd/","id":"Perkuliahan dimulai pada tanggal 3 September."},{"label":"Tanpa Preposisi (next)","jp":"We''ll launch the app next week.","reading":"/wiːl lɔːntʃ ði æp nɛkst wiːk/","id":"Kami akan meluncurkan aplikasinya minggu depan."}],"mistakes":[{"wrong":"The scholarship deadline is in March 15.","right":"The scholarship deadline is on March 15.","why":"Begitu nama bulan diikuti angka tanggal spesifik, skalanya menyempit menjadi satu hari kalender sehingga wajib memakai ''on''."},{"wrong":"See you on next Friday!","right":"See you next Friday!","why":"Kata penunjuk ''next'', ''last'', ''this'', dan ''every'' langsung menempel ke kata waktu tanpa ''on/in/at''."}],"quiz":[{"question":"Lengkapi undangan rapat berikut: ''Can we hop ___ a quick Zoom call ___ 10 a.m.?''","options":["in / on","on / at","at / in","on / in"],"answer":1,"why":"Media komunikasi digital memakai ''on'' (''on a call / on Zoom'') dan jam spesifik memakai ''at'' (''at 10 a.m.'')."},{"question":"Pilih preposisi lokasi yang benar untuk American English: ''Their bookstore is ___ Broadway, right ___ New York City.''","options":["in / at","at / on","on / in","on / at"],"answer":2,"why":"Nama jalan tanpa nomor rumah memakai ''on'' (''on Broadway''), sedangkan kota besar memakai ''in'' (''in New York City'')."},{"question":"Manakah ungkapan waktu malam yang benar?","options":["in the morning, tetapi at night","at the morning, tetapi in night","on the morning, dan on night","in the morning, dan in the night"],"answer":0,"why":"Bagian hari memakai ''in the morning / afternoon / evening'', namun khusus malam secara umum memakai idiomatis ''at night''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000007', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-007', 'conjugation', 'Modal Can: Kemampuan & Permintaan Santai (can / can''t)', '[Subject] + can / can''t + V1 (Base Verb) + [Object]', 'Menyatakan keahlian, kemungkinan, izin, atau permintaan praktis tanpa mengubah bentuk kata kerja.', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"She can speak Indonesian, English, and Japanese.","reading":"/ʃiː kən spiːk ˌɪndəˈniːʒən ˈɪŋɡlɪʃ ænd ˌdʒæpəˈniːz/","id":"Dia bisa berbicara Bahasa Indonesia, Inggris, dan Jepang."},{"jp":"Sorry, I can''t join the call right now.","reading":"/ˈsɑːri aɪ kænt dʒɔɪn ðə kɔːl raɪt naʊ/","id":"Maaf, saya tidak bisa bergabung ke panggilan sekarang."}]'::jsonb, 'can + V1 (/kən/ lemah) vs can''t + V1 (/kænt/ vokal melebar jelas + hentakan t)', '{"analogy":"''Can'' adalah kata bantu paling ramah bagi pemula karena kebal terhadap perubahan subjek: baik ''I'', ''you'', maupun ''she'', bentuknya tetap ''can'' + V1 polos (tanpa ''to'', tanpa ''-s''). Tantangan uniknya di aksen Amerika justru di telinga: ''can'' positif diucapkan cepat lemah (/kən/), sedangkan ''can''t'' negatif ditekan lantang (/kænt/)!","when_to_use":["Menjelaskan kemampuan teknis atau bahasa saat perkenalan kerja","Menyatakan apakah sesuatu memungkinkan secara jadwal atau aturan (''You can park here'')","Meminta bantuan rekan sejawat secara akrab (''Can you send me the file?'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Semua Subjek"},{"role":"verb","text":"can / can''t","label":"Modal Kemampuan"},{"role":"verb","text":"V1 (murni)","label":"Tanpa ''to'' / ''-s''"},{"role":"object","text":"Object","label":"Pelengkap"}],"steps":["Letakkan ''can'' atau ''can''t'' (tulisan formal utuh: ''cannot'' satu kata gandeng!) tepat setelah subjek.","Ikuti langsung dengan kata kerja bentuk dasar V1 tanpa ''to'' dan tanpa ''-s/-ing''.","Untuk bertanya, pindahkan ''Can'' ke awal kalimat: ''Can I...?'' (meminta izin) atau ''Can you...?'' (meminta tolong)."],"breakdowns":[{"tokens":[{"jp":"Can","reading":"/kæn/","meaning":"bisakah","role":"verb"},{"jp":"everyone","reading":"/ˈɛvriwʌn/","meaning":"semua orang","role":"subject"},{"jp":"see","reading":"/siː/","meaning":"melihat (V1 murni)","role":"verb"},{"jp":"my screen?","reading":"/maɪ skriːn/","meaning":"layar saya?","role":"object"}],"translation":"Bisakah semuanya melihat layar saya?"},{"tokens":[{"jp":"Students","reading":"/ˈstuːdənts/","meaning":"mahasiswa","role":"subject"},{"jp":"cannot","reading":"/ˈkænɑːt/","meaning":"tidak boleh / tidak dapat (formal)","role":"verb"},{"jp":"access","reading":"/ˈæksɛs/","meaning":"mengakses","role":"verb"},{"jp":"the lab","reading":"/ðə læb/","meaning":"laboratorium","role":"object"},{"jp":"after midnight.","reading":"/ˈæftər ˈmɪdnaɪt/","meaning":"setelah tengah malam.","role":"time"}],"translation":"Mahasiswa tidak dapat mengakses laboratorium setelah tengah malam."}],"forms":[{"label":"Kemampuan (Positif)","jp":"He can build mobile apps in Flutter.","reading":"/hiː kən bɪld ˈmoʊbəl æps ɪn ˈflʌtər/","id":"Dia bisa membuat aplikasi seluler dengan Flutter."},{"label":"Negatif Formal (1 Kata)","jp":"We cannot approve this expense.","reading":"/wiː ˈkænɑːt əˈpruːv ðɪs ɪkˈspɛns/","id":"Kami tidak dapat menyetujui pengeluaran ini."},{"label":"Permintaan Rekan Kerja","jp":"Can you double-check these numbers?","reading":"/kən juː ˈdʌbəltʃɛk ðiːz ˈnʌmbərz/","id":"Bisa tolong cek ulang angka-angka ini?"}],"mistakes":[{"wrong":"She cans speaks French fluently.","right":"She can speak French fluently.","why":"Modal ''can'' tidak pernah memakai ''-s'', dan kata kerja setelahnya wajib V1 murni (''speak'')."},{"wrong":"I can to help you tomorrow.","right":"I can help you tomorrow.","why":"Setelah modal verb (''can'', ''will'', ''must'', ''should''), dilarang menyisipkan ''to'' sebelum kata kerja."}],"quiz":[{"question":"Pilih kalimat yang benar secara tata bahasa dan ejaan standar:","options":["He can''t to attend the seminar.","He can nots attend the seminar.","He cannot attend the seminar.","He doesn''t can attend the seminar."],"answer":2,"why":"Bentuk negatif formal dari ''can'' ditulis satu kata sambung ''cannot'' diikuti V1 ''attend''."},{"question":"Dalam pelafalan American English di TOEFL Listening, bagaimana cara membedakan ''I can go'' vs ''I can''t go''?","options":["''Can'' diucapkan panjang keras, ''can''t'' diucapkan bisik","''Can'' direduksi pendek (/kən/) sedangkan ''can''t'' mendapat tekanan vokal jelas (/kænt/)","Keduanya diucapkan 100% identik","''Can''t'' selalu diucapkan dua suku kata"],"answer":1,"why":"Penutur Amerika mereduksi ''can'' positif menjadi /kən GO/, sedangkan ''can''t'' diberi penekanan penuh /KÆNT go/."},{"question":"Lengkapi respons rapat daring berikut: ''Sorry, ___ you repeat the last question? Your audio cut out.''","options":["do","are","can","have"],"answer":2,"why":"''Can you repeat...?'' adalah cara alami meminta lawan bicara mengulangi ucapan."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000008', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-008', 'tense', 'Present Continuous: Aksi Sedang Berlangsung (am / is / are + -ing)', '[Subject] + am / is / are + V-ing + [Object]', 'Menggambarkan aktivitas yang sedang terjadi tepat saat berbicara atau proyek sementara minggu/bulan ini.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"I''m waiting for my Uber outside the terminal.","reading":"/aɪm ˈweɪtɪŋ fɔːr maɪ ˈuːbər ˌaʊtˈsaɪd ðə ˈtɜːrmɪnəl/","id":"Saya sedang menunggu Uber saya di luar terminal."},{"jp":"Our company is hiring two cloud engineers this quarter.","reading":"/ˈaʊər ˈkʌmpəni ɪz ˈhaɪrɪŋ tuː klaʊd ˌɛndʒɪˈnɪrz ðɪs ˈkwɔːrtər/","id":"Perusahaan kami sedang merekrut dua insinyur cloud kuartal ini."}]'::jsonb, 'I''m working • She''s presenting • We''re testing (/wɪr ˈtɛstɪŋ/)', '{"analogy":"Kalau Present Simple itu seperti foto profil permanen, Present Continuous adalah ''Live Streaming Instagram'' yang sedang tayang detik ini atau tren sementara periode ini. Rumusnya wajib paket kombo dua bagian: ''Be Verb'' (am/is/are) + akhiran ''-ing''. Hilang salah satu, siaran langsungnya putus!","when_to_use":["Menceritakan aktivitas yang persis sedang berlangsung detik ini (''right now'', ''at the moment'')","Menjelaskan proyek, kursus, atau situasi sementara periode ini meski tidak sedang dilakukan detik ini (''I''m taking a TOEFL prep course this month'')","Menyebutkan agenda dekat yang sudah pasti disepakati bersama (''We''re having lunch with the client tomorrow'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"am / is / are","label":"Be Verb Wajib"},{"role":"verb","text":"Verb + -ing","label":"Aksi Berlangsung"},{"role":"time","text":"right now / this week","label":"Waktu Sementara"}],"steps":["Pasangkan subjek dengan ''am'', ''is'', atau ''are'' terlebih dahulu—jangan pernah langsung menaruh V-ing sendirian setelah subjek!","Tambahkan ''-ing'' pada kata kerja: buang ''-e'' bisu di akhir (''make'' → ''making''), dan gandakan konsonan akhir untuk suku kata pendek KVK (''run'' → ''running'').","Ingat aturan emas TOEFL: kata kerja keadaan/pikiran/kepemilikan (''know'', ''want'', ''need'', ''belong'', ''understand'') TIDAK dipakai dalam bentuk ''-ing''!"],"breakdowns":[{"tokens":[{"jp":"They''re","reading":"/ðɛr/","meaning":"mereka sedang (they + are)","role":"subject"},{"jp":"fixing","reading":"/ˈfɪksɪŋ/","meaning":"memperbaiki","role":"verb"},{"jp":"the payment server","reading":"/ðə ˈpeɪmənt ˈsɜːrvər/","meaning":"server pembayaran","role":"object"},{"jp":"right now.","reading":"/raɪt naʊ/","meaning":"sekarang juga.","role":"time"}],"translation":"Mereka sedang memperbaiki server pembayaran sekarang juga."},{"tokens":[{"jp":"What","reading":"/wʌt/","meaning":"apa yang","role":"object"},{"jp":"are","reading":"/ɑːr/","meaning":"(be tanya)","role":"verb"},{"jp":"you","reading":"/juː/","meaning":"kamu","role":"subject"},{"jp":"working on","reading":"/ˈwɜːrkɪŋ ɑːn/","meaning":"sedang kerjakan","role":"verb"},{"jp":"this sprint?","reading":"/ðɪs sprɪnt/","meaning":"pada sprint ini?","role":"time"}],"translation":"Apa yang sedang kamu kerjakan pada sprint ini?"}],"forms":[{"label":"Positif","jp":"She''s sharing her slides now.","reading":"/ʃiːz ˈʃɛrɪŋ hɜːr slaɪdz naʊ/","id":"Dia sedang membagikan salindiamya sekarang."},{"label":"Negatif","jp":"I''m not working from home today.","reading":"/aɪm nɑːt ˈwɜːrkɪŋ frʌm hoʊm təˈdeɪ/","id":"Saya tidak sedang kerja dari rumah hari ini."},{"label":"Tanya","jp":"Are you still waiting for approval?","reading":"/ɑːr juː stɪl ˈweɪtɪŋ fɔːr əˈpruːvəl/","id":"Apakah Anda masih menunggu persetujuan?"}],"mistakes":[{"wrong":"I''m knowing the answer to this question.","right":"I know the answer to this question.","why":"''Know'' adalah stative verb (kondisi mental, bukan aksi fisik berdurasi), sehingga wajib memakai Present Simple."},{"wrong":"He working on the presentation right now.","right":"He is working on the presentation right now.","why":"V-ing tidak bisa menjadi predikat kalimat tanpa kata bantu ''am/is/are'' di depannya."}],"quiz":[{"question":"Pilih kalimat yang tepat untuk menggambarkan situasi detik ini:","options":["Look! It snows outside the window.","Look! It snowing outside the window.","Look! It''s snowing outside the window.","Look! It is snow outside the window."],"answer":2,"why":"Kata seru ''Look!'' menandakan kejadian tepat saat dilihat mata sekarang, sehingga memakai ''It''s snowing''."},{"question":"Manakah kalimat yang SALAH karena melanggar aturan Stative Verb?","options":["We are reviewing the contract now.","She is needing your signature right now.","I am staying at a hotel this week.","They are building a new lab."],"answer":1,"why":"''Need'' adalah stative verb yang tidak dipakai dalam bentuk Continuous; yang benar adalah ''She needs your signature right now''."},{"question":"Bagaimana ejaan bentuk ''-ing'' yang benar untuk kata kerja ''plan'' dan ''write''?","options":["planing / writeing","planning / writing","planning / writting","planing / writing"],"answer":1,"why":"''Plan'' berpola konsonan-vokal-konsonan satu suku kata (''planning''), sedangkan ''write'' membuang ''-e'' akhir (''writing'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000009', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-009', 'honorific', 'Imperatives & Polite Suggestions: Instruksi & Ajakan (Please / Let''s)', '(Please) + V1 + [Object] • Don''t + V1 • Let''s (+ not) + V1', 'Memberikan petunjuk kerja yang lugas namun sopan, peringatan, serta ajakan kolaboratif.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"Please mute your microphone during the presentation.","reading":"/pliːz mjuːt jʊr ˈmaɪkrəfoʊn ˈdʊrɪŋ ðə ˌprɛzənˈteɪʃən/","id":"Mohon bisukan mikrofon Anda selama presentasi berlangsung."},{"jp":"Let''s take a five-minute break before the next session.","reading":"/lɛts teɪk ə ˈfaɪvˌmɪnɪt breɪk bɪˈfɔːr ðə nɛkst ˈsɛʃən/","id":"Mari kita istirahat lima menit sebelum sesi berikutnya."}]'::jsonb, 'Please review (/pliːz rɪˈvjuː/) • Don''t forget (/doʊnt fərˈɡɛt/) • Let''s start (/lɛts stɑːrt/)', '{"analogy":"Kalimat Imperative ibarat tombol pintas: subjek ''You'' sengaja disembunyikan karena kita langsung bicara ke orang di depan kita (''Open the file!''). Supaya tidak terdengar memerintah kasar di kantor Amerika, tambahkan pelembut ''Please'', atau gunakan ''Let''s'' (= Let us) saat mengajak bergerak bersama sebagai satu tim.","when_to_use":["Menulis instruksi langkah demi langkah di email, SOP, UI aplikasi, atau papan petunjuk","Mengingatkan rekan kerja agar tidak melakukan kesalahan (''Don''t share your password'')","Mengajak anggota tim memulai rapat, makan siang, atau berdiskusi bersama (''Let''s wrap up'')"],"formula_parts":[{"role":"particle","text":"Please / Let''s / Don''t","label":"Pelembut / Ajakan / Larangan"},{"role":"verb","text":"V1 (Base Verb)","label":"Kata Kerja Dasar"},{"role":"object","text":"Object / Complement","label":"Sasaran Instruksi"}],"steps":["Mulai langsung dengan V1 murni (untuk kata sifat seperti ''careful'' atau ''quiet'', awali dengan ''Be'': ''Please be careful!'').","Untuk larangan, taruh ''Don''t'' di depan V1—bahkan sebelum ''be'' sekalipun (''Don''t be late!'').","Gunakan ''Let''s + V1'' untuk ajakan positif (''Mari kita...''), dan ''Let''s not + V1'' untuk ajakan menghindari sesuatu (''Sebaiknya kita jangan...'')."],"breakdowns":[{"tokens":[{"jp":"Please","reading":"/pliːz/","meaning":"tolong / silakan","role":"particle"},{"jp":"attach","reading":"/əˈtætʃ/","meaning":"lampirkan (V1)","role":"verb"},{"jp":"your receipt","reading":"/jʊr rɪˈsiːt/","meaning":"tanda terima Anda","role":"object"},{"jp":"as a PDF.","reading":"/æz ə ˌpiːdiːˈɛf/","meaning":"sebagai berkas PDF.","role":"noun"}],"translation":"Silakan lampirkan tanda terima Anda sebagai berkas PDF."},{"tokens":[{"jp":"Let''s not","reading":"/lɛts nɑːt/","meaning":"mari kita jangan","role":"particle"},{"jp":"rush","reading":"/rʌʃ/","meaning":"terburu-buru (V1)","role":"verb"},{"jp":"this decision.","reading":"/ðɪs dɪˈsɪʒən/","meaning":"keputusan ini.","role":"object"}],"translation":"Mari kita jangan terburu-buru mengambil keputusan ini."}],"forms":[{"label":"Instruksi Sopan","jp":"Please feel free to ask questions.","reading":"/pliːz fiːl friː tu æsk ˈkwɛstʃənz/","id":"Silakan bertanya dengan leluasa."},{"label":"Larangan (+ Be)","jp":"Don''t be afraid to make mistakes.","reading":"/doʊnt biː əˈfreɪd tə meɪk mɪˈsteɪks/","id":"Jangan takut membuat kesalahan."},{"label":"Ajakan Tim (Let''s)","jp":"Let''s circle back to this tomorrow.","reading":"/lɛts ˈsɜːrkəl bæk tə ðɪs təˈmɑːroʊ/","id":"Mari kita bahas kembali hal ini besok."}],"mistakes":[{"wrong":"Don''t late for the onboarding session!","right":"Don''t be late for the onboarding session!","why":"''Late'' adalah kata sifat, bukan kata kerja; setelah ''Don''t'' wajib ada kata kerja dasar ''be''."},{"wrong":"Let''s to grab some coffee downstairs.","right":"Let''s grab some coffee downstairs.","why":"''Let''s'' (= Let us) wajib langsung diikuti bare infinitive V1 tanpa ''to''."}],"quiz":[{"question":"Lengkapi kalimat pengingat di kantor berikut: ''___ forget to lock your screen before leaving your desk.''","options":["Not","No","Don''t","Doesn''t"],"answer":2,"why":"Kalimat larangan/pengingat imperatif selalu diawali ''Don''t'' + V1 (''Don''t forget'')."},{"question":"Bagaimana bentuk negatif alami dari ajakan ''Let''s'' dalam Bahasa Inggris Amerika?","options":["Don''t let''s to jump to conclusions.","Let''s not jump to conclusions.","Let''s don''t jumping to conclusions.","Not let''s jump to conclusions."],"answer":1,"why":"Dalam American English standar, bentuk negatif ''Let''s'' adalah ''Let''s not + V1''."},{"question":"Pilih instruksi yang benar dengan kata sifat ''patient'':","options":["Please patient while the page loads.","Please are patient while the page loads.","Please be patient while the page loads.","Please being patient while the page loads."],"answer":2,"why":"Kata sifat dalam kalimat imperatif wajib didahului kata kerja dasar ''be'' (''Please be patient'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000010', 'e1000001-0000-4000-8000-000000000001', 'GP-EN-A1-010', 'sentence_pattern', 'Basic Wh- Questions: Pertanyaan Informasi Dasar (What / Where / How)', '[Wh- Word] + am/is/are/do/does/can + [Subject] + [Verb / Complement]?', 'Menggali informasi spesifik (apa, di mana, kapan, mengapa, siapa, bagaimana) dengan urutan kata tanya standar.', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"Where do you see yourself in five years?","reading":"/wɛr də juː siː jərˈsɛlf ɪn faɪv jɪrz/","id":"Di mana Anda melihat diri Anda dalam lima tahun ke depan?"},{"jp":"How long does it take to get to the campus?","reading":"/haʊ lɔːŋ dʌz ɪt teɪk tə ɡɛt tə ðə ˈkæmpəs/","id":"Berapa lama waktu yang dibutuhkan untuk sampai ke kampus?"}]'::jsonb, 'Where do you...? (/wɛr də juː/) • How much is...? • Who led...? (Subject Q tanpa do)', '{"analogy":"Dalam Bahasa Indonesia lisan, kata tanya boleh ditaruh di ujung kalimat (''Kamu tinggal di mana?''). Dalam Bahasa Inggris, kata tanya Wh- selalu menjadi ''lokomotif kereta'' di gerbong paling depan, diikuti gerbong kata bantu (do/does/is/are/can), baru subjeknya!","when_to_use":["Mengajukan pertanyaan terbuka saat networking, wawancara kerja, atau orientasi kampus","Menanyakan durasi (''How long''), frekuensi (''How often''), harga (''How much''), atau jumlah (''How many'')","Menanyakan pelaku langsung menggunakan Subject Question (''Who manages this repo?'' tanpa ''do/does'')"],"formula_parts":[{"role":"connector","text":"Wh- / How","label":"Kata Tanya Pembuka"},{"role":"particle","text":"do / does / is / are","label":"Kata Bantu (Auxiliary)"},{"role":"subject","text":"Subject","label":"Subjek"},{"role":"verb","text":"V1 (jika pakai do/does)","label":"Kata Kerja Utama"}],"steps":["Pilih kata tanya yang tepat: What (apa), Where (di mana), When (kapan), Why (mengapa), Who (siapa), Which (yang mana), How (bagaimana/berapa).","Pasang rumus QUASM: Question word + Auxiliary (do/does/am/is/are/can) + Subject + Main verb.","Pengecualian penting: jika ''Who'' atau ''What'' sendiri yang menjadi SUBJEK pelaku aksi (''Siapa yang menelepon?''), langsung tempel kata kerja tanpa ''do/does'' (''Who called you?'')."],"breakdowns":[{"tokens":[{"jp":"Why","reading":"/waɪ/","meaning":"mengapa","role":"connector"},{"jp":"do","reading":"/duː/","meaning":"(kata bantu tanya)","role":"particle"},{"jp":"you","reading":"/juː/","meaning":"Anda","role":"subject"},{"jp":"want to join","reading":"/wɑːnt tə dʒɔɪn/","meaning":"ingin bergabung dengan","role":"verb"},{"jp":"our company?","reading":"/ˈaʊər ˈkʌmpəni/","meaning":"perusahaan kami?","role":"object"}],"translation":"Mengapa Anda ingin bergabung dengan perusahaan kami?"},{"tokens":[{"jp":"Who","reading":"/huː/","meaning":"siapa yang (sebagai subjek)","role":"subject"},{"jp":"leads","reading":"/liːdz/","meaning":"memimpin (langsung V+s)","role":"verb"},{"jp":"the design team?","reading":"/ðə dɪˈzaɪn tiːm/","meaning":"tim desain?","role":"object"}],"translation":"Siapa yang memimpin tim desain?"}],"forms":[{"label":"Dengan Do/Does","jp":"What time does the keynote start?","reading":"/wʌt taɪm dʌz ðə ˈkiːnoʊt stɑːrt/","id":"Jam berapa pidato utamanya dimulai?"},{"label":"Dengan Be Verb","jp":"How is your new apartment?","reading":"/haʊ ɪz jʊr nuː əˈpɑːrtmənt/","id":"Bagaimana apartemen baru kamu?"},{"label":"Subject Question","jp":"What causes this error message?","reading":"/wʌt ˈkɔːzɪz ðɪs ˈɛrər ˈmɛsɪdʒ/","id":"Apa yang menyebabkan pesan galat ini?"}],"mistakes":[{"wrong":"Where you live right now?","right":"Where do you live right now?","why":"Pertanyaan Wh- dengan kata kerja aksi (''live'') wajib menyertakan kata bantu ''do/does'' sebelum subjek."},{"wrong":"Who does manage this project?","right":"Who manages this project?","why":"Saat menanyakan subjek pelaku (''Who'' = pelaku), jangan gunakan ''does'' kecuali memberi penekanan kontras khusus."}],"quiz":[{"question":"Susun pertanyaan yang benar untuk menanyakan frekuensi olahraga:","options":["How often you work out?","How often do you work out?","How often are you work out?","What often do you work out?"],"answer":1,"why":"Menanyakan frekuensi memakai ''How often'' diikuti pola QUASM ''do + you + work out''."},{"question":"Pilih pertanyaan yang tepat saat menanyakan pelaku: ''___ wrote the feedback on this document?''","options":["Who did","Who","Whom did","Whose"],"answer":1,"why":"''Who'' berfungsi langsung sebagai subjek kalimat, sehingga langsung diikuti kata kerja ''wrote'' tanpa ''did''."},{"question":"Lengkapi pertanyaan orientasi kampus: ''___ building is the student center—the red one or the glass one?''","options":["What","Who","Which","Where"],"answer":2,"why":"Ketika memilih dari pilihan terbatas yang disebutkan (''the red one or the glass one''), gunakan ''Which''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000011', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-001', 'tense', 'Past Simple: Kejadian Lampau Tuntas (worked / went / did)', '[Subject] + V2 (Regular -ed / Irregular) • didn''t + V1 • Did + [Subject] + V1?', 'Menceritakan peristiwa, pencapaian, atau riwayat masa lalu yang sudah selesai di titik waktu tertentu.', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"We launched our beta version two weeks ago.","reading":"/wiː lɔːntʃt ˈaʊər ˈbeɪtə ˈvɜːrʒən tuː wiːks əˈɡoʊ/","id":"Kami meluncurkan versi beta kami dua minggu yang lalu."},{"jp":"I didn''t receive the calendar invite yesterday.","reading":"/aɪ ˈdɪdənt rɪˈsiːv ðə ˈkæləndər ˈɪnvaɪt ˈjɛstərdeɪ/","id":"Saya tidak menerima undangan kalender kemarin."}]'::jsonb, 'launched (/lɔːntʃt/) • needed (/ˈniːdɪd/) • went (/wɛnt/) • didn''t + V1', '{"analogy":"Jika Bahasa Indonesia cukup menambahkan kata ''kemarin'' atau ''tadi'' tanpa mengubah kata kerja, Bahasa Inggris wajib memasang ''stempel masa lalu'' langsung di kata kerjanya (V2). Namun begitu satpam ''did / didn''t'' masuk di kalimat tanya atau negatif, stempel lampaunya pindah ke ''did'' sehingga kata kerja kembali murni ke V1!","when_to_use":["Menjelaskan pengalaman kerja atau proyek terdahulu saat wawancara (''In 2024, I led a team of five'')","Melaporkan apa yang sudah dikerjakan kemarin saat daily standup meeting","Menceritakan kronologi peristiwa dengan penanda waktu selesai (''yesterday'', ''last night'', ''in 2022'', ''...ago'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Semua Subjek Sama"},{"role":"verb","text":"V2 (-ed / Irregular)","label":"Bentuk Lampau"},{"role":"object","text":"Object","label":"Sasaran"},{"role":"time","text":"yesterday / last week","label":"Waktu Lampau Selesai"}],"steps":["Gunakan V2 untuk semua subjek di kalimat positif: tambahkan ''-ed'' untuk regular verbs (''worked'', ''studied''), atau hafalkan irregular verbs (''go → went'', ''build → built'').","Untuk kalimat negatif, gunakan ''didn''t + V1'' (jangan pernah ''didn''t went''!).","Khusus Be Verb di masa lampau, gunakan ''was'' (I/he/she/it) atau ''were'' (you/we/they) tanpa memakai ''did''!"],"breakdowns":[{"tokens":[{"jp":"She","reading":"/ʃiː/","meaning":"dia","role":"subject"},{"jp":"graduated","reading":"/ˈɡrædʒueɪtɪd/","meaning":"lulus (V2 regular)","role":"verb"},{"jp":"from UCLA","reading":"/frʌm ˌjuːsiːɛlˈeɪ/","meaning":"dari UCLA","role":"place"},{"jp":"in 2023.","reading":"/ɪn ˈtwɛnti ˈtwɛnti θriː/","meaning":"pada tahun 2023.","role":"time"}],"translation":"Dia lulus dari UCLA pada tahun 2023."},{"tokens":[{"jp":"Did","reading":"/dɪd/","meaning":"apakah (lampau)","role":"particle"},{"jp":"the client","reading":"/ðə ˈklaɪənt/","meaning":"klien tersebut","role":"subject"},{"jp":"sign","reading":"/saɪn/","meaning":"menandatangani (kembali V1)","role":"verb"},{"jp":"the contract","reading":"/ðə ˈkɑːntrækt/","meaning":"kontraknya","role":"object"},{"jp":"last Friday?","reading":"/læst ˈfraɪdeɪ/","meaning":"Jumat lalu?","role":"time"}],"translation":"Apakah klien tersebut menandatangani kontraknya Jumat lalu?"}],"forms":[{"label":"Irregular Positif","jp":"They built the prototype in three days.","reading":"/ðeɪ bɪlt ðə ˈproʊtətaɪp ɪn θriː deɪz/","id":"Mereka membangun prototipenya dalam tiga hari."},{"label":"Negatif (didn''t + V1)","jp":"We didn''t hit our target last month.","reading":"/wiː ˈdɪdənt hɪt ˈaʊər ˈtɑːrɡɪt læst mʌnθ/","id":"Kami tidak mencapai target kami bulan lalu."},{"label":"Lampau Be (was/were)","jp":"Were you at the town hall yesterday?","reading":"/wɜːr juː æt ðə taʊn hɔːl ˈjɛstərdeɪ/","id":"Apakah Anda hadir di rapat umum kemarin?"}],"mistakes":[{"wrong":"I didn''t went to the seminar yesterday.","right":"I didn''t go to the seminar yesterday.","why":"Setelah ''did'' atau ''didn''t'', kata kerja utama wajib kembali ke V1 (''go''), bukan V2 (''went'')."},{"wrong":"Did you were tired after the flight?","right":"Were you tired after the flight?","why":"''Tired'' adalah kata sifat yang memakai Be Verb (''was/were''), sehingga tidak boleh dicampur dengan ''Did''."}],"quiz":[{"question":"Pilih bentuk lampau yang benar: ''Last semester, Reza ___ a research paper on renewable energy.''","options":["write","writed","wrote","written"],"answer":2,"why":"''Write'' adalah irregular verb: write (V1) → wrote (V2) → written (V3)."},{"question":"Manakah kalimat tanya Past Simple yang tepat?","options":["Where did you stayed in Chicago?","Where did you stay in Chicago?","Where were you stay in Chicago?","Where you stayed in Chicago?"],"answer":1,"why":"Rumus tanya Past Simple adalah Wh- + did + Subject + V1 murni (''stay'')."},{"question":"Bagaimana pelafalan akhiran ''-ed'' pada kata ''worked'' dalam American English?","options":["/ˈwɜːrkɪd/ (dua suku kata)","/wɜːrkt/ (bunyi /t/ satu suku kata)","/wɜːrkd/ (bunyi /d/)","/wɜːrkɛd/"],"answer":1,"why":"Setelah bunyi tak bersuara /k/, akhiran ''-ed'' dilafalkan menyatu sebagai /t/ (/wɜːrkt/), bukan /ɪd/!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000012', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-002', 'tense', 'Future Plans vs Decisions: Rencana vs Spontan (be going to vs will)', '[Subject] + am/is/are going to + V1 (Rencana/Bukti) vs [Subject] + will + V1 (Spontan/Janji)', 'Membedakan niat masa depan yang sudah direncanakan sebelumnya (''be going to'') dari keputusan mendadak atau janji (''will'').', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"I''m going to apply for the Fulbright scholarship this fall.","reading":"/aɪm ˈɡɔɪŋ tu əˈplaɪ fɔːr ðə ˈfʊlbraɪt ˈskɑːlərʃɪp ðɪs fɔːl/","id":"Saya berencana melamar beasiswa Fulbright musim gugur ini."},{"jp":"Your bag looks heavy—I''ll carry it for you.","reading":"/jʊr bæɡ lʊks ˈhɛvi aɪl ˈkæri ɪt fɔːr juː/","id":"Tas Anda terlihat berat—biar saya bawakan untuk Anda."}]'::jsonb, 'going to (/ˈɡɔɪŋ tə/ atau lisan /ˈɡʌnə/) vs I''ll (/aɪl/) + V1', '{"analogy":"Dalam Bahasa Indonesia keduanya diterjemahkan menjadi ''akan''. Bedanya: ''be going to'' itu seperti tiket pesawat yang SUDAH kamu beli di kantong (rencana matang atau bukti sudah terlihat di depan mata), sedangkan ''will'' itu refleks spontan detik ini (''Oh telepon bunyi, aku yang angkat: I''ll get it!'') atau janji.","when_to_use":["Pakai ''be going to'' untuk rencana pribadi/karier yang sudah diputuskan sebelum berbicara","Pakai ''be going to'' untuk prediksi berdasarkan bukti fisik nyata saat ini (''Look at those dark clouds—it''s going to rain'')","Pakai ''will'' (''ll / won''t) untuk keputusan spontan saat bicara, tawaran bantuan, janji, atau prediksi opini (''I think... will...'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"am/is/are going to | will","label":"Rencana vs Spontan"},{"role":"verb","text":"V1 (Base Verb)","label":"Aksi Masa Depan"}],"steps":["Tanyakan pada diri sendiri: ''Apakah saya sudah merencanakan ini sebelum percakapan dimulai?'' Jika YA, pakai ''am/is/are going to + V1''.","Jika baru saja memutuskan detik ini untuk membantu/merespons, pakai kontraksi alami ''I''ll + V1'' (negatif: ''won''t + V1'').","Catatan gaya bahasa: ucapan lisan cepat ''gonna'' lazim di obrolan santai AS, tetapi DILARANG ditulis di esai TOEFL atau email resmi!"],"breakdowns":[{"tokens":[{"jp":"We''re going to","reading":"/wɪr ˈɡɔɪŋ tə/","meaning":"kami sudah berencana akan","role":"verb"},{"jp":"migrate","reading":"/ˈmaɪɡreɪt/","meaning":"memigrasikan (V1)","role":"verb"},{"jp":"our database","reading":"/ˈaʊər ˈdeɪtəbeɪs/","meaning":"basis data kami","role":"object"},{"jp":"next month.","reading":"/nɛkst mʌnθ/","meaning":"bulan depan.","role":"time"}],"translation":"Kami berencana memigrasikan basis data kami bulan depan."},{"tokens":[{"jp":"Don''t worry,","reading":"/doʊnt ˈwɜːri/","meaning":"jangan khawatir,","role":"connector"},{"jp":"I''ll","reading":"/aɪl/","meaning":"saya akan (janji spontan)","role":"subject"},{"jp":"send","reading":"/sɛnd/","meaning":"mengirimkan","role":"verb"},{"jp":"the summary","reading":"/ðə ˈsʌməri/","meaning":"ringkasannya","role":"object"},{"jp":"right away.","reading":"/raɪt əˈweɪ/","meaning":"segera.","role":"time"}],"translation":"Jangan khawatir, saya akan segera mengirimkan ringkasannya."}],"forms":[{"label":"Rencana Matang","jp":"She''s going to study computer science at MIT.","reading":"/ʃiːz ˈɡɔɪŋ tə ˈstʌdi kəmˈpjuːtər ˈsaɪəns æt ˌɛmaɪˈtiː/","id":"Dia akan kuliah ilmu komputer di MIT."},{"label":"Keputusan Spontan","jp":"Wait, I forgot my badge. I''ll go grab it.","reading":"/weɪt aɪ fərˈɡɑːt maɪ bædʒ aɪl ɡoʊ ɡræb ɪt/","id":"Tunggu, kartu akses saya ketinggalan. Saya ambil sebentar."},{"label":"Janji Negatif (won''t)","jp":"I promise it won''t happen again.","reading":"/aɪ ˈprɑːmɪs ɪt woʊnt ˈhæpən əˈɡɛn/","id":"Saya berjanji hal itu tidak akan terjadi lagi."}],"mistakes":[{"wrong":"I going to meet the advisor tomorrow.","right":"I''m going to meet the advisor tomorrow.","why":"Pola ''be going to'' wajib selalu menyertakan ''am / is / are'' sebelum ''going to''."},{"wrong":"Wait a second, I''m going to open the door for you!","right":"Wait a second, I''ll open the door for you!","why":"Tawaran bantuan yang diputuskan spontan saat melihat situasi langsung memakai ''I''ll'', bukan ''I''m going to''."}],"quiz":[{"question":"Rekan kerja berkata: ''We''re out of printer paper.'' Respons spontan yang paling alami adalah:","options":["I''m going to order some right now—I planned it yesterday.","Oh, I''ll order some right now.","I order some right now.","I''ll to order some right now."],"answer":1,"why":"Karena kamu baru tahu kertasnya habis detik itu juga, keputusan spontan menawarkan bantuan memakai ''I''ll + V1''."},{"question":"Pilih kalimat yang tepat untuk bukti nyata di depan mata: ''Watch out! That coffee cup is on the edge of the desk—it ___!''","options":["will falling","is going to fall","falls","going to fall"],"answer":1,"why":"Prediksi dari bukti fisik yang terlihat jelas detik ini memakai ''is going to fall''."},{"question":"Manakah bentuk singkatan negatif dari ''will not''?","options":["willn''t","wouldn''t","won''t","don''t will"],"answer":2,"why":"''Will not'' disingkat menjadi ''won''t'' (/woʊnt/)."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000013', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-003', 'particle', 'Countable, Uncountable & Quantifiers: Takaran Benda (much / many / a lot of)', 'many / a few (+ Plural Countable) • much / a little (+ Uncountable) • a lot of (+ Keduanya)', 'Memilih penanda jumlah yang tepat antara kata benda yang dapat dihitung satu-satu dan kata benda tak terhitung.', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"We received a lot of helpful feedback from early users.","reading":"/wiː rɪˈsiːvd ə lɑːt əv ˈhɛlpfəl ˈfiːdbæk frʌm ˈɜːrli ˈjuːzərz/","id":"Kami menerima banyak masukan bermanfaat dari pengguna awal."},{"jp":"How many applicants passed the coding test?","reading":"/haʊ ˈmɛni ˈæplɪkənts pæst ðə ˈkoʊdɪŋ tɛst/","id":"Berapa banyak pelamar yang lulus tes pemrograman?"}]'::jsonb, 'many tasks • much feedback (/mʌtʃ ˈfiːdbæk/) • a lot of data', '{"analogy":"Bayangkan Countable Noun seperti butir telur (bisa dihitung 1, 2, 3 dan diberi ''-s''), sedangkan Uncountable Noun seperti air atau beras dalam karung—tidak dihitung per butir sehingga TIDAK PERNAH memakai ''a/an'' maupun akhiran ''-s''! Jebakan favorit TOEFL adalah kata yang di Indonesia terasa bisa dihitung padahal di Inggris Uncountable: advice, information, equipment, research, furniture, luggage, feedback.","when_to_use":["Menanyakan kuantitas dengan ''How many'' (benda jamak terhitung) vs ''How much'' (benda tak terhitung / harga)","Memakai ''many'' dan ''much'' terutama di kalimat negatif dan tanya, serta ''a lot of / plenty of'' di kalimat positif alami","Membedakan nuansa ''a few / a little'' (ada sedikit, positif cukup) vs ''few / little'' tanpa ''a'' (hampir tidak ada, bernada kurang)"],"formula_parts":[{"role":"adjective","text":"many / (a) few","label":"+ Benda Jamak (-s)"},{"role":"adjective","text":"much / (a) little","label":"+ Benda Tak Terhitung"},{"role":"noun","text":"a lot of / some / any","label":"+ Fleksibel Keduanya"}],"steps":["Pastikan dulu apakah kata bendanya Countable atau Uncountable (ingat daftar emas TOEFL: information, advice, equipment, software, traffic, progress = SELALU tunggal tak terhitung!).","Jika ingin menghitung satuannya untuk kata Uncountable, tambahkan wadah pembilang seperti ''a piece of advice'' atau ''two pieces of equipment''.","Gunakan ''some'' untuk kalimat positif dan tawaran sopan (''Would you like some coffee?''), serta ''any'' untuk kalimat negatif dan tanya umum."],"breakdowns":[{"tokens":[{"jp":"We don''t have","reading":"/wiː doʊnt hæv/","meaning":"kami tidak punya","role":"verb"},{"jp":"much","reading":"/mʌtʃ/","meaning":"banyak (uncountable)","role":"adjective"},{"jp":"time","reading":"/taɪm/","meaning":"waktu","role":"object"},{"jp":"before boarding.","reading":"/bɪˈfɔːr ˈbɔːrdɪŋ/","meaning":"sebelum naik pesawat.","role":"time"}],"translation":"Kita tidak punya banyak waktu sebelum naik pesawat."},{"tokens":[{"jp":"I have","reading":"/aɪ hæv/","meaning":"saya punya","role":"verb"},{"jp":"a few","reading":"/ə fjuː/","meaning":"beberapa (positif cukup)","role":"adjective"},{"jp":"suggestions","reading":"/səɡˈdʒɛstʃənz/","meaning":"saran (countable jamak)","role":"object"},{"jp":"for the slide deck.","reading":"/fɔːr ðə slaɪd dɛk/","meaning":"untuk materi presentasi ini.","role":"noun"}],"translation":"Saya punya beberapa saran untuk materi presentasi ini."}],"forms":[{"label":"Countable (Jamak)","jp":"Only a few seats are available.","reading":"/ˈoʊnli ə fjuː siːts ɑːr əˈveɪləbəl/","id":"Hanya beberapa kursi yang tersedia."},{"label":"Uncountable (Tunggal)","jp":"My mentor gave me a great piece of advice.","reading":"/maɪ ˈmɛntɔːr ɡeɪv miː ə ɡreɪt piːs əv ədˈvaɪs/","id":"Mentor saya memberi saya satu nasihat hebat."},{"label":"Negatif dengan Any","jp":"The lab doesn''t need any new equipment.","reading":"/ðə læb ˈdʌzənt niːd ˈɛni nuː ɪˈkwɪpmənt/","id":"Laboratorium tersebut tidak membutuhkan peralatan baru apa pun."}],"mistakes":[{"wrong":"Let me give you some advices and informations.","right":"Let me give you some advice and information.","why":"''Advice'' dan ''information'' adalah Uncountable Nouns—dilarang keras menambahkan akhiran ''-s'' atau artikel ''an''!"},{"wrong":"How many money do we need for the campaign?","right":"How much money do we need for the campaign?","why":"Meskipun mata uang (''dollars'', ''rupiah'') bisa dihitung, kata ''money'' itu sendiri adalah Uncountable sehingga memakai ''How much''."}],"quiz":[{"question":"Pilih kalimat yang 100% benar menurut standar TOEFL Structure:","options":["The researchers gathered many new equipments.","The researchers gathered a lot of new equipment.","The researchers gathered a few new equipments.","The researchers gathered an equipment."],"answer":1,"why":"''Equipment'' adalah kata benda tak terhitung (uncountable), sehingga tidak pernah berakhiran ''-s'' dan cocok dengan ''a lot of''."},{"question":"Apa perbedaan makna antara ''I have a few contacts in New York'' dan ''I have few contacts in New York''?","options":["Tidak ada bedanya sama sekali","''A few'' bernada positif (ada beberapa yang bisa dihubungi), sedangkan ''few'' bernada negatif (hampir tidak punya)","''Few'' artinya ratusan orang","''A few'' hanya untuk benda cair"],"answer":1,"why":"''A few'' berarti ''beberapa (cukup membantu)'', sementara ''few'' tanpa ''a'' menekankan kelangkaan (''sangat sedikit / nyaris tidak ada'')."},{"question":"Lengkapi pertanyaan berikut: ''How ___ luggage are we allowed to check in?''","options":["many","much","few","number of"],"answer":1,"why":"''Luggage'' (berbeda dari ''suitcases'' atau ''bags'') adalah Uncountable Noun sehingga memakai ''How much''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000014', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-004', 'conjugation', 'Comparatives & Superlatives: Perbandingan & Paling (-er / more / the -est)', '[Adj-er / more Adj] + than (2 hal) • the + [Adj-est / most Adj] (3+ hal / teratas)', 'Membandingkan dua opsi untuk pengambilan keputusan (''lebih... daripada'') dan menunjuk peringkat tertinggi (''paling...'').', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"The new algorithm is much faster than the previous version.","reading":"/ðə nuː ˈælɡərɪðəm ɪz mʌtʃ ˈfæstər ðæn ðə ˈpriːviəs ˈvɜːrʒən/","id":"Algoritma baru ini jauh lebih cepat daripada versi sebelumnya."},{"jp":"This is the most reliable cloud service on the market.","reading":"/ðɪs ɪz ðə moʊst rɪˈlaɪəbəl klaʊd ˈsɜːrvɪs ɑːn ðə ˈmɑːrkɪt/","id":"Ini adalah layanan cloud paling andal di pasaran."}]'::jsonb, 'faster than (/ˈfæstər ðæn/) • more efficient • the best (/ðə bɛst/)', '{"analogy":"Aturan panjang-pendeknya sangat logis bagi lidah: kata sifat pendek 1 suku kata (''fast'', ''cheap'') cukup ditempeli ekor ''-er / -est'' supaya ringkas. Tapi kata sifat panjang 2–3+ suku kata (''expensive'', ''convenient'') kalau ditempeli ''-er'' bakal bikin lidah keseleo (''expensiver'' ❌), jadi diberi kata pendamping ''more / the most'' di depannya!","when_to_use":["Membandingkan performa dua produk, kandidat, strategi, atau kota dengan ''...than''","Menonjolkan pencapaian tertinggi atau prioritas utama menggunakan ''the + superlative''","Menyatakan kesetaraan dua hal dengan pola ''as + adjective murni + as'' (''as effective as'')"],"formula_parts":[{"role":"adjective","text":"Adj-er / more + Adj","label":"Lebih... (1 vs 2+ suku kata)"},{"role":"connector","text":"than","label":"Daripada (Ejaan -an!)"},{"role":"adjective","text":"the Adj-est / the most Adj","label":"Paling... (3+ objek)"}],"steps":["Hitung suku kata: 1 suku kata (dan 2 suku kata berakhiran ''-y'' seperti ''easy → easier'') memakai ''-er / the -est''.","Kata sifat 2+ suku kata lainnya (''modern'', ''reliable'', ''important'') memakai ''more ... than'' dan ''the most ...''.","Wajib kuasai 3 bentuk tak beraturan terpenting: good → better → the best, bad → worse → the worst, far → farther/further → the farthest/furthest."],"breakdowns":[{"tokens":[{"jp":"Taking the subway","reading":"/ˈteɪkɪŋ ðə ˈsʌbweɪ/","meaning":"naik kereta bawah tanah","role":"subject"},{"jp":"is","reading":"/ɪz/","meaning":"adalah","role":"verb"},{"jp":"cheaper and easier","reading":"/ˈtʃiːpər ænd ˈiːziər/","meaning":"lebih murah dan lebih mudah","role":"adjective"},{"jp":"than driving.","reading":"/ðæn ˈdraɪvɪŋ/","meaning":"daripada menyetir.","role":"connector"}],"translation":"Naik kereta bawah tanah lebih murah dan lebih mudah daripada menyetir."},{"tokens":[{"jp":"Security","reading":"/sɪˈkjʊrəti/","meaning":"keamanan","role":"subject"},{"jp":"is","reading":"/ɪz/","meaning":"adalah","role":"verb"},{"jp":"our highest","reading":"/ˈaʊər ˈhaɪɪst/","meaning":"paling tinggi kami","role":"adjective"},{"jp":"priority.","reading":"/praɪˈɔːrəti/","meaning":"prioritas.","role":"noun"}],"translation":"Keamanan adalah prioritas tertinggi kami."}],"forms":[{"label":"Comparative + Penguat","jp":"Option B is far more scalable than Option A.","reading":"/ˈɑːpʃən biː ɪz fɑːr mɔːr ˈskeɪləbəl ðæn ˈɑːpʃən eɪ/","id":"Opsi B jauh lebih mudah diskalakan daripada Opsi A."},{"label":"Superlative Irregular","jp":"What was the worst bug you ever fixed?","reading":"/wʌt wʌz ðə wɜːrst bʌɡ juː ˈɛvər fɪkst/","id":"Apa kutu sistem terparah yang pernah Anda perbaiki?"},{"label":"Setara (as...as)","jp":"Remote work is just as productive as office work.","reading":"/rɪˈmoʊt wɜːrk ɪz dʒʌst æz prəˈdʌktɪv æz ˈɔːfɪs wɜːrk/","id":"Kerja jarak jauh sama produktifnya dengan kerja di kantor."}],"mistakes":[{"wrong":"This monitor is more bigger then mine.","right":"This monitor is much bigger than mine.","why":"Hindari double comparative (''more bigger'' ❌); untuk menekankan ''jauh lebih'', gunakan ''much / far bigger'', dan eja ''than'' pakai huruf ''a'', bukan ''then''!"},{"wrong":"Between the two candidates, Sari is the best.","right":"Between the two candidates, Sari is the better one.","why":"Dalam TOEFL formal, saat membandingkan HANYA DUA kandidat (''between the two''), gunakan comparative (''the better''), bukan superlative (''the best'')."}],"quiz":[{"question":"Pilih kalimat perbandingan yang bebas dari kesalahan grammar:","options":["Customer retention is more cheaper than acquisition.","Customer retention is much cheaper than acquisition.","Customer retention is cheaper then acquisition.","Customer retention is most cheap than acquisition."],"answer":1,"why":"''Cheap'' (1 suku kata) menjadi ''cheaper'', diperkuat dengan ''much'' (bukan ''more''), dan diikuti ''than''."},{"question":"Lengkapi kalimat berikut: ''Out of all five proposals, Nadia''s plan is ___ practical.''","options":["more","most","the most","the practicalest"],"answer":2,"why":"Membandingkan satu dari lima proposal (3+ objek) dengan kata sifat 3 suku kata memakai superlative ''the most practical''."},{"question":"Manakah bentuk comparative yang tepat dari kata sifat ''bad''?","options":["badder","more bad","worse","worst"],"answer":2,"why":"Perubahan tak beraturan dari ''bad'' adalah: bad → worse (comparative) → the worst (superlative)."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000015', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-005', 'tense', 'Past Continuous: Aksi Sedang Terjadi di Masa Lalu (was / were + -ing)', '[Subject] + was / were + V-ing (+ when + Past Simple)', 'Melukiskan aksi berdurasi yang sedang berlangsung di titik waktu lampau atau saat diinterupsi kejadian lain.', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"I was presenting our roadmap when the Wi-Fi dropped.","reading":"/aɪ wəz prɪˈzɛntɪŋ ˈaʊər ˈroʊdmæp wɛn ðə ˈwaɪfaɪ drɑːpt/","id":"Saya sedang mempresentasikan peta jalan kami ketika Wi-Fi terputus."},{"jp":"What were you doing at 8 p.m. last night?","reading":"/wʌt wɜːr juː ˈduːɪŋ æt eɪt ˌpiːˈɛm læst naɪt/","id":"Apa yang sedang kamu lakukan pukul 8 tadi malam?"}]'::jsonb, 'I/He/She/It was (/wʌz/) + V-ing • You/We/They were (/wɜːr/) + V-ing', '{"analogy":"Bayangkan adegan film: Past Continuous (''was/were + -ing'') adalah kamera video panjang sebagai latar suasana yang sedang berjalan, sedangkan Past Simple (''V2'') adalah bunyi ''KLIK!'' kejadian singkat yang tiba-tiba memotong di tengahnya (''Saya SEDANG mandi ketika paket DATANG'').","when_to_use":["Menceritakan aktivitas yang sedang di tengah jalan ketika kejadian pendek menyela (''was coding when the power went out'')","Menjelaskan aktivitas yang sedang berlangsung pada jam spesifik di masa lalu (''At noon yesterday, we were flying to Denver'')","Menggambarkan dua aktivitas lampau yang berjalan paralel bersamaan dengan ''while''"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"was / were + V-ing","label":"Aksi Panjang Berlangsung"},{"role":"connector","text":"when","label":"Ketika Tiba-Tiba"},{"role":"predicate","text":"Subject + V2","label":"Interupsi Singkat"}],"steps":["Pilih ''was'' untuk subjek tunggal (I, he, she, it) dan ''were'' untuk subjek jamak serta ''you'' (you, we, they).","Gunakan Past Continuous untuk aksi yang berdurasi lebih panjang (latar), dan Past Simple (V2) untuk kejadian pendobrak yang singkat.","Jika dua aksi panjang terjadi serentak tanpa saling menghentikan, hubungkan keduanya dengan ''while'' (''While I was taking notes, he was sharing his screen'')."],"breakdowns":[{"tokens":[{"jp":"We","reading":"/wiː/","meaning":"kami","role":"subject"},{"jp":"were testing","reading":"/wɜːr ˈtɛstɪŋ/","meaning":"sedang menguji (durasi panjang)","role":"verb"},{"jp":"the checkout page","reading":"/ðə ˈtʃɛkaʊt peɪdʒ/","meaning":"halaman pembayaran","role":"object"},{"jp":"when we found","reading":"/wɛn wiː faʊnd/","meaning":"ketika kami menemukan (V2 singkat)","role":"connector"},{"jp":"a critical bug.","reading":"/ə ˈkrɪtɪkəl bʌɡ/","meaning":"sebuah kutu kritis.","role":"object"}],"translation":"Kami sedang menguji halaman pembayaran ketika menemukan kutu kritis."},{"tokens":[{"jp":"She","reading":"/ʃiː/","meaning":"dia","role":"subject"},{"jp":"wasn''t looking","reading":"/ˈwʌzənt ˈlʊkɪŋ/","meaning":"sedang tidak melihat","role":"verb"},{"jp":"at her phone","reading":"/æt hɜːr foʊn/","meaning":"ke ponselnya","role":"place"},{"jp":"during the lecture.","reading":"/ˈdʊrɪŋ ðə ˈlɛktʃər/","meaning":"selama perkuliahan.","role":"time"}],"translation":"Dia sedang tidak melihat ke ponselnya selama perkuliahan."}],"forms":[{"label":"Aksi Terinterupsi","jp":"He was walking to work when it started to rain.","reading":"/hiː wəz ˈwɔːkɪŋ tə wɜːrk wɛn ɪt ˈstɑːrtɪd tə reɪn/","id":"Dia sedang berjalan kaki ke kantor ketika hujan mulai turun."},{"label":"Dua Aksi Paralel","jp":"While I was cooking, my roommate was studying.","reading":"/waɪl aɪ wəz ˈkʊkɪŋ maɪ ˈruːmmeɪt wəz ˈstʌdiɪŋ/","id":"Sementara saya sedang memasak, teman sekamar saya sedang belajar."},{"label":"Latar Sopan Alasan","jp":"Sorry I missed your call—I was driving.","reading":"/ˈsɑːri aɪ mɪst jʊr kɔːl aɪ wəz ˈdraɪvɪŋ/","id":"Maaf saya melewatkan telepon Anda—tadi saya sedang menyetir."}],"mistakes":[{"wrong":"You was sleeping when I called.","right":"You were sleeping when I called.","why":"Meski bermakna satu orang (''kamu''), subjek ''You'' selalu wajib berpasangan dengan ''were'', tidak pernah ''was''."},{"wrong":"When I walked down the street, I was dropping my keys.","right":"While I was walking down the street, I dropped my keys.","why":"''Walking'' adalah aksi berdurasi panjang (Past Continuous), sedangkan ''dropped my keys'' adalah kejadian sekejap (Past Simple)."}],"quiz":[{"question":"Lengkapi kronologi berikut: ''The engineers ___ the server logs when the alarm suddenly ___ off.''","options":["checked / was going","were checking / went","was checking / went","were check / go"],"answer":1,"why":"''The engineers'' (jamak) sedang melakukan aksi panjang (''were checking'') saat diinterupsi bunyi alarm sekejap (''went off'')."},{"question":"Pilih kalimat yang benar:","options":["I was knowing him in college.","At 10 a.m. yesterday, we were interviewing a candidate.","They was waiting at the gate.","Were she working late last night?"],"answer":1,"why":"Pada titik jam spesifik kemarin (''At 10 a.m. yesterday''), subjek ''we'' memakai ''were interviewing''."},{"question":"Mengapa ''I was wondering if you could help me'' terdengar jauh lebih sopan daripada ''I wonder...''?","options":["Karena artinya sudah batal minta tolong","Karena bentuk Past Continuous memberi jarak psikologis yang halus sehingga tidak terkesan mendesak lawan bicara","Karena hanya boleh dipakai untuk masa lalu 10 tahun silam","Karena merupakan kalimat pasif"],"answer":1,"why":"Dalam Bahasa Inggris profesional, ''I was wondering / I was hoping'' dipakai untuk memperhalus permintaan saat ini!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000016', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-006', 'tense', 'Present Perfect Basics: Pengalaman Hidup & Hasil Kini (have / has + V3)', '[Subject] + have / has + V3 (Past Participle) + [ever / never / already / yet]', 'Menghubungkan pengalaman hidup tanpa tanggal spesifik atau aksi baru selesai yang hasilnya terasa sekarang.', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"Have you ever spoken at an international conference?","reading":"/hæv juː ˈɛvər ˈspoʊkən æt ən ˌɪntərˈnæʃənəl ˈkɑːnfərəns/","id":"Pernahkah Anda berbicara di konferensi internasional?"},{"jp":"She has already submitted her visa application.","reading":"/ʃiː hæz ɔːlˈrɛdi səbˈmɪtɪd hɜːr ˈviːzə ˌæplɪˈkeɪʃən/","id":"Dia sudah mengirimkan permohonan visanya."}]'::jsonb, 'I''ve visited (/aɪv ˈvɪzɪtɪd/) • She''s finished (/ʃiːz ˈfɪnɪʃt/) • Have you ever...?', '{"analogy":"Dalam Bahasa Indonesia kita punya dua kata sakti: ''SUDAH'' dan ''PERNAH''. Begitu kamu ingin bilang ''Saya sudah makan'' (hasilnya sekarang kenyang, jam makannya tidak penting) atau ''Saya pernah ke Tokyo'' (pengalaman seumur hidup hingga detik ini), itulah wilayah kekuasaan Present Perfect (''have/has + V3'')!","when_to_use":["Menanyakan atau membagikan pengalaman hidup seumur hidup (''Have you ever...?'' / ''I''ve never...'')","Melaporkan tugas yang baru saja atau sudah beres dengan ''just'', ''already'', atau ''yet''","Menyatakan pencapaian sejauh ini pada periode waktu yang belum habis (''so far'', ''this week'', ''three times'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"have / has","label":"Kata Bantu Kini"},{"role":"verb","text":"V3 (Past Participle)","label":"Sudah / Pernah"},{"role":"time","text":"already / yet / ever","label":"Penanda Status"}],"steps":["Gunakan ''have'' (''ve / haven''t) untuk I/you/we/they, dan ''has'' (''s / hasn''t) untuk he/she/it.","Ikuti dengan kata kerja bentuk ketiga (V3): akhiran ''-ed'' untuk regular, atau bentuk ketiga irregular (''go → gone/been'', ''see → seen'', ''write → written'').","Bedakan ''been to'' vs ''gone to'': ''She has been to Boston'' (pernah ke sana dan sudah pulang), sedangkan ''She has gone to Boston'' (sedang berangkat/berada di sana sekarang!)."],"breakdowns":[{"tokens":[{"jp":"I''ve","reading":"/aɪv/","meaning":"saya sudah/pernah (I + have)","role":"subject"},{"jp":"never","reading":"/ˈnɛvər/","meaning":"tidak pernah","role":"time"},{"jp":"used","reading":"/juːzd/","meaning":"menggunakan (V3)","role":"verb"},{"jp":"this software","reading":"/ðɪs ˈsɔːftwɛr/","meaning":"perangkat lunak ini","role":"object"},{"jp":"before.","reading":"/bɪˈfɔːr/","meaning":"sebelumnya.","role":"time"}],"translation":"Saya belum pernah menggunakan perangkat lunak ini sebelumnya."},{"tokens":[{"jp":"Has","reading":"/hæz/","meaning":"sudahkah (tunggal)","role":"verb"},{"jp":"the courier","reading":"/ðə ˈkʊriər/","meaning":"kurir tersebut","role":"subject"},{"jp":"arrived","reading":"/əˈraɪvd/","meaning":"tiba (V3)","role":"verb"},{"jp":"yet?","reading":"/jɛt/","meaning":"(penanda tanya ''sudah/belum'')?","role":"time"}],"translation":"Apakah kurirnya sudah tiba?"}],"forms":[{"label":"Positif (+ already)","jp":"We''ve already backed up all the files.","reading":"/wiːv ɔːlˈrɛdi bækt ʌp ɔːl ðə faɪlz/","id":"Kami sudah mencadangkan semua berkasnya."},{"label":"Negatif (+ yet)","jp":"He hasn''t replied to my email yet.","reading":"/hiː ˈhæzənt rɪˈplaɪd tə maɪ ˈiːmeɪl jɛt/","id":"Dia belum membalas email saya."},{"label":"Pengalaman (been to)","jp":"I''ve been to Singapore twice.","reading":"/aɪv bɪn tə ˌsɪŋəˈpɔːr twaɪs/","id":"Saya pernah ke Singapura dua kali."}],"mistakes":[{"wrong":"Have you ever went to San Francisco?","right":"Have you ever been to San Francisco?","why":"Setelah ''have/has'' wajib memakai V3 (''been'' untuk pengalaman berkunjung, bukan V2 ''went'')."},{"wrong":"I already have eat lunch.","right":"I have already eaten lunch.","why":"''Already'' diletakkan di antara ''have/has'' dan V3 (''eaten'', bukan V1 ''eat'')."}],"quiz":[{"question":"Pilih kalimat yang benar untuk menyatakan ''belum'':","options":["They haven''t announce the winners yet.","They haven''t announced the winners yet.","They didn''t announced the winners already.","They hasn''t announced the winners yet."],"answer":1,"why":"Subjek ''They'' memakai ''haven''t'' + V3 (''announced'') dengan ''yet'' di ujung kalimat negatif."},{"question":"Jika rekanmu berkata ''Mr. Lee has gone to Tokyo'', di manakah Mr. Lee berada sekarang?","options":["Sudah kembali duduk di kantor Jakarta","Sedang berada di Tokyo atau dalam perjalanan ke sana","Batal berangkat ke Tokyo","Tinggal di Tokyo 20 tahun lalu"],"answer":1,"why":"''Has gone to'' berarti ia pergi ke sana dan BELUM kembali; jika sudah kembali, gunakan ''has been to''."},{"question":"Lengkapi pertanyaan pengalaman berikut: ''How many times ___ you ___ the TOEFL iBT?''","options":["did / took","have / took","have / taken","has / taken"],"answer":2,"why":"Bentuk V3 dari ''take'' (take → took → taken) wajib dipakai setelah ''have''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000017', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-007', 'conjugation', 'Modals of Obligation & Advice: Kewajiban & Saran (have to / must / should)', '[Subject] + have/has to / must + V1 (Wajib) • don''t have to (Tak perlu) vs mustn''t (Dilarang) • should + V1 (Saran)', 'Membedakan aturan wajib, larangan keras, ketiadaan kewajiban, serta rekomendasi bijak.', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"All visitors have to wear an ID badge inside the building.","reading":"/ɔːl ˈvɪzɪtərz ˈhæf tə wɛr ən ˌaɪˈdiː bædʒ ɪnˈsaɪd ðə ˈbɪldɪŋ/","id":"Semua pengunjung wajib mengenakan kartu identitas di dalam gedung."},{"jp":"You don''t have to print the ticket—a QR code works fine.","reading":"/juː doʊnt ˈhæf tə prɪnt ðə ˈtɪkɪt ə ˌkjuːˈɑːr koʊd wɜːrks faɪn/","id":"Anda tidak perlu mencetak tiketnya—kode QR sudah cukup."}]'::jsonb, 'have to (/ˈhæf tə/) • must + V1 • shouldn''t (/ˈʃʊdənt/) + V1', '{"analogy":"Di kalimat positif, ''must'' dan ''have to'' mirip seperti saudara kembar yang artinya sama-sama ''harus'' (di AS, ''have to'' jauh lebih sering dipakai sehari-hari, sedangkan ''must'' untuk aturan tertulis). TAPI begitu menjadi negatif, keduanya berpisah 180 derajat! ''Must not'' = DILARANG KERAS (lampu merah!), sedangkan ''don''t have to'' = TIDAK USAH / OPSIONAL (boleh kalau mau, tapi tidak wajib)!","when_to_use":["Pakai ''have to / has to'' untuk kewajiban eksternal sehari-hari (aturan kantor, jadwal pajak, syarat kampus)","Pakai ''must / must not'' untuk regulasi tertulis resmi atau tekad kuat dari diri sendiri","Pakai ''should / shouldn''t'' untuk memberi saran profesional yang sopan tanpa terkesan memaksa"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"have to / must / should","label":"Tingkat Keharusan"},{"role":"verb","text":"V1 (Base Verb)","label":"Tindakan"}],"steps":["Ingat bahwa ''must'' dan ''should'' adalah modal murni (tidak berubah jadi ''-s'' dan langsung + V1), sedangkan ''have to'' berubah menjadi ''has to'' untuk he/she/it dan memakai ''do/does'' untuk negatif/tanya.","Cek ulang makna negatifmu: kalau maksudmu ''tidak perlu repot-repot'', gunakan ''don''t/doesn''t have to'', JANGAN ''must not''!","Untuk kewajiban di masa lalu (''kemarin harus lembur''), ubah menjadi ''had to + V1'' (karena ''must'' tidak punya bentuk lampau sendiri)."],"breakdowns":[{"tokens":[{"jp":"Applicants","reading":"/ˈæplɪkənts/","meaning":"para pelamar","role":"subject"},{"jp":"must submit","reading":"/mʌst səbˈmɪt/","meaning":"wajib menyerahkan (aturan resmi)","role":"verb"},{"jp":"two recommendation letters.","reading":"/tuː ˌrɛkəmɛnˈdeɪʃən ˈlɛtərz/","meaning":"dua surat rekomendasi.","role":"object"}],"translation":"Para pelamar wajib menyerahkan dua surat rekomendasi."},{"tokens":[{"jp":"You","reading":"/juː/","meaning":"kamu","role":"subject"},{"jp":"should","reading":"/ʃʊd/","meaning":"sebaiknya (saran)","role":"verb"},{"jp":"back up","reading":"/bæk ʌp/","meaning":"mencadangkan","role":"verb"},{"jp":"your thesis","reading":"/jʊr ˈθiːsɪs/","meaning":"tesis kamu","role":"object"},{"jp":"every night.","reading":"/ˈɛvri naɪt/","meaning":"setiap malam.","role":"time"}],"translation":"Sebaiknya kamu mencadangkan tesismu setiap malam."}],"forms":[{"label":"Larangan Keras (must not)","jp":"Employees must not share client data externally.","reading":"/ɪmˈplɔɪiːz mʌst nɑːt ʃɛr ˈklaɪənt ˈdeɪtə ɪkˈstɜːrnəli/","id":"Karyawan dilarang keras membagikan data klien ke pihak luar."},{"label":"Opsional (doesn''t have to)","jp":"She doesn''t have to work this Saturday.","reading":"/ʃiː ˈdʌzənt ˈhæf tə wɜːrk ðɪs ˈsætərdeɪ/","id":"Dia tidak perlu bekerja hari Sabtu ini."},{"label":"Kewajiban Lampau (had to)","jp":"We had to reschedule the flight yesterday.","reading":"/wiː hæd tə ˌriːˈskɛdʒuːl ðə flaɪt ˈjɛstərdeɪ/","id":"Kami terpaksa menjadwalkan ulang penerbangannya kemarin."}],"mistakes":[{"wrong":"Tomorrow is a holiday, so you mustn''t wake up early!","right":"Tomorrow is a holiday, so you don''t have to wake up early!","why":"''Mustn''t wake up early'' berarti ''dilarang bangun pagi''! Untuk arti ''tidak usah bangun pagi'', gunakan ''don''t have to''."},{"wrong":"He shoulds to apologize to the client.","right":"He should apologize to the client.","why":"Modal ''should'' tidak pernah ditambah ''-s'' maupun ''to''."}],"quiz":[{"question":"Acara makan malam tim bersifat sukarela (boleh ikut, boleh tidak). Kalimat mana yang tepat?","options":["You must not attend the team dinner.","You don''t have to attend the team dinner.","You haven''t to attend the team dinner.","You shouldn''t to attend the team dinner."],"answer":1,"why":"''Don''t have to'' menyatakan bahwa sesuatu bersifat opsional / tidak diwajibkan."},{"question":"Lengkapi kalimat untuk masa lampau: ''Because my passport expired, I ___ renew it last week.''","options":["must","musted","had to","have to"],"answer":2,"why":"Bentuk lampau dari kewajiban ''must / have to'' selalu menggunakan ''had to''."},{"question":"Pilih pertanyaan saran yang benar saat berdiskusi dengan mentor:","options":["Do I should include my GPA on my resume?","Should I include my GPA on my resume?","Should I to include my GPA on my resume?","Am I should include my GPA on my resume?"],"answer":1,"why":"Pertanyaan dengan modal ''should'' langsung memindahkan ''Should'' ke depan subjek tanpa ''Do/Am''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000018', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-008', 'honorific', 'Polite Requests: Permintaan Sopan Profesional (Could you / Would you mind)', 'Could / Would you + V1...? • Would you mind + V-ing...? • Would you mind if I + V2...?', 'Mengajukan permintaan kerja dan izin secara santun kepada klien, dosen, atau rekan lintas divisi.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"Could you look over my cover letter when you have a chance?","reading":"/kʊd juː lʊk ˈoʊvər maɪ ˈkʌvər ˈlɛtər wɛn juː hæv ə tʃæns/","id":"Bisakah Anda memeriksa surat lamaran saya saat Anda ada waktu luang?"},{"jp":"Would you mind sending me the raw dataset?","reading":"/wʊd juː maɪnd ˈsɛndɪŋ miː ðə rɔː ˈdeɪtəsɛt/","id":"Apakah Anda keberatan mengirimkan kumpulan data mentahnya kepada saya?"}]'::jsonb, 'Could you (/ˈkʊdʒuː/) + V1 • Would you mind (/wʊdʒuː maɪnd/) + V-ing', '{"analogy":"Memakai ''Give me...'' atau ''Can you...'' ke profesor atau klien baru rasanya seperti menepuk bahu orang asing terlalu keras. Menggantinya dengan ''Could you / Would you'' memberi bantalan kesopanan profesional. Khusus ''Would you mind...?'', artinya harfiahnya ''Apakah Anda KEBERATAN...?''—jadi kalau kamu TIDAK keberatan dan mau membantu, jawabannya justru ''Not at all! / No, go ahead!'' (bukan ''Yes''!).","when_to_use":["Meminta bantuan dosen pembimbing, atasan, atau klien lewat email maupun rapat","Memakai ''Would you mind + V-ing'' saat meminta hal yang agak merepotkan lawan bicara","Meminta izin dengan sangat halus menggunakan ''Could I...?'' atau ''Would you mind if I + V2...?''"],"formula_parts":[{"role":"verb","text":"Could / Would you + V1","label":"Sopan Standar (+ V1)"},{"role":"verb","text":"Would you mind + V-ing","label":"Ekstra Halus (+ V-ing!)"},{"role":"ending","text":"Not at all! / Sure!","label":"Respons Menyetujui"}],"steps":["Untuk permintaan sopan serbaguna, gunakan ''Could you (please) + V1...?'' atau ''Would you + V1...?''.","Jika memakai kata kerja ''mind'' (''keberatan''), WAJIB ubah kata kerja setelahnya menjadi Gerund V-ing (''Would you mind waiting?'').","Hati-hati merespons ''Would you mind...?'': di TOEFL Listening, jawaban ''No, not at all'' atau ''Of course not'' artinya SETUJU membantu (''Sama sekali tidak keberatan'')!"],"breakdowns":[{"tokens":[{"jp":"Would you mind","reading":"/wʊd juː maɪnd/","meaning":"apakah Anda keberatan","role":"verb"},{"jp":"moving","reading":"/ˈmuːvɪŋ/","meaning":"memindahkan (wajib V-ing)","role":"verb"},{"jp":"our call","reading":"/ˈaʊər kɔːl/","meaning":"panggilan kita","role":"object"},{"jp":"to 3 p.m.?","reading":"/tə θriː ˌpiːˈɛm/","meaning":"ke pukul 3 sore?","role":"time"}],"translation":"Apakah Anda keberatan menggeser jadwal panggilan kita ke pukul 3 sore?"},{"tokens":[{"jp":"Would you mind","reading":"/wʊd juː maɪnd/","meaning":"apakah Anda keberatan","role":"verb"},{"jp":"if I","reading":"/ɪf aɪ/","meaning":"jika saya (meminta izin)","role":"connector"},{"jp":"recorded","reading":"/rɪˈkɔːrdɪd/","meaning":"merekam (V2 untuk jarak sopan)","role":"verb"},{"jp":"this session?","reading":"/ðɪs ˈsɛʃən/","meaning":"sesi ini?","role":"object"}],"translation":"Apakah Anda keberatan jika saya merekam sesi ini?"}],"forms":[{"label":"Email Profesional","jp":"Could you please confirm receipt of this email?","reading":"/kʊd juː pliːz kənˈfɜːrm rɪˈsiːt əv ðɪs ˈiːmeɪl/","id":"Mohon konfirmasi penerimaan email ini."},{"label":"Meminta Orang Lain (+ V-ing)","jp":"Would you mind speaking a bit louder?","reading":"/wʊd juː maɪnd ˈspiːkɪŋ ə bɪt ˈlaʊdər/","id":"Apakah Anda keberatan berbicara sedikit lebih keras?"},{"label":"Respons Setuju Alami","jp":"Not at all—I''d be happy to help!","reading":"/nɑːt æt ɔːl aɪd biː ˈhæpi tə hɛlp/","id":"Sama sekali tidak keberatan—saya senang membantu!"}],"mistakes":[{"wrong":"Would you mind to open the window?","right":"Would you mind opening the window?","why":"Kata kerja ''mind'' selalu diikuti Gerund (V-ing), tidak pernah diikuti ''to + V1''."},{"wrong":"A: ''Do you mind if I sit here?'' — B: ''Yes, please sit down!''","right":"A: ''Do you mind if I sit here?'' — B: ''No, not at all—go right ahead!''","why":"Menjawab ''Yes'' pada ''Do/Would you mind'' secara harfiah berarti ''Ya, saya keberatan (jangan duduk)''!"}],"quiz":[{"question":"Lengkapi permintaan halus berikut: ''Would you mind ___ me CC''d on the client thread?''","options":["keep","to keep","keeping","kept"],"answer":2,"why":"Setelah ''Would you mind'', kata kerja wajib berbentuk V-ing (''keeping'')."},{"question":"Dalam TOEFL Listening: Wanita bertanya ''Would you mind closing the blinds?'' dan Pria menjawab ''Not in the least.'' Apa yang dilakukan pria itu?","options":["Menolak menutup tirai karena marah","Menutup tirai dengan senang hati karena sama sekali tidak keberatan","Meminta wanita itu menutupnya sendiri","Membuka jendela lebar-lebar"],"answer":1,"why":"''Not in the least'' (= sama sekali tidak keberatan) adalah ekspresi idiomatis menyetujui permintaan ''Would you mind''."},{"question":"Pilih kalimat meminta izin yang paling sopan dan tepat secara grammar:","options":["Would you mind if I borrowed your adapter for ten minutes?","Would you mind if I borrowing your adapter?","Could I borrowed your adapter?","Would you mind me to borrow your adapter?"],"answer":0,"why":"Pola izin ''Would you mind if I...'' diikuti Past Simple (''borrowed'') atau Present Simple (''borrow''), di mana V2 terdengar ekstra santun."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000019', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-009', 'conjugation', 'Infinitive of Purpose vs Gerunds: Tujuan & Kata Kerja Benda (to + V1 vs V-ing)', '[Action] + to + V1 (Tujuan ''untuk...'') • [Verb/Preposition] + V-ing (enjoy / finish / interested in)', 'Menggunakan ''to + V1'' untuk menyatakan tujuan tindakan, serta ''V-ing'' setelah kata kerja tertentu dan semua preposisi.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"I moved to Austin to join an AI research lab.","reading":"/aɪ muːvd tu ˈɔːstɪn tə dʒɔɪn ən ˌeɪˈaɪ ˈriːsɜːrtʃ læb/","id":"Saya pindah ke Austin untuk bergabung dengan laboratorium riset AI."},{"jp":"Thank you for taking the time to interview me today.","reading":"/θæŋk juː fɔːr ˈteɪkɪŋ ðə taɪm tu ˈɪntərvjuː miː təˈdeɪ/","id":"Terima kasih telah meluangkan waktu untuk mewawancarai saya hari ini."}]'::jsonb, 'came to learn (/keɪm tə lɜːrn/) • enjoy coding • good at solving', '{"analogy":"Jebakan nomor satu penutur Indonesia adalah menerjemahkan kata ''untuk'' + kata kerja menjadi ''for + V1'' (''I came here for study'' ❌)! Ingat rumus besinya: kalau menjelaskan TUJUAN suatu aksi (''demi/untuk melakukan...''), pakai ''to + V1''. Sebaliknya, begitu bertemu preposisi apa pun (for, in, at, about, without, before, after) atau kata kerja seperti ''enjoy / finish / avoid'', kata kerja di belakangnya wajib menyamar jadi kata benda dengan kostum ''-ing''!","when_to_use":["Menjawab alasan/tujuan ''Mengapa melakukan X?'' menggunakan Infinitive of Purpose (''to + V1'' atau formal ''in order to + V1'')","Meletakkan V-ing (Gerund) setelah kata kerja kelompok ''enjoy, finish, avoid, suggest, keep, consider, mind''","Meletakkan V-ing setelah SEMUA preposisi (''thank you for helping'', ''interested in learning'', ''without checking'') dan sebagai subjek kalimat (''Coding requires focus'')"],"formula_parts":[{"role":"verb","text":"to + V1","label":"Tujuan Aksi (''untuk...'')"},{"role":"verb","text":"enjoy/finish/avoid + V-ing","label":"Verba Peminta Gerund"},{"role":"particle","text":"Prep (in/for/by) + V-ing","label":"Preposisi Wajib + V-ing"}],"steps":["Untuk menyatakan tujuan tindakan, gunakan ''to + V1'' (''I called her to confirm''), BUKAN ''for + V1''.","Kenali dua kubu kata kerja: kubu ''+ to V1'' (want, need, decide, plan, hope, promise) vs kubu ''+ V-ing'' (enjoy, finish, avoid, suggest, keep, practice).","Hafalkan aturan mutlak tanpa kompromi: setiap kata kerja tepat setelah preposisi (of, in, at, for, about, by, without) WAJIB menjadi V-ing!"],"breakdowns":[{"tokens":[{"jp":"She stayed late","reading":"/ʃiː steɪd leɪt/","meaning":"dia pulang larut","role":"verb"},{"jp":"to finish","reading":"/tə ˈfɪnɪʃ/","meaning":"untuk menyelesaikan (tujuan)","role":"verb"},{"jp":"writing","reading":"/ˈraɪtɪŋ/","meaning":"penulisan (finish + V-ing!)","role":"object"},{"jp":"the grant proposal.","reading":"/ðə ɡrænt prəˈpoʊzəl/","meaning":"proposal hibah tersebut.","role":"object"}],"translation":"Dia pulang larut untuk menyelesaikan penulisan proposal hibah tersebut."},{"tokens":[{"jp":"Automating","reading":"/ˈɔːtəmeɪtɪŋ/","meaning":"mengotomatiskan (Gerund subjek)","role":"subject"},{"jp":"tests","reading":"/tɛsts/","meaning":"pengujian","role":"object"},{"jp":"saves","reading":"/seɪvz/","meaning":"menghemat (tunggal!)","role":"verb"},{"jp":"hours of manual work.","reading":"/ˈaʊərz əv ˈmænjuəl wɜːrk/","meaning":"berjam-jam kerja manual.","role":"object"}],"translation":"Mengotomatiskan pengujian menghemat berjam-jam kerja manual."}],"forms":[{"label":"Tujuan (to + V1)","jp":"Click the link below to reset your password.","reading":"/klɪk ðə lɪŋk bɪˈloʊ tə ˌriːˈsɛt jʊr ˈpæswɜːrd/","id":"Klik tautan di bawah ini untuk mengatur ulang kata sandi Anda."},{"label":"Setelah Preposisi (by + V-ing)","jp":"You can improve fluency by shadowing native speakers.","reading":"/juː kən ɪmˈpruːv ˈfluːənsi baɪ ˈʃædoʊɪŋ ˈneɪtɪv ˈspiːkərz/","id":"Anda bisa meningkatkan kelancaran dengan menirukan penutur asli."},{"label":"Setelah Suggest (+ V-ing)","jp":"Our advisor suggested narrowing the research topic.","reading":"/ˈaʊər ədˈvaɪzər səɡˈdʒɛstɪd ˈnæroʊɪŋ ðə ˈriːsɜːrtʃ ˈtɑːpɪk/","id":"Pembimbing kami menyarankan untuk mempersempit topik riset."}],"mistakes":[{"wrong":"I''m saving money for buy a new MacBook.","right":"I''m saving money to buy a new MacBook.","why":"Tujuan melakukan suatu aksi wajib memakai ''to + V1'' (''to buy''), bukan ''for + V1''."},{"wrong":"We decided postponing the launch, and avoided to rush.","right":"We decided to postpone the launch, and avoided rushing.","why":"''Decide'' selalu diikuti ''to + V1'', sedangkan ''avoid'' selalu diikuti Gerund ''V-ing''."}],"quiz":[{"question":"Lengkapi kalimat penutup email berikut: ''I am excited about ___ your engineering team this summer.''","options":["join","to join","joining","joined"],"answer":2,"why":"''About'' adalah preposisi, sehingga kata kerja sesudahnya wajib berbentuk Gerund (''joining'')."},{"question":"Pilih kalimat yang benar saat menjelaskan tujuan keberangkatan:","options":["He flew to Seattle for attend the cloud summit.","He flew to Seattle to attend the cloud summit.","He flew to Seattle for attending to the cloud summit.","He flew to Seattle attend the cloud summit."],"answer":1,"why":"Infinitive of Purpose (''untuk menghadiri'') dinyatakan dengan ''to attend''."},{"question":"Jika Gerund menjadi subjek kalimat ''Learning two foreign languages ___ patience'', kata kerja mana yang benar?","options":["require","requires","are requiring","requiring"],"answer":1,"why":"Subjek utamanya adalah aktivitas tunggal ''Learning'' (bukan kata benda ''languages'' di dalamnya!), sehingga kata kerjanya tunggal: ''requires''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000020', 'e1000001-0000-4000-8000-000000000002', 'GP-EN-A2-010', 'particle', 'Time Clauses: Urutan Waktu & Kejadian (when / before / after / while)', '[When / Before / After / As soon as + Present Simple], [Subject + will + V1]', 'Menghubungkan dua kejadian berurutan di masa lalu maupun masa depan tanpa menggandakan ''will'' di klausa waktu.', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"I''ll ping you on Slack as soon as the build finishes.","reading":"/aɪl pɪŋ juː ɑːn slæk æz suːn æz ðə bɪld ˈfɪnɪʃɪz/","id":"Saya akan mengabari Anda di Slack segera setelah proses kompilasi selesai."},{"jp":"Always save your work before you close the editor.","reading":"/ˈɔːlweɪz seɪv jʊr wɜːrk bɪˈfɔːr juː kloʊz ði ˈɛdɪtər/","id":"Selalu simpan pekerjaan Anda sebelum menutup editor."}]'::jsonb, 'When she arrives (/wɛn ʃiː əˈraɪvz/), we''ll start — TANPA ''will'' di klausa waktu!', '{"analogy":"Aturan emas Time Clause masa depan ini sering mengecoh peserta TOEFL: klausa yang diawali ''when, before, after, as soon as, until'' alergi berat terhadap kata ''will''! Walaupun kejadiannya besok atau tahun depan, di dalam anak kalimat waktunya cukup pakai Present Simple (''When I arrive tomorrow...''), karena makna masa depannya sudah diwakili oleh ''will'' di induk kalimat!","when_to_use":["Menjanjikan tindakan lanjutan begitu suatu syarat waktu terpenuhi (''as soon as'', ''once'', ''when'')","Menentukan batas waktu tunggu menggunakan ''until'' (''Wait here until your name is called'')","Merangkai urutan logis sebelum (''before''), sesudah (''after''), atau selama (''while'') suatu aktivitas"],"formula_parts":[{"role":"connector","text":"When / As soon as / Before","label":"Konjungsi Waktu"},{"role":"predicate","text":"Subject + Present Simple","label":"Dilarang Pakai ''will''!"},{"role":"predicate","text":"Subject + will + V1","label":"Induk Kalimat Masa Depan"}],"steps":["Jika klausa waktu diletakkan di AWAL kalimat, pisahkan dengan tanda koma sebelum masuk ke induk kalimat (''Before you leave, turn off the lights'').","Jika membicarakan masa depan, pastikan klausa ''when/before/after/until/as soon as'' memakai Present Simple (jangan lupa ''-s'' untuk he/she/it!).","Tips ringkas profesional: jika subjek kedua klausa SAMA, ''before/after/while'' boleh langsung diringkas menjadi ''+ V-ing'' (''After graduating, she joined Google'')."],"breakdowns":[{"tokens":[{"jp":"When","reading":"/wɛn/","meaning":"ketika (nanti)","role":"connector"},{"jp":"the professor","reading":"/ðə prəˈfɛsər/","meaning":"profesor tersebut","role":"subject"},{"jp":"posts","reading":"/poʊsts/","meaning":"mengunggah (Present Simple, bukan will post!)","role":"verb"},{"jp":"the grades,","reading":"/ðə ɡreɪdz/","meaning":"nilainya,","role":"object"},{"jp":"we''ll celebrate.","reading":"/wiːl ˈsɛləbreɪt/","meaning":"kita akan merayakannya.","role":"predicate"}],"translation":"Ketika nanti profesor mengunggah nilainya, kita akan merayakannya."},{"tokens":[{"jp":"Please stay","reading":"/pliːz steɪ/","meaning":"mohon tetap berada","role":"verb"},{"jp":"on the line","reading":"/ɑːn ðə laɪn/","meaning":"di sambungan telepon","role":"place"},{"jp":"until","reading":"/ənˈtɪl/","meaning":"sampai","role":"connector"},{"jp":"an agent","reading":"/ən ˈeɪdʒənt/","meaning":"petugas layanan","role":"subject"},{"jp":"answers.","reading":"/ˈænsərz/","meaning":"menjawab.","role":"verb"}],"translation":"Mohon tetap berada di sambungan telepon sampai petugas menjawab."}],"forms":[{"label":"Masa Depan (Present di Time Clause)","jp":"Once we get budget approval, we''ll hire a designer.","reading":"/wʌns wiː ɡɛt ˈbʌdʒɪt əˈpruːvəl wiːl ˈhaɪər ə dɪˈzaɪnər/","id":"Begitu kami mendapat persetujuan anggaran, kami akan merekrut desainer."},{"label":"Masa Lalu Sejajar","jp":"After he reviewed the code, he merged the pull request.","reading":"/ˈæftər hiː rɪˈvjuːd ðə koʊd hiː mɜːrdʒd ðə pʊl rɪˈkwɛst/","id":"Setelah meninjau kodenya, dia menggabungkan pull request tersebut."},{"label":"Bentuk Ringkas (+ V-ing)","jp":"Before signing any contract, read the fine print.","reading":"/bɪˈfɔːr ˈsaɪnɪŋ ˈɛni ˈkɑːntrækt riːd ðə faɪn prɪnt/","id":"Sebelum menandatangani kontrak apa pun, bacalah klausul kecilnya."}],"mistakes":[{"wrong":"I will call you when my plane will land in Los Angeles.","right":"I will call you when my plane lands in Los Angeles.","why":"Dalam klausa waktu (''when...''), masa depan wajib dinyatakan dengan Present Simple (''lands''), bukan ''will land''."},{"wrong":"During I was interning in Tokyo, I learned a lot.","right":"While I was interning in Tokyo, I learned a lot.","why":"''During'' adalah preposisi yang hanya diikuti kata benda (''during my internship''), sedangkan ''while'' adalah konjungsi yang diikuti klausa Subjek + Verb!"}],"quiz":[{"question":"Pilih bentuk yang tepat untuk kalimat masa depan: ''We won''t release the feature until QA ___ every edge case.''","options":["will verify","verifies","verified","verifying"],"answer":1,"why":"Klausa waktu setelah ''until'' memakai Present Simple, dan subjek tunggal ''QA'' membutuhkan akhiran ''-ies'' (''verifies'')."},{"question":"Bedakan ''during'' vs ''while'': ''Please silence your devices ___ the keynote speaker is on stage.''","options":["during","while","despite","until to"],"answer":1,"why":"Karena diikuti klausa utuh (''the keynote speaker is on stage'' = S + V), wajib memakai konjungsi ''while'', bukan preposisi ''during''."},{"question":"Tanda baca manakah yang benar untuk penulisan akademik?","options":["As soon as the data arrives we will run the model.","As soon as the data arrives, we will run the model.","We will run the model, as soon as the data arrives.","As soon as, the data arrives we will run the model."],"answer":1,"why":"Anak kalimat waktu di posisi awal kalimat dipisahkan dengan koma sebelum induk kalimat; jika di belakang, tidak memakai koma."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000021', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-001', 'tense', 'Present Perfect vs Past Simple: Kini vs Lampau (have done vs did)', 'have/has + V3 (Waktu belum tutup / Dampak kini) vs V2 (Waktu lampau tertutup spesifik)', 'Membedakan kejadian yang terikat ke masa kini dari peristiwa yang terkunci di titik masa lampau yang sudah selesai.', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"Our revenue has grown by 40% since January.","reading":"/ˈaʊər ˈrɛvənuː hæz ɡroʊn baɪ ˈfɔːrti pərˈsɛnt sɪns ˈdʒænjuɛri/","id":"Pendapatan kami telah tumbuh sebesar 40% sejak Januari (hingga kini)."},{"jp":"Our revenue grew by 15% in 2023.","reading":"/ˈaʊər ˈrɛvənuː ɡruː baɪ ˌfɪfˈtiːn pərˈsɛnt ɪn ˈtwɛnti ˈtwɛnti θriː/","id":"Pendapatan kami tumbuh sebesar 15% pada tahun 2023 (tahunnya sudah lewat)."}]'::jsonb, 'have grown (since 2022) vs grew (in 2022 / last year)', '{"analogy":"Bayangkan dua jenis kotak waktu: Past Simple itu ''kotak tersegel''—begitu kamu sebut stempel tanggal mati seperti ''yesterday, last week, in 2021, when I was in college'', pintunya ke masa kini tertutup rapat (wajib V2!). Sebaliknya, Present Perfect adalah ''jembatan terbuka'' yang ujungnya masih menyentuh hari ini (''since Monday, this quarter, over the past five years'').","when_to_use":["Pakai Present Perfect dengan ''since'' (+ titik awal), ''for'' (+ durasi yang masih lanjut), ''lately'', ''recently'', ''so far'', ''this year''","Pakai Past Simple begitu muncul keterangan waktu selesai (''ago'', ''yesterday'', ''last month'', ''in 1998'', ''What time did...?'')","Dalam alur cerita wawancara: buka topik pengalaman secara umum dengan Present Perfect (''I''ve led two migrations''), lalu pindah ke Past Simple saat merinci kronologinya (''The first one happened in 2023...'')"],"formula_parts":[{"role":"verb","text":"have/has + V3","label":"Jembatan ke Kini (since/so far)"},{"role":"verb","text":"V2 (Past Simple)","label":"Titik Lampau Tertutup (in 2022/ago)"},{"role":"time","text":"Time Marker","label":"Penentu Mutlak Tenses"}],"steps":["Periksa penanda waktunya terlebih dahulu: apakah periode waktu itu masih berjalan (misal ''this week'') atau sudah selesai (''last week'')?","Bedakan ''for'' di kedua tenses: ''I worked there for 3 years'' (sekarang sudah resign!) vs ''I have worked here for 3 years'' (sampai detik ini masih kerja di sini!).","Ingat aturan ketat setelah kata ''since'': klausa sesudah ''since'' memakai V2, sedangkan induk kalimatnya memakai Present Perfect (''We have scaled rapidly since we launched'')."],"breakdowns":[{"tokens":[{"jp":"We''ve interviewed","reading":"/wiːv ˈɪntərvjuːd/","meaning":"kami sudah mewawancarai","role":"verb"},{"jp":"six candidates","reading":"/sɪks ˈkændɪdɪts/","meaning":"enam kandidat","role":"object"},{"jp":"this week.","reading":"/ðɪs wiːk/","meaning":"minggu ini (minggunya belum berakhir).","role":"time"}],"translation":"Kami sudah mewawancarai enam kandidat minggu ini."},{"tokens":[{"jp":"She lived","reading":"/ʃiː lɪvd/","meaning":"dulu dia tinggal (sekarang tidak lagi)","role":"verb"},{"jp":"in Seattle","reading":"/ɪn siˈætəl/","meaning":"di Seattle","role":"place"},{"jp":"for four years","reading":"/fɔːr fɔːr jɪrz/","meaning":"selama empat tahun","role":"time"},{"jp":"before moving here.","reading":"/bɪˈfɔːr ˈmuːvɪŋ hɪr/","meaning":"sebelum pindah ke sini.","role":"time"}],"translation":"Dia sempat tinggal di Seattle selama empat tahun sebelum pindah ke sini."}],"forms":[{"label":"Pola Emas Since","jp":"Tech has evolved dramatically since the iPhone debuted in 2007.","reading":"/tɛk hæz ɪˈvɑːlvd drəˈmætɪkli sɪns ði ˈaɪfoʊn deɪˈbjuːd/","id":"Teknologi telah berkembang pesat sejak iPhone pertama rilis tahun 2007."},{"label":"Masih Kerja (Present Perfect)","jp":"Rama has been our CTO for five years.","reading":"/ˈrɑːmə hæz bɪn ˈaʊər ˌsiːtiːˈoʊ fɔːr faɪv jɪrz/","id":"Rama telah menjabat CTO kami selama lima tahun (dan masih menjabat)."},{"label":"Sudah Selesai (Past Simple)","jp":"When did you graduate from college?","reading":"/wɛn dɪd juː ˈɡrædʒueɪt frʌm ˈkɑːlɪdʒ/","id":"Kapan Anda lulus kuliah? (''When'' meminta titik lampau → Past Simple)."}],"mistakes":[{"wrong":"I have sent the invoice yesterday afternoon.","right":"I sent the invoice yesterday afternoon.","why":"Dilarang keras menggabungkan Present Perfect (''have sent'') dengan waktu lampau spesifik seperti ''yesterday''!"},{"wrong":"I live in Bandung since 2020.","right":"I have lived in Bandung since 2020.","why":"Untuk kondisi yang dimulai di masa lalu (''since 2020'') dan berlanjut sampai sekarang, Bahasa Inggris tidak memakai Present Simple melainkan Present Perfect!"}],"quiz":[{"question":"Pilih kalimat yang benar untuk esai atau laporan bisnis:","options":["Global e-commerce has expanded rapidly in 2020.","Global e-commerce has expanded rapidly over the past decade.","Global e-commerce expanded rapidly since 2015.","When have they founded the startup?"],"answer":1,"why":"''Over the past decade'' menghubungkan sepuluh tahun terakhir hingga hari ini, sehingga tepat dipasangkan dengan ''has expanded''."},{"question":"Apa perbedaan makna antara ''I worked at Gojek for two years'' dan ''I''ve worked at Gojek for two years''?","options":["Kalimat pertama salah grammar","Kalimat pertama berarti sudah tidak bekerja di sana lagi; kalimat kedua berarti masih bekerja di sana hingga kini","Kalimat kedua berarti baru akan mulai kerja besok","Keduanya bermakna 100% sama"],"answer":1,"why":"Past Simple + ''for'' menandakan periode yang sudah berakhir, sedangkan Present Perfect + ''for'' menandakan durasi yang masih berlangsung."},{"question":"Lengkapi pola klausa ''since'': ''Ever since our team ___ automated testing, deployment bugs ___ by half.''","options":["has adopted / dropped","adopted / have dropped","adopted / dropped","adopts / have dropped"],"answer":1,"why":"Titik awal sesudah ''since'' memakai V2 (''adopted''), sedangkan dampak kumulatif hingga kini memakai Present Perfect (''have dropped'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000022', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-002', 'tense', 'Present Perfect Continuous: Durasi hingga Kini (have been + -ing)', '[Subject] + have / has + been + V-ing + [for + durasi / since + titik awal]', 'Menekankan proses atau durasi tanpa henti dari masa lalu yang masih berlangsung (atau baru saja berhenti dengan jejak terlihat).', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"We''ve been debugging this memory leak since 9 a.m.","reading":"/wiːv bɪn diːˈbʌɡɪŋ ðɪs ˈmɛməri liːk sɪns naɪn ˌeɪˈɛm/","id":"Kami sudah berkutat mencari kebocoran memori ini sejak jam 9 pagi (dan masih lanjut)."},{"jp":"How long have you been preparing for the TOEFL?","reading":"/haʊ lɔːŋ hæv juː bɪn prɪˈpɛrɪŋ fɔːr ðə ˈtoʊfəl/","id":"Sudah berapa lama kamu mempersiapkan diri untuk tes TOEFL?"}]'::jsonb, 'I''ve been working (/aɪv bɪn ˈwɜːrkɪŋ/) • She''s been studying', '{"analogy":"Kalau Present Perfect biasa (''have written 3 reports'') fokus memamerkan JUMLAH HASIL piala di meja, Present Perfect Continuous (''have been writing all morning'') fokus menyorot KERINGAT DAN DURASI stopwatch yang terus berdetak dari tadi sampai detik ini!","when_to_use":["Menjawab ''How long...?'' untuk aktivitas aktif yang dimulai di masa lalu dan masih berjalan sekarang","Menjelaskan sebab fisik yang jejaknya terlihat sekarang (''Sorry my eyes are red—I''ve been staring at code all night'')","Menunjukkan aktivitas rutin belakangan ini (''Lately, we''ve been testing AI agents'')"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"have / has been","label":"Jembatan Durasi"},{"role":"verb","text":"Verb + -ing","label":"Proses Berkelanjutan"},{"role":"time","text":"for 3 hours / all day","label":"Rentang Waktu"}],"steps":["Rangkai tiga komponen berurutan tanpa putus: ''have/has'' + ''been'' + ''V-ing''.","Gunakan ''for'' untuk hitungan durasi waktu (''for two months'', ''for ages'') dan ''since'' untuk patokan titik mulainya (''since Tuesday'', ''since 2024'').","Ingat dua pantangan: jangan pakai bentuk ''-ing'' ini untuk Stative Verbs (''I''ve known her for years'', BUKAN ''been knowing''), dan jangan pakai saat menyebut angka kuantitas selesai (''I''ve sent 5 emails'', BUKAN ''been sending 5 emails'')."],"breakdowns":[{"tokens":[{"jp":"She''s been","reading":"/ʃiːz bɪn/","meaning":"dia sudah sedang (she + has been)","role":"verb"},{"jp":"waiting","reading":"/ˈweɪtɪŋ/","meaning":"menunggu","role":"verb"},{"jp":"on hold","reading":"/ɑːn hoʊld/","meaning":"di antrean telepon","role":"place"},{"jp":"for twenty minutes.","reading":"/fɔːr ˈtwɛnti ˈmɪnɪts/","meaning":"selama dua puluh menit.","role":"time"}],"translation":"Dia sudah menunggu di antrean telepon selama dua puluh menit."},{"tokens":[{"jp":"It","reading":"/ɪt/","meaning":"cuaca","role":"subject"},{"jp":"has been raining","reading":"/hæz bɪn ˈreɪnɪŋ/","meaning":"terus turun hujan","role":"verb"},{"jp":"nonstop","reading":"/ˌnɑːnˈstɑːp/","meaning":"tanpa henti","role":"adjective"},{"jp":"all afternoon.","reading":"/ɔːl ˌæftərˈnuːn/","meaning":"sepanjang siang hingga sore ini.","role":"time"}],"translation":"Hujan terus turun tanpa henti sepanjang sore ini."}],"forms":[{"label":"Durasi Aktif (for)","jp":"They''ve been negotiating the merger for months.","reading":"/ðeɪv bɪn nɪˈɡoʊʃieɪtɪŋ ðə ˈmɜːrdʒər fɔːr mʌnθs/","id":"Mereka sudah menegosiasikan merger tersebut selama berbulan-bulan."},{"label":"Jejak Baru Selesai","jp":"The pavement is wet—it''s been raining.","reading":"/ðə ˈpeɪvmənt ɪz wɛt ɪts bɪn ˈreɪnɪŋ/","id":"Trotoarnya basah—habis turun hujan dari tadi."},{"label":"Bandingkan Hasil Kuantitas","jp":"I''ve read three chapters so far.","reading":"/aɪv rɛd θriː ˈtʃæptərz soʊ fɑːr/","id":"Saya sudah menyelesaikan tiga bab sejauh ini (angka hasil → tanpa -ing)."}],"mistakes":[{"wrong":"I am waiting for your reply since Monday.","right":"I have been waiting for your reply since Monday.","why":"Begitu ada rentang dari masa lalu hingga kini (''since Monday'' / ''for two hours''), jangan gunakan Present Continuous biasa (''am waiting'')—wajib ''have been waiting''!"},{"wrong":"We have been knowing each other since freshman year.","right":"We have known each other since freshman year.","why":"''Know'' adalah stative verb, sehingga durasinya cukup memakai Present Perfect Simple (''have known'')."}],"quiz":[{"question":"Pilih kalimat yang benar untuk menanyakan lama seseorang belajar Bahasa Inggris:","options":["How long are you learning English?","How long have you been learning English?","How long do you learn English?","Since when you are learning English?"],"answer":1,"why":"''How long'' untuk aktivitas dari masa lalu yang masih berlangsung sekarang wajib memakai ''have you been + V-ing''."},{"question":"Kapan kita WAJIB memilih ''have written'' daripada ''have been writing''?","options":["Saat ada kata ''all morning''","Saat menyebutkan jumlah hasil yang tuntas, misalnya ''three articles today''","Saat subjeknya jamak","Saat kalimatnya berbentuk tanya"],"answer":1,"why":"Menyebutkan kuantitas hasil selesai (''three articles'', ''five cups of coffee'') memakai Present Perfect Simple (''have written'')."},{"question":"Lengkapi kalimat berikut: ''Dr. Patel ___ clinical trials on this vaccine ___ 2022.''","options":["is conducting / since","has been conducting / since","has been conducting / for","conducted / since"],"answer":1,"why":"Tahun spesifik ''2022'' adalah titik awal waktu (''since''), dan proses riset berkelanjutan hingga kini memakai ''has been conducting''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000023', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-003', 'conjugation', 'First & Second Conditionals: Realistis vs Imajiner (If + Present / Past)', 'Type 1: If + Present Simple, will + V1 (Mungkin) • Type 2: If + Past Simple (were), would + V1 (Khayalan kini)', 'Membedakan skenario masa depan yang realistis terjadi (Type 1) dari pengandaian imajiner yang berlawanan dengan fakta saat ini (Type 2).', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"If we lower latency, conversion rates will increase.","reading":"/ɪf wiː ˈloʊər ˈleɪtənsi kənˈvɜːrʒən reɪts wɪl ɪnˈkriːs/","id":"Jika kita menurunkan latensi, tingkat konversi akan meningkat (prediksi realistis)."},{"jp":"If I were in your shoes, I would accept the fellowship offer.","reading":"/ɪf aɪ wɜːr ɪn jʊr ʃuːz aɪ wʊd ækˈsɛpt ðə ˈfɛloʊʃɪp ˈɔːfər/","id":"Andaikan saya di posisi Anda, saya akan menerima tawaran beasiswa riset tersebut."}]'::jsonb, 'If we launch, users will love it • If I were (/wɜːr/) you, I''d negotiate', '{"analogy":"Perhatikan trik psikologis Bahasa Inggris: di Second Conditional (''If I had a million dollars...''), kata kerja lampau V2 (''had / were'') SAMA SEKALI BUKAN menceritakan masa lalu! Ia dipinjam untuk ''mundur satu langkah dari kenyataan hari ini'' (kenyataannya sekarang belum punya sejuta dolar!). Sedangkan First Conditional berpijak di tanah nyata: peluangnya terbuka lebar di masa depan.","when_to_use":["First Conditional (If + Present, will/can/may + V1): negosiasi bisnis, peringatan proyek, dan rencana kontingensi yang sangat mungkin terjadi","Second Conditional (If + V2/were, would/could + V1): membayangkan situasi hipotesis saat ini atau memberi nasihat elegan (''If I were you...'')","Menggunakan ''unless'' sebagai pengganti ringkas untuk ''if ... not'' (''kecuali jika'')"],"formula_parts":[{"role":"connector","text":"If / Unless","label":"Syarat Pengandaian"},{"role":"verb","text":"Present (T1) | Past/were (T2)","label":"Nyata vs Khayalan Kini"},{"role":"predicate","text":"will + V1 (T1) | would + V1 (T2)","label":"Konsekuensi Utama"}],"steps":["Ukur seberapa realistis syaratnya: jika nyata dan mungkin terjadi nanti → Type 1 (Present Simple + will V1).","Jika berlawanan dengan realita hari ini atau murni berandai-andai → Type 2 (Past Simple + would V1).","Aturan emas TOEFL & penulisan formal: dalam Second Conditional, SEMUA subjek (termasuk I, he, she, it) memakai subjunctive ''were'' (''If she were here...''), bukan ''was''!"],"breakdowns":[{"tokens":[{"jp":"Unless","reading":"/ənˈlɛs/","meaning":"kecuali jika (= if not)","role":"connector"},{"jp":"we leave","reading":"/wiː liːv/","meaning":"kita berangkat (Present Simple)","role":"verb"},{"jp":"now,","reading":"/naʊ/","meaning":"sekarang,","role":"time"},{"jp":"we''ll miss","reading":"/wiːl mɪs/","meaning":"kita akan ketinggalan","role":"predicate"},{"jp":"the train.","reading":"/ðə treɪn/","meaning":"keretanya.","role":"object"}],"translation":"Kecuali jika kita berangkat sekarang, kita akan ketinggalan kereta."},{"tokens":[{"jp":"If","reading":"/ɪf/","meaning":"seandainya (imajiner kini)","role":"connector"},{"jp":"our startup had","reading":"/ˈaʊər ˈstɑːrtʌp hæd/","meaning":"startup kita punya (V2 hipotesis)","role":"verb"},{"jp":"more funding,","reading":"/mɔːr ˈfʌndɪŋ/","meaning":"lebih banyak pendanaan,","role":"object"},{"jp":"we could expand","reading":"/wiː kʊd ɪkˈspænd/","meaning":"kita bisa berekspansi","role":"predicate"},{"jp":"across Asia.","reading":"/əˈkrɔːs ˈeɪʒə/","meaning":"ke seluruh Asia.","role":"place"}],"translation":"Seandainya perusahaan rintisan kita memiliki lebih banyak dana, kita bisa berekspansi ke seluruh Asia."}],"forms":[{"label":"Type 1 (Realistis)","jp":"If the client approves the mockup, we''ll start coding Monday.","reading":"/ɪf ðə ˈklaɪənt əˈpruːvz ðə ˈmɑːkʌp wiːl stɑːrt ˈkoʊdɪŋ ˈmʌndeɪ/","id":"Jika klien menyetujui purwarupa desainnya, kami mulai memprogram hari Senin."},{"label":"Type 2 (Subjunctive were)","jp":"If he were more detail-oriented, he wouldn''t make typos.","reading":"/ɪf hiː wɜːr mɔːr dɪˈteɪl ˈɔːriɛntɪd hiː ˈwʊdənt meɪk ˈtaɪpoʊz/","id":"Andaikan dia lebih teliti, dia tidak akan membuat salah ketik (faktanya ia kurang teliti)."},{"label":"Unless (= If not)","jp":"The system won''t save changes unless you click Submit.","reading":"/ðə ˈsɪstəm woʊnt seɪv ˈtʃeɪndʒɪz ənˈlɛs juː klɪk səbˈmɪt/","id":"Sistem tidak akan menyimpan perubahan kecuali Anda mengeklik Kirim."}],"mistakes":[{"wrong":"If I would have more free time, I would learn Mandarin.","right":"If I had more free time, I would learn Mandarin.","why":"Jangan menaruh ''would'' atau ''will'' di dalam klausa ''If'' standar; gunakan V2 (''had'') di klausa ''If'', dan simpan ''would'' di induk kalimat!"},{"wrong":"Unless you don''t hurry, you''ll be late.","right":"Unless you hurry, you''ll be late.","why":"''Unless'' sudah mengandung makna negatif (''jika tidak''), jadi jangan ditambah ''don''t'' lagi (double negative)."}],"quiz":[{"question":"Pilih bentuk standar TOEFL Structure untuk Second Conditional: ''If the campus ___ closer to downtown, more students would commute by bike.''","options":["is","was","were","would be"],"answer":2,"why":"Dalam Bahasa Inggris formal/akademik, klausa pengandaian tak nyata masa kini memakai ''were'' untuk semua subjek tunggal maupun jamak."},{"question":"Apa fakta sebenarnya di balik kalimat ''If I knew her email address, I would forward the invite''?","options":["Dulu saya tahu emailnya, sekarang lupa","Sekarang saya TIDAK tahu alamat emailnya, jadi saya tidak bisa meneruskan undangannya","Saya pasti akan mengirim undangannya sebentar lagi","Dia tidak punya akun email"],"answer":1,"why":"Second Conditional menyatakan kebalikan dari fakta SAAT INI (''knew'' hipotesis = faktanya sekarang ''I don''t know'')."},{"question":"Lengkapi negosiasi realistis berikut: ''If you ___ an annual plan today, we ___ a 20% discount.''","options":["choose / will include","will choose / include","chose / will include","choose / would included"],"answer":0,"why":"Tawaran bisnis nyata yang terbuka saat ini menggunakan First Conditional: If + Present Simple (''choose''), will + V1 (''will include'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000024', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-004', 'conjugation', 'Passive Voice: Kalimat Pasif Proses & Laporan (be + V3)', '[Object jadi Subject] + am/is/are/was/were/has been/will be + V3 (+ by Agent)', 'Menggeser sorotan kalimat dari ''siapa pelakunya'' ke ''apa objek atau proses yang dikenai tindakan'' secara objektif.', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"All user passwords are encrypted before storage.","reading":"/ɔːl ˈjuːzər ˈpæswɜːrdz ɑːr ɪnˈkrɪptɪd bɪˈfɔːr ˈstɔːrɪdʒ/","id":"Semua kata sandi pengguna dienkripsi sebelum disimpan."},{"jp":"The scholarship winners will be announced next Monday.","reading":"/ðə ˈskɑːlərʃɪp ˈwɪnərz wɪl biː əˈnaʊnst nɛkst ˈmʌndeɪ/","id":"Para pemenang beasiswa akan diumumkan Senin depan."}]'::jsonb, 'is encrypted (/ɪz ɪnˈkrɪptɪd/) • was founded in • has been approved', '{"analogy":"Dalam Bahasa Indonesia kita tinggal mengganti awalan ''me-'' menjadi ''di-'' (''mengirim → dikirim''). Dalam Bahasa Inggris tidak ada awalan ''di-''; sebagai gantinya kita merakit mesin pasif dua roda: ''Be Verb'' (yang berubah menyesuaikan tenses: is, was, has been, will be, can be) + ''V3 (Past Participle)'' yang selalu tetap!","when_to_use":["Menulis laporan ilmiah, metode riset TOEFL, atau dokumentasi teknis di mana proses lebih penting daripada pelaku (''Samples were heated to 80°C'')","Ketika pelaku tindakan tidak diketahui, sudah jelas otomatis, atau merupakan sistem umum","Menjaga nada diplomatis di kantor agar tidak terkesan menyalahkan individu (''A mistake was made in the invoice'')"],"formula_parts":[{"role":"subject","text":"Receiver (Target)","label":"Penerima Tindakan"},{"role":"verb","text":"be (sesuai tense)","label":"is / was / has been / will be"},{"role":"verb","text":"V3 (Past Participle)","label":"Makna ''di- / ter-''"},{"role":"particle","text":"(by + Agent)","label":"Opsional jika Penting"}],"steps":["Pindahkan objek penerima aksi ke depan sebagai subjek, lalu sesuaikan hanya bagian ''BE''-nya mengikuti waktu (Present: is/are, Past: was/were, Present Perfect: has/have been, Continuous: is/are being, Modal: can/will/must be).","Kunci kata kerja utamanya selalu dalam bentuk V3 (Past Participle).","Peringatan kritis TOEFL: kata kerja INTRANSITIF (yang tidak punya objek seperti ''happen, occur, arrive, rise, consist, appear'') TIDAK BISA dipasifkan (''was happened'' ❌)!"],"breakdowns":[{"tokens":[{"jp":"The pull request","reading":"/ðə pʊl rɪˈkwɛst/","meaning":"permintaan penggabungan kode itu","role":"subject"},{"jp":"has been","reading":"/hæz bɪn/","meaning":"sudah (Present Perfect Be)","role":"verb"},{"jp":"reviewed","reading":"/rɪˈvjuːd/","meaning":"ditinjau (V3)","role":"verb"},{"jp":"by two senior engineers.","reading":"/baɪ tuː ˈsiːnjər ˌɛndʒɪˈnɪrz/","meaning":"oleh dua insinyur senior.","role":"particle"}],"translation":"Pull request tersebut sudah ditinjau oleh dua insinyur senior."},{"tokens":[{"jp":"Our headquarters","reading":"/ˈaʊər ˈhɛdkwɔːrtərz/","meaning":"kantor pusat kami","role":"subject"},{"jp":"is being","reading":"/ɪz ˈbiːɪŋ/","meaning":"sedang (Present Continuous Be)","role":"verb"},{"jp":"renovated","reading":"/ˈrɛnəveɪtɪd/","meaning":"direnovasi (V3)","role":"verb"},{"jp":"this month.","reading":"/ðɪs mʌnθ/","meaning":"bulan ini.","role":"time"}],"translation":"Kantor pusat kami sedang direnovasi bulan ini."}],"forms":[{"label":"Past Passive","jp":"The company was founded in Palo Alto in 2018.","reading":"/ðə ˈkʌmpəni wəz ˈfaʊndɪd ɪn ˈpæloʊ ˈæltoʊ/","id":"Perusahaan tersebut didirikan di Palo Alto pada tahun 2018."},{"label":"Continuous Passive","jp":"Your request is currently being processed.","reading":"/jʊr rɪˈkwɛst ɪz ˈkɜːrəntli ˈbiːɪŋ ˈprɑːsɛst/","id":"Permintaan Anda saat ini sedang diproses."},{"label":"Modal Passive","jp":"Applications must be submitted before midnight.","reading":"/ˌæplɪˈkeɪʃənz mʌst biː səbˈmɪtɪd bɪˈfɔːr ˈmɪdnaɪt/","id":"Berkas lamaran wajib diserahkan sebelum tengah malam."}],"mistakes":[{"wrong":"A sudden power outage was occurred last night.","right":"A sudden power outage occurred last night.","why":"''Occur'' dan ''happen'' adalah kata kerja intransitif (bermakna ''terjadi'', bukan ''menterjadikan''), sehingga pantang dibuat pasif!"},{"wrong":"The bug has fixed by the backend team.","right":"The bug has been fixed by the backend team.","why":"Tanpa ''been'', ''has fixed'' berarti aktif (''kutu itu telah memperbaiki''). Untuk pasif Present Perfect wajib ''has been + V3''."}],"quiz":[{"question":"Pilih kalimat yang benar untuk laporan insiden teknis:","options":["An unexpected error was happened during deployment.","An unexpected error occurred during deployment.","An unexpected error was occured during deployment.","An unexpected error has been happened."],"answer":1,"why":"''Occur'' dan ''happen'' tidak pernah berbentuk pasif; gunakan bentuk aktif Past Simple ''occurred''."},{"question":"Ubahlah ke bentuk pasif sedang berlangsung: ''Technicians are upgrading the main server right now.''","options":["The main server is upgraded right now.","The main server is being upgraded right now.","The main server has been upgrading right now.","The main server are being upgraded right now."],"answer":1,"why":"Present Continuous Passive untuk subjek tunggal ''The main server'' adalah ''is + being + V3 (upgraded)''."},{"question":"Perhatikan beda ''found'' vs ''founded'': ''The research institute ___ in 1995.''","options":["was found","was founded","founded","is finding"],"answer":1,"why":"Kata kerja dasar ''found'' (= mendirikan) memiliki V3 ''founded'' (''was founded'' = didirikan), berbeda dari ''find → found'' (= ditemukan)."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000025', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-005', 'sentence_pattern', 'Defining Relative Clauses: Klausa Penjelas (who / which / that / where)', '[Noun] + who (orang) / which atau that (benda) / whose (milik) / where (tempat) + [Clause]', 'Merangkai dua kalimat menjadi satu kalimat tajam dengan klausa ''yang...'' untuk mengidentifikasi kata benda secara spesifik.', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"We''re looking for a designer who understands accessibility.","reading":"/wɪr ˈlʊkɪŋ fɔːr ə dɪˈzaɪnər huː ˌʌndərˈstændz ækˌsɛsəˈbɪləti/","id":"Kami mencari desainer yang memahami aksesibilitas."},{"jp":"The dataset that we analyzed yesterday had missing values.","reading":"/ðə ˈdeɪtəsɛt ðæt wiː ˈænəlaɪzd ˈjɛstərdeɪ hæd ˈmɪsɪŋ ˈvæljuːz/","id":"Kumpulan data yang kami analisis kemarin memiliki nilai yang hilang."}]'::jsonb, 'the engineer who built... • the tool (that) we use • the lab where...', '{"analogy":"Dalam Bahasa Indonesia, satu kata ''YANG'' memborong semua tugas (''orang yang...'', ''buku yang...'', ''kota tempat yang...''). Dalam Bahasa Inggris, kata ''yang'' punya spesialis masing-masing: ''who'' khusus manusia, ''which/that'' untuk benda/konsep (di AS, ''that'' jauh lebih favorit untuk klausa tanpa koma!), ''whose'' untuk kepemilikan (''yang ...-nya''), dan ''where'' untuk lokasi aktivitas!","when_to_use":["Mendefinisikan persis orang atau benda mana yang dimaksud tanpa tanda koma","Menghilangkan kata penghubung (''that/who/which'') secara elegan ketika diikuti Subjek + Verb baru (''the email [that] you sent'')","Menghubungkan kepemilikan baik untuk orang maupun perusahaan dengan ''whose'' (''a startup whose product went viral'')"],"formula_parts":[{"role":"noun","text":"Head Noun","label":"Orang / Benda / Tempat"},{"role":"connector","text":"who / that / whose / where","label":"Kata Penghubung ''Yang''"},{"role":"predicate","text":"Modifying Clause","label":"Tanpa Mengulang Pronoun!"}],"steps":["Cocokkan dengan kata benda di depannya: manusia → ''who/that'', benda/ide → ''that/which'', kepemilikan → ''whose + noun'', lokasi tempat kejadian → ''where'' (+ S + V).","Cek kata kerja di dalam relative clause: harus sesuai jumlah (tunggal/jamak) dengan kata benda yang dijelaskannya (''engineers who WORK'' vs ''an engineer who WORKS'').","Pantangan mutlak: JANGAN mengulang kata ganti objek (''it/him/there'') yang sudah digantikan oleh who/that/where!"],"breakdowns":[{"tokens":[{"jp":"Candidates","reading":"/ˈkændɪdɪts/","meaning":"para kandidat","role":"subject"},{"jp":"whose applications","reading":"/huːz ˌæplɪˈkeɪʃənz/","meaning":"yang berkas lamarannya","role":"connector"},{"jp":"pass screening","reading":"/pæs ˈskriːnɪŋ/","meaning":"lolos seleksi awal","role":"verb"},{"jp":"will receive","reading":"/wɪl rɪˈsiːv/","meaning":"akan menerima (predikat utama)","role":"predicate"},{"jp":"a coding test.","reading":"/ə ˈkoʊdɪŋ tɛst/","meaning":"tes pemrograman.","role":"object"}],"translation":"Para kandidat yang berkas lamarannya lolos seleksi awal akan menerima tes pemrograman."},{"tokens":[{"jp":"That''s","reading":"/ðæts/","meaning":"itulah","role":"verb"},{"jp":"the coworking space","reading":"/ðə ˈkoʊwɜːrkɪŋ speɪs/","meaning":"ruang kerja bersama","role":"noun"},{"jp":"where","reading":"/wɛr/","meaning":"tempat di mana (+ S + V)","role":"connector"},{"jp":"our founders met.","reading":"/ˈaʊər ˈfaʊndərz mɛt/","meaning":"para pendiri kami bertemu.","role":"predicate"}],"translation":"Itulah ruang kerja bersama tempat para pendiri kami bertemu."}],"forms":[{"label":"Subjek (Wajib Ada who/that)","jp":"Anyone who needs visa sponsorship can apply.","reading":"/ˈɛniwʌn huː niːdz ˈviːzə ˈspɑːnsərʃɪp kən əˈplaɪ/","id":"Siapa pun yang membutuhkan sponsor visa dapat melamar."},{"label":"Objek (Boleh Dihilangkan)","jp":"The feedback (that) she gave us was spot-on.","reading":"/ðə ˈfiːdbæk ʃiː ɡeɪv ʌs wəz ˈspɑːtˈɑːn/","id":"Masukan yang dia berikan kepada kami sangat tepat sasaran."},{"label":"Where vs Which untuk Tempat","jp":"Boston is a city that attracts top researchers.","reading":"/ˈbɔːstən ɪz ə ˈsɪti ðæt əˈtrækts tɑːp ˈriːsɜːrtʃərz/","id":"Boston adalah kota yang menarik peneliti papan atas (langsung diikuti Verb → pakai that/which, bukan where!)."}],"mistakes":[{"wrong":"This is the laptop that I bought it last week.","right":"This is the laptop that I bought last week.","why":"Kata ''that'' sudah menggantikan ''the laptop''; menambahkan ''it'' lagi menghasilkan pengulangan objek ganda yang salah di TOEFL."},{"wrong":"Jakarta is a city where has many skyscrapers.","right":"Jakarta is a city that has many skyscrapers.","why":"''Where'' hanya dipakai jika diikuti Subjek + Verb lokasi (''where I live''); jika langsung diikuti kata kerja (''has''), wajib pakai ''that'' atau ''which''!"}],"quiz":[{"question":"Pilih kata penghubung yang tepat: ''We partnered with a logistics firm ___ warehouse network covers Java and Sumatra.''","options":["who","which","whose","where"],"answer":2,"why":"''Whose'' menyatakan kepemilikan (''yang jaringan gudangnya...'') dan boleh dipakai untuk perusahaan/benda maupun manusia!"},{"question":"Dalam kalimat manakah kata ''that'' BOLEH dihilangkan tanpa mengubah kebenaran grammar?","options":["The server that crashed last night is back online.","The article that you shared on Slack was eye-opening.","Students that miss three labs fail the course.","Everything that happens is logged."],"answer":1,"why":"Relative pronoun boleh dihilangkan HANYA saat berfungsi sebagai objek (diikuti Subjek + Verb baru: ''you shared'')."},{"question":"Perhatikan kesesuaian subjek-kata kerja: ''One of the engineers who ___ on this module ___ on vacation.''","options":["works / are","work / is","work / are","working / is"],"answer":1,"why":"''Who'' merujuk ke jamak ''engineers'' → ''work'', sedangkan subjek induk kalimat adalah tunggal ''One'' → ''is''!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000026', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-006', 'conjugation', 'Past Habits vs Adaptation: Dulu vs Terbiasa (used to vs be/get used to)', 'used to + V1 (Dulu pernah/biasa) vs be / get used to + Noun / V-ing (Sudah/Mulai terbiasa)', 'Membedakan kebiasaan masa lalu yang sudah berhenti (''used to + V1'') dari adaptasi terhadap hal baru (''be/get used to + V-ing'').', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"I used to commute two hours a day, but now I work remotely.","reading":"/aɪ ˈjuːst tə kəˈmjuːt tuː ˈaʊərz ə deɪ bʌt naʊ aɪ wɜːrk rɪˈmoʊtli/","id":"Dulu saya biasa menempuh perjalanan dua jam sehari, tetapi sekarang saya bekerja jarak jauh."},{"jp":"It took me a month to get used to speaking English all day.","reading":"/ɪt tʊk miː ə mʌnθ tə ɡɛt ˈjuːst tə ˈspiːkɪŋ ˈɪŋɡlɪʃ ɔːl deɪ/","id":"Butuh sebulan bagi saya untuk mulai terbiasa berbicara Bahasa Inggris seharian."}]'::jsonb, 'used to (/ˈjuːst tə/) + V1 vs I''m used to (/ˈjuːst tuː/) + V-ing', '{"analogy":"Tiga pola kembar ini adalah jebakan klasik lintas level! Rahasianya: ''used to + V1'' tanpa be/get artinya ''DULU biasa/pernah (sekarang sudah tidak lagi)''. Tapi begitu ada kata ''am/is/are'' atau ''get'' di depannya (''be/get used to''), kata ''used'' berubah fungsi menjadi kata sifat yang artinya ''TERBIASA DENGAN'', sehingga kata ''to''-nya adalah preposisi yang WAJIB diikuti Kata Benda atau V-ing!","when_to_use":["Pakai ''used to + V1'' untuk kebiasaan atau keadaan masa lalu yang kontras dengan sekarang (''There used to be a cinema here'')","Pakai ''be used to + Noun / V-ing'' saat sesuatu sudah tidak terasa asing atau berat lagi (''sudah terbiasa'')","Pakai ''get used to + Noun / V-ing'' untuk proses penyesuaian diri menghadapi lingkungan baru (''mulai membiasakan diri'')"],"formula_parts":[{"role":"verb","text":"used to + V1","label":"Dulu Biasa (Kini Berhenti)"},{"role":"adjective","text":"be used to + V-ing/N","label":"Sudah Terbiasa"},{"role":"verb","text":"get used to + V-ing/N","label":"Proses Beradaptasi"}],"steps":["Cek ada tidaknya ''be'' (am/is/are/was) atau ''get'' sebelum ''used to'': jika TIDAK ADA → wajib diikuti V1 murni (''used to live'').","Jika ADA ''be'' atau ''get'' → ''to'' adalah preposisi, jadi WAJIB diikuti kata benda atau Gerund V-ing (''am used to living'', ''got used to the cold weather'')!","Perhatikan ejaan negatif & tanya untuk masa lalu: karena memakai ''did/didn''t'', huruf ''-d'' luluh menjadi ''didn''t use to + V1'' dan ''Did you use to + V1?''."],"breakdowns":[{"tokens":[{"jp":"She","reading":"/ʃiː/","meaning":"dia","role":"subject"},{"jp":"used to be","reading":"/ˈjuːst tə biː/","meaning":"dulunya adalah (kini bukan lagi)","role":"verb"},{"jp":"shy","reading":"/ʃaɪ/","meaning":"pemalu","role":"adjective"},{"jp":"about public speaking.","reading":"/əˈbaʊt ˈpʌblɪk ˈspiːkɪŋ/","meaning":"soal berbicara di depan umum.","role":"noun"}],"translation":"Dulunya dia pemalu soal berbicara di depan umum."},{"tokens":[{"jp":"Now","reading":"/naʊ/","meaning":"sekarang","role":"time"},{"jp":"she''s used to","reading":"/ʃiːz ˈjuːst tə/","meaning":"dia sudah terbiasa dengan","role":"adjective"},{"jp":"pitching","reading":"/ˈpɪtʃɪŋ/","meaning":"mempresentasikan ide (wajib V-ing!)","role":"object"},{"jp":"to investors.","reading":"/tu ɪnˈvɛstərz/","meaning":"kepada para investor.","role":"noun"}],"translation":"Sekarang dia sudah terbiasa mempresentasikan ide kepada para investor."}],"forms":[{"label":"Kebiasaan Dulu (+ V1)","jp":"We didn''t use to have automated CI/CD pipelines.","reading":"/wiː ˈdɪdənt ˈjuːs tə hæv ˈɔːtəmeɪtɪd ˈpaɪplaɪnz/","id":"Dulu kami belum punya jalur CI/CD otomatis."},{"label":"Sudah Terbiasa (+ V-ing)","jp":"I''m used to waking up at 5 a.m.","reading":"/aɪm ˈjuːst tə ˈweɪkɪŋ ʌp æt faɪv ˌeɪˈɛm/","id":"Saya sudah terbiasa bangun pukul 5 pagi."},{"label":"Adaptasi (+ Noun)","jp":"Are you getting used to the winter in Chicago?","reading":"/ɑːr juː ˈɡɛtɪŋ ˈjuːst tə ðə ˈwɪntər ɪn ʃɪˈkɑːɡoʊ/","id":"Apakah kamu mulai terbiasa dengan musim dingin di Chicago?"}],"mistakes":[{"wrong":"I usually wake up early, so I''m used to wake up at 5.","right":"I usually wake up early, so I''m used to waking up at 5.","why":"Setelah ''am/is/are used to'', kata ''to'' adalah preposisi yang wajib diikuti V-ing (''waking up''), bukan V1! Untuk kebiasaan rutin masa kini tanpa makna adaptasi, gunakan kata keterangan ''usually''."},{"wrong":"I use to play badminton every weekend now.","right":"I usually play badminton every weekend.","why":"''Used to + V1'' HANYA untuk masa lalu! Tidak ada bentuk masa kini ''I use to'' untuk arti ''biasanya sekarang''—gunakan ''usually''."}],"quiz":[{"question":"Pilih bentuk yang tepat untuk soal standar TOEFL: ''International students quickly get used to ___ academic papers in English.''","options":["write","wrote","writing","written"],"answer":2,"why":"Pola ''get used to'' wajib diikuti kata benda atau Gerund V-ing (''writing'')."},{"question":"Lengkapi kalimat kontras masa lalu vs masa kini: ''This neighborhood ___ quiet, but now it''s full of tech offices.''","options":["is used to being","used to be","gets used to be","use to be"],"answer":1,"why":"Kondisi masa lalu yang sekarang sudah berubah total dinyatakan dengan ''used to + V1 (be)''."},{"question":"Bagaimana cara alami mengatakan ''Saya biasanya minum teh setiap pagi'' (kebiasaan rutin sekarang)?","options":["I use to drink tea every morning.","I usually drink tea every morning.","I used to drink tea every morning.","I am use to drink tea every morning."],"answer":1,"why":"Rutinitas masa kini memakai Present Simple dengan adverbia ''usually'', bukan ''use to''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000027', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-007', 'conjugation', 'Modals of Deduction: Menyimpulkan Bukti Kini (must / might / can''t)', '[Subject] + must (95% yakin ya) / might, could (50% mungkin) / can''t (95% mustahil) + V1 / be V-ing', 'Menarik kesimpulan logis tentang situasi saat ini berdasarkan petunjuk nyata, dari hampir pasti benar hingga mustahil.', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"You''ve been traveling for 18 hours—you must be exhausted!","reading":"/juːv bɪn ˈtrævəlɪŋ fɔːr ˌeɪˈtiːn ˈaʊərz juː mʌst biː ɪɡˈzɔːstɪd/","id":"Anda sudah menempuh perjalanan 18 jam—Anda pasti sangat kelelahan!"},{"jp":"That can''t be Sarah at the door; she''s in Tokyo this week.","reading":"/ðæt kænt biː ˈsærə æt ðə dɔːr ʃiːz ɪn ˈtoʊkioʊ ðɪs wiːk/","id":"Tidak mungkin itu Sarah di depan pintu; dia sedang di Tokyo minggu ini."}]'::jsonb, 'She must be busy • It might rain • That can''t be true (/kænt biː truː/)', '{"analogy":"Jadilah detektif Sherlock Holmes! Di sini ''must'' bukan lagi soal aturan ''wajib'', melainkan kesimpulan logis ''PASTI begitu!'' karena buktinya kuat. Kejutan terbesarnya ada di lawan katanya: kebalikan deduksi ''She must be rich'' (Dia pasti kaya) BUKAN ''She mustn''t be rich'', melainkan ''She CAN''T be rich'' (Tidak mungkin dia kaya)!","when_to_use":["Pakai ''must + be / V1'' saat bukti menunjukkan kesimpulan 95% pasti benar (juga untuk empati sosial: ''That must be exciting!'')","Pakai ''might / may / could + be / V1'' saat menebak kemungkinan 40–50% (''bisa jadi / mungkin saja'')","Pakai ''can''t / couldn''t + be / V1'' saat bukti membuktikan sesuatu 95% mustahil terjadi saat ini"],"formula_parts":[{"role":"subject","text":"Subject","label":"Topik yang Ditebak"},{"role":"verb","text":"must | might/could | can''t","label":"Pasti | Mungkin | Mustahil"},{"role":"predicate","text":"be + Adj/Noun / be V-ing","label":"Kondisi Saat Ini"}],"steps":["Nilai kekuatan buktinya dulu: yakin positif → ''must'', ragu-ragu → ''might/may/could'' (negatif ragu: ''might not / may not'', JANGAN ''couldn''t''!), yakin mustahil → ''can''t''.","Jika menyimpulkan aksi yang SEDANG berlangsung detik ini, pasangkan modal + ''be + V-ing'' (''He isn''t answering; he must be driving'').","Bedakan tajam ''might not'' (= mungkin tidak) vs ''can''t / couldn''t'' (= sama sekali tidak mungkin / mustahil)!"],"breakdowns":[{"tokens":[{"jp":"His Slack status","reading":"/hɪz slæk ˈstætəs/","meaning":"status Slack-nya","role":"subject"},{"jp":"is offline—","reading":"/ɪz ˈɔːflaɪn/","meaning":"sedang luring—","role":"predicate"},{"jp":"he might be having","reading":"/hiː maɪt biː ˈhævɪŋ/","meaning":"dia mungkin sedang makan","role":"verb"},{"jp":"lunch.","reading":"/lʌntʃ/","meaning":"siang.","role":"object"}],"translation":"Status Slack-nya sedang luring—dia mungkin sedang makan siang."},{"tokens":[{"jp":"This invoice","reading":"/ðɪs ˈɪnvɔɪs/","meaning":"tagihan ini","role":"subject"},{"jp":"can''t be","reading":"/kænt biː/","meaning":"tidak mungkin (deduksi negatif)","role":"verb"},{"jp":"accurate;","reading":"/ˈækjərət/","meaning":"akurat;","role":"adjective"},{"jp":"it charges us twice.","reading":"/ɪt ˈtʃɑːrdʒɪz ʌs twaɪs/","meaning":"ini menagih kita dua kali.","role":"predicate"}],"translation":"Tagihan ini tidak mungkin akurat; tagihannya tertulis dua kali lipat."}],"forms":[{"label":"Yakin Positif (must)","jp":"Winning that grant must feel incredible!","reading":"/ˈwɪnɪŋ ðæt ɡrænt mʌst fiːl ɪnˈkrɛdəbəl/","id":"Memenangkan hibah itu pasti rasanya luar biasa!"},{"label":"Kemungkinan 50% (might/could)","jp":"The server slowdown could be a DNS issue.","reading":"/ðə ˈsɜːrvər ˈsloʊdaʊn kʊd biː ə ˌdiːɛnˈɛs ˈɪʃuː/","id":"Melambatnya server ini bisa jadi karena masalah DNS."},{"label":"Yakin Mustahil (can''t)","jp":"You just had a huge burger—you can''t be hungry already!","reading":"/juː dʒʌst hæd ə hjuːdʒ ˈbɜːrɡər juː kænt biː ˈhʌŋɡri ɔːlˈrɛdi/","id":"Kamu baru saja makan burger besar—tidak mungkin kamu sudah lapar lagi!"}],"mistakes":[{"wrong":"The office lights are completely off. Everyone mustn''t be inside.","right":"The office lights are completely off. Nobody can be inside. / Everyone must have gone home.","why":"Untuk menyimpulkan ketidakmungkinan logis (''tidak mungkin berada di dalam''), gunakan ''can''t be'', bukan ''mustn''t be'' (yang cenderung berarti larangan)."},{"wrong":"Take a jacket—it could not be warm tonight (maksud: mungkin tidak hangat).","right":"Take a jacket—it might not be warm tonight.","why":"''Couldn''t be warm'' berarti ''100% mustahil hangat''! Untuk arti ''mungkin tidak hangat'', gunakan ''might not / may not''."}],"quiz":[{"question":"Pilih modal deduksi yang logis: ''Her car isn''t in the parking lot, and her desk is empty. She ___ working from home today.''","options":["can''t be","must be","must to be","shouldn''t"],"answer":1,"why":"Bukti kuat (mobil tidak ada, meja kosong) mengarah pada kesimpulan logis positif yang sedang berlangsung: ''must be working''."},{"question":"Rekan kerja berkata ''Look, this flight from Jakarta to New York takes only two hours!'' Respons logis yang tepat adalah:","options":["That mustn''t be right—check the time zones!","That can''t be right—check the time zones!","That might be right!","That doesn''t have to be right!"],"answer":1,"why":"Menyatakan suatu klaim ''mustahil benar'' secara logis menggunakan ''That can''t be right!''."},{"question":"Manakah kalimat yang menyatakan kemungkinan 50% bahwa rapat ditunda?","options":["The meeting might be postponed due to the storm.","The meeting can''t be postponed due to the storm.","The meeting must postponed due to the storm.","The meeting maybe be postponed."],"answer":0,"why":"''Might be postponed'' (modal + pasif) menyatakan kemungkinan yang belum pasti; perhatikan juga kata ''maybe'' adalah adverbia, bukan modal verb!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000028', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-008', 'sentence_pattern', 'Reported Speech: Kalimat Tak Langsung Kerja (said / told + Backshift)', 'said (that) + Clause • told + [Object] + (that) + Backshifted Verb • asked + if/Wh- + S + V', 'Menyampaikan ulang ucapan, pembaruan rapat, atau instruksi seseorang dengan pergeseran waktu dan urutan kalimat pernyataan.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"The client told us that they needed an extra week.","reading":"/ðə ˈklaɪənt toʊld ʌs ðæt ðeɪ ˈniːdɪd ən ˈɛkstrə wiːk/","id":"Klien memberi tahu kami bahwa mereka membutuhkan tambahan waktu satu minggu."},{"jp":"HR asked me whether I could start in June.","reading":"/ˌeɪtʃˈɑːr æskt miː ˈwɛðər aɪ kʊd stɑːrt ɪn dʒuːn/","id":"Pihak HR bertanya kepada saya apakah saya bisa mulai bekerja bulan Juni."}]'::jsonb, '''I''m ready'' → She said she was ready • told me to + V1', '{"analogy":"Ketika meneruskan ucapan orang kemarin, sudut pandang kamera otomatis mundur satu langkah ke masa lalu (Backshift): ''am/is → was'', ''have → had'', ''will → would'', ''can → could''. Dan ingat aturan kembar ''say vs tell'': ''say'' langsung bicara ke udara (''She said that...''), sedangkan ''tell'' WAJIB menyebut siapa pendengarnya dulu (''She told ME that...'')!","when_to_use":["Merangkum hasil percakapan dengan klien atau atasan kepada anggota tim","Melaporkan pertanyaan seseorang (''asked if/whether...'' atau ''asked where...'') dengan urutan Subjek + Verb normal tanpa tanda tanya","Melaporkan permintaan atau instruksi menggunakan ''told / asked + Object + (not) to + V1''"],"formula_parts":[{"role":"verb","text":"said (that) / told + Obj","label":"Verba Pelapor"},{"role":"subject","text":"Adjusted Pronoun","label":"Penyesuaian Kata Ganti"},{"role":"verb","text":"Backshifted Verb","label":"Mundur 1 Tense (was/would/had)"}],"steps":["Pilih kata kerja pelapor yang tepat: ''said (that)...'' TANPA objek orang langsung, atau ''told + seseorang (that)...'' DENGAN objek orang wajib.","Geser tenses mundur satu tingkat jika kata kerja pelapornya lampau (''said/told/asked''): Present → Past, Past/Present Perfect → Past Perfect (''had + V3''), ''will → would'', ''can → could'' (plus ''tomorrow → the next day'').","Saat melaporkan pertanyaan (''He asked where the file WAS''), kembalikan urutan ke Subjek + Verb dan hilangkan ''do/does/did''!"],"breakdowns":[{"tokens":[{"jp":"Maya said","reading":"/ˈmaɪə sɛd/","meaning":"Maya berkata (tanpa objek orang)","role":"verb"},{"jp":"she had already fixed","reading":"/ʃiː hæd ɔːlˈrɛdi fɪkst/","meaning":"bahwa dia sudah memperbaiki (mundur ke had + V3)","role":"predicate"},{"jp":"the login issue.","reading":"/ðə ˈlɔːɡɪn ˈɪʃuː/","meaning":"masalah masuk akun tersebut.","role":"object"}],"translation":"Maya mengatakan bahwa dia sudah memperbaiki masalah login tersebut."},{"tokens":[{"jp":"My manager","reading":"/maɪ ˈmænɪdʒər/","meaning":"manajer saya","role":"subject"},{"jp":"reminded us","reading":"/rɪˈmaɪndɪd ʌs/","meaning":"mengingatkan kami","role":"verb"},{"jp":"not to push","reading":"/nɑːt tə pʊʃ/","meaning":"agar tidak mengunggah (not + to V1)","role":"verb"},{"jp":"code on Friday evening.","reading":"/koʊd ɑːn ˈfraɪdeɪ ˈiːvnɪŋ/","meaning":"kode pada Jumat malam.","role":"time"}],"translation":"Manajer saya mengingatkan kami agar tidak mengunggah kode pada Jumat malam."}],"forms":[{"label":"Pernyataan (will → would)","jp":"He promised he would send the draft by noon.","reading":"/hiː ˈprɑːmɪst hiː wʊd sɛnd ðə dræft baɪ nuːn/","id":"Dia berjanji akan mengirimkan drafnya sebelum tengah hari."},{"label":"Pertanyaan Yes/No (if/whether)","jp":"They asked if we offered enterprise support.","reading":"/ðeɪ æskt ɪf wiː ˈɔːfərd ˈɛntərpraɪz səˈpɔːrt/","id":"Mereka bertanya apakah kami menyediakan dukungan korporat."},{"label":"Instruksi (told + Obj + to V1)","jp":"The IT desk told me to restart my laptop.","reading":"/ði ˌaɪˈtiː dɛsk toʊld miː tə ˌriːˈstɑːrt maɪ ˈlæptɑːp/","id":"Tim IT menyuruh saya menyalakan ulang laptop saya."}],"mistakes":[{"wrong":"She said me that the meeting was canceled.","right":"She told me that the meeting was canceled. / She said that the meeting was canceled.","why":"''Say'' tidak boleh langsung diikuti objek orang (''said me'' ❌); gunakan ''told me'' atau ''said (to me) that''."},{"wrong":"The interviewer asked me where did I study.","right":"The interviewer asked me where I had studied.","why":"Pertanyaan yang dilaporkan bukan lagi kalimat tanya langsung, sehingga ''did'' dibuang dan susunannya kembali Subjek + Verb!"}],"quiz":[{"question":"Ubah kalimat langsung berikut ke Reported Speech: Dina said, ''I am flying to Boston tomorrow.''","options":["Dina told that she is flying to Boston tomorrow.","Dina said she was flying to Boston the next day.","Dina said me she was flying to Boston the next day.","Dina said she had flown to Boston yesterday."],"answer":1,"why":"''Am flying'' bergeser menjadi ''was flying'', ''tomorrow'' menjadi ''the next day'', dan ''said'' dipakai tanpa objek orang."},{"question":"Pilih pelaporan instruksi negatif yang benar untuk kalimat: ''Don''t share this link publicly.''","options":["He told us don''t share the link publicly.","He told us to not sharing the link publicly.","He told us not to share the link publicly.","He said us not to share the link publicly."],"answer":2,"why":"Imperatif negatif ''Don''t + V1'' dilaporkan menggunakan pola ''told/asked + Object + not to + V1''."},{"question":"Lengkapi laporan pertanyaan berikut: ''The professor asked ___ anyone had questions about the syllabus.''","options":["that","whether","what did","to"],"answer":1,"why":"Pertanyaan Yes/No yang dilaporkan dihubungkan dengan ''if'' atau ''whether'' (bukan ''that'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000029', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-009', 'honorific', 'Indirect Questions: Pertanyaan Halus Tanpa Inversi (Could you tell me where...)', '[Polite Opener: Could you tell me / Do you know] + [Wh- / if / whether] + [Subject + Verb]?', 'Membungkus pertanyaan langsung di dalam pembuka sopan dengan mengembalikan klausa kedua ke urutan Subjek + Kata Kerja normal.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"Could you tell me where the registration desk is?","reading":"/kʊd juː tɛl miː wɛr ðə ˌrɛdʒɪˈstreɪʃən dɛsk ɪz/","id":"Bisakah Anda memberi tahu saya di mana meja registrasi berada?"},{"jp":"Do you happen to know what time the shuttle leaves?","reading":"/duː juː ˈhæpən tə noʊ wʌt taɪm ðə ˈʃʌtəl liːvz/","id":"Apakah Anda kebetulan tahu jam berapa bus antar-jemputnya berangkat?"}]'::jsonb, 'Could you tell me where the lab is? (BUKAN ''where is the lab'')', '{"analogy":"Sebuah kalimat hanya boleh melakukan ''salto tanya'' (inversi) SATU KALI saja! Karena bagian pembukanya (''Could you tell me...'' atau ''Do you know...'') SUDAH berposisi tanya, maka bagian kedua setelah ''where/what/how/if'' harus berjalan lurus normal (Subjek dulu, baru Kata Kerja) dan membuang ''do/does/did''!","when_to_use":["Bertanya kepada resepsionis, petugas bandara, dosen, atau klien baru agar terdengar sopan dan berkelas","Menulis pertanyaan informasi di email profesional menggunakan ''I was wondering if...'' atau ''I''d like to know...''","Menjawab soal favorit TOEFL Structure tentang Noun Clause Word Order!"],"formula_parts":[{"role":"verb","text":"Could you tell me / Do you know","label":"Pembuka (Sudah Inversi)"},{"role":"connector","text":"Wh- / if / whether","label":"Penghubung Klausa"},{"role":"subject","text":"Subject","label":"Subjek Dulu!"},{"role":"verb","text":"Normal Verb","label":"Tanpa do/does/did!"}],"steps":["Awali dengan frasa sopan: ''Could you tell me...?'', ''Do you know...?'' (pakai tanda tanya di ujung), atau pernyataan ''I wonder... / Please let me know...'' (pakai tanda titik di ujung!).","Untuk pertanyaan informasi, pasang kata Wh-; untuk pertanyaan Yes/No, pasang ''if'' atau ''whether''.","Susun sisanya persis seperti kalimat pernyataan biasa: ''where is it'' → ''where it is''; ''when does it start'' → ''when it starts''; ''what did she say'' → ''what she said''!"],"breakdowns":[{"tokens":[{"jp":"Do you know","reading":"/duː juː noʊ/","meaning":"apakah Anda tahu (bagian tanya)","role":"verb"},{"jp":"how much","reading":"/haʊ mʌtʃ/","meaning":"berapa harga","role":"connector"},{"jp":"the conference pass","reading":"/ðə ˈkɑːnfərəns pæs/","meaning":"tiket konferensi itu (subjek)","role":"subject"},{"jp":"costs?","reading":"/kɔːsts/","meaning":"berharga? (does hilangkan → tambah -s!)","role":"verb"}],"translation":"Apakah Anda tahu berapa harga tiket konferensi tersebut?"},{"tokens":[{"jp":"I was wondering","reading":"/aɪ wəz ˈwʌndərɪŋ/","meaning":"saya ingin tahu (pernyataan sopan)","role":"verb"},{"jp":"whether","reading":"/ˈwɛðər/","meaning":"apakah","role":"connector"},{"jp":"the position","reading":"/ðə pəˈzɪʃən/","meaning":"posisi lowongan itu (subjek)","role":"subject"},{"jp":"is still open.","reading":"/ɪz stɪl ˈoʊpən/","meaning":"masih terbuka. (pakai titik!)","role":"predicate"}],"translation":"Saya ingin menanyakan apakah posisi tersebut masih terbuka."}],"forms":[{"label":"Be Verb di Ujung","jp":"Can you tell me what the Wi-Fi password is?","reading":"/kən juː tɛl miː wʌt ðə ˈwaɪfaɪ ˈpæswɜːrd ɪz/","id":"Bisa beri tahu saya apa kata sandi Wi-Fi-nya?"},{"label":"Hilangkan does → V+s","jp":"Do you have any idea when the dean arrives?","reading":"/duː juː hæv ˈɛni aɪˈdiːə wɛn ðə diːn əˈraɪvz/","id":"Apakah Anda tahu kapan dekan tiba?"},{"label":"Pernyataan (Titik, Bukan ?)","jp":"Please let me know how long the review takes.","reading":"/pliːz lɛt miː noʊ haʊ lɔːŋ ðə rɪˈvjuː teɪks/","id":"Mohon kabari saya berapa lama proses peninjauannya berlangsung."}],"mistakes":[{"wrong":"Could you tell me where is the nearest subway station?","right":"Could you tell me where the nearest subway station is?","why":"Hindari inversi ganda! Setelah ''where'', letakkan subjek ''the nearest subway station'' terlebih dahulu baru ''is'' di belakang."},{"wrong":"Do you know what time does the webinar begin?","right":"Do you know what time the webinar begins?","why":"Kata bantu ''does'' wajib dihapus dalam embedded/indirect question, lalu akhiran ''-s'' dikembalikan ke kata kerja ''begins''."}],"quiz":[{"question":"Pilih Indirect Question yang 100% tepat menurut standar TOEFL:","options":["Do you know why did the build fail?","Do you know why the build failed?","Do you know why failed the build?","Do you know why the build did fail?"],"answer":1,"why":"''Did'' dihapus dan tenses lampaunya menyatu kembali ke kata kerja menjadi urutan Subjek + V2 (''why the build failed'')."},{"question":"Perhatikan tanda baca kalimat email ini: ''I was wondering if we could reschedule our 1-on-1___''","options":["Wajib memakai tanda tanya (?) karena ada kata ''if''","Memakai tanda titik (.) karena induk kalimat ''I was wondering'' berbentuk kalimat berita/pernyataan","Wajib memakai tanda seru (!)","Memakai titik dua (:)"],"answer":1,"why":"''I was wondering...'' dan ''Please let me know...'' secara gramatikal adalah kalimat pernyataan, sehingga diakhiri tanda titik (.)."},{"question":"Manakah pengecualian di mana urutan katanya terlihat tidak berubah karena kata tanyanya sendiri adalah SUBJEK?","options":["Could you tell me who is in charge of billing?","Could you tell me where is the billing office?","Could you tell me when is the bill due?","Could you tell me how much does it cost?"],"answer":0,"why":"Dalam ''who is in charge'', kata ''who'' sendiri adalah Subjek diikuti Verb ''is'', sehingga susunannya memang sudah Subjek + Verb!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000030', 'e1000001-0000-4000-8000-000000000003', 'GP-EN-B1-010', 'particle', 'Connectors of Contrast & Reason: Kontras & Sebab (although / despite / because of)', 'Although / Because + [Subject + Verb] vs Despite / In spite of / Because of / Due to + [Noun / V-ing]', 'Memilih kata penghubung pertentangan dan alasan berdasarkan struktur tata bahasa di belakangnya: klausa utuh atau frasa benda.', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"Although the budget was tight, the team delivered on time.","reading":"/ɔːlˈðoʊ ðə ˈbʌdʒɪt wəz taɪt ðə tiːm dɪˈlɪvərd ɑːn taɪm/","id":"Meskipun anggarannya ketat, tim berhasil menyelesaikannya tepat waktu."},{"jp":"Despite the tight budget, the team delivered on time.","reading":"/dɪˈspaɪt ðə taɪt ˈbʌdʒɪt ðə tiːm dɪˈlɪvərd ɑːn taɪm/","id":"Terlepas dari anggaran yang ketat, tim berhasil menyelesaikannya tepat waktu."}]'::jsonb, 'although (/ɔːlˈðoʊ/) + S+V vs despite (/dɪˈspaɪt/) + Noun (TANPA ''of''!)', '{"analogy":"Makna ''although'' dan ''despite'' sama-sama ''meskipun'', begitu pula ''because'' dan ''because of'' sama-sama ''karena''. Bedanya murni soal ''colokan kabel'' di belakangnya! Kubu Konjungsi (''although, even though, because, since'') butuh kalimat lengkap (Subjek + Verb). Kubu Preposisi (''despite, in spite of, because of, due to'') HANYA mau menerima Kata Benda atau V-ing!","when_to_use":["Menunjukkan kontras tak terduga dengan ''although / even though + S + V'' atau ''despite / in spite of + Noun/V-ing''","Menjelaskan penyebab dengan ''because / as / since + S + V'' atau ''because of / due to + Noun/V-ing''","Trik konversi cepat di TOEFL Writing: tambahkan jembatan ''the fact that'' jika ingin menyambung ''despite / due to'' dengan klausa S + V!"],"formula_parts":[{"role":"connector","text":"Although / Because","label":"Wajib + Subjek & Verb"},{"role":"particle","text":"Despite / Due to","label":"Wajib + Frasa Benda / V-ing"},{"role":"predicate","text":"Main Clause","label":"Tanpa ''but'' / ''so'' Ganda!"}],"steps":["Intip kata-kata tepat setelah rumpang: apakah ada pasangan Subjek + Kata Kerja aktif (''the rain WAS heavy'') atau cuma Frasa Benda (''the heavy rain'')?","Ingat dua larangan ejaan & pasangan: (1) JANGAN pernah menulis ''despite OF'' (''despite'' tanpa ''of''; yang pakai ''of'' adalah ''in spite of''!), dan (2) JANGAN menaruh ''but'' lagi setelah ''although'', atau ''so'' lagi setelah ''because''!","Gunakan ''However,'' (diikuti koma) jika ingin memisahkan kontras menjadi kalimat baru yang mandiri."],"breakdowns":[{"tokens":[{"jp":"The flight","reading":"/ðə flaɪt/","meaning":"penerbangan itu","role":"subject"},{"jp":"was delayed","reading":"/wəz dɪˈleɪd/","meaning":"tertunda","role":"verb"},{"jp":"due to","reading":"/duː tuː/","meaning":"dikarenakan (+ frasa benda)","role":"particle"},{"jp":"severe weather.","reading":"/sɪˈvɪr ˈwɛðər/","meaning":"cuaca buruk (Noun Phrase).","role":"noun"}],"translation":"Penerbangan tersebut tertunda dikarenakan cuaca buruk."},{"tokens":[{"jp":"Despite","reading":"/dɪˈspaɪt/","meaning":"meskipun (tanpa ''of''!)","role":"particle"},{"jp":"having","reading":"/ˈhævɪŋ/","meaning":"memiliki (Gerund V-ing)","role":"noun"},{"jp":"limited data,","reading":"/ˈlɪmɪtɪd ˈdeɪtə/","meaning":"data terbatas,","role":"object"},{"jp":"the model performed well.","reading":"/ðə ˈmɑːdəl pərˈfɔːrmd wɛl/","meaning":"modelnya bekerja dengan baik.","role":"predicate"}],"translation":"Meskipun memiliki data terbatas, model tersebut bekerja dengan baik."}],"forms":[{"label":"Konjungsi + Klausa","jp":"Even though she was jet-lagged, she aced the pitch.","reading":"/ˈiːvən ðoʊ ʃiː wəz ˈdʒɛtlæɡd ʃiː eɪst ðə pɪtʃ/","id":"Walaupun terkena jet lag, dia tampil gemilang saat presentasi."},{"label":"Preposisi + Noun/V-ing","jp":"In spite of the fierce competition, we won the tender.","reading":"/ɪn spaɪt əv ðə fɪrs ˌkɑːmpəˈtɪʃən wiː wʌn ðə ˈtɛndər/","id":"Meskipun persaingannya ketat, kami memenangkan tender tersebut."},{"label":"Jembatan ''the fact that''","jp":"Despite the fact that costs rose, profits remained steady.","reading":"/dɪˈspaɪt ðə fækt ðæt kɔːsts roʊz ˈprɑːfɪts rɪˈmeɪnd ˈstɛdi/","id":"Terlepas dari kenyataan bahwa biaya naik, laba tetap stabil."}],"mistakes":[{"wrong":"Although the server traffic doubled, but the app stayed fast.","right":"Although the server traffic doubled, the app stayed fast.","why":"Dalam Bahasa Indonesia kita sering bilang ''Walaupun..., tapi...'', namun dalam Bahasa Inggris DILARANG memakai ''although'' dan ''but'' sekaligus dalam satu kalimat!"},{"wrong":"Despite of the rain, hundreds attended the career fair.","right":"Despite the rain, hundreds attended the career fair.","why":"''Despite'' berdiri sendiri tanpa ''of''! Pilih ''Despite the rain'' atau ''In spite of the rain''."}],"quiz":[{"question":"Pilih kata penghubung yang tepat untuk soal klasik TOEFL: ''___ its remote location, the observatory attracts astronomers worldwide.''","options":["Although","Even though","Despite","Because"],"answer":2,"why":"''Its remote location'' adalah Frasa Benda tanpa kata kerja, sehingga wajib didahului preposisi kontras ''Despite''."},{"question":"Manakah kalimat yang BEBAS dari kesalahan struktur ganda?","options":["Because the API changed, so our integration broke.","Because of the API changed, our integration broke.","Because the API changed, our integration broke.","Due to the API changed, our integration broke."],"answer":2,"why":"''The API changed'' adalah klausa S + V sehingga memakai ''Because'', dan induk kalimat tidak boleh ditambah ''so'' lagi."},{"question":"Lengkapi kalimat berikut: ''___ working full-time, Andi completed his master''s thesis with honors.''","options":["Although","In spite of","Despite of","Whereas"],"answer":1,"why":"''Working full-time'' adalah bentuk Gerund (V-ing) tanpa subjek eksplisit di depannya, sehingga tepat dipasangkan dengan ''In spite of'' (atau ''Despite'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000031', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-001', 'conjugation', 'Third & Mixed Conditionals: Evaluasi Masa Lalu (If + had V3, would have V3)', 'Type 3: If + had V3, would/could have V3 • Mixed: If + had V3, would + V1 (now)', 'Mengevaluasi skenario masa lalu yang tak terulang lagi (Type 3) serta dampaknya yang masih terasa hari ini (Mixed).', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"If we had load-tested the server, it wouldn''t have crashed.","reading":"/ɪf wiː hæd ˈloʊdtɛstɪd ðə ˈsɜːrvər ɪt ˈwʊdənt hæv kræʃt/","id":"Andaikan dulu kami menguji beban servernya, server itu tidak akan tumbang (faktanya dulu tumbang)."},{"jp":"If she had taken that job in Austin, she would live in Texas now.","reading":"/ɪf ʃiː hæd ˈteɪkən ðæt dʒɑːb ɪn ˈɔːstɪn ʃiː wʊd lɪv ɪn ˈtɛksəs naʊ/","id":"Seandainya dulu dia mengambil pekerjaan di Austin itu, sekarang dia pasti tinggal di Texas."}]'::jsonb, 'If we''d tested (/wiːd ˈtɛstɪd/), we wouldn''t have crashed', '{"analogy":"Jika Second Conditional adalah khayalan hari ini, Third Conditional adalah ''mesin waktu penyesalan / post-mortem'' untuk membedah sejarah yang sudah terlanjur lewat (''Nasi sudah menjadi bubur''). Dan kalau keputusan masa lalu itu mengubah nasibmu HARI INI, kita mengawinkan klausa syarat Type 3 (''If + had V3'') dengan hasil Type 2 (''would + V1 now'') menjadi Mixed Conditional!","when_to_use":["Melakukan post-mortem proyek atau refleksi kesalahan masa lalu tanpa bisa mengubahnya lagi (Type 3)","Menghubungkan keputusan masa lalu dengan kondisi saat ini menggunakan penanda ''now / today'' (Mixed Conditional)","Mengekspresikan kelegaan atas bencana yang untungnya terhindarkan (''If you hadn''t backed it up, we would have lost everything'')"],"formula_parts":[{"role":"connector","text":"If + Subject + had V3","label":"Syarat Lampau Tak Nyata"},{"role":"predicate","text":"would/could have + V3","label":"Hasil Lampau (Type 3)"},{"role":"predicate","text":"would + V1 (now)","label":"Hasil Hari Ini (Mixed)"}],"steps":["Di dalam klausa ''If'' untuk masa lalu, kunci rumusnya pada Past Perfect: ''had / hadn''t + V3'' (DILARANG memakai ''would have'' di klausa ''If''!).","Cek waktu konsekuensinya: jika konsekuensinya juga selesai di masa lalu → pakai ''would/could/might + have + V3''.","Jika konsekuensinya adalah status HARI INI (ada kata ''now, today, right now'') → potong ''have V3'' menjadi ''would + V1 / be'' (Mixed Conditional)!"],"breakdowns":[{"tokens":[{"jp":"If I had known","reading":"/ɪf aɪ hæd noʊn/","meaning":"seandainya dulu saya tahu (had + V3)","role":"connector"},{"jp":"about the grant,","reading":"/əˈbaʊt ðə ɡrænt/","meaning":"tentang hibah itu,","role":"object"},{"jp":"I would have applied","reading":"/aɪ wʊd hæv əˈplaɪd/","meaning":"pasti dulu saya sudah melamar","role":"predicate"},{"jp":"immediately.","reading":"/ɪˈmiːdiətli/","meaning":"seketika itu juga.","role":"time"}],"translation":"Seandainya dulu saya tahu tentang hibah itu, saya pasti langsung melamar."},{"tokens":[{"jp":"If we hadn''t automated","reading":"/ɪf wiː ˈhædənt ˈɔːtəmeɪtɪd/","meaning":"jika dulu kami tidak mengotomatiskan","role":"connector"},{"jp":"billing,","reading":"/ˈbɪlɪŋ/","meaning":"penagihan,","role":"object"},{"jp":"we''d still be doing","reading":"/wiːd stɪl biː ˈduːɪŋ/","meaning":"sekarang kita pasti masih mengerjakan (Mixed)","role":"predicate"},{"jp":"it manually today.","reading":"/ɪt ˈmænjuəli təˈdeɪ/","meaning":"itu secara manual hari ini.","role":"time"}],"translation":"Jika dulu kami tidak mengotomatiskan penagihan, hari ini kita pasti masih mengerjakannya secara manual."}],"forms":[{"label":"Type 3 Murni (Lampau → Lampau)","jp":"Could we have prevented the outage if we had patched earlier?","reading":"/kʊd wiː hæv prɪˈvɛntɪd ði ˈaʊtɪdʒ ɪf wiː hæd pætʃt ˈɜːrliər/","id":"Bisakah dulu kita mencegah gangguan itu seandainya kita menambalnya lebih awal?"},{"label":"Mixed (Lampau → Kini)","jp":"If he had saved his equity, he would be financially independent now.","reading":"/ɪf hiː hæd seɪvd hɪz ˈɛkwəti hiː wʊd biː faɪˈnænʃəli ˌɪndɪˈpɛndənt naʊ/","id":"Seandainya dulu ia menyimpan sahamnya, sekarang ia sudah mandiri finansial."},{"label":"Tanpa If (But for)","jp":"But for your quick fix, the demo would have failed.","reading":"/bʌt fɔːr jʊr kwɪk fɪks ðə ˈdɛmoʊ wʊd hæv feɪld/","id":"Tanpa perbaikan cepat Anda, demonya pasti sudah gagal."}],"mistakes":[{"wrong":"If I would have seen your message, I would have replied.","right":"If I had seen your message, I would have replied.","why":"Kesalahan lisan paling umum yang fatal di TOEFL: jangan pernah menaruh ''would have'' di dalam klausa ''If''; wajib ''If + had + V3''!"},{"wrong":"would of / could of / should of","right":"would have / could have / should have","why":"Karena kontraksi ''would''ve'' terdengar seperti ''/ˈwʊdəv/'', banyak orang salah menulisnya menjadi ''would of''—dalam tulisan wajib ''would have''!"}],"quiz":[{"question":"Pilih jawaban yang tepat untuk soal TOEFL Structure: ''If the researchers ___ a larger sample size, their findings ___ statistically significant.''","options":["used / would have been","had used / would have been","would have used / had been","have used / would be"],"answer":1,"why":"Evaluasi riset masa lalu memakai Third Conditional: ''If + had V3 (had used)'' dan ''would have + V3 (would have been)''."},{"question":"Perhatikan kata ''right now'' di ujung kalimat: ''If I hadn''t missed my connecting flight in Tokyo, I ___ in San Francisco right now.''","options":["would have been","would be","will be","had been"],"answer":1,"why":"Penyebab di masa lalu (''hadn''t missed'') dengan hasil SAAT INI (''right now'') membentuk Mixed Conditional → ''would be''."},{"question":"Apa fakta nyata dari kalimat: ''If they hadn''t encrypted the backup, the hackers could have read it''?","options":["Mereka lupa mengenkripsi cadangan data dan peretas membacanya","Mereka SUDAH mengenkripsi cadangan data, sehingga peretas TIDAK BISA membacanya","Peretas membantu mengenkripsi data mereka","Mereka baru akan mengenkripsi data besok"],"answer":1,"why":"Klausa negatif hipotesis lampau (''hadn''t encrypted'') berarti kenyataannya mereka SUDAH mengenkripsinya."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000032', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-002', 'tense', 'Past Perfect: Urutan Kronologis Lampau (had + V3 sebelum Past Simple)', '[Earlier Past: Subject + had + V3] + before / by the time / when + [Later Past: Subject + V2]', 'Menandai mana kejadian yang terjadi LEBIH DULU (''lampau dari masa lampau'') ketika menceritakan dua peristiwa masa lalu.', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"By the time we arrived at the gate, the plane had already taken off.","reading":"/baɪ ðə taɪm wiː əˈraɪvd æt ðə ɡeɪt ðə pleɪn hæd ɔːlˈrɛdi ˈteɪkən ɔːf/","id":"Pada saat kami tiba di gerbang, pesawatnya sudah lebih dulu lepas landas."},{"jp":"She aced the interview because she had researched the company thoroughly.","reading":"/ʃiː eɪst ði ˈɪntərvjuː bɪˈkɔːz ʃiː hæd ˈriːsɜːrtʃt ðə ˈkʌmpəni ˈθɜːroʊli/","id":"Dia sukses besar dalam wawancara karena sebelumnya sudah meneliti perusahaan tersebut secara mendalam."}]'::jsonb, 'By the time I joined (/dʒɔɪnd/), they had already launched (/hæd ɔːlˈrɛdi lɔːntʃt/)', '{"analogy":"Past Perfect (''had + V3'') bukanlah ''masa lalu yang terjadi ribuan tahun silam''! Dinosaurus punah cukup pakai V2 (''Dinosaurs died out'') kalau cuma satu titik cerita. Past Perfect baru keluar dari sarangnya kalau ada DUA kejadian masa lalu, dan kamu ingin memberi label tegas: ''Kejadian A sudah kelar DULUAN sebelum Kejadian B menyusul!''","when_to_use":["Memakai frasa patokan ''By the time + V2, ... had + V3'' (''Pada saat X terjadi, Y sudah selesai duluan'')","Menceritakan kilas balik (flashback) atau alasan terdahulu di balik peristiwa masa lalu (''was nervous because he had never flown before'')","Menunjukkan durasi yang berlangsung hingga titik masa lalu tertentu (''had worked there for ten years before retiring'')"],"formula_parts":[{"role":"time","text":"By the time + S + V2","label":"Kejadian ke-2 (Patokan Lampau)"},{"role":"subject","text":"Subject","label":"Pelaku"},{"role":"verb","text":"had + V3","label":"Kejadian ke-1 (Selesai Duluan)"}],"steps":["Urutkan dua kejadian masa lalu di kepalamu: Kejadian #1 (lebih awal) → ''had + V3''; Kejadian #2 (lebih belakangan) → ''V2 (Past Simple)''.","Jangan memakai ''had + V3'' sendirian untuk satu kalimat tunggal tanpa patokan masa lalu lainnya!","Perhatikan perbedaan drastis makna ''when'': ''When I arrived, the meeting started'' (saya datang dulu, baru mulai) vs ''When I arrived, the meeting HAD started'' (rapat sudah mulai duluan sebelum saya datang!)."],"breakdowns":[{"tokens":[{"jp":"By the time","reading":"/baɪ ðə taɪm/","meaning":"pada saat","role":"connector"},{"jp":"the patch went live,","reading":"/ðə pætʃ wɛnt laɪv/","meaning":"tambalan sistem tayang (Kejadian #2: V2),","role":"time"},{"jp":"thousands of users","reading":"/ˈθaʊzəndz əv ˈjuːzərz/","meaning":"ribuan pengguna","role":"subject"},{"jp":"had reported","reading":"/hæd rɪˈpɔːrtɪd/","meaning":"sudah lebih dulu melaporkan (Kejadian #1: had V3)","role":"verb"},{"jp":"the glitch.","reading":"/ðə ɡlɪtʃ/","meaning":"gangguan tersebut.","role":"object"}],"translation":"Pada saat tambalan sistem tayang, ribuan pengguna sudah telanjur melaporkan gangguan tersebut."},{"tokens":[{"jp":"I didn''t recognize","reading":"/aɪ ˈdɪdənt ˈrɛkəɡnaɪz/","meaning":"saya tidak mengenali (V2)","role":"verb"},{"jp":"him","reading":"/hɪm/","meaning":"dia","role":"object"},{"jp":"because we hadn''t met","reading":"/bɪˈkɔːz wiː ˈhædənt mɛt/","meaning":"karena sebelumnya kami belum pernah bertemu","role":"connector"},{"jp":"in person.","reading":"/ɪn ˈpɜːrsən/","meaning":"secara tatap muka.","role":"place"}],"translation":"Saya tidak mengenalinya karena sebelumnya kami belum pernah bertemu secara langsung."}],"forms":[{"label":"Pola Klasik By the time","jp":"By 2020, smartphone adoption had surpassed 80%.","reading":"/baɪ ˈtwɛnti ˈtwɛnti ˈsmɑːrtfoʊn əˈdɑːpʃən hæd sərˈpæst/","id":"Menjelang tahun 2020, adopsi ponsel pintar telah melampaui 80%."},{"label":"Past Perfect Continuous","jp":"They had been negotiating for weeks before signing.","reading":"/ðeɪ hæd bɪn nɪˈɡoʊʃieɪtɪŋ fɔːr wiːks bɪˈfɔːr ˈsaɪnɪŋ/","id":"Mereka sudah bernegosiasi berminggu-minggu sebelum menandatangani kontrak."},{"label":"Urutan Jelas (before/after)","jp":"After she had backed up the drive, she formatted it.","reading":"/ˈæftər ʃiː hæd bækt ʌp ðə draɪv ʃiː ˈfɔːrmætɪd ɪt/","id":"Setelah selesai mencadangkan diska tersebut, dia memformatnya."}],"mistakes":[{"wrong":"Yesterday I had eaten sushi for dinner.","right":"Yesterday I ate sushi for dinner.","why":"Untuk satu kejadian tunggal di masa lalu (''Yesterday''), gunakan Past Simple (''ate''), bukan Past Perfect (''had eaten'')!"},{"wrong":"By the time the firefighters arrived, the warehouse burned down completely (maksud: sudah habis terbakar duluan).","right":"By the time the firefighters arrived, the warehouse had burned down completely.","why":"Frasa ''By the time + V2'' menuntut Past Perfect (''had + V3'') untuk menegaskan kejadiannya sudah tuntas sebelum titik waktu itu."}],"quiz":[{"question":"Lengkapi soal kronologi TOEFL berikut: ''By the time the printing press was invented in Europe, movable type ___ in East Asia for centuries.''","options":["existed","has existed","had existed","was existing"],"answer":2,"why":"Karena terjadi berabad-abad SEBELUM penemuan mesin cetak di Eropa (V2), wajib memakai Past Perfect ''had existed''."},{"question":"Bandingkan: (A) ''When the CEO walked in, everyone stood up.'' vs (B) ''When the CEO walked in, everyone had stood up.'' Mana yang menunjukkan orang-orang berdiri KARENA melihat CEO masuk?","options":["Kalimat (A), karena dua V2 berurutan menunjukkan reaksi langsung setelahnya","Kalimat (B), karena ''had stood up'' berarti baru berdiri belakangan","Keduanya sama persis","Kalimat (A) salah grammar"],"answer":0,"why":"Dalam (A), CEO masuk dulu lalu semua berdiri; dalam (B), semua orang sudah berdiri duluan sebelum CEO masuk!"},{"question":"Pilih kalimat yang menggunakan Past Perfect Continuous secara tepat:","options":["He was tired yesterday because he has been coding all night.","He was tired yesterday because he had been coding all night.","He is tired yesterday because he had coded.","He had been knowing the answer before the test."],"answer":1,"why":"Durasi penyebab sebelum titik lelah kemarin (''was tired yesterday'') dinyatakan dengan Past Perfect Continuous (''had been coding'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000033', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-003', 'sentence_pattern', 'Non-Defining & Reduced Relative Clauses: Klausa Ringkas (the data collected...)', 'Non-Defining: , who / which ..., (PAKAI koma, TANPA ''that'') • Reduced: Noun + V-ing (aktif) / V3 (pasif)', 'Menyisipkan info tambahan berkoma serta memadatkan klausa relatif menjadi frasa V-ing/V3 ringkas khas bacaan TOEFL.', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"The survey conducted last month revealed a shift in user behavior.","reading":"/ðə ˈsɜːrveɪ kənˈdʌktɪd læst mʌnθ rɪˈviːld ə ʃɪft ɪn ˈjuːzər bɪˈheɪvjər/","id":"Survei yang dilakukan bulan lalu mengungkap pergeseran perilaku pengguna."},{"jp":"Dr. Lin, who leads our AI ethics board, will deliver the keynote.","reading":"/ˈdɑːktər lɪn huː liːdz ˈaʊər ˌeɪˈaɪ ˈɛθɪks bɔːrd wɪl dɪˈlɪvər ðə ˈkiːnoʊt/","id":"Dr. Lin, yang memimpin dewan etika AI kami, akan menyampaikan pidato utama."}]'::jsonb, 'Our CTO, who joined in May, ... • the data collected (/kəˈlɛktɪd/) by...', '{"analogy":"Ini adalah senjata rahasia nomor satu di soal TOEFL Structure & Reading! Pertama, kalau kata bendanya sudah jelas unik (seperti nama orang ''Dr. Lin'' atau ''Jakarta''), klausa penjelasnya diapit DUA KOMA sebagai info bonus, dan DILARANG memakai ''that'' setelah koma! Kedua, penulis akademik suka ''memangkas lemak'' klausa relatif: buang ''who/which/that + be'', sisakan ''V-ing'' untuk aktif (''students applying'' = who apply) atau ''V3'' untuk pasif (''data collected'' = which was collected)!","when_to_use":["Mengapit informasi tambahan tentang nama diri/entitas spesifik dengan koma ('', who..., '' atau '', which..., '')","Meringkas klausa aktif ''who/which/that + Verb'' menjadi ''V-ing'' (''Anyone wishing to attend...'' = Anyone who wishes...)","Meringkas klausa pasif ''who/which/that + be + V3'' menjadi langsung ''V3'' (''The method proposed by Chen...'' = which was proposed)"],"formula_parts":[{"role":"noun","text":"Specific Noun, who/which ...,","label":"Info Tambahan (Tanpa ''that''!)"},{"role":"adjective","text":"Noun + V-ing","label":"Ringkasan Aktif (''yang me-'')"},{"role":"adjective","text":"Noun + V3 (-ed/irreg)","label":"Ringkasan Pasif (''yang di-'')"}],"steps":["Cek tanda koma: jika ada koma sebelum klausa relatif, pilih ''who'' (orang) atau ''which'' (benda/seluruh ide kalimat)—JANGAN PERNAH memilih ''that'' setelah koma!","Saat bertemu kata kerja di sebelah kata benda pada soal TOEFL (''The algorithm [used] in this study IS fast''), kenali bahwa ''used'' bukan kata kerja utama kalimat, melainkan ringkasan pasif dari ''(which is) used''!","Pastikan bedanya: pakai V-ing jika kata bendanya MELAKUKAN aksi (''users experiencing issues''), dan pakai V3 jika kata bendanya DIKENAI aksi (''issues reported by users'')."],"breakdowns":[{"tokens":[{"jp":"The samples","reading":"/ðə ˈsæmpəlz/","meaning":"sampel-sampel tersebut (Subjek Utama)","role":"subject"},{"jp":"stored in liquid nitrogen","reading":"/stɔːrd ɪn ˈlɪkwɪd ˈnaɪtrədʒən/","meaning":"yang disimpan dalam nitrogen cair (Reduced Passive V3)","role":"adjective"},{"jp":"remained","reading":"/rɪˈmeɪnd/","meaning":"tetap (Kata Kerja Utama Kalimat!)","role":"verb"},{"jp":"intact.","reading":"/ɪnˈtækt/","meaning":"utuh.","role":"adjective"}],"translation":"Sampel-sampel yang disimpan dalam nitrogen cair tersebut tetap utuh."},{"tokens":[{"jp":"Revenue rose 18%,","reading":"/ˈrɛvənuː roʊz ˌeɪˈtiːn pərˈsɛnt/","meaning":"pendapatan naik 18%,","role":"predicate"},{"jp":"which exceeded","reading":"/wɪtʃ ɪkˈsiːdɪd/","meaning":"hal yang melampaui (merujuk seluruh klausa depan)","role":"connector"},{"jp":"Wall Street''s forecast.","reading":"/wɔːl striːts ˈfɔːrkæst/","meaning":"perkiraan Wall Street.","role":"object"}],"translation":"Pendapatan naik 18%, yang mana melampaui perkiraan Wall Street."}],"forms":[{"label":"Non-Defining Berkoma","jp":"Austin, which is the capital of Texas, is a major tech hub.","reading":"/ˈɔːstɪn wɪtʃ ɪz ðə ˈkæpɪtəl əv ˈtɛksəs ɪz ə ˈmeɪdʒər tɛk hʌb/","id":"Austin, yang merupakan ibu kota Texas, adalah pusat teknologi besar."},{"label":"Reduced Active (V-ing)","jp":"Passengers traveling with infants may board first.","reading":"/ˈpæsɪndʒərz ˈtrævəlɪŋ wɪð ˈɪnfənts meɪ bɔːrd fɜːrst/","id":"Penumpang yang bepergian bersama bayi boleh naik lebih dulu."},{"label":"Reduced Passive (V3)","jp":"Any code written without tests will be rejected.","reading":"/ˈɛni koʊd ˈrɪtən wɪˈðaʊt tɛsts wɪl biː rɪˈdʒɛktɪd/","id":"Kode apa pun yang ditulis tanpa pengujian akan ditolak."}],"mistakes":[{"wrong":"Our flagship app, that launched in June, hit one million downloads.","right":"Our flagship app, which launched in June, hit one million downloads.","why":"Dalam Non-Defining Relative Clause yang diapit tanda koma, penggunaan ''that'' dilarang keras—wajib gunakan ''which'' (atau ''who'' untuk orang)!"},{"wrong":"The Strategy proposing by the consultant saved us millions.","right":"The strategy proposed by the consultant saved us millions.","why":"Strategi ''diusulkan'' (pasif), bukan ''mengusulkan'' (aktif), sehingga ringkasannya wajib V3 (''proposed''), bukan V-ing (''proposing'')!"}],"quiz":[{"question":"Soal klasik jebakan TOEFL Structure: ''The artifacts ___ during the excavation are now on display at the museum.''","options":["discovering","discovered","were discovered","which discovering"],"answer":1,"why":"Kalimat sudah punya kata kerja utama ''are''! Maka bagian rumpang butuh Reduced Passive Relative Clause ''discovered'' (= which were discovered), bukan kata kerja penuh ''were discovered'' lagi."},{"question":"Pilih kata yang tepat setelah tanda koma: ''Solar panels, ___ convert sunlight directly into electricity, have plummeted in cost.''","options":["that","which","who","what"],"answer":1,"why":"Klausa penjelas tambahan setelah koma untuk benda wajib memakai ''which'', tidak pernah ''that'' atau ''what''."},{"question":"Ringkaslah kalimat aktif ini: ''Applicants who hold a master''s degree qualify for the senior track.''","options":["Applicants held a master''s degree...","Applicants holding a master''s degree...","Applicants are holding a master''s degree...","Applicants hold a master''s degree..."],"answer":1,"why":"Klausa relatif aktif (''who hold'') diringkas dengan membuang ''who'' dan mengubah kata kerja menjadi Present Participle ''holding''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000034', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-004', 'conjugation', 'Causative Verbs: Delegasi Tugas & Layanan (have / get something done)', 'Pasif Layanan: have / get + [Object] + V3 • Aktif: have / make + [Person] + V1 vs get + [Person] + to V1', 'Menyatakan bahwa kita meminta/membayar pihak lain melakukan sesuatu untuk kita, baik fokus ke objek maupun ke pelakunya.', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"I need to get my academic transcripts notarized before Friday.","reading":"/aɪ niːd tə ɡɛt maɪ ˌækəˈdɛmɪk ˈtrænskrɪpts ˈnoʊtəraɪzd bɪˈfɔːr ˈfraɪdeɪ/","id":"Saya perlu melegalisasi transkrip akademik saya (di notaris) sebelum hari Jumat."},{"jp":"Our legal team had the vendor revise two clauses in the NDA.","reading":"/ˈaʊər ˈliːɡəl tiːm hæd ðə ˈvɛndər rɪˈvaɪz tuː ˈklɔːzɪz ɪn ði ˌɛndiːˈeɪ/","id":"Tim hukum kami meminta pihak vendor merevisi dua klausul dalam perjanjian kerahasiaan."}]'::jsonb, 'had my transcripts translated • have IT reset (/riːˈsɛt/) vs get IT to reset', '{"analogy":"Kalau di Amerika kamu bilang ''I cut my hair'', orang akan membayangkan kamu memegang gunting sendiri di depan cermin! Untuk bilang ''Saya potong rambut (di salon)'' atau ''Saya menyervis laptop'', gunakan Passive Causative: ''I got/had my hair cut'' (have/get + Benda + V3). Sedangkan kalau menyebut ORANG yang disuruh, hafalkan rumus sakti TOEFL: ''make / have / let + Orang + V1 polos'', TAPI khusus ''get + Orang + TO V1''!","when_to_use":["Passive Causative (''have/get + Object + V3''): menggunakan jasa profesional (potong rambut, servis laptop, menerjemahkan dokumen, memeriksa mata)","Active Causative (''have + Person + V1''): mendelegasikan tugas secara wajar sesuai wewenang profesional (''I''ll have my assistant send the link'')","Active Causative (''get + Person + to V1'' vs ''make + Person + V1''): membujuk seseorang (''get...to'') vs memaksa/membuat tak punya pilihan (''make...V1'')"],"formula_parts":[{"role":"verb","text":"have / get + Benda + V3","label":"Jasa Profesional (Pasif)"},{"role":"verb","text":"have / make / let + Orang + V1","label":"Tanpa ''to'' (Bare Infinitive!)"},{"role":"verb","text":"get + Orang + to V1","label":"Wajib Pakai ''to''!"}],"steps":["Lihat kata tepat setelah ''have/get/make'': apakah itu BENDA yang dikenai pekerjaan (''the roof'', ''my visa photo'') atau ORANG pelakunya (''the contractor'', ''the intern'')?","Jika BENDA yang dikerjakan → kunci ujungnya dengan V3 (''had the contract reviewed'', ''got my screen replaced'').","Jika ORANG yang melakukan → cek kata kerja depannya: ''make/have/let'' diikuti V1 polos tanpa ''to'', sedangkan ''get'' diikuti ''to + V1'' (dan khusus ''help'' boleh V1 atau ''to V1''!)."],"breakdowns":[{"tokens":[{"jp":"We''re having","reading":"/wɪr ˈhævɪŋ/","meaning":"kami sedang menyuruh orang (causative)","role":"verb"},{"jp":"our security system","reading":"/ˈaʊər sɪˈkjʊrəti ˈsɪstəm/","meaning":"sistem keamanan kami (benda sasaran)","role":"object"},{"jp":"audited","reading":"/ˈɔːdɪtɪd/","meaning":"diaudit (wajib V3!)","role":"verb"},{"jp":"next week.","reading":"/nɛkst wiːk/","meaning":"minggu depan.","role":"time"}],"translation":"Kami akan mengauditkan sistem keamanan kami (lewat auditor) minggu depan."},{"tokens":[{"jp":"How did you","reading":"/haʊ dɪd juː/","meaning":"bagaimana kamu berhasil","role":"verb"},{"jp":"get","reading":"/ɡɛt/","meaning":"membujuk (causative get)","role":"verb"},{"jp":"the stakeholders","reading":"/ðə ˈsteɪkhoʊldərz/","meaning":"para pemangku kepentingan (orang)","role":"object"},{"jp":"to agree?","reading":"/tu əˈɡriː/","meaning":"untuk setuju? (get + orang + TO V1!)","role":"verb"}],"translation":"Bagaimana kamu berhasil membujuk para pemangku kepentingan agar setuju?"}],"forms":[{"label":"Passive Causative (Benda + V3)","jp":"She got her resume proofread by a career coach.","reading":"/ʃiː ɡɑːt hɜːr ˈrɛzəmeɪ ˈpruːfrɛd baɪ ə kəˈrɪr koʊtʃ/","id":"Dia memeriksakan CV-nya kepada pelatih karier."},{"label":"Have + Orang + V1 (Delegasi)","jp":"I''ll have the DevOps engineer check the logs.","reading":"/aɪl hæv ðə ˈdɛvɑːps ˌɛndʒɪˈnɪr tʃɛk ðə lɔːɡz/","id":"Saya akan meminta insinyur DevOps memeriksa catatan sistem."},{"label":"Make Pasif (+ to V1!)","jp":"The regulator made the bank refund users → The bank was made to refund users.","reading":"/ðə bæŋk wəz meɪd tə ˈriːfʌnd ˈjuːzərz/","id":"Ketika ''make'' diubah ke kalimat pasif (''was made''), kata ''to'' wajib muncul kembali!"}],"mistakes":[{"wrong":"The professor had the students to rewrite their abstracts.","right":"The professor had the students rewrite their abstracts.","why":"Pola aktif ''have + person'' wajib diikuti V1 murni (''rewrite'') tanpa ''to''!"},{"wrong":"I need to have my laptop repair today.","right":"I need to have my laptop repaired today.","why":"''My laptop'' adalah benda yang diservis (pasif), sehingga wajib memakai V3 (''repaired''), bukan V1 (''repair'')."}],"quiz":[{"question":"Soal favorit TOEFL Structure: ''Strict new privacy laws made tech companies ___ how they collect user consent.''","options":["redesign","to redesign","redesigned","redesigning"],"answer":0,"why":"Causative aktif ''make + object pelaku (tech companies)'' wajib diikuti bare infinitive V1 (''redesign'') tanpa ''to''."},{"question":"Bandingkan ''have'' vs ''get'' untuk pelaku orang: ''Could you get the finance team ___ this reimbursement today?''","options":["approve","to approve","approved","approving"],"answer":1,"why":"Berbeda dari ''have + person + V1'', pola ''get + person'' WAJIB memakai ''to + V1'' (''to approve'')!"},{"question":"Lengkapi Passive Causative berikut: ''Before submitting your thesis, you should have the formatting ___ professionally.''","options":["check","to check","checked","checking"],"answer":2,"why":"''The formatting'' adalah objek benda yang diperiksa oleh pihak lain, sehingga memakai ''have + object + V3 (checked)''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000035', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-005', 'tense', 'Future Continuous & Future Perfect: Proyeksi & Target (will be -ing / will have V3)', 'Future Continuous: will be + V-ing (Sedang nanti) • Future Perfect: will have + V3 (Sudah tuntas sebelum batas nanti)', 'Memproyeksikan aktivitas yang sedang berlangsung di satu titik masa depan vs target yang sudah tuntas menjelang tenggat tertentu.', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"This time next week, I''ll be attending orientation at Stanford.","reading":"/ðɪs taɪm nɛkst wiːk aɪl biː əˈtɛndɪŋ ˌɔːriɛnˈteɪʃən æt ˈstænfərd/","id":"Di jam segini minggu depan, saya akan sedang menghadiri orientasi di Stanford."},{"jp":"By December, our platform will have reached one million users.","reading":"/baɪ dɪˈsɛmbər ˈaʊər ˈplætfɔːrm wɪl hæv riːtʃt wʌn ˈmɪljən ˈjuːzərz/","id":"Menjelang bulan Desember nanti, platform kami sudah akan mencapai satu juta pengguna."}]'::jsonb, 'This time tomorrow, I''ll be flying • By Q4, we''ll have launched', '{"analogy":"Lompatlah naik mesin waktu ke masa depan lalu menoleh! Kalau di masa depan kamu melihat dirimu SEDANG di tengah aksi (''Jam 10 besok jangan telepon, saya sedang ujian''), pakai Future Continuous (''will be + V-ing''). Tapi kalau di garis finis masa depan (''By Friday / By 2030'') kamu melihat ke belakang bahwa tugasnya SUDAH BERES TUNTAS, pakai Future Perfect (''will have + V3'')!","when_to_use":["Future Continuous (''will be + V-ing''): aktivitas yang sedang berlangsung pada jam spesifik di masa depan (''At 3 p.m. tomorrow'', ''This time next month'') atau menanyakan rencana orang secara halus (''Will you be using the projector?'')","Future Perfect (''will have + V3''): menetapkan milestone bisnis, OKR, atau tenggat proyek dengan penanda ''By + waktu masa depan'' / ''By the time + Present Simple''","Future Perfect Continuous (''will have been + V-ing''): menghitung genap durasi kerja/studi pada tanggal masa depan (''By June, I''ll have been working here for five years'')"],"formula_parts":[{"role":"time","text":"At 9 tomorrow | By Friday","label":"Titik Berlangsung vs Tenggat"},{"role":"verb","text":"will be + V-ing","label":"Akan Sedang Berjalan"},{"role":"verb","text":"will have + V3","label":"Sudah Akan Tuntas"}],"steps":["Cari kata kunci penanda waktunya: jika ada ''By...'' (''menjelang / paling lambat pada...'') atau ''in X years'' time'' untuk pencapaian selesai → pilih Future Perfect (''will have + V3'').","Perhatikan: walaupun subjeknya tunggal seperti ''She'' atau ''The system'', setelah modal ''will'' SELALU memakai ''have'' (''She will have finished''), JANGAN PERNAH ''will has''!","Jika dikombinasikan dengan klausa ''By the time...'', klausa ''By the time'' tetap memakai Present Simple (''By the time you wake up, I will have landed'')."],"breakdowns":[{"tokens":[{"jp":"By the end of Q3,","reading":"/baɪ ði ɛnd əv kjuː θriː/","meaning":"menjelang akhir Kuartal 3,","role":"time"},{"jp":"we","reading":"/wiː/","meaning":"kami","role":"subject"},{"jp":"will have migrated","reading":"/wɪl hæv ˈmaɪɡreɪtɪd/","meaning":"sudah akan menyelesaikan migrasi","role":"verb"},{"jp":"all legacy services.","reading":"/ɔːl ˈlɛɡəsi ˈsɜːrvɪsɪz/","meaning":"semua layanan lama.","role":"object"}],"translation":"Menjelang akhir Kuartal 3, kami sudah akan memigrasikan semua layanan lama."},{"tokens":[{"jp":"Don''t call at noon—","reading":"/doʊnt kɔːl æt nuːn/","meaning":"jangan menelepon jam 12 siang—","role":"time"},{"jp":"we''ll be pitching","reading":"/wiːl biː ˈpɪtʃɪŋ/","meaning":"kami akan sedang presentasi","role":"verb"},{"jp":"to the board.","reading":"/tə ðə bɔːrd/","meaning":"di hadapan dewan direksi.","role":"object"}],"translation":"Jangan menelepon jam 12 siang—kami akan sedang presentasi di hadapan dewan direksi."}],"forms":[{"label":"Future Continuous (Sopan)","jp":"Will you be joining us for dinner tonight?","reading":"/wɪl juː biː ˈdʒɔɪnɪŋ ʌs fɔːr ˈdɪnər təˈnaɪt/","id":"Apakah Anda akan ikut makan malam bersama kami malam ini? (menanyakan jadwal tanpa mendesak)."},{"label":"Future Perfect (Target)","jp":"By the time she graduates, she will have published two papers.","reading":"/baɪ ðə taɪm ʃiː ˈɡrædʒueɪts ʃiː wɪl hæv ˈpʌblɪʃt tuː ˈpeɪpərz/","id":"Pada saat dia lulus nanti, dia sudah akan menerbitkan dua makalah."},{"label":"Future Perfect Continuous","jp":"Next month, he''ll have been leading the lab for a decade.","reading":"/nɛkst mʌnθ hiːl hæv bɪn ˈliːdɪŋ ðə læb fɔːr ə ˈdɛkeɪd/","id":"Bulan depan, genap satu dekade dia memimpin laboratorium tersebut."}],"mistakes":[{"wrong":"She will has completed the audit by Friday.","right":"She will have completed the audit by Friday.","why":"Setelah modal ''will'', kata kerja bantu wajib berbentuk dasar murni ''have'', tidak pernah berubah menjadi ''has''!"},{"wrong":"By the time the investor will arrive, we will have set up the demo.","right":"By the time the investor arrives, we will have set up the demo.","why":"''By the time...'' adalah klausa waktu, sehingga pantang memakai ''will'' di dalamnya—gunakan Present Simple (''arrives'')!"}],"quiz":[{"question":"Pilih bentuk yang tepat untuk proyeksi masa depan: ''By 2035, renewable sources ___ fossil fuels as the primary grid input in many regions.''","options":["surpassed","will have surpassed","will has surpassed","have been surpassing"],"answer":1,"why":"Penanda tenggat masa depan ''By 2035'' meminta Future Perfect ''will have + V3 (surpassed)''."},{"question":"Lengkapi kalimat berikut: ''At 2 p.m. tomorrow, please cover my Slack channel because I ___ a client workshop.''","options":["will facilitate","will be facilitating","have facilitated","facilitated"],"answer":1,"why":"Aktivitas yang sedang di tengah jalan pada jam spesifik besok (''At 2 p.m. tomorrow'') memakai Future Continuous ''will be facilitating''."},{"question":"Pilih gabungan yang benar: ''By the time the semester ___, we ___ twelve case studies.''","options":["will end / will have analyzed","ends / will have analyzed","ended / will analyze","ends / have analyzed"],"answer":1,"why":"Klausa ''By the time'' memakai Present Simple (''ends'') dan induk kalimatnya memakai Future Perfect (''will have analyzed'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000036', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-006', 'conjugation', 'Gerund vs Infinitive Shifts: Perubahan Makna (remember / stop / try)', 'remember/forget/regret + to V1 (Tugas belum dikerjakan) vs + V-ing (Memori lampau) • stop/try + to V1 vs + V-ing', 'Menguasai kata kerja yang sah diikuti ''to V1'' maupun ''V-ing'' tetapi menghasilkan arti yang bertolak belakang.', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"Please remember to back up your code before updating the OS.","reading":"/pliːz rɪˈmɛmbər tə bæk ʌp jʊr koʊd bɪˈfɔːr ʌpˈdeɪtɪŋ ði ˌoʊˈɛs/","id":"Harap ingat untuk mencadangkan kode Anda sebelum memperbarui sistem operasi (ingat dulu → baru lakukan)."},{"jp":"I clearly remember backing up the folder last night.","reading":"/aɪ ˈklɪrli rɪˈmɛmbər ˈbækɪŋ ʌp ðə ˈfoʊldər læst naɪt/","id":"Saya ingat betul sudah mencadangkan folder itu tadi malam (lakukan dulu → baru dikenang)."}]'::jsonb, 'remember to lock (tugas) vs remember locking (ingatan) • stop to rest vs stop smoking', '{"analogy":"Kunci rahasianya ada di garis waktu kronologis! Kata ''to'' selalu menunjuk panah KE DEPAN (aksi masa depan yang belum terjadi saat mengingat/berhenti), sedangkan ''-ing'' memutar rekaman aksi yang SUDAH/SEDANG berjalan! Jadi ''stop smoking'' = menghentikan rokok yang sedang berjalan (berhenti merokok total); ''stop to smoke'' = berhenti berjalan kaki DEMI menyalakan rokok!","when_to_use":["Remember / Forget + to V1 (ingat/lupa menunaikan kewajiban) vs + V-ing (punya/hilang memori pernah melakukan sesuatu di masa lalu)","Stop + V-ing (menghentikan kebiasaan/aktivitas itu sendiri) vs Stop + to V1 (menghentikan aktivitas sebelumnya sejenak DEMI melakukan aktivitas baru)","Try + to V1 (berusaha keras mencapai hal sulit) vs Try + V-ing (bereksperimen menjajal satu metode/solusi praktis) & Regret + to V1 (pengumuman sopan ''Kami menyesal mengabarkan...'') vs + V-ing (menyesali perbuatan lampau)"],"formula_parts":[{"role":"verb","text":"Verb + to V1","label":"Arah ke Depan (Tugas / Tujuan / Usaha Keras)"},{"role":"verb","text":"Verb + V-ing","label":"Rekaman Lampau / Hentikan Aksi / Eksperimen"}],"steps":["Untuk ''remember / forget / regret'': tanyakan mana yang terjadi duluan! Ingat dulu baru kunci pintu → ''remember to lock''. Kunci pintu dulu kemarin baru sekarang teringat → ''remember locking''.","Untuk ''stop'': apakah kamu memutus aktivitas itu (''stop scrolling social media'') atau jeda mampir demi tujuan lain (''stopped to grab coffee'')?","Untuk memberi saran troubleshooting teknis di kantor (''Coba deh restart routernya''), gunakan ''Try + V-ing'' (''Try restarting the router''), karena me-restart itu mudah dan kita sedang mengecek apakah cara itu mempan!"],"breakdowns":[{"tokens":[{"jp":"We regret","reading":"/wiː rɪˈɡrɛt/","meaning":"kami dengan berat hati","role":"verb"},{"jp":"to inform you","reading":"/tu ɪnˈfɔːrm juː/","meaning":"memberitahukan Anda (pengumuman resmi saat ini)","role":"verb"},{"jp":"that your application","reading":"/ðæt jʊr ˌæplɪˈkeɪʃən/","meaning":"bahwa lamaran Anda","role":"subject"},{"jp":"was unsuccessful.","reading":"/wəz ˌʌnsəkˈsɛsfəl/","meaning":"belum berhasil.","role":"predicate"}],"translation":"Dengan berat hati kami memberitahukan bahwa lamaran Anda belum berhasil."},{"tokens":[{"jp":"If the page freezes,","reading":"/ɪf ðə peɪdʒ ˈfriːzɪz/","meaning":"jika halamannya macet,","role":"connector"},{"jp":"try clearing","reading":"/traɪ ˈklɪrɪŋ/","meaning":"cobalah menjajal menghapus (eksperimen solusi)","role":"verb"},{"jp":"your browser cache.","reading":"/jʊr ˈbraʊzər kæʃ/","meaning":"tembolok peramban Anda.","role":"object"}],"translation":"Jika halamannya macet, cobalah bersihkan cache peramban Anda."}],"forms":[{"label":"Stop + V-ing (Putus Total)","jp":"They stopped supporting Internet Explorer years ago.","reading":"/ðeɪ stɑːpt səˈpɔːrtɪŋ ˈɪntərnɛt ɪkˈsplɔːrər jɪrz əˈɡoʊ/","id":"Mereka sudah menghentikan dukungan untuk Internet Explorer bertahun-tahun lalu."},{"label":"Stop + to V1 (Jeda Bertujuan)","jp":"On my way home, I stopped to pick up groceries.","reading":"/ɑːn maɪ weɪ hoʊm aɪ stɑːpt tə pɪk ʌp ˈɡroʊsəriz/","id":"Dalam perjalanan pulang, saya mampir berhenti untuk membeli bahan makanan."},{"label":"Need + V-ing (= Pasif!)","jp":"This paragraph needs rewriting (= needs to be rewritten).","reading":"/ðɪs ˈpærəɡræf niːdz ˌriːˈraɪtɪŋ/","id":"Paragraf ini perlu ditulis ulang (pola unik: Benda + need + V-ing bermakna pasif!)."}],"mistakes":[{"wrong":"Don''t forget attaching the signed PDF!","right":"Don''t forget to attach the signed PDF!","why":"Mengingatkan tugas yang BELUM dilakukan memakai ''Don''t forget to + V1'', bukan V-ing!"},{"wrong":"Please stop to talk during the exam!","right":"Please stop talking during the exam!","why":"''Stop to talk'' justru berarti ''berhentilah menulis supaya bisa mengobrol''! Untuk menyuruh berhenti mengobrol, gunakan ''stop talking''."}],"quiz":[{"question":"Apa arti kalimat: ''I''ll never forget presenting my research at MIT''?","options":["Saya lupa datang ke presentasi di MIT","Saya sudah pernah presentasi di MIT, dan kenangan berharga itu takkan pernah terlupakan","Besok saya harus ingat untuk presentasi di MIT","Saya batal diundang ke MIT"],"answer":1,"why":"''Never forget + V-ing'' merujuk pada memori peristiwa yang sudah pernah dialami di masa lalu."},{"question":"Lengkapi surat resmi universitas berikut: ''The Admissions Committee regrets ___ that we cannot offer you a seat this fall.''","options":["inform you","informing you","to inform you","informed you"],"answer":2,"why":"Ungkapan baku surat resmi saat hendak menyampaikan kabar buruk adalah ''regret to inform / announce / say''."},{"question":"Dalam Bahasa Inggris standar, ''The projector battery needs ___'' setara dengan ''needs to be replaced''. Pilihan yang tepat adalah:","options":["replace","replaced","replacing","to replace"],"answer":2,"why":"Untuk subjek benda mati, ''need / require + V-ing'' (''needs replacing'') mengandung makna pasif (= ''needs to be replaced'')!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000037', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-007', 'sentence_pattern', 'Participial Phrases: Klausa Pembuka Ringkas (Having analyzed..., ...)', 'V-ing ..., (Aktif bersamaan/sebab) • V3 ..., (Pasif) • Having + V3 ..., (Selesai duluan) + [SAME Subject + Verb]', 'Memadatkan anak kalimat waktu atau sebab di awal kalimat menjadi frasa partisip elegan dengan subjek yang wajib identik.', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"Having analyzed the user data, our team redesigned the onboarding flow.","reading":"/ˈhævɪŋ ˈænəlaɪzd ðə ˈjuːzər ˈdeɪtə ˈaʊər tiːm ˌriːdɪˈzaɪnd ði ˈɑːnbɔːrdɪŋ floʊ/","id":"Setelah menganalisis data pengguna, tim kami merancang ulang alur orientasi awal."},{"jp":"Founded in 1998, Google transformed how people search for information.","reading":"/ˈfaʊndɪd ɪn ˌnaɪnˈtiːn ˈnaɪnti eɪt ˈɡuːɡəl trænsˈfɔːrmd haʊ ˈpiːpəl sɜːrtʃ/","id":"Didirikan pada tahun 1998, Google mengubah cara manusia mencari informasi."}]'::jsonb, 'Having reviewed (/ˈhævɪŋ rɪˈvjuːd/) the logs, she found the root cause', '{"analogy":"Participial Phrase adalah gaya penulisan favorit jurnal ilmiah dan soal tersulit di TOEFL Structure (Dangling Modifiers)! Bayangkan gerbong pembuka tanpa subjek (''Founded in 1998, ...''): begitu tanda koma lewat, kata PERTAMA setelah koma WAJIB merupakan subjek pemilik aksi pembuka tadi! Kalau kamu menulis ''Walking into the lab, the microscope was broken'', artinya mikroskop itulah yang punya kaki dan berjalan masuk ke lab (Dangling Modifier ❌)!","when_to_use":["V-ing di awal: menggantikan ''Because / While + Subject + Verb aktif'' (''Realizing the risk, we halted deployment'')","V3 di awal: menggantikan ''Because / Although + Subject + be + V3 pasif'' (''Built on Rust, the engine runs blazingly fast'')","Having + V3 (atau pasif ''Having been + V3'') di awal: menegaskan aksi pertama SUDAH TUNTAS sebelum aksi kedua dimulai"],"formula_parts":[{"role":"verb","text":"V-ing | V3 | Having V3,","label":"Frasa Pembuka Ringkas"},{"role":"subject","text":"Matching Subject","label":"WAJIB Pelaku/Sasaran Sama!"},{"role":"predicate","text":"Main Verb + Object","label":"Induk Kalimat"}],"steps":["Periksa kata tepat setelah tanda koma! Tanyakan: apakah subjek induk kalimat ini yang MELAKUKAN (pakai V-ing / Having V3) atau DIKENAI (pakai V3) frasa pembuka tadi?","Pastikan tidak terjadi Dangling Participial: jika pembukanya ''Having completed the experiment,'', subjek setelah koma wajib peneliti manusianya (''the scientists''), BUKAN ''the results''!","Untuk bentuk negatif frasa partisip, cukup letakkan kata ''Not'' paling depan (''Not knowing the local regulations, they hired legal counsel'')."],"breakdowns":[{"tokens":[{"jp":"Not wanting","reading":"/nɑːt ˈwɑːntɪŋ/","meaning":"karena tidak ingin (negatif aktif)","role":"verb"},{"jp":"to interrupt,","reading":"/tu ˌɪntəˈrʌpt/","meaning":"menyela pembicaraan,","role":"verb"},{"jp":"Raka","reading":"/ˈrɑːkə/","meaning":"Raka (subjek yang tidak ingin menyela)","role":"subject"},{"jp":"typed his question","reading":"/taɪpt hɪz ˈkwɛstʃən/","meaning":"mengetikkan pertanyaannya","role":"predicate"},{"jp":"in the chat.","reading":"/ɪn ðə tʃæt/","meaning":"di kolom obrolan.","role":"place"}],"translation":"Karena tidak ingin menyela, Raka mengetikkan pertanyaannya di kolom obrolan."},{"tokens":[{"jp":"Equipped with","reading":"/ɪˈkwɪpt wɪð/","meaning":"dilengkapi dengan (Pasif V3)","role":"adjective"},{"jp":"dual GPUs,","reading":"/ˈduːəl ˌdʒiːpiːˈjuːz/","meaning":"dua kartu grafis,","role":"noun"},{"jp":"the workstation","reading":"/ðə ˈwɜːrkˌsteɪʃən/","meaning":"komputer kerja itu (subjek yang dilengkapi!)","role":"subject"},{"jp":"trains models rapidly.","reading":"/treɪnz ˈmɑːdəlz ˈræpɪdli/","meaning":"melatih model dengan cepat.","role":"predicate"}],"translation":"Dilengkapi dua GPU, komputer kerja tersebut melatih model dengan cepat."}],"forms":[{"label":"Aktif Sebab (V-ing)","jp":"Facing stiff competition, the firm pivoted to B2B.","reading":"/ˈfeɪsɪŋ stɪf ˌkɑːmpəˈtɪʃən ðə fɜːrm ˈpɪvətɪd/","id":"Menghadapi persaingan ketat, perusahaan itu beralih ke segmen B2B."},{"label":"Pasif Pembuka (V3)","jp":"Viewed from orbit, the archipelago looks breathtaking.","reading":"/vjuːd frʌm ˈɔːrbɪt ði ˌɑːrkɪˈpɛləɡoʊ lʊks ˈbrɛθˌteɪkɪŋ/","id":"Dilihat dari orbit, kepulauan tersebut tampak memukau."},{"label":"Tuntas Duluan (Having + V3)","jp":"Having secured seed funding, they leased an office.","reading":"/ˈhævɪŋ sɪˈkjʊrd siːd ˈfʌndɪŋ ðeɪ liːst ən ˈɔːfɪs/","id":"Setelah berhasil mengamankan pendanaan awal, mereka menyewa kantor."}],"mistakes":[{"wrong":"Reviewing the resume carefully, several typos were found by HR.","right":"Reviewing the resume carefully, HR found several typos.","why":"Dangling Modifier klasik TOEFL! Yang ''meninjau CV'' adalah ''HR'', bukan ''several typos''—maka ''HR'' wajib ditaruh tepat setelah tanda koma!"},{"wrong":"Locating in the heart of Silicon Valley, the campus attracts talent.","right":"Located in the heart of Silicon Valley, the campus attracts talent.","why":"Kampus itu ''terletak/ditempatkan'' (pasif: ''is located''), sehingga pembukanya wajib V3 (''Located''), bukan ''Locating''!"}],"quiz":[{"question":"Soal TOEFL Written Expression—pilih lanjutan yang BEBAS dari Dangling Modifier: ''Having completed three rounds of clinical trials, ___.''","options":["the FDA approval was granted to the drug","the pharmaceutical team submitted the vaccine for FDA approval","the side effects proved minimal","it was ready for mass distribution"],"answer":1,"why":"Pelaku yang ''menyelesaikan tiga tahap uji klinis'' adalah ''the pharmaceutical team'', sehingga wajib menjadi subjek tepat setelah koma!"},{"question":"Pilih bentuk partisip yang tepat: ''___ by rising interest rates, first-time homebuyers delayed their purchases.''","options":["Discouraging","Discouraged","Having discouraging","To discourage"],"answer":1,"why":"Para pembeli rumah ''merasa kecil hati / dibuat urung'' (pasif: were discouraged by...), sehingga memakai Past Participle V3 ''Discouraged''."},{"question":"Bagaimana bentuk negatif dari participial phrase ''Knowing the password, he couldn''t log in''?","options":["Don''t knowing the password, he couldn''t log in.","Not knowing the password, he couldn''t log in.","No knowing the password, he couldn''t log in.","Didn''t know the password, he couldn''t log in."],"answer":1,"why":"Semua non-finite clause (participial, gerund, infinitive) dinegatifkan cukup dengan menaruh ''Not'' di depannya (''Not knowing...'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000038', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-008', 'conjugation', 'Unreal Past: Penyesalan & Preferensi Halus (wish / if only / would rather)', 'wish + V2/were (Harapan kini) • wish + had V3 (Sesal lampau) • would rather + [Other Person] + V2', 'Mengungkapkan harapan yang berlawanan dengan kenyataan menggunakan pergeseran kata kerja mundur satu waktu.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"I wish our team had a dedicated UX researcher right now.","reading":"/aɪ wɪʃ ˈaʊər tiːm hæd ə ˈdɛdɪkeɪtɪd ˌjuːˈɛks ˈriːsɜːrtʃər raɪt naʊ/","id":"Andai saja tim kita punya peneliti UX khusus saat ini (faktanya sekarang belum punya)."},{"jp":"I''d rather you didn''t share these preliminary numbers yet.","reading":"/aɪd ˈræðər juː ˈdɪdənt ʃɛr ðiːz prɪˈlɪmənɛri ˈnʌmbərz jɛt/","id":"Saya lebih memilih Anda tidak membagikan angka-angka awal ini dulu."}]'::jsonb, 'I wish I knew (/nuː/) • wish we had started • I''d rather you didn''t (/ˈdɪdənt/)', '{"analogy":"Bedakan tajam antara ''hope'' dan ''wish''! ''Hope'' dipakai untuk hal yang MASIH MUNGKIN terjadi (''I hope you pass the test tomorrow'' → pakai Present Simple). Sebaliknya, ''wish'' dan ''if only'' dipakai ketika kenyataannya SUDAH BERLAWANAN (''Andai saja... sayang faktanya tidak!''). Karena tak nyata, mesin waktunya sama persis seperti Conditional: harapan hari ini mundur ke V2/were, dan penyesalan masa lalu mundur ke ''had + V3''!","when_to_use":["Wish / If only + Past Simple (were / could): mengeluhkan situasi saat ini yang ingin diubah (''I wish I spoke Spanish'')","Wish / If only + Past Perfect (had + V3): menyesali sesuatu yang sudah terlanjur terjadi/tidak terjadi di masa lalu","Would rather: diikuti V1 murni jika subjeknya diri sendiri (''I''d rather walk''), TAPI wajib berubah menjadi V2 jika meminta ORANG LAIN melakukan/tidak melakukan sesuatu (''I''d rather you stayed / didn''t tell'')!"],"formula_parts":[{"role":"verb","text":"wish / if only + S + V2/were","label":"Andai Sekarang Berbeda"},{"role":"verb","text":"wish / if only + S + had V3","label":"Penyesalan Masa Lalu"},{"role":"verb","text":"would rather + Orang Lain + V2","label":"Preferensi Sopan Sekarang"}],"steps":["Cek dulu apakah harapannya mungkin terjadi di masa depan biasa: jika ya, gunakan ''I hope + Present/will'', BUKAN ''wish''!","Jika berlawanan dengan fakta sekarang → ''wish + V2 / were / could V1'' (khusus keluhan atas kebiasaan menjengkelkan orang lain yang tak mau berhenti: ''I wish you WOULD stop interrupting'').","Perhatikan jebakan emas TOEFL pada ''would rather'': ''I''d rather go'' (1 subjek → V1) vs ''I''d rather YOU went / didn''t go'' (beda subjek → V2 untuk masa kini/depan!) dan ''It''s high time we LEFT'' (+ V2!)."],"breakdowns":[{"tokens":[{"jp":"She wishes","reading":"/ʃiː ˈwɪʃɪz/","meaning":"dia berharap (menyesal sekarang)","role":"verb"},{"jp":"she had negotiated","reading":"/ʃiː hæd nɪˈɡoʊʃieɪtɪd/","meaning":"dulu dia sempat menegosiasikan (had + V3)","role":"predicate"},{"jp":"her starting salary.","reading":"/hɜːr ˈstɑːrtɪŋ ˈsæləri/","meaning":"gaji awalnya.","role":"object"}],"translation":"Dia menyesal dulu tidak menegosiasikan gaji awalnya."},{"tokens":[{"jp":"It''s about time","reading":"/ɪts əˈbaʊt taɪm/","meaning":"sudah saatnya (seharusnya dari tadi!)","role":"connector"},{"jp":"we upgraded","reading":"/wiː ʌpˈɡreɪdɪd/","meaning":"kita meningkatkan (Unreal Past V2 untuk sekarang!)","role":"predicate"},{"jp":"our staging server.","reading":"/ˈaʊər ˈsteɪdʒɪŋ ˈsɜːrvər/","meaning":"server pengujian kita.","role":"object"}],"translation":"Sudah saatnya kita memperbarui server pengujian kita."}],"forms":[{"label":"Harapan Kini (Subjunctive were)","jp":"I wish the deadline weren''t so tight.","reading":"/aɪ wɪʃ ðə ˈdɛdlaɪn wɜːrnt soʊ taɪt/","id":"Andai saja tenggat waktunya tidak seketat ini."},{"label":"Penyesalan Lampau (had V3)","jp":"If only we had invested in cloud security earlier!","reading":"/ɪf ˈoʊnli wiː hæd ɪnˈvɛstɪd ɪn klaʊd sɪˈkjʊrəti ˈɜːrliər/","id":"Coba saja dulu kita berinvestasi di keamanan cloud lebih awal!"},{"label":"Would Rather (1 vs 2 Subjek)","jp":"I''d rather take the train, and I''d rather you came with me.","reading":"/aɪd ˈræðər teɪk ðə treɪn ænd aɪd ˈræðər juː keɪm wɪð miː/","id":"Saya lebih suka naik kereta, dan saya lebih suka kamu ikut bersama saya."}],"mistakes":[{"wrong":"I wish you have a safe flight tomorrow!","right":"I hope you have a safe flight tomorrow! / I wish you a safe flight!","why":"''Wish'' yang diikuti klausa S + V bermakna kontra-faktual (mustahil/sedih)! Untuk mendoakan hal baik yang nyata, gunakan ''I hope + S + V'' atau ''wish + seseorang + kata benda''."},{"wrong":"I''d rather you don''t mention this in the meeting tomorrow.","right":"I''d rather you didn''t mention this in the meeting tomorrow.","why":"Ketika ''would rather'' diikuti subjek baru (''you''), kata kerjanya wajib menggunakan Unreal Past (''didn''t mention'') meskipun waktunya besok!"}],"quiz":[{"question":"Pilih jawaban yang tepat untuk soal TOEFL Structure: ''I''d rather you ___ the contract until our attorney reviews it tomorrow.''","options":["don''t sign","not sign","didn''t sign","won''t sign"],"answer":2,"why":"''Would rather'' diikuti subjek berbeda (''you'') untuk masa kini/depan menuntut bentuk Past Simple (''didn''t sign'')."},{"question":"Lengkapi penyesalan masa lalu berikut: ''Many graduates wish they ___ more internships while they were in college.''","options":["took","had taken","would take","have taken"],"answer":1,"why":"Penyesalan atas masa lalu (''while they were in college'') setelah ''wish'' wajib menggunakan Past Perfect (''had taken'')."},{"question":"Apa arti dari ungkapan idiomatis ''It''s high time the city fixed these potholes''?","options":["Pemerintah kota sudah memperbaiki jalan berlubang itu tahun lalu","Sudah terlambat sedikit / sudah semestinya dari tadi pemerintah kota memperbaiki jalan berlubang ini sekarang","Jalan berlubang itu berada di dataran tinggi","Pemerintah kota tidak boleh memperbaikinya"],"answer":1,"why":"''It''s (high/about) time + S + V2'' memakai Unreal Past untuk menekankan sesuatu yang seharusnya sudah dilakukan sekarang."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000039', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-009', 'particle', 'Correlative Conjunctions: Konjungsi Berpasangan & Subjek (not only... but also)', 'both A and B (+ Plural V) • either A or B / neither A nor B / not only A but also B (+ Verb ikuti B terdekat!)', 'Menjaga keseimbangan struktur paralel pada konjungsi berpasangan sekaligus menguasai aturan kesesuaian kata kerja terdekat.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"Neither the manager nor the developers were aware of the outage.","reading":"/ˈniːðər ðə ˈmænɪdʒər nɔːr ðə dɪˈvɛləpərz wɜːr əˈwɛr əv ði ˈaʊtɪdʒ/","id":"Baik manajer maupun para pengembang tidak menyadari adanya gangguan tersebut."},{"jp":"The course teaches not only how to write clean code but also how to scale systems.","reading":"/ðə kɔːrs ˈtiːtʃɪz nɑːt ˈoʊnli haʊ tə raɪt kliːn koʊd bʌt ˈɔːlsoʊ haʊ tə skeɪl ˈsɪstəmz/","id":"Kursus ini mengajarkan bukan hanya cara menulis kode rapi melainkan juga cara menskalakan sistem."}]'::jsonb, 'Neither the PM nor the engineers are... • Neither the engineers nor the PM is...', '{"analogy":"Correlative Conjunctions adalah ''timbangan dua piring'' yang diuji hampir di setiap tes TOEFL! Hukum #1 (Pasangan Setia): ''neither'' HARUS kawin dengan ''nor'' (bukan ''or''!), ''either'' dengan ''or'', ''both'' dengan ''and'' (bukan ''as well as''!). Hukum #2 (Paralel): jika setelah ''not only'' berupa V-ing, maka setelah ''but also'' wajib V-ing juga! Hukum #3 (Proximity Rule): selain ''both...and'' yang selalu jamak, kata kerja selalu tunduk mengikuti subjek yang PALING DEKAT dengannya!","when_to_use":["Menekankan dua keunggulan sekaligus dengan ''both A and B'' (selalu dihitung jamak) atau ''not only A but also B''","Menyatakan pilihan di antara dua opsi (''either A or B'') atau menolak keduanya sekaligus (''neither A nor B'')","Menjaga keseimbangan gramatikal (Parallel Structure) dalam esai TOEFL Writing dan presentasi eksekutif"],"formula_parts":[{"role":"connector","text":"neither...nor / either...or","label":"Pasangan Baku Tak Terpisahkan"},{"role":"subject","text":"Noun A ... Noun B","label":"Elemen A & B Wajib Setara"},{"role":"verb","text":"Verb agrees with B!","label":"Ikuti Subjek Terdekat (B)"}],"steps":["Cek jodoh konjungsinya lebih dulu: both ↔ and, either ↔ or, neither ↔ nor, not only ↔ but also, whether ↔ or.","Cek kesetaraan bentuk (Parallelism): tempatkan kata pembuka tepat sebelum elemen yang dibandingkan! Jika membandingkan dua preposisi (''in Jakarta'' dan ''in Bali''), tulis ''not only IN Jakarta but also IN Bali''.","Saat pasangan ini menjadi subjek kalimat: ''Both A and B'' → selalu Verb Jamak (''are''); untuk ''Either...or / Neither...nor / Not only...but also'' → lirik HANYA kata benda B yang nempel tepat di kiri kata kerja!"],"breakdowns":[{"tokens":[{"jp":"Not only","reading":"/nɑːt ˈoʊnli/","meaning":"tidak hanya","role":"connector"},{"jp":"the interns","reading":"/ði ˈɪntɜːrnz/","meaning":"para pemagang (jamak - jauh)","role":"subject"},{"jp":"but also","reading":"/bʌt ˈɔːlsoʊ/","meaning":"tetapi juga","role":"connector"},{"jp":"the director","reading":"/ðə dəˈrɛktər/","meaning":"sang direktur (tunggal - TERDEKAT!)","role":"subject"},{"jp":"attends","reading":"/əˈtɛndz/","meaning":"menghadiri (ikut tunggal -s!)","role":"verb"},{"jp":"the weekly demo.","reading":"/ðə ˈwiːkli ˈdɛmoʊ/","meaning":"demo mingguan.","role":"object"}],"translation":"Bukan hanya para pemagang, sang direktur pun turut menghadiri demo mingguan."},{"tokens":[{"jp":"Both","reading":"/boʊθ/","meaning":"baik","role":"connector"},{"jp":"accuracy","reading":"/ˈækjərəsi/","meaning":"akurasi","role":"subject"},{"jp":"and","reading":"/ænd/","meaning":"maupun (wajib ''and'')","role":"connector"},{"jp":"speed","reading":"/spiːd/","meaning":"kecepatan","role":"subject"},{"jp":"are critical.","reading":"/ɑːr ˈkrɪtɪkəl/","meaning":"sangat krusial (selalu jamak).","role":"predicate"}],"translation":"Baik akurasi maupun kecepatan sama-sama sangat krusial."}],"forms":[{"label":"Subjek Terdekat Tunggal","jp":"Either the cables or the router is faulty.","reading":"/ˈiːðər ðə ˈkeɪbəlz ɔːr ðə ˈraʊtər ɪz ˈfɔːlti/","id":"Entah kabel-kabelnya atau routernya yang bermasalah (''the router'' tunggal → ''is'')."},{"label":"Subjek Terdekat Jamak","jp":"Either the router or the cables are faulty.","reading":"/ˈiːðər ðə ˈraʊtər ɔːr ðə ˈkeɪbəlz ɑːr ˈfɔːlti/","id":"Entah routernya atau kabel-kabelnya yang bermasalah (''the cables'' jamak → ''are'')."},{"label":"Parallel Verbs","jp":"She neither confirmed nor denied the rumor.","reading":"/ʃiː ˈniːðər kənˈfɜːrmd nɔːr dɪˈnaɪd ðə ˈruːmər/","id":"Dia tidak membenarkan maupun membantah rumor tersebut (V2 sejajar dengan V2)."}],"mistakes":[{"wrong":"Both Tokyo as well as Singapore have world-class transit.","right":"Both Tokyo and Singapore have world-class transit.","why":"Jebakan klasik TOEFL Written Expression: pasangan sah dari ''Both'' hanyalah ''and'', BUKAN ''as well as''!"},{"wrong":"He not only speaks fluent English, but also Japanese.","right":"He speaks not only fluent English but also conversational Japanese.","why":"Dalam contoh salah, ''not only'' ditaruh di depan kata kerja (''speaks'') padahal ''but also'' diikuti kata benda (''Japanese'')—taruh ''not only'' tepat setelah ''speaks'' agar sejajar Noun dengan Noun!"}],"quiz":[{"question":"Soal kesesuaian subjek TOEFL: ''Neither the lead researcher nor her lab assistants ___ able to replicate the anomaly.''","options":["was","were","is","has been"],"answer":1,"why":"Pada ''Neither A nor B'', kata kerja mengikuti subjek terdekat B (''her lab assistants'' = jamak → ''were'')."},{"question":"Pilih kalimat yang memenuhi aturan Parallel Structure:","options":["The fellowship covers both tuition fees as well as living expenses.","The fellowship covers not only tuition fees but also living expenses.","The fellowship not only covers tuition fees but also living expenses.","Neither the fellowship covers tuition or living expenses."],"answer":1,"why":"Setelah ''covers'', frasa ''not only [tuition fees] but also [living expenses]'' menyejajarkan dua Noun Phrase secara presisi."},{"question":"Berbeda dari ''not only A but also B'', bagaimana aturan kata kerja untuk ''A, as well as B, ___'' (misal: ''The CEO, as well as the VPs, ___ attending'')?","options":["Selalu jamak (''are'')","Mengikuti subjek pertama A (''The CEO'' → tunggal ''is'') karena '', as well as B,'' hanya sisipan pengiring!","Mengikuti subjek kedua B (''the VPs'' → ''are'')","Memakai V1 tanpa be"],"answer":1,"why":"Frasa pengiring seperti ''as well as'', ''along with'', dan ''together with'' TIDAK mengubah jumlah subjek pertama (''The CEO'' tunggal → ''is'')!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000040', 'e1000001-0000-4000-8000-000000000004', 'GP-EN-B2-010', 'honorific', 'Diplomatic Hedging: Bahasa Lunak Rapat & Review (It seems / tend to / might want to)', 'It seems/appears that... • tend to + V1 • You might want to + V1 • a bit / slightly + Negative Adj', 'Menyampaikan kritik kode, ketidaksetujuan rapat, dan koreksi kepada kolega global secara taktis tanpa terkesan konfrontatif.', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"You might want to add error handling here in case the API times out.","reading":"/juː maɪt wɑːnt tu æd ˈɛrər ˈhændlɪŋ hɪr ɪn keɪs ði ˌeɪpiːˈaɪ taɪmz aʊt/","id":"Ada baiknya Anda menambahkan penanganan galat di sini kalau-kalau API-nya habis waktu."},{"jp":"It seems that our current approach isn''t quite scalable enough.","reading":"/ɪt siːmz ðæt ˈaʊər ˈkɜːrənt əˈproʊtʃ ˈɪzənt kwaɪt ˈskeɪləbəl ɪˈnʌf/","id":"Tampaknya pendekatan kita saat ini belum cukup mudah untuk diskalakan."}]'::jsonb, 'You might want to (/maɪt ˈwɑːnt tə/) consider... • It seems there''s a slight delay', '{"analogy":"Di budaya kerja perusahaan teknologi AS, mengatakan ''Your code is wrong—change it'' terdengar kasar dan mematikan kolaborasi, sementara berputar-putar terlalu kabur membuat pesan tidak sampai. ''Diplomatic Hedging'' adalah seni melapisi kritik tajam dengan bantalan beludru: ubah tuduhan langsung menjadi observasi objektif (''It seems...''), ubah perintah jadi saran otonom (''You might want to...''), dan ubah kata sifat negatif mutlak menjadi bentuk negatif dari kata sifat positif (''not quite clear'' alih-alih ''confusing'')!","when_to_use":["Memberi masukan pada Pull Request (code review), dokumen desain, atau draf rekan kerja (''You might want to...'', ''Have we considered...?'')","Menyampaikan kabar kurang baik atau ketidaksetujuan di depan klien/atasan (''It appears there may be a slight bottleneck'')","Menghindari generalisasi berlebihan dalam TOEFL Speaking & Writing menggunakan ''tend to + V1'' (''cenderung'') alih-alih ''always''"],"formula_parts":[{"role":"connector","text":"It seems / appears (that)","label":"Observasi Objektif"},{"role":"verb","text":"tend to / might want to + V1","label":"Kecenderungan / Saran Halus"},{"role":"adjective","text":"not quite + Positive Adj","label":"Pelembut Kritik Elegan"}],"steps":["Ganti perintah ''You should / You must change X'' di code review menjadi ''You might want to consider changing X'' atau pertanyaan kolaboratif ''What if we tried X?''.","Gunakan ''not very / not quite + Kata Sifat Positif'' (''isn''t very intuitive'') ketimbang kata sifat keras (''is terrible / confusing'').","Dalam argumen esai/presentasi, ganti klaim 100% absolut (''Remote workers are lonely'' ❌) dengan frekuensi terukur: ''Remote workers sometimes tend to experience isolation'' ✅."],"breakdowns":[{"tokens":[{"jp":"I see your point,","reading":"/aɪ siː jʊr pɔɪnt/","meaning":"saya paham maksud Anda (validasi pembuka),","role":"connector"},{"jp":"though","reading":"/ðoʊ/","meaning":"namun (lebih lunak dari ''but'')","role":"connector"},{"jp":"enterprise users","reading":"/ˈɛntərpraɪz ˈjuːzərz/","meaning":"pengguna korporat","role":"subject"},{"jp":"tend to prefer","reading":"/tɛnd tə prɪˈfɜːr/","meaning":"cenderung lebih memilih","role":"verb"},{"jp":"SSO login.","reading":"/ˌɛsɛsˈoʊ ˈlɔːɡɪn/","meaning":"masuk akun lewat SSO.","role":"object"}],"translation":"Saya memahami poin Anda, namun pengguna korporat cenderung lebih memilih login SSO."},{"tokens":[{"jp":"This timeline","reading":"/ðɪs ˈtaɪmlaɪn/","meaning":"linimasa ini","role":"subject"},{"jp":"looks","reading":"/lʊks/","meaning":"terlihat","role":"verb"},{"jp":"a bit","reading":"/ə bɪt/","meaning":"sedikit (downtoner)","role":"particle"},{"jp":"ambitious.","reading":"/æmˈbɪʃəs/","meaning":"terlalu ambisius (= hampir mustahil).","role":"adjective"}],"translation":"Linimasa ini terlihat sedikit terlalu ambisius."}],"forms":[{"label":"Saran Code Review","jp":"We might want to cache this query to reduce latency.","reading":"/wiː maɪt wɑːnt tə kæʃ ðɪs ˈkwɪri tə rɪˈduːs ˈleɪtənsi/","id":"Sebaiknya kita menyimpan kueri ini di cache untuk menekan latensi."},{"label":"Ketidaksetujuan Taktis","jp":"I''m not entirely convinced that''s the root cause.","reading":"/aɪm nɑːt ɪnˈtaɪərli kənˈvɪnst ðæts ðə ruːt kɔːz/","id":"Saya belum sepenuhnya yakin bahwa itu akar masalahnya."},{"label":"Generalisasi Aman TOEFL","jp":"Startups tend to iterate faster than legacy corporations.","reading":"/ˈstɑːrtʌps tɛnd tu ˈɪtəreɪt ˈfæstər ðæn ˈlɛɡəsi ˌkɔːrpəˈreɪʃənz/","id":"Perusahaan rintisan cenderung beriterasi lebih cepat daripada korporasi lama."}],"mistakes":[{"wrong":"Your slide design is ugly and unreadable.","right":"The text on this slide isn''t quite readable from the back—we might want to bump up the font size.","why":"Kritik personal langsung terdengar tidak profesional; fokuskan pada objeknya (''the text'') dengan negasi positif (''isn''t quite readable'') + solusi."},{"wrong":"A bit good / slightly awesome","right":"a bit slow / slightly delayed","why":"Pelembut ''a bit'' dan ''slightly'' secara alami berpasangan dengan sifat bermasalah/negatif atau komparatif (''a bit faster''), bukan kata sifat pujian ekstrem!"}],"quiz":[{"question":"Dalam rapat AS, ketika manajer berkata ''You might want to double-check slide 4 before the client call'', apa maksud sebenarnya?","options":["Boleh dicek kalau kamu lagi iseng saja, tidak penting","Ada kesalahan/hal krusial di slide 4—tolong segera periksa dan perbaiki sebelum rapat klien!","Slide 4 sudah sempurna tanpa cela","Manajer yang akan memperbaiki slide 4 sendiri"],"answer":1,"why":"Dalam komunikasi kerja Amerika (sering keluar di TOEFL Listening pragmatics!), ''You might want to...'' adalah cara halus menyampaikan koreksi atau instruksi penting!"},{"question":"Pilih kalimat yang paling tepat secara akademik untuk menghindari klaim absolut yang lemah di esai TOEFL:","options":["Public transit always eliminates all pollution.","Expanding public transit tends to reduce urban carbon emissions.","Public transit is a bit incredible.","Everyone in cities hates cars."],"answer":1,"why":"''Tends to reduce'' menunjukkan ketelitian ilmiah tanpa klaim ekstrem yang mudah dipatahkan."},{"question":"Manakah cara paling diplomatis untuk menolak ide rekan di rapat?","options":["That makes zero sense.","You''re completely wrong about the budget.","I see where you''re coming from, though I''m slightly concerned about the maintenance cost.","No, we won''t do that."],"answer":2,"why":"Mengakui sudut pandang lawan bicara terlebih dahulu (''I see where you''re coming from'') lalu menyisipkan kekhawatiran terukur (''slightly concerned'') adalah standar emas komunikasi eksekutif."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000041', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-001', 'sentence_pattern', 'Negative Inversion: Penekanan Terbalik (Not only did... / Rarely have...)', '[Negative / Limiting Adverbial] + Auxiliary (do/does/did/have/can/is) + [Subject] + [Main Verb]', 'Membalik urutan kata bantu ke depan subjek setelah kata keterangan negatif/pembatas di awal kalimat untuk penekanan retoris tingkat tinggi.', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"Not only did the new model cut latency in half, but it also lowered GPU costs.","reading":"/nɑːt ˈoʊnli dɪd ðə nuː ˈmɑːdəl kʌt ˈleɪtənsi ɪn hæf bʌt ɪt ˈɔːlsoʊ ˈloʊərd kɔːsts/","id":"Model baru ini bukan hanya memangkas latensi hingga separuhnya, melainkan juga menurunkan biaya GPU."},{"jp":"Rarely have researchers observed such rapid cellular regeneration.","reading":"/ˈrɛrli hæv ˈriːsɜːrtʃərz əbˈzɜːrvd sʌtʃ ˈræpɪd ˈsɛljələr rɪˌdʒɛnəˈreɪʃən/","id":"Sangat jarang para peneliti mengamati regenerasi seluler yang begitu cepat."}]'::jsonb, 'Not only did (/dɪd/) it cut costs, ... • Rarely have (/hæv/) we seen...', '{"analogy":"Bayangkan lampu sorot panggung teater! Dalam kalimat biasa (''We have rarely seen...''), alurnya datar. Tapi begitu kamu menyeret kata negatif/langka (''Never, Rarely, Seldom, Little, Under no circumstances, Not only'') ke ujung PALING DEPAN kalimat, kalimat mengalami efek kejut sehingga kata bantu wajib ''salto'' melompati subjek persis seperti formasi kalimat tanya—meskipun diakhiri tanda titik!","when_to_use":["Mencetak skor tinggi di TOEFL Writing & pidato formal dengan satu kalimat berinversi yang dramatis (''Not only does..., but...'')","Menjawab soal favorit level sulit TOEFL Structure setelah pembuka ''Never, Rarely, Seldom, Hardly...when, No sooner...than, Little''","Menegaskan larangan mutlak dalam dokumen kebijakan (''Under no circumstances should employees share API keys'')"],"formula_parts":[{"role":"connector","text":"Never / Rarely / Not only / Only after...","label":"Pemicu Negatif di Awal"},{"role":"particle","text":"did / does / have / should","label":"Auxiliary Lompat ke Depan!"},{"role":"subject","text":"Subject","label":"Subjek"},{"role":"verb","text":"Base / V3 Verb","label":"Kata Kerja Utama"}],"steps":["Kenali pemicu inversi: kata negatif murni (''Never, Under no circumstances, At no time''), kata hampir negatif (''Rarely, Seldom, Hardly, Scarcely, Little''), dan frasa ''Only...'' (''Only by, Only when, Only after'').","Balikkan Auxiliary + Subject! Jika tidak ada ''have/be/modal'', panggil ''do/does/did'' lalu kembalikan verba ke V1 (''Little DID he KNOW''—bukan ''Little he knew''!).","Jebakan super licik pada ''Only when / Only after / Not until'' yang diikuti dua klausa: JANGAN menginversi klausa pertamanya! Inversi terjadi di INDUK KALIMAT kedua (''Only when the server crashed DID we realize the flaw'')!"],"breakdowns":[{"tokens":[{"jp":"Little","reading":"/ˈlɪtəl/","meaning":"sama sekali tidak sedikit pun","role":"connector"},{"jp":"did","reading":"/dɪd/","meaning":"(kata bantu inversi lampau)","role":"particle"},{"jp":"the founders","reading":"/ðə ˈfaʊndərz/","meaning":"para pendiri itu","role":"subject"},{"jp":"realize","reading":"/ˈriːəlaɪz/","meaning":"menyadari (kembali V1!)","role":"verb"},{"jp":"how fast it would grow.","reading":"/haʊ fæst ɪt wʊd ɡroʊ/","meaning":"betapa cepat produk itu akan tumbuh.","role":"object"}],"translation":"Para pendiri itu sama sekali tidak menyangka betapa cepat produk tersebut akan berkembang."},{"tokens":[{"jp":"Only by automating QA","reading":"/ˈoʊnli baɪ ˈɔːtəmeɪtɪŋ ˌkjuːˈeɪ/","meaning":"hanya dengan mengotomatiskan QA","role":"connector"},{"jp":"can","reading":"/kæn/","meaning":"dapat (modal di depan subjek!)","role":"particle"},{"jp":"our team","reading":"/ˈaʊər tiːm/","meaning":"tim kami","role":"subject"},{"jp":"ship daily releases.","reading":"/ʃɪp ˈdeɪli rɪˈliːsɪz/","meaning":"merilis pembaruan harian.","role":"predicate"}],"translation":"Hanya dengan mengotomatiskan pengujian kualitas, tim kami dapat merilis pembaruan setiap hari."}],"forms":[{"label":"No sooner ... than","jp":"No sooner had we deployed the patch than traffic spiked.","reading":"/noʊ ˈsuːnər hæd wiː dɪˈplɔɪd ðə pætʃ ðæn ˈtræfɪk spaɪkt/","id":"Baru saja kami menayangkan tambalan tersebut, trafik langsung melonjak."},{"label":"Only after (+ Inversi di Klausa 2!)","jp":"Only after the audit ended did the board approve the merger.","reading":"/ˈoʊnli ˈæftər ði ˈɔːdɪt ˈɛndɪd dɪd ðə bɔːrd əˈpruːv ðə ˈmɜːrdʒər/","id":"Baru setelah audit selesai, dewan direksi menyetujui merger tersebut."},{"label":"Kebijakan Ketat","jp":"Under no circumstances are interns permitted to alter production data.","reading":"/ˈʌndər noʊ ˈsɜːrkəmstænsɪz ɑːr ˈɪntɜːrnz pərˈmɪtɪd/","id":"Dalam kondisi apa pun pemagang tidak diizinkan mengubah data produksi."}],"mistakes":[{"wrong":"Not only the algorithm improved accuracy, but it also saved memory.","right":"Not only did the algorithm improve accuracy, but it also saved memory.","why":"Ketika ''Not only'' membuka seluruh klausa dari awal kalimat, klausa pertamanya wajib diinversi (''did the algorithm improve''), sedangkan klausa keduanya tetap normal!"},{"wrong":"Only when did the alarm ring we evacuated the lab.","right":"Only when the alarm rang did we evacuate the lab.","why":"Pada ''Only when + Klausa 1, Klausa 2'', klausa waktu pertama berjalan normal (''the alarm rang''), dan inversi baru terjadi pada induk kalimat kedua (''did we evacuate'')!"}],"quiz":[{"question":"Soal klasik skor tinggi TOEFL Structure: ''Seldom ___ a single technological breakthrough reshaped global supply chains so rapidly.''","options":["it has","has","did it had","that has"],"answer":1,"why":"Pembuka negatif ''Seldom'' memicu inversi Auxiliary + Subject + V3: ''Seldom has [a single technological breakthrough] reshaped...''."},{"question":"Perhatikan pasangan konjungsi untuk ''Hardly / Scarcely'' vs ''No sooner'': ''No sooner had the keynote begun ___ the livestream crashed.''","options":["when","than","then","that"],"answer":1,"why":"''No sooner'' adalah bentuk komparatif (''sooner'') sehingga wajib berpasangan dengan ''than'' (sedangkan ''Hardly/Scarcely'' berpasangan dengan ''when'')."},{"question":"Pilih susunan yang tepat setelah ''Not until'': ''Not until the 1990s ___ accessible to the general public.''","options":["the World Wide Web became","did the World Wide Web become","became the World Wide Web","did the World Wide Web became"],"answer":1,"why":"Frasa negatif ''Not until the 1990s'' memicu inversi di induk kalimat: ''did + Subject + V1 (become)''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000042', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-002', 'conjugation', 'Mandative Subjunctive: Rekomendasi & Proposal (essential that he submit)', '[recommend / suggest / insist / demand / It is essential / vital] + that + [Subject] + (not) + V1 Murni / be', 'Menggunakan kata kerja dasar telanjang (tanpa -s, tanpa -ed, ''be'' utuh, negatif ''not + V1'') setelah kata desakan atau kepentingan di Bahasa Inggris Amerika.', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"The committee recommended that each applicant submit a portfolio.","reading":"/ðə kəˈmɪti ˌrɛkəˈmɛndɪd ðæt iːtʃ ˈæplɪkənt səbˈmɪt ə pɔːrtˈfoʊlioʊ/","id":"Komite merekomendasikan agar setiap pelamar menyerahkan portofolio."},{"jp":"It is imperative that confidential records not be stored locally.","reading":"/ɪt ɪz ɪmˈpɛrətɪv ðæt ˌkɑːnfɪˈdɛnʃəl ˈrɛkərdz nɑːt biː stɔːrd ˈloʊkəli/","id":"Sangat mutlak bahwa catatan rahasia tidak disimpan di perangkat lokal."}]'::jsonb, 'essential that she submit (/səbˈmɪt/ TANPA -s!) • insist that he be (/biː/) notified', '{"analogy":"Sekilas kalimat ''It is vital that she SUBMIT the report'' terlihat salah ketik karena ''she'' tidak pakai ''-s''! Padahal inilah ciri khas kebanggaan American Formal English yang SELALU keluar di TOEFL! Begitu ada kata kerja tuntutan/saran (''suggest, recommend, insist, require, demand, propose'') atau kata sifat urgensi (''essential, vital, crucial, mandatory, imperative'') + ''that'', waktu seolah dibekukan: kata kerjanya wajib kembali ke bentuk paling telanjang (V1 murni, ''be'' utuh, dan negatifnya cukup ''not + V1'' tanpa don''t/doesn''t)!","when_to_use":["Menulis rekomendasi kebijakan, notula rapat direksi, kontrak hukum, atau esai solusi di TOEFL Writing","Setelah verba mandatif: suggest, recommend, propose, insist, demand, request, require, ask, urge + that","Setelah adjektiva/nomina urgensi: It is essential / vital / crucial / imperative / mandatory / necessary / important + that"],"formula_parts":[{"role":"verb","text":"recommend / It is vital","label":"Pemicu Urgensi / Desakan"},{"role":"connector","text":"that + Subject","label":"Berlaku Semua Subjek"},{"role":"verb","text":"(not) + Base Verb / be","label":"TANPA -s, -ed, don''t, atau should!"}],"steps":["Waspadai kata pemicu di depan ''that'': meskipun verba utamanya lampau (''The doctor ADVISED that...'' atau ''They INSISTED that...''), kata kerja di dalam klausa ''that'' TETAP V1 telanjang, tidak ikut jadi V2!","Untuk kalimat pasif di dalam Subjunctive, gunakan ''be + V3'' (''demanded that the fee BE waived'', bukan ''is/was waived'').","Untuk kalimat negatif di dalam Subjunctive, JANGAN pakai ''doesn''t / didn''t''—langsung pasang ''not + V1'' (''suggested that he NOT sign yet'')!"],"breakdowns":[{"tokens":[{"jp":"Our auditor insisted","reading":"/ˈaʊər ˈɔːdɪtər ɪnˈsɪstɪd/","meaning":"auditor kami bersikeras (meski V2 lampau!)","role":"verb"},{"jp":"that the CFO","reading":"/ðæt ðə ˌsiːɛfˈoʊ/","meaning":"agar direktur keuangan (subjek tunggal)","role":"subject"},{"jp":"be present","reading":"/biː ˈprɛzənt/","meaning":"hadir (wajib ''be'' murni, bukan was/is!)","role":"predicate"},{"jp":"during the review.","reading":"/ˈdʊrɪŋ ðə rɪˈvjuː/","meaning":"selama peninjauan.","role":"time"}],"translation":"Auditor kami bersikeras agar direktur keuangan hadir selama peninjauan."},{"tokens":[{"jp":"She proposed","reading":"/ʃiː prəˈpoʊzd/","meaning":"dia mengusulkan","role":"verb"},{"jp":"that the team","reading":"/ðæt ðə tiːm/","meaning":"agar tim tersebut","role":"subject"},{"jp":"not delay","reading":"/nɑːt dɪˈleɪ/","meaning":"tidak menunda (negatif murni: not + V1)","role":"verb"},{"jp":"the security patch.","reading":"/ðə sɪˈkjʊrəti pætʃ/","meaning":"tambalan keamanan itu.","role":"object"}],"translation":"Dia mengusulkan agar tim tidak menunda tambalan keamanan tersebut."}],"forms":[{"label":"Aktif Orang ke-3 (Tanpa -s)","jp":"Regulations require that every pilot undergo annual testing.","reading":"/ˌrɛɡjəˈleɪʃənz rɪˈkwaɪər ðæt ˈɛvri ˈpaɪlət ˌʌndərˈɡoʊ/","id":"Regulasi mewajibkan agar setiap pilot menjalani pengujian tahunan."},{"label":"Pasif Subjunctive (be + V3)","jp":"It is crucial that patient data be anonymized.","reading":"/ɪt ɪz ˈkruːʃəl ðæt ˈpeɪʃənt ˈdeɪtə biː əˈnɑːnɪmaɪzd/","id":"Sangat krusial agar data pasien dianonimkan."},{"label":"Negatif Subjunctive (not + V1)","jp":"The mentor advised that she not take five heavy courses at once.","reading":"/ðə ˈmɛntɔːr ədˈvaɪzd ðæt ʃiː nɑːt teɪk faɪv ˈhɛvi ˈkɔːrsɪz/","id":"Mentor menyarankan agar dia tidak mengambil lima mata kuliah berat sekaligus."}],"mistakes":[{"wrong":"The professor suggested us to narrow our thesis topic.","right":"The professor suggested that we narrow our thesis topic.","why":"Jebakan maut! ''Suggest'' dan ''recommend'' TIDAK PERNAH berpola ''suggest + somebody + to V1''—gunakan ''suggest + that + S + V1'' atau ''suggest + V-ing''!"},{"wrong":"Note: ''insist'' untuk FAKTA vs TUNTUTAN! (The witness insisted that he saw/had seen the car).","right":"Tuntutan: ''He insisted that she apologize'' vs Fakta: ''He insisted that he was innocent''.","why":"Jika ''insist'' atau ''suggest'' berarti mengklaim fakta yang sudah terjadi (bukan menuntut seseorang berbuat sesuatu), gunakan tenses normal, bukan subjunctive!"}],"quiz":[{"question":"Soal ikonik TOEFL Structure (American English): ''The hospital board mandated that every surgeon ___ sterile protocol prior to entering the suite.''","options":["follows","followed","follow","to follow"],"answer":2,"why":"Setelah verba mandatif ''mandated that'', subjek tunggal ''every surgeon'' diikuti Subjunctive V1 murni ''follow'' tanpa ''-s'' dan tanpa ''-ed''!"},{"question":"Pilih bentuk negatif Subjunctive yang benar: ''Legal counsel recommended that the CEO ___ on the pending lawsuit.''","options":["doesn''t comment","didn''t comment","not comment","not to comment"],"answer":2,"why":"Negasi dalam Mandative Subjunctive dibentuk langsung dengan ''not + bare infinitive'' (''not comment'') tanpa kata bantu ''do/does/did''."},{"question":"Manakah kalimat yang SALAH secara tata bahasa?","options":["I recommend taking the express train.","I recommend that you take the express train.","I recommend you to take the express train.","It is recommended that passengers arrive early."],"answer":2,"why":"Berbeda dari ''advise/ask someone to do'', kata kerja ''recommend'' dan ''suggest'' TIDAK BISA diikuti ''someone + to V1''!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000043', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-003', 'sentence_pattern', 'Cleft & Pseudo-Cleft Sentences: Fokus Tajam (It was... that / What... is)', 'It-Cleft: It is/was + [Focused Element] + that/who + [Rest] • Wh-Cleft: What + [Clause] + is/was + [Focus]', 'Membelah kalimat tunggal menjadi dua bagian layaknya lampu sorot untuk menonjolkan satu informasi krusial dalam argumen.', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"It was poor onboarding—not pricing—that caused the high churn rate.","reading":"/ɪt wəz pʊr ˈɑːnbɔːrdɪŋ nɑːt ˈpraɪsɪŋ ðæt kɔːzd ðə haɪ tʃɜːrn reɪt/","id":"Orientasi awal yang buruklah—bukan harga—yang menyebabkan tingginya tingkat berhenti langganan."},{"jp":"What sets great engineers apart is their ability to simplify complexity.","reading":"/wʌt sɛts ɡreɪt ˌɛndʒɪˈnɪrz əˈpɑːrt ɪz ðɛr əˈbɪləti tə ˈsɪmplɪfaɪ kəmˈplɛksəti/","id":"Hal yang membedakan insinyur hebat adalah kemampuan mereka menyederhanakan kerumitan."}]'::jsonb, 'It was latency that killed conversion • What drives growth is retention', '{"analogy":"Dalam tulisan tidak ada intonasi suara untuk menekan kata penting. ''Cleft'' (artinya ''belahan'') adalah teknik membelah kalimat datar (''Retention drives growth'') menjadi panggung dramatis: bisa memakai bingkai penunjuk ''It is [RETENTION] that drives growth'' (seperti imbuhan ''-lah'' di Bahasa Indonesia: ''Retensilah yang...''), atau memakai pembuka penasaran ''What drives growth is [RETENTION]'' (''Apa yang mendorong pertumbuhan adalah...'')!","when_to_use":["Meluruskan kesalahpahaman atau mengoreksi asumsi lawan debat dengan It-Cleft (''It wasn''t the budget that failed us; it was execution'')","Membuka poin utama presentasi atau paragraf topik TOEFL Writing dengan Pseudo-Cleft (''What we need most right now is...'')","Menekankan tindakan dengan ''What + S + do + is/was + (to) V1'' (''What the patch does is block unauthorized requests'')"],"formula_parts":[{"role":"particle","text":"It is/was + [FOKUS] + that/who","label":"It-Cleft (''...-lah yang...'')"},{"role":"subject","text":"What + (S) + V","label":"Wh-Cleft (Subjek Tunggal)"},{"role":"predicate","text":"is / was + [FOKUS]","label":"Puncak Informasi Baru"}],"steps":["Untuk It-Cleft: selalu gunakan ''It is'' atau ''It was'' (meskipun elemen yang disorot jamak, tetap ''It was the engineers who...'', BUKAN ''They were''!), lalu sambung dengan ''who'' (orang) atau ''that'' (benda/waktu/tempat/alasan).","Untuk Wh-Cleft (''What...''): klausa ''What...'' di awal kalimat umumnya dihitung TUNGGAL (''What matters most IS...''), kecuali pelengkap di belakangnya berupa kata benda jamak yang jelas.","Jika Wh-Cleft menyorot kata kerja menggunakan ''What + S + do/did + is/was...'', bagian setelah ''is/was'' diikuti ''(to) + V1'' (''What we did was rebuild the index'')."],"breakdowns":[{"tokens":[{"jp":"It wasn''t until 2023","reading":"/ɪt ˈwʌzənt ənˈtɪl ˈtwɛnti ˈtwɛnti θriː/","meaning":"baru pada tahun 2023-lah (It-Cleft waktu)","role":"time"},{"jp":"that","reading":"/ðæt/","meaning":"bahwa / ketika (wajib ''that'', bukan ''when''!)","role":"connector"},{"jp":"generative AI","reading":"/ˈdʒɛnərətɪv ˌeɪˈaɪ/","meaning":"AI generatif","role":"subject"},{"jp":"entered mainstream workflows.","reading":"/ˈɛntərd ˈmeɪnstriːm ˈwɜːrkfloʊz/","meaning":"memasuki alur kerja arus utama.","role":"predicate"}],"translation":"Baru pada tahun 2023-lah AI generatif memasuki alur kerja arus utama."},{"tokens":[{"jp":"What","reading":"/wʌt/","meaning":"hal yang (= the thing that)","role":"subject"},{"jp":"we did first","reading":"/wiː dɪd fɜːrst/","meaning":"kami lakukan pertama kali","role":"verb"},{"jp":"was","reading":"/wʌz/","meaning":"adalah (tunggal lampau)","role":"verb"},{"jp":"interview power users.","reading":"/ˈɪntərvjuː ˈpaʊər ˈjuːzərz/","meaning":"mewawancarai pengguna aktif ((to) + V1).","role":"predicate"}],"translation":"Hal pertama yang kami lakukan adalah mewawancarai para pengguna aktif."}],"forms":[{"label":"It-Cleft Waktu (It wasn''t until...that)","jp":"It was in Seattle that they met their seed investors.","reading":"/ɪt wəz ɪn siˈætəl ðæt ðeɪ mɛt ðɛr siːd ɪnˈvɛstərz/","id":"Di Seattle-lah mereka bertemu para investor awal mereka."},{"label":"Wh-Cleft Penekanan Solusi","jp":"What this thesis demonstrates is a link between sleep and memory.","reading":"/wʌt ðɪs ˈθiːsɪs ˈdɛmənstreɪts ɪz ə lɪŋk/","id":"Apa yang ditunjukkan oleh tesis ini adalah kaitan antara tidur dan daya ingat."},{"label":"All-Cleft (''Satu-satunya yang...'')","jp":"All you need to do is verify your email address.","reading":"/ɔːl juː niːd tə duː ɪz ˈvɛrɪfaɪ jʊr ˈiːmeɪl əˈdrɛs/","id":"Yang perlu Anda lakukan hanyalah memverifikasi alamat email Anda."}],"mistakes":[{"wrong":"It wasn''t until midnight when the server came back online.","right":"It wasn''t until midnight that the server came back online.","why":"Dalam pola baku It-Cleft ''It was / wasn''t until [waktu]...'', pasangan resminya di TOEFL adalah ''that'', bukan ''when''!"},{"wrong":"That we need right now is clearer documentation.","right":"What we need right now is clearer documentation.","why":"''What'' mengandung makna ganda ''the thing that'' sehingga bisa membuka Pseudo-Cleft tanpa kata benda di depannya; ''That'' di sini tidak memiliki anteseden!"}],"quiz":[{"question":"Lengkapi struktur It-Cleft standar TOEFL: ''It was not until the invention of the electron microscope ___ scientists could visualize viruses directly.''","options":["when","that","which","then"],"answer":1,"why":"Konstruksi It-Cleft ''It was not until X ___ S + V'' selalu diselesaikan dengan kata penghubung ''that''."},{"question":"Pilih pembuka Pseudo-Cleft yang tepat: ''___ surprised the analysts most was the resilience of consumer spending.''","options":["That","Which","What","It"],"answer":2,"why":"''What'' (= the thing that) berfungsi membentuk klausa nomina sebagai subjek kalimat sebelum predikat ''was''."},{"question":"Perhatikan bentuk kata kerja setelah ''All we did was ___'':","options":["restarting the container","restarted the container","restart the container","for restart the container"],"answer":2,"why":"Setelah ''What/All + S + do/did + be'', pelengkapnya memakai bare infinitive V1 (''restart'') atau ''to restart''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000044', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-004', 'conjugation', 'Past Modals of Critique & Speculation: Evaluasi Lampau (should have / needn''t have)', '[Subject] + should/could/must/might/can''t/needn''t + have + V3 (Past Participle)', 'Membedah nuansa evaluasi, kritik halus, peluang yang terlewat, serta deduksi atas peristiwa masa lalu.', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"We should have consulted the legal team before publishing the press release.","reading":"/wiː ˈʃʊdəv kənˈsʌltɪd ðə ˈliːɡəl tiːm bɪˈfɔːr ˈpʌblɪʃɪŋ ðə prɛs rɪˈliːs/","id":"Seharusnya dulu kita berkonsultasi dengan tim hukum sebelum menerbitkan siaran pers (faktanya tidak)."},{"jp":"She hasn''t arrived yet—her flight must have been delayed.","reading":"/ʃiː ˈhæzənt əˈraɪvd jɛt hɜːr flaɪt ˈmʌstəv bɪn dɪˈleɪd/","id":"Dia belum tiba juga—penerbangannya pasti tadi mengalami penundaan."}]'::jsonb, 'should''ve (/ˈʃʊdəv/) asked • must''ve missed • needn''t have worried', '{"analogy":"Modal biasa (''should, must, could'') hanya bicara soal sekarang/nanti. Untuk menarik modal ke MASA LALU, kita tidak bisa menempelkan ''-ed'' ke modalnya; gantinya kita memasang adaptor ''have + V3'' di belakangnya! Setiap modal punya cerita tersembunyi: ''should have V3'' = penyesalan/kritik (seharusnya dilakukan, tapi TIDAK dilakukan); ''could have V3'' = sebenarnya mampu dilakukan, tapi TIDAK diambil; ''must have V3'' = tebakan 95% yakin pasti terjadi kemarin!","when_to_use":["Mengevaluasi keputusan masa lalu: ''should(n''t) have + V3'' (seharusnya dulu [tidak] melakukan) & ''could have + V3'' (sebenarnya dulu punya opsi/peluang melakukan)","Menyimpulkan penyebab kejadian masa lalu: ''must have + V3'' (pasti tadi terjadi), ''might/may/could have + V3'' (mungkin tadi terjadi), ''can''t/couldn''t have + V3'' (mustahil tadi terjadi)","Membedakan kesia-siaan masa lalu: ''didn''t need to V1'' (tidak perlu dan memang tidak dilakukan) vs ''needn''t have V3'' (sebenarnya tidak perlu, TAPI terlanjur repot-repot dilakukan!)"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku / Topik"},{"role":"verb","text":"Modal (should/must/could/can''t)","label":"Sikap / Tingkat Keyakinan"},{"role":"verb","text":"have + V3","label":"Penanda Masa Lampau"}],"steps":["Pastikan setelah modal selalu tertulis ''have + V3'' (baik subjeknya ''I'' maupun ''she'', tidak pernah ''has'', dan dalam tulisan dilarang menulis ''should of''!).","Bedakan dua fungsi ''could have + V3'': (1) peluang lampau yang tak diambil (''You could have told me!'' = kenapa nggak bilang sih?!), atau (2) spekulasi 50% atas kejadian lampau (''He could have forgotten'').","Untuk pasif masa lalu, susunannya menjadi ''Modal + have + been + V3'' (''The file might have been deleted accidentally'')."],"breakdowns":[{"tokens":[{"jp":"You","reading":"/juː/","meaning":"kamu","role":"subject"},{"jp":"could have bricked","reading":"/ˈkʊdəv brɪkt/","meaning":"tadi nyaris saja bisa merusak total (untung tidak terjadi!)","role":"verb"},{"jp":"the motherboard","reading":"/ðə ˈmʌðərbɔːrd/","meaning":"papan induknya","role":"object"},{"jp":"by unplugging it!","reading":"/baɪ ʌnˈplʌɡɪŋ ɪt/","meaning":"gara-gara mencabut kabelnya!","role":"particle"}],"translation":"Tadi kamu nyaris saja merusak total motherboard-nya gara-gara mencabut kabelnya!"},{"tokens":[{"jp":"He","reading":"/hiː/","meaning":"dia","role":"subject"},{"jp":"can''t have approved","reading":"/kænt hæv əˈpruːvd/","meaning":"mustahil telah menyetujui (deduksi negatif lampau)","role":"verb"},{"jp":"that transfer;","reading":"/ðæt ˈtrænsfɜːr/","meaning":"transfer dana itu;","role":"object"},{"jp":"his account was frozen.","reading":"/hɪz əˈkaʊnt wəz ˈfroʊzən/","meaning":"akunnya sedang dibekukan.","role":"predicate"}],"translation":"Mustahil dia yang menyetujui transfer itu; akunnya sedang dibekukan saat itu."}],"forms":[{"label":"Kritik / Evaluasi (should''ve)","jp":"We shouldn''t have rushed the database migration.","reading":"/wiː ˈʃʊdəntəv rʌʃt ðə ˈdeɪtəbeɪs maɪˈɡreɪʃən/","id":"Seharusnya kemarin kita tidak memaksakan migrasi basis data secara terburu-buru."},{"label":"Deduksi Pasti Lampau (must''ve)","jp":"They must have spent months curating this dataset.","reading":"/ðeɪ ˈmʌstəv spɛnt mʌnθs kjʊˈreɪtɪŋ ðɪs ˈdeɪtəsɛt/","id":"Mereka pasti telah menghabiskan berbulan-bulan mengkurasi kumpulan data ini."},{"label":"Terlanjur Sia-Sia (needn''t have)","jp":"I bought a physical ticket, though I needn''t have bothered—entry was free!","reading":"/aɪ ˈniːdənt hæv ˈbɑːðərd ˈɛntri wəz friː/","id":"Saya sudah terlanjur beli tiket fisik, padahal tidak perlu repot—masuknya gratis!"}],"mistakes":[{"wrong":"The streets are dry; it must not have rained last night (dalam ragam formal British/TOEFL kadang rancu dengan larangan).","right":"The streets are dry; it can''t / couldn''t have rained last night.","why":"Untuk menyimpulkan 99% mustahil terjadi di masa lalu secara paling tegas dan universal di tes akademik, gunakan ''can''t have + V3'' atau ''couldn''t have + V3''."},{"wrong":"You should have tell me earlier!","right":"You should have told me earlier!","why":"Setelah ''have'' pada Past Modal, kata kerja wajib berbentuk V3 (''told''), bukan V1 (''tell'')."}],"quiz":[{"question":"Dalam TOEFL Listening, temanmu berkata: ''Why did you take a cab? I could have picked you up at the station!'' Apa makna tersiratnya?","options":["Temanmu tadi menjemputmu di stasiun","Temanmu sebenarnya siap & mampu menjemputmu, tapi kamu tidak memberi tahunya sehingga ia tidak jadi menjemput","Temanmu tidak punya mobil","Temanmu melarangmu naik kereta"],"answer":1,"why":"''Could have + V3'' sering menyiratkan peluang bantuan yang tersedia di masa lalu namun tidak terwujud."},{"question":"Pilih deduksi logis masa lalu: ''The ancient observatory aligns perfectly with the solstice; its builders ___ advanced astronomical knowledge.''","options":["should have possessed","must have possessed","needn''t have possessed","can''t possess"],"answer":1,"why":"Menarik kesimpulan ilmiah yang sangat meyakinkan tentang fakta sejarah masa lalu memakai ''must have + V3'' (bukan ''should have'' yang berarti ''seharusnya tapi gagal'')."},{"question":"Apa perbedaan ''We didn''t need to print the handouts'' vs ''We needn''t have printed the handouts''?","options":["Keduanya berarti kertas sudah dicetak","Yang pertama umumnya berarti tahu dari awal tidak perlu sehingga tidak mencetak; yang kedua berarti sudah terlanjur mencetak padahal ternyata sia-sia!","Yang kedua salah secara grammar","Yang pertama hanya untuk masa depan"],"answer":1,"why":"''Needn''t have + V3'' secara spesifik menyoroti tindakan yang SUDAH dilakukan namun belakangan terbukti tidak diperlukan."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000045', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-005', 'sentence_pattern', 'Academic Nominalization: Pemadatan Jadi Frasa Benda (the implementation of)', '[Clause: S + Verb + Adverb] → [Dense Noun Phrase: The + Adjective + Noun-tion/-ment/-ance + of + Noun] + Analytical Verb', 'Mengubah rangkaian klausa kata kerja lisan menjadi frasa kata benda padat untuk membangun register ilmiah C1 dan esai TOEFL.', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"The rapid proliferation of remote work has reshaped urban real estate.","reading":"/ðə ˈræpɪd prəˌlɪfəˈreɪʃən əv rɪˈmoʊt wɜːrk hæz riːˈʃeɪpt ˈɜːrbən ˈriːəl ɪˈsteɪt/","id":"Meluasnya kerja jarak jauh secara pesat telah membentuk ulang pasar properti perkotaan."},{"jp":"Failure to encrypt sensitive endpoints resulted in a compliance breach.","reading":"/ˈfeɪljər tu ɪnˈkrɪpt ˈsɛnsətɪv ˈɛndpɔɪnts rɪˈzʌltɪd ɪn ə kəmˈplaɪəns briːtʃ/","id":"Kegagalan mengenkripsi titik akses sensitif mengakibatkan pelanggaran kepatuhan."}]'::jsonb, 'They adopted AI rapidly → The rapid adoption of AI accelerated...', '{"analogy":"Percakapan sehari-hari bergerak dengan KATA KERJA (''People cut down trees quickly, so the soil eroded''). Sebaliknya, jurnal akademik dan bacaan TOEFL memadatkan seluruh peristiwa menjadi KATA BENDA layaknya file `.zip` (''Rapid deforestation accelerated soil erosion'')! Begitu aksi dibendakan (Nominalization), seluruh kalimat bisa diringkas menjadi [Konsep A] + [Kata Kerja Hubungan Sebab-Akibat] + [Konsep B]!","when_to_use":["Meningkatkan skor Lexical Resource & Grammatical Range di TOEFL Academic Discussion dan Integrated Writing","Merangkum ide paragraf sebelumnya di awal kalimat baru (''This shift in consumer preference led to...'')","Menghubungkan dua fenomena abstrak dengan verba analitis seperti ''stem from, trigger, facilitate, underscore, exacerbate, account for''"],"formula_parts":[{"role":"noun","text":"The + Adj + Nominalized Noun + of X","label":"Klausa yang Di-.zip Jadi Benda"},{"role":"verb","text":"triggered / facilitated / stemmed from","label":"Verba Analitis Kausal"},{"role":"object","text":"Dense Noun Phrase Y","label":"Dampak / Fenomena Kedua"}],"steps":["Ubah kata kerja utama menjadi kata benda turunan (-tion, -ment, -ance/-ence, -al, -ity): implement → implementation, analyze → analysis, rely → reliance, fail → failure.","Ubah kata keterangan cara (adverb ''-ly'') menjadi kata sifat (adjective) di depan kata benda baru tadi: ''grew exponentially'' → ''exponential growth''!","Jaga keseimbangan: gunakan Nominalization untuk memadatkan sebab-akibat konsep abstrak, tetapi jangan berlebihan (zombie nouns seperti ''make a utilization of'' ❌ → cukup ''utilize'' ✅)!"],"breakdowns":[{"tokens":[{"jp":"Overreliance on","reading":"/ˌoʊvərrɪˈlaɪəns ɑːn/","meaning":"ketergantungan berlebih pada (dari ''rely overly on'')","role":"subject"},{"jp":"single-region servers","reading":"/ˈsɪŋɡəl ˈriːdʒən ˈsɜːrvərz/","meaning":"server satu wilayah","role":"noun"},{"jp":"exposes","reading":"/ɪkˈspoʊzɪz/","meaning":"memaparkan (verba analitis)","role":"verb"},{"jp":"firms to outage risks.","reading":"/fɜːrmz tu ˈaʊtɪdʒ rɪsks/","meaning":"perusahaan pada risiko lumpuh layanan.","role":"object"}],"translation":"Ketergantungan berlebih pada server satu wilayah memaparkan perusahaan pada risiko gangguan layanan."},{"tokens":[{"jp":"The integration of","reading":"/ði ˌɪntɪˈɡreɪʃən əv/","meaning":"pengintegrasian (dari ''integrating'')","role":"subject"},{"jp":"solar storage","reading":"/ˈsoʊlər ˈstɔːrɪdʒ/","meaning":"penyimpanan tenaga surya","role":"noun"},{"jp":"mitigates","reading":"/ˈmɪtɪɡeɪts/","meaning":"meredam / memitigasi","role":"verb"},{"jp":"grid instability.","reading":"/ɡrɪd ˌɪnstəˈbɪləti/","meaning":"ketidakstabilan jaringan listrik (dari ''unstable grid'').","role":"object"}],"translation":"Pengintegrasian penyimpanan tenaga surya memitigasi ketidakstabilan jaringan listrik."}],"forms":[{"label":"Verba + Adverbia → Adj + Noun","jp":"Prices rose sharply → A sharp rise in prices eroded purchasing power.","reading":"/ə ʃɑːrp raɪz ɪn ˈpraɪsɪz ɪˈroʊdɪd ˈpɜːrtʃəsɪŋ ˈpaʊər/","id":"Kenaikan tajam harga menggerus daya beli masyarakat."},{"label":"Adjektiva → Nomina Abstrak (-ity/-ness)","jp":"The network was vulnerable → Network vulnerability prompted an audit.","reading":"/ˈnɛtwɜːrk ˌvʌlnərəˈbɪləti ˈprɑːmptɪd ən ˈɔːdɪt/","id":"Kerentanan jaringan mendorong dilakukannya audit."},{"label":"Kohesi Antar-Kalimat","jp":"Users abandoned the checkout flow. This friction cost us 12% in sales.","reading":"/ðɪs ˈfrɪkʃən kɔːst ʌs twɛlv pərˈsɛnt ɪn seɪlz/","id":"Merangkum seluruh kalimat sebelumnya dengan ''This + kata benda abstrak''."}],"mistakes":[{"wrong":"We conducted an investigation into the problem (bertele-tele jika cuma mau bilang ''menyelidiki'').","right":"Gunakan nominalisasi saat menjadi SUBJEK/OBJEK kausal (''The investigation revealed...''), bukan mengganti verba aktif kuat menjadi ''make/conduct a + Noun'' tanpa alasan!","why":"Gaya akademik Amerika modern membenci ''bloated/smothered verbs'' (''perform an analysis of'' → ''analyze''), namun mencintai nominalisasi sebagai subjek penggerak argumen!"},{"wrong":"The rapidly expansion of AI...","right":"The rapid expansion of AI...","why":"Begitu ''expand'' diubah menjadi kata benda ''expansion'', penjelas di depannya wajib ikut berubah dari adverbia (''rapidly'') menjadi kata sifat (''rapid'')!"}],"quiz":[{"question":"Ubahlah klausa lisan ''Because antibiotics were used excessively, bacteria became resistant'' menjadi kalimat akademik C1 yang ringkas:","options":["The excessively use of antibiotics made resistant.","The excessive use of antibiotics accelerated bacterial resistance.","Using antibiotics excessive caused bacteria resist.","Antibiotics excessive usage was resisted by bacteria."],"answer":1,"why":"''Used excessively'' dinominalisasi menjadi ''The excessive use'', dan ''bacteria became resistant'' menjadi ''bacterial resistance'' yang dihubungkan verba analitis ''accelerated''."},{"question":"Pilih bentuk kata yang tepat untuk melengkapi subjek nominalisasi: ''The ___ of wetland ecosystems threatens migratory bird populations.''","options":["destroy","destructive","destruction","destructively"],"answer":2,"why":"Posisi di antara ''The'' dan ''of'' membutuhkan kata benda murni (Noun): ''destruction''."},{"question":"Preposisi apa yang secara idiomatis mengikuti nomina kenaikan/penurunan seperti ''a dramatic increase / decline ___ user engagement''?","options":["of","in","at","to"],"answer":1,"why":"''Increase / decrease / rise / drop / decline'' diikuti ''in'' untuk menyebutkan bidang/hal yang berubah (''an increase IN engagement''), dan ''of'' untuk angkanya (''an increase OF 20%'')!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000046', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-006', 'particle', 'Concessive & Conditional Clauses: Syarat & Konsesi (Provided that / Granted that)', 'Syarat Ketat: Provided (that) / As long as / On condition that • Konsesi: Granted (that) / Albeit / While', 'Mengungkapkan syarat perjanjian presisi tinggi dan konsesi argumen bernuansa tajam tanpa mengulang ''if'' dan ''although''.', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"You may work from anywhere provided that your time zone overlaps four hours.","reading":"/juː meɪ wɜːrk frʌm ˈɛniwɛr prəˈvaɪdɪd ðæt jʊr taɪm zoʊn ˌoʊvərˈlæps fɔːr ˈaʊərz/","id":"Anda boleh bekerja dari mana saja dengan syarat zona waktu Anda beririsan empat jam."},{"jp":"The prototype delivered accurate results, albeit at a slower speed.","reading":"/ðə ˈproʊtətaɪp dɪˈlɪvərd ˈækjərət rɪˈzʌlts ɔːlˈbiːɪt æt ə ˈsloʊər spiːd/","id":"Prototipe tersebut memberikan hasil akurat, kendatipun dengan kecepatan yang lebih lambat."}]'::jsonb, 'provided (that) (/prəˈvaɪdɪd/) • albeit (/ɔːlˈbiːɪt/ + Adj/Adv) • granted (that)', '{"analogy":"Di level C1, kata ''if'' dan ''although'' terasa terlalu umum untuk kontrak bisnis atau esai analisis. ''Provided (that) / Providing (that) / As long as'' artinya BUKAN sekadar ''jika'', melainkan ''HANYA JIKA / DENGAN SYARAT MUTLAK''. Sementara di kubu konsesi, ''Granted (that)...'' digunakan untuk mengakui poin lawan debat dengan gagah sebelum membalasnya (''Diakui memang benar bahwa X, namun...''), dan ''albeit'' adalah permata ringkas yang menyisipkan catatan ''meskipun'' langsung ke kata sifat/frasa tanpa perlu Subjek + Verb baru!","when_to_use":["Provided (that) / As long as / So long as: menetapkan syarat kerja sama, klausul lisensi, atau kebijakan dengan Present Simple untuk masa depan","In the event that / Should / In case: merancang rencana darurat risiko (''In case'' = untuk berjaga-jaga SEBELUM terjadi, BUKAN terjemahan harfiah ''kalau''!)","Granted (that) + Klausa vs Albeit + Adjective / Adverb / Prepositional Phrase: mengakui kelemahan kecil di tengah klaim utama"],"formula_parts":[{"role":"connector","text":"Provided (that) / As long as","label":"Syarat Mutlak (+ Present Simple)"},{"role":"connector","text":"Granted (that) + S + V","label":"Mengakui Argumen Lawan"},{"role":"particle","text":", albeit + Adj/Adv/Prep Phrase","label":"Konsesi Ringkas (Tanpa S+V!)"}],"steps":["Gunakan ''provided (that)'' ketika ingin menekankan syarat yang tidak bisa ditawar; sama seperti klausa ''if'' Type 1, jangan pakai ''will'' di dalamnya!","Hati-hati memakai ''albeit'': ''albeit'' TIDAK BOLEH diikuti klausa Subjek + Verb penuh (''albeit it was slow'' ❌)—langsung ikuti dengan kata sifat/keterangan/frasa (''albeit slowly'' / ''albeit expensive'')!","Waspadai jebakan ''in case'' vs ''if'' di American English: ''Bring a charger in case your battery dies'' (bawa dari sekarang untuk jaga-jaga), berbeda dari ''Call me if your battery dies'' (telepon nanti kalau sudah kejadian)!"],"breakdowns":[{"tokens":[{"jp":"Granted that","reading":"/ˈɡræntɪd ðæt/","meaning":"memang diakui bahwa (konsesi pembuka)","role":"connector"},{"jp":"initial setup is costly,","reading":"/ɪˈnɪʃəl ˈsɛtʌp ɪz ˈkɔːstli/","meaning":"pemasangan awalnya mahal,","role":"predicate"},{"jp":"long-term savings","reading":"/ˈlɔːŋtɜːrm ˈseɪvɪŋz/","meaning":"penghematan jangka panjangnya","role":"subject"},{"jp":"outweigh the expense.","reading":"/ˌaʊtˈweɪ ði ɪkˈspɛns/","meaning":"jauh melampaui biayanya.","role":"predicate"}],"translation":"Memang diakui pemasangan awalnya mahal, namun penghematan jangka panjangnya jauh melampaui biaya tersebut."},{"tokens":[{"jp":"Keep an offline copy","reading":"/kiːp ən ˈɔːflaɪn ˈkɑːpi/","meaning":"simpan salinan luring","role":"verb"},{"jp":"in case","reading":"/ɪn keɪs/","meaning":"untuk berjaga-jaga kalau-kalau","role":"connector"},{"jp":"the venue Wi-Fi fails.","reading":"/ðə ˈvɛnjuː ˈwaɪfaɪ feɪlz/","meaning":"Wi-Fi gedungnya mati.","role":"predicate"}],"translation":"Simpan salinan luring untuk berjaga-jaga kalau-kalau Wi-Fi gedungnya mati."}],"forms":[{"label":"Syarat Kontrak (Provided that)","jp":"The license is free provided that you credit the author.","reading":"/ðə ˈlaɪsəns ɪz friː prəˈvaɪdɪd ðæt juː ˈkrɛdɪt ði ˈɔːθər/","id":"Lisensi ini gratis dengan syarat Anda mencantumkan kredit penulis."},{"label":"Konsesi Padat (albeit)","jp":"Inflation has begun to cool, albeit gradually.","reading":"/ɪnˈfleɪʃən hæz bɪˈɡʌn tə kuːl ɔːlˈbiːɪt ˈɡrædʒuəli/","id":"Inflasi telah mulai mereda, meskipun secara bertahap."},{"label":"Alternatif Negatif (Otherwise)","jp":"Verify your identity by Friday; otherwise, access will expire.","reading":"/ˈvɛrɪfaɪ jʊr aɪˈdɛntəti baɪ ˈfraɪdeɪ ˈʌðərwaɪz ˈæksɛs wɪl ɪkˈspaɪər/","id":"Verifikasi identitas Anda paling lambat Jumat; jika tidak, akses akan kedaluwarsa."}],"mistakes":[{"wrong":"The experiment succeeded, albeit it took three attempts.","right":"The experiment succeeded, albeit after three attempts. / ...although it took three attempts.","why":"''Albeit'' hanya diikuti frasa pendek (adjektiva, adverbia, frasa preposisi), BUKAN klausa penuh ber-kata kerja finit (''it took'')!"},{"wrong":"Please email IT support in case you see an error message (di AS standar, ''if'' jauh lebih tepat untuk reaksi ''apabila terjadi'').","right":"Please email IT support if / in the event that you see an error message.","why":"''In case'' berarti melakukan tindakan pencegahan SEBELUM masalah terjadi; untuk tindakan yang baru diambil SETELAH syarat muncul, gunakan ''if'' atau formal ''in the event that''."}],"quiz":[{"question":"Pilih penggunaan kata ''albeit'' yang 100% tepat untuk esai akademik C1:","options":["Albeit the sample was small, the trend was clear.","The vaccine proved effective, albeit slightly less potent against the new variant.","She accepted the offer, albeit she had to relocate.","Albeit of the high cost, sales grew."],"answer":1,"why":"''Albeit'' menyambung langsung ke frasa adjektiva (''slightly less potent...'') tanpa subjek dan kata kerja finit."},{"question":"Lengkapi klausul kebijakan berikut: ''Scholarships are renewed annually, ___ recipients maintain a 3.5 GPA.''","options":["provided that","despite","albeit","in case of"],"answer":0,"why":"''Provided that'' (= hanya dengan syarat bahwa) diikuti klausa lengkap ''recipients maintain...''."},{"question":"Jika di belakang konjungsi berupa Frasa Benda ''an emergency'' (''___ an emergency, use the stairs''), frasa mana yang benar?","options":["In case","In the event of","Provided that","As long as"],"answer":1,"why":"Karena diikuti kata benda (''an emergency'') tanpa kata kerja, dibutuhkan bentuk berpreposisi ''of'': ''In the event of'' (atau ''In case of'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000047', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-007', 'particle', 'Preposition + Relative Pronoun: Relatif Akademik (the framework on which)', '[Noun] + [Preposition: in / on / to / by / through / of] + which (benda) / whom (orang) + [Subject + Verb]', 'Memindahkan preposisi ke depan ''which'' atau ''whom'' untuk menciptakan struktur kalimat akademik formal yang sangat presisi.', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"The dataset on which our conclusions are based spans twenty years.","reading":"/ðə ˈdeɪtəsɛt ɑːn wɪtʃ ˈaʊər kənˈkluːʒənz ɑːr beɪst spænz ˈtwɛnti jɪrz/","id":"Kumpulan data yang menjadi dasar kesimpulan kami mencakup rentang dua puluh tahun."},{"jp":"We surveyed 200 startups, nearly half of which had adopted Rust.","reading":"/wiː ˈsɜːrveɪd tuː ˈhʌndrəd ˈstɑːrtʌps ˈnɪrli hæf əv wɪtʃ hæd əˈdɑːptɪd rʌst/","id":"Kami menyurvei 200 perusahaan rintisan, yang hampir separuhnya telah mengadopsi bahasa Rust."}]'::jsonb, 'the assumptions on which (/ɑːn wɪtʃ/) • the mentor to whom (/tə huːm/) • most of which', '{"analogy":"Dalam obrolan santai kita menaruh preposisi di ujung kalimat: ''the company (that) she works FOR''. Dalam penulisan ilmiah dan soal TOEFL Structure, preposisi itu diangkat secara terhormat ke DEPAN menjadi ''the company FOR WHICH she works''! Begitu preposisi maju ke depan, hanya DUA kata ganti yang sah menemaninya: ''WHICH'' untuk benda dan ''WHOM'' (wajib pakai -m!) untuk manusia—kata ''that'' dan ''who'' langsung dilarang masuk!","when_to_use":["Menulis kalimat akademik elegan di mana verba/adjektiva punya pasangan preposisi tetap (''rely ON → on which we rely'', ''refer TO → to whom I referred'')","Menggantikan ''where'' dan ''when'' secara formal menggunakan ''in which / at which / on which'' (''the era in which...'' = ''when'')","Menyatakan proporsi bagian dari kelompok dengan ''[Quantifier] + of which / of whom'' (''three of whom'', ''most of which'')—jebakan klasik koma di TOEFL!"],"formula_parts":[{"role":"noun","text":"Antecedent Noun","label":"Benda / Orang yang Dijelaskan"},{"role":"particle","text":"Prep + which / whom","label":"Dilarang ''Prep + that/who''!"},{"role":"predicate","text":"Subject + Verb","label":"Tanpa Preposisi Ganda di Ujung!"}],"steps":["Lacak preposisi asli dari kata kerja di belakangnya: ''is based ON X'' → ''X on which it is based''; ''contributed TO X'' → ''X to which they contributed''.","Pastikan setelah preposisi HANYA menggunakan ''which'' (benda), ''whom'' (manusia), atau ''whose + Noun'' (''in whose lab she worked'')—pantang menulis ''in that'' (kecuali arti khusus ''karena/dalam hal'') atau ''to who''!","Hafalkan perbedaan satu kata yang paling sering menjebak di TOEFL: setelah TANDA KOMA, sambung dengan ''most of WHICH / WHOM'' (satu kalimat), BUKAN ''most of THEM'' (kalau pakai ''them'' tanpa ''and'', jadi kesalahan Comma Splice!)!"],"breakdowns":[{"tokens":[{"jp":"The speed","reading":"/ðə spiːd/","meaning":"kecepatan","role":"subject"},{"jp":"at which","reading":"/æt wɪtʃ/","meaning":"yang dengannya (pasangan baku: at a speed!)","role":"particle"},{"jp":"glaciers are melting","reading":"/ˈɡleɪʃərz ɑːr ˈmɛltɪŋ/","meaning":"gletser mencair","role":"predicate"},{"jp":"has alarmed climatologists.","reading":"/hæz əˈlɑːrmd ˌklaɪməˈtɑːlədʒɪsts/","meaning":"telah mengkhawatirkan para ahli iklim.","role":"predicate"}],"translation":"Kecepatan mencairnya gletser telah mengkhawatirkan para ahli iklim."},{"tokens":[{"jp":"The panel interviewed ten finalists,","reading":"/ðə ˈpænəl ˈɪntərvjuːd tɛn ˈfaɪnəlɪsts/","meaning":"panel mewawancarai sepuluh finalis,","role":"predicate"},{"jp":"three of whom","reading":"/θriː əv huːm/","meaning":"yang tiga di antaranya (manusia → whom!)","role":"connector"},{"jp":"received full fellowships.","reading":"/rɪˈsiːvd fʊl ˈfɛloʊʃɪps/","meaning":"menerima beasiswa penuh.","role":"predicate"}],"translation":"Panel mewawancarai sepuluh finalis, yang tiga di antaranya menerima beasiswa penuh."}],"forms":[{"label":"Prep + whom (Manusia)","jp":"The professor with whom I co-authored the paper retired.","reading":"/ðə prəˈfɛsər wɪð huːm aɪ koʊˈɔːθərd ðə ˈpeɪpər/","id":"Profesor yang bersama beliau saya menulis makalah itu telah pensiun."},{"label":"By/Through which (Mekanisme)","jp":"Photosynthesis is the process by which plants convert light.","reading":"/ˌfoʊtoʊˈsɪnθəsɪs ɪz ðə ˈprɑːsɛs baɪ wɪtʃ plænts kənˈvɜːrt laɪt/","id":"Fotosintesis adalah proses yang melaluinya tumbuhan mengubah cahaya."},{"label":"Quantifier + of which","jp":"He proposed four solutions, none of which was feasible.","reading":"/hiː prəˈpoʊzd fɔːr səˈluːʃənz nʌn əv wɪtʃ wəz ˈfiːzəbəl/","id":"Dia mengusulkan empat solusi, yang tak satu pun di antaranya layak dijalankan."}],"mistakes":[{"wrong":"The study included 500 participants, most of them were college students.","right":"The study included 500 participants, most of whom were college students.","why":"Koma tidak boleh menyambung dua kalimat mandiri (''most of them were...'' = Comma Splice ❌)! Gunakan kata ganti penghubung ''most of whom'' (atau tambahkan titik koma ''; most of them...'')."},{"wrong":"This is the principle on which our policy is based on.","right":"This is the principle on which our policy is based.","why":"Karena ''on'' sudah dipindahkan ke depan (''on which''), jangan mengulang ''on'' lagi di akhir kalimat!"}],"quiz":[{"question":"Soal klasik TOEFL Structure: ''Enzymes act as biological catalysts, ___ metabolic reactions would proceed far too slowly to sustain life.''","options":["without that","without which","without them","which without"],"answer":1,"why":"Untuk menggabungkan klausa kedua setelah koma dengan makna ''yang tanpanya'', gunakan Preposition + Relative Pronoun ''without which'' (bukan ''without them'' karena akan memicu comma splice)."},{"question":"Pilih pasangan preposisi kolokasi yang tepat: ''The degree ___ cultural norms influence negotiation styles varies widely.''","options":["in which","to which","on which","by whom"],"answer":1,"why":"Kolokasi baku Bahasa Inggris adalah ''to a degree / to an extent'', sehingga bentuk relatifnya wajib ''the degree/extent TO which''!"},{"question":"Lengkapi kalimat berikut: ''The keynote featured four Nobel laureates, two of ___ graduated from public universities.''","options":["who","them","whom","which"],"answer":2,"why":"Setelah koma tanpa konjungsi ''and'', dan tepat sesudah preposisi ''of'' untuk merujuk manusia (''laureates''), bentuk wajibnya adalah ''whom''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000048', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-008', 'honorific', 'Academic Hedging & Boosting: Presisi Klaim Ilmiah (arguably / compelling evidence)', 'Hedging (Klaim Hati-Hati): arguably / plausibly / suggest / appear to • Boosting (Bukti Kuat): compelling evidence demonstrates', 'Mengkalibrasi kekuatan klaim dalam esai riset, tesis beasiswa, dan TOEFL Writing agar terukur secara ilmiah.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"Preliminary findings suggest that microplastics may disrupt marine food webs.","reading":"/prɪˈlɪmənɛri ˈfaɪndɪŋz səɡˈdʒɛst ðæt ˈmaɪkroʊˌplæstɪks meɪ dɪsˈrʌpt məˈriːn fuːd wɛbz/","id":"Temuan awal mengindikasikan bahwa mikroplastik berpotensi mengganggu jaring-jaring makanan laut."},{"jp":"Compelling empirical evidence demonstrates a strong correlation between literacy and income.","reading":"/kəmˈpɛlɪŋ ɪmˈpɪrɪkəl ˈɛvɪdəns ˈdɛmənstreɪts ə strɔːŋ ˌkɔːrəˈleɪʃən/","id":"Bukti empiris yang kuat menunjukkan korelasi erat antara tingkat literasi dan pendapatan."}]'::jsonb, 'arguably (/ˈɑːrɡjuəbli/) the most... • findings suggest (BUKAN ''prove''!)', '{"analogy":"Dalam tulisan akademik AS, kata ''prove'' (''membuktikan 100% mutlak'') hampir tabu dipakai di luar matematika karena sains selalu terbuka untuk diuji ulang! Penulis C1 bekerja layaknya pengatur volume audio: saat buktinya masih korelasi atau opini berdasar argumen, turunkan tuas dengan Academic Hedging (''arguably, plausibly, indicate, suggest, appear to''); saat datanya masif dan tak terbantahkan, naikkan wibawanya dengan Academic Boosting terukur (''compelling evidence demonstrates, undeniably, substantially'')—tanpa terdengar emosional seperti iklan!","when_to_use":["Menggunakan ''arguably'' (''bisa dibilang berdasarkan argumen kuat'') sebelum superlatif agar klaim tetap elegan dan tak mudah diserang (''arguably the most influential paper'')","Memilih verba pelapor ilmiah sesuai kekuatan data: ''speculate / hypothesize'' (lemah) → ''suggest / indicate / point to'' (menengah) → ''demonstrate / establish / confirm'' (kuat)","Menjawab soal TOEFL Reading Inference/Rhetorical Purpose yang menguji sikap kehati-hatian penulis!"],"formula_parts":[{"role":"particle","text":"arguably / plausibly / largely","label":"Adverbia Pengukur Klaim"},{"role":"verb","text":"suggests / indicates / appears to","label":"Verba Ilmiah Terukur"},{"role":"noun","text":"compelling / mounting evidence","label":"Penguat Berbasis Data"}],"steps":["Hindari kata emosional/hiperbolis non-akademik di esai (''obviously, of course, 100% proves, everybody knows, super huge'' ❌).","Saat membuat klaim tertinggi (''the biggest challenge''), sisipkan ''arguably'' atau ''among the...'' (''arguably the biggest challenge'' / ''one of the most pressing challenges'') agar klaimmu tahan peluru kritik!","Hindari juga ''double/triple hedging'' berlebihan yang membuat tulisan terdengar ragu tak berpendirian (''It seems that maybe it could possibly suggest...'' ❌ → cukup ''The data suggests it may...'' ✅)."],"breakdowns":[{"tokens":[{"jp":"Transformer architecture","reading":"/trænsˈfɔːrmər ˈɑːrkɪtɛktʃər/","meaning":"arsitektur Transformer","role":"subject"},{"jp":"is arguably","reading":"/ɪz ˈɑːrɡjuəbli/","meaning":"bisa dibilang (hedged superlative)","role":"particle"},{"jp":"the most pivotal breakthrough","reading":"/ðə moʊst ˈpɪvətəl ˈbreɪkθruː/","meaning":"terobosan paling menentukan","role":"noun"},{"jp":"in modern NLP.","reading":"/ɪn ˈmɑːdərn ˌɛnɛlˈpiː/","meaning":"dalam NLP modern.","role":"place"}],"translation":"Arsitektur Transformer bisa dibilang merupakan terobosan paling menentukan dalam pemrosesan bahasa alami modern."},{"tokens":[{"jp":"Mounting evidence","reading":"/ˈmaʊntɪŋ ˈɛvɪdəns/","meaning":"bukti yang terus bertambah kuat (booster)","role":"subject"},{"jp":"points to","reading":"/pɔɪnts tuː/","meaning":"mengarah pada / mengindikasikan","role":"verb"},{"jp":"sleep deprivation","reading":"/sliːp ˌdɛprɪˈveɪʃən/","meaning":"kurang tidur","role":"object"},{"jp":"as a key risk factor.","reading":"/æz ə kiː rɪsk ˈfæktər/","meaning":"sebagai faktor risiko utama.","role":"noun"}],"translation":"Bukti yang kian menumpuk mengindikasikan kurang tidur sebagai faktor risiko utama."}],"forms":[{"label":"Hedge Klaim Sebab-Akibat","jp":"Sleep loss appears to impair prefrontal cortex function.","reading":"/sliːp lɔːs əˈpɪrz tu ɪmˈpɛr priːˈfrʌntəl ˈkɔːrtɛks/","id":"Kurang tidur tampak mengganggu fungsi korteks prefrontal."},{"label":"Hedge Ruang Lingkup","jp":"These findings apply primarily to urban populations.","reading":"/ðiːz ˈfaɪndɪŋz əˈplaɪ praɪˈmɛrəli tu ˈɜːrbən ˌpɑːpjəˈleɪʃənz/","id":"Temuan ini berlaku terutama pada populasi perkotaan."},{"label":"Academic Booster Elegan","jp":"Decades of longitudinal data underscored this disparity.","reading":"/ˈdɛkeɪdz əv ˌlɑːndʒɪˈtuːdənəl ˈdeɪtə ˌʌndərˈskɔːrd/","id":"Data jangka panjang selama puluhan tahun mempertegas kesenjangan ini."}],"mistakes":[{"wrong":"This single survey of 30 students definitely proves that online classes are better.","right":"This initial survey of 30 students suggests that online classes may offer distinct advantages.","why":"Sampel kecil tidak pernah ''membuktikan mutlak'' (definitely proves); penilai TOEFL Writing memberi nilai tinggi pada klaim yang proporsional dengan bukti!"},{"wrong":"In my humble opinion, I maybe think perhaps taxes possibly might rise.","right":"Current fiscal deficits suggest that tax rates may rise.","why":"Menumpuk 4–5 kata keraguan sekaligus membuat argumen lumpuh; pilih maksimal 1–2 penanda hedging yang tajam."}],"quiz":[{"question":"Dalam TOEFL Reading, penulis menulis: ''While intriguing, Dr. Kim''s hypothesis rests largely on circumstantial fossils.'' Apa fungsi kata ''largely'' dan ''circumstantial''?","options":["Penulis 100% menyetujui bahwa hipotesis Dr. Kim sudah terbukti mutlak","Penulis bersikap kritis-terukur: mengakui idenya menarik namun membatasi validitasnya karena buktinya belum langsung","Penulis mengejek Dr. Kim secara pribadi","Penulis menyatakan fosil tidak pernah ada"],"answer":1,"why":"Kombinasi konsesi (''While intriguing'') dan pembatas (''largely on circumstantial...'') mencerminkan evaluasi akademik yang objektif dan hati-hati."},{"question":"Pilih kalimat tesis paling kuat dan berwibawa akademik untuk TOEFL Writing:","options":["Everybody obviously knows public libraries are 100% perfect forever.","Public libraries remain arguably one of the most vital pillars of civic equity.","Maybe I kind of feel libraries could possibly be somewhat okay.","This essay will definitely prove libraries never fail."],"answer":1,"why":"''Remain arguably one of the most vital pillars...'' menggabungkan keyakinan argumen dengan presisi akademik C1 tanpa overclaiming."},{"question":"Kata benda ''evidence'' dan ''research'' dalam kalimat akademik berpasangan dengan kata kerja apa? (''Compelling evidence ___ that...'')","options":["indicates (tunggal, karena uncountable)","indicate (jamak)","are indicating","have indicated"],"answer":0,"why":"''Evidence'' dan ''research'' selalu Uncountable Singular dalam Bahasa Inggris, sehingga memakai kata kerja tunggal ''indicates / suggests / demonstrates''!"}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000049', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-009', 'sentence_pattern', 'Fronting & Parallelism: Keseimbangan Struktur TOEFL (Crucial to this is...)', 'Fronting: [Adj/Participle/Place Phrase] + V (be/intransitive) + [Subject] • Parallelism: A, B, and C (Identical Form)', 'Mengedepankan predikat/lokasi untuk transisi mulus antar-kalimat serta menjaga kesetaraan mutlak pada deretan dan perbandingan.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"Central to this architecture is a zero-trust security layer.","reading":"/ˈsɛntrəl tə ðɪs ˈɑːrkɪtɛktʃər ɪz ə ˈzɪroʊ trʌst sɪˈkjʊrəti ˈleɪər/","id":"Hal yang menjadi inti dari arsitektur ini adalah lapisan keamanan tanpa kepercayaan buta (zero-trust)."},{"jp":"The battery life of the new model is longer than that of its predecessor.","reading":"/ðə ˈbætəri laɪf əv ðə nuː ˈmɑːdəl ɪz ˈlɔːŋɡər ðæn ðæt əv ɪts ˈprɛdɪsɛsər/","id":"Daya tahan baterai model baru ini lebih lama daripada daya tahan baterai pendahulunya."}]'::jsonb, 'Central to our thesis is... • more efficient than that of (/ðæt əv/)...', '{"analogy":"Ada dua jurus penataan kalimat yang membedakan penulis C1 dari B1: (1) FRONTING—memindahkan pelengkap seperti ''Central to this issue / Equally important / Attached'' ke depan ''is/are'', sehingga subjek panjang yang baru diperkenalkan ditaruh di belakang! Hati-hati: kata kerjanya harus melirik ke KANAN mengikuti subjek asli di belakangnya! (2) LOGICAL COMPARISON & PARALLELISM—kamu tidak boleh membandingkan ''gaji guru'' dengan ''dokter'' (''a teacher''s salary is lower than a doctor'' ❌ = membandingkan uang dengan manusia!); wajib sejajarkan pakai ''that of'' (tunggal) atau ''those of'' (jamak)!","when_to_use":["Menyambung kalimat baru ke paragraf sebelumnya dengan mulus menggunakan Fronting (''Equally concerning are the privacy risks'')","Menjaga keseimbangan deret A, B, and C dalam resume dan esai (semua Gerund, semua Infinitive, atau semua Noun)","Menyamakan objek perbandingan logis di TOEFL dengan ''that of'' (tunggal) dan ''those of'' (jamak)"],"formula_parts":[{"role":"adjective","text":"Equally vital / Behind X","label":"Pelengkap / Lokasi di Depan"},{"role":"verb","text":"is (tunggal) / are (jamak)","label":"Ikuti Subjek di Kanan!"},{"role":"subject","text":"Delayed Subject","label":"Subjek Asli di Belakang"},{"role":"connector","text":"than that of / those of","label":"Perbandingan Apel-ke-Apel"}],"steps":["Saat bertemu kalimat yang diawali Frasa Preposisi atau Kata Sifat + Be (''Among the winners WAS/WERE...'', ''Crucial to these reforms IS/ARE...''), jangan terkecoh kata benda di depan—cari SUBJEK ASLI di sebelah kanan kata kerja!","Dalam daftar ''A, B, and C'', jika kamu membuka dengan ''to'' (''to design, build, and deploy''), konsistenkan V1 semua atau ulangi ''to'' di ketiganya—jangan mencampur ''to design, building, and deployment'' ❌!","Dalam perbandingan (''X of A is higher than ___ of B''), gunakan ''that of'' jika X tunggal (''the cost → that of''), dan ''those of'' jika X jamak (''the features → those of'')."],"breakdowns":[{"tokens":[{"jp":"Equally impressive","reading":"/ˈiːkwəli ɪmˈprɛsɪv/","meaning":"sama mengesankannya (Adjective di-fronting)","role":"adjective"},{"jp":"were","reading":"/wɜːr/","meaning":"adalah (jamak mengikuti subjek di kanan!)","role":"verb"},{"jp":"the latency benchmarks","reading":"/ðə ˈleɪtənsi ˈbɛntʃmɑːrks/","meaning":"tolok ukur latensinya (Subjek Jamak!)","role":"subject"},{"jp":"under peak load.","reading":"/ˈʌndər piːk loʊd/","meaning":"saat beban puncak.","role":"time"}],"translation":"Hal yang tak kalah mengesankan adalah tolok ukur latensinya saat beban puncak."},{"tokens":[{"jp":"The admission criteria","reading":"/ði ədˈmɪʃən kraɪˈtɪriə/","meaning":"kriteria penerimaan (jamak dari criterion!)","role":"subject"},{"jp":"at MIT","reading":"/æt ˌɛmaɪˈtiː/","meaning":"di MIT","role":"place"},{"jp":"rival","reading":"/ˈraɪvəl/","meaning":"menyaingi","role":"verb"},{"jp":"those of Caltech.","reading":"/ðoʊz əv ˈkæltɛk/","meaning":"kriteria milik Caltech (''those'' merujuk jamak ''criteria'').","role":"object"}],"translation":"Kriteria penerimaan di MIT seketat kriteria penerimaan di Caltech."}],"forms":[{"label":"Fronting Lokasi (+ Inversi)","jp":"At the top of the agenda sits cybersecurity.","reading":"/æt ðə tɑːp əv ði əˈdʒɛndə sɪts ˌsaɪbərsɪˈkjʊrəti/","id":"Di urutan teratas agenda terdapat keamanan siber."},{"label":"Perbandingan Setara (that of)","jp":"Jakarta''s population density exceeds that of New York.","reading":"/dʒəˈkɑːrtəz ˌpɑːpjəˈleɪʃən ˈdɛnsəti ɪkˈsiːdz ðæt əv nuː jɔːrk/","id":"Kepadatan penduduk Jakarta melampaui kepadatan penduduk New York."},{"label":"Parallelism di Resume/Esai","jp":"Her role involves mentoring juniors, reviewing PRs, and scaling APIs.","reading":"/hɜːr roʊl ɪnˈvɑːlvz ˈmɛntɔːrɪŋ ˈdʒuːnjərz rɪˈvjuːɪŋ ænd ˈskeɪlɪŋ/","id":"Perannya mencakup membimbing junior, meninjau PR, dan menskalakan API (V-ing, V-ing, and V-ing)."}],"mistakes":[{"wrong":"The climate of Bandung is cooler than Jakarta.","right":"The climate of Bandung is cooler than that of Jakarta. / ...cooler than Jakarta''s.","why":"Jebakan nomor satu TOEFL Written Expression! Kamu membandingkan ''the climate'' (iklim) dengan ''Jakarta'' (kota)—wajib sisipkan ''that of'' agar membandingkan iklim dengan iklim!"},{"wrong":"Among the most promising technologies are quantum computing.","right":"Among the most promising technologies is quantum computing.","why":"''Among the most promising technologies'' adalah frasa preposisi yang dikedepankan (bukan subjek!); subjek sebenarnya adalah tunggal ''quantum computing'' → wajib ''is''!"}],"quiz":[{"question":"Soal TOEFL Structure tentang Inverted Place/Adjective Fronting: ''Attached to this email ___ the signed NDA and the revised project scope.''","options":["is","are","be","has"],"answer":1,"why":"Subjek kalimat berada di sebelah kanan kata kerja dan terdiri dari dua item jamak (''the signed NDA AND the revised project scope''), sehingga wajib ''are''!"},{"question":"Perbaiki perbandingan tak logis ini: ''The wingspan of a wandering albatross is far wider than ___ any other living bird.''","options":["those of","that of","which of","them of"],"answer":1,"why":"Kata benda yang dibandingkan adalah tunggal ''The wingspan'', sehingga kata ganti penunjuk yang sejajar adalah ''that of''."},{"question":"Pilih kalimat dengan Parallel Structure yang sempurna:","options":["Investors evaluate startups based on traction, scalability, and how strong the team is.","Investors evaluate startups based on market traction, technical scalability, and team execution.","Investors evaluate startups based on growing fast, scalability, and to execute.","Investors evaluate traction, scalable, and executing."],"answer":1,"why":"Ketiga elemen setelah ''based on'' setara sempurna sebagai Noun Phrases: ''[market traction], [technical scalability], and [team execution]''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000050', 'e1000001-0000-4000-8000-000000000005', 'GP-EN-C1-010', 'sentence_pattern', 'Ellipsis & Substitution: Kohesi Tanpa Ulang (do so / if so / if not)', 'Verb Substitution: do so / did so / doing so • Clause Substitution: if so / if not / I believe so • Auxiliary Ellipsis: can, and will,', 'Menghindari pengulangan kata kerja atau klausa panjang menggunakan substitusi ''do so / so / not / one(s)'' yang ringkas dan kohesif.', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"Users can opt out of analytics at any time, and doing so won''t limit core features.","reading":"/ˈjuːzərz kən ɑːpt aʊt əv ˌænəˈlɪtɪks æt ˈɛni taɪm ænd ˈduːɪŋ soʊ woʊnt ˈlɪmɪt/","id":"Pengguna dapat menonaktifkan analitik kapan saja, dan melakukan hal tersebut tidak akan membatasi fitur inti."},{"jp":"Check whether the port is open; if not, update your firewall rules.","reading":"/tʃɛk ˈwɛðər ðə pɔːrt ɪz ˈoʊpən ɪf nɑːt ʌpˈdeɪt jʊr ˈfaɪərwɔːl ruːlz/","id":"Periksa apakah port tersebut terbuka; jika tidak, perbarui aturan firewall Anda."}]'::jsonb, 'asked to upgrade, and did so (/dɪd soʊ/) • Doing so saves time • If not, ...', '{"analogy":"Penulis pemula mengulang seluruh frasa berkali-kali hingga tulisan terasa kaku; penulis C1 menggunakan ''kata ganti pintar'' bukan cuma untuk benda (''one / ones''), melainkan juga untuk SELURUH AKSI (''do so / doing so'') dan SELURUH KALIMAT (''if so / if not / it appears so'')! Bahkan jika subjek dan kata kerjanya sama, kita bisa memangkas bagian yang kembar (Ellipsis) sehingga kalimat mengalir tajam tanpa lemak!","when_to_use":["Mengganti seluruh frasa kata kerja yang baru disebut dengan ''do so / does so / did so / doing so'' (''Those wishing to appeal must do so within 14 days'')","Meringkas percabangan logika di tulisan teknis dan esai dengan ''If so,'' (Jika demikian) dan ''If not,'' (Jika tidak demikian)","Menggunakan ''so'' atau ''not'' setelah verba opini (''I suppose so / I hope not / It appears so'') serta memangkas kata berulang setelah konjungsi (''while [they are] asleep'')"],"formula_parts":[{"role":"verb","text":"do so / did so / doing so","label":"Pengganti Seluruh Frasa Verba"},{"role":"connector","text":"If so, ... / If not, ...","label":"Pengganti Seluruh Klausa Syarat"},{"role":"noun","text":"one / ones | so / neither + Aux + S","label":"Substitusi Benda & Persetujuan"}],"steps":["Saat ingin merujuk kembali pada tindakan di kalimat sebelumnya sebagai subjek kalimat baru, buka dengan ''Doing so + Verb tunggal'' (''Refactor the module first. Doing so prevents bugs'')!","Ingat pasangan opini negatif: untuk ''hope, suspect, assume, be afraid'', bentuk negatifnya memakai ''not'' di belakang (''I hope not'', ''I''m afraid not''), sedangkan ''think / believe'' umumnya ''I don''t think so''.","Kuasai kesepakatan inversi singkat di TOEFL: positif memakai ''so + Aux + Subject'' (''She codes in Go, and so does he''), negatif memakai ''neither / nor + Aux + Subject'' (''She didn''t go, and neither did I'')!"],"breakdowns":[{"tokens":[{"jp":"We planned to expand in Q2,","reading":"/wiː plænd tu ɪkˈspænd ɪn kjuː tuː/","meaning":"kami berencana berekspansi di Q2,","role":"predicate"},{"jp":"but failed to","reading":"/bʌt feɪld tə/","meaning":"tetapi gagal untuk","role":"verb"},{"jp":"do so","reading":"/duː soʊ/","meaning":"melakukan hal tersebut (= expand in Q2)","role":"verb"},{"jp":"due to supply delays.","reading":"/duː tə səˈplaɪ dɪˈleɪz/","meaning":"akibat keterlambatan pasokan.","role":"particle"}],"translation":"Kami berencana berekspansi di Kuartal 2, tetapi gagal melakukannya akibat keterlambatan pasokan."},{"tokens":[{"jp":"Legacy servers consume vast power,","reading":"/ˈlɛɡəsi ˈsɜːrvərz kənˈsuːm væst ˈpaʊər/","meaning":"server lama mengonsumsi daya besar,","role":"predicate"},{"jp":"whereas modern ones","reading":"/wɛrˈæz ˈmɑːdərn wʌnz/","meaning":"sedangkan yang modern (''ones'' = servers)","role":"subject"},{"jp":"do not.","reading":"/duː nɑːt/","meaning":"tidak (ellipsis dari ''consume vast power'').","role":"verb"}],"translation":"Server lama mengonsumsi daya besar, sedangkan server modern tidak."}],"forms":[{"label":"Doing so di Awal Kalimat","jp":"Enable two-factor authentication. Doing so blocks 99% of attacks.","reading":"/ˈduːɪŋ soʊ blɑːks ˈnaɪnti naɪn pərˈsɛnt əv əˈtæks/","id":"Aktifkan autentikasi dua faktor. Melakukan hal itu memblokir 99% serangan."},{"label":"Ellipsis Setelah Konjungsi","jp":"Keep the sensor dry when not in use (= when it is not in use).","reading":"/kiːp ðə ˈsɛnsər draɪ wɛn nɑːt ɪn juːs/","id":"Jaga sensor tetap kering saat tidak digunakan."},{"label":"So / Neither Agreement","jp":"Hardware costs haven''t dropped, and neither have cloud fees.","reading":"/ˈhɑːrdwɛr kɔːsts ˈhævənt drɑːpt ænd ˈniːðər hæv klaʊd fiːz/","id":"Biaya perangkat keras belum turun, dan begitu pula biaya layanan cloud."}],"mistakes":[{"wrong":"He didn''t attend the orientation, and neither I did.","right":"He didn''t attend the orientation, and neither did I. / ...and I didn''t either.","why":"Setelah ''neither'' atau ''nor'' (dan ''so'' bermakna ''begitu juga''), wajib terjadi inversi Auxiliary + Subject (''neither did I''), dan jangan diberi ''not'' lagi!"},{"wrong":"I asked her to leave her laptop, but she didn''t want to leave.","right":"I asked her to leave her laptop, but she didn''t want to.","why":"Dalam Ellipsis Infinitive (''didn''t want to'', ''would love to'', ''used to''), pertahankan kata ''to'' sebagai penanda kata kerja yang dilesapkan agar artinya tidak berubah menjadi ''pergi'' (''leave'')!"}],"quiz":[{"question":"Soal TOEFL Reading Reference: ''Firms were urged to disclose carbon metrics voluntarily, yet few chose to do so.'' Frasa ''do so'' merujuk pada:","options":["urge other firms","disclose carbon metrics voluntarily","pay carbon fines","choose a few metrics"],"answer":1,"why":"''Do so'' menggantikan seluruh frasa verba predikat sebelumnya, yaitu ''disclose carbon metrics voluntarily''."},{"question":"Pilih lanjutan paralel negatif yang benar: ''Traditional antibiotics cannot neutralize viral infections, ___.''","options":["and neither herbal supplements can","nor can unverified herbal supplements","and so can''t herbal supplements","nor herbal supplements cannot"],"answer":1,"why":"Konjungsi negatif ''nor'' (atau ''and neither'') menuntut inversi positif Auxiliary + Subject: ''nor + can + [subject]''."},{"question":"Dalam dialog: A: ''Will the budget cut affect our fellowship?'' — B: ''I certainly hope ___.'' Kata yang tepat adalah:","options":["no","not","none","don''t"],"answer":1,"why":"Substitusi klausa negatif setelah ''hope'', ''assume'', ''suspect'', dan ''be afraid'' menggunakan ''not'' (''I hope not'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000051', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-001', 'sentence_pattern', 'Inverted Conditionals: Pengandaian Elit Tanpa If (Had we known / Were it to fail)', 'Type 1: Should + S + V1 • Type 2: Were + S + (to V1) • Type 3: Had + S + (not) + V3 (TANPA ''If''!)', 'Menghapus kata ''if'' dan mengedepankan ''Should'', ''Were'', atau ''Had'' untuk menghasilkan pengandaian tingkat eksekutif dan akademik tertinggi.', 1, '2026-11-26T00:00:00+00:00', '[{"jp":"Should you require any further clarification, please do not hesitate to reach out.","reading":"/ʃʊd juː rɪˈkwaɪər ˈɛni ˈfɜːrðər ˌklærəfɪˈkeɪʃən pliːz duː nɑːt ˈhɛzɪteɪt/","id":"Apabila Anda membutuhkan klarifikasi lebih lanjut, jangan ragu untuk menghubungi kami."},{"jp":"Had we not diversified our cloud providers, the outage would have paralyzed operations.","reading":"/hæd wiː nɑːt daɪˈvɜːrsɪfaɪd ˈaʊər klaʊd prəˈvaɪdərz ði ˈaʊtɪdʒ wʊd hæv ˈpærəlaɪzd/","id":"Seandainya dulu kami tidak mendiversifikasi penyedia cloud kami, gangguan itu pasti telah melumpuhkan operasional."}]'::jsonb, 'Should you require... • Were the grid to fail... • Had it not been for...', '{"analogy":"Di level C2 dan soal tersulit TOEFL, kata ''If'' dianggap bisa digantikan oleh gerakan akrobatik elegan: hapus ''If'', lalu tarik ''Should'' (Type 1 sopan), ''Were'' (Type 2 hipotesis), atau ''Had'' (Type 3 lampau) ke paling depan kalimat! Hati-hati satu aturan besi negasinya: dalam Conditional Inversion, dilarang keras memakai kontraksi ''Hadn''t / Weren''t''—kata ''NOT'' wajib berdiri terpisah SETELAH subjek (''Had we NOT known'', bukan ''Hadn''t we known''!)!","when_to_use":["Should + Subject + V1: korespondensi bisnis formal, kontrak, dan layanan eksekutif (''Should any issue arise...'')","Were + Subject + Adj/Noun (atau ''Were + Subject + to V1'' untuk kata kerja aksi!): menganalisis skenario risiko hipotesis yang kecil kemungkinannya terjadi","Had + Subject + (not) + V3 (termasuk idiom emas ''Had it not been for...''): mengevaluasi titik balik sejarah atau post-mortem strategis"],"formula_parts":[{"role":"particle","text":"Should / Were / Had","label":"Pengganti ''If'' di Awal"},{"role":"subject","text":"Subject (+ not)","label":"''not'' Wajib Setelah Subjek!"},{"role":"verb","text":"V1 | to V1 | V3","label":"Sesuai Tipe 1, 2, atau 3"},{"role":"predicate","text":"Main Result Clause","label":"will / would / would have"}],"steps":["Untuk Type 1 formal: ganti ''If you need...'' menjadi ''Should you need...'' (+ V1 murni walaupun subjeknya tunggal: ''Should the server crash...'').","Untuk Type 2 dengan kata kerja aksi (''If interest rates rose...''): karena tidak ada ''were'' di kalimat aslinya, panggil rumus ''Were + Subject + TO V1'' (''Were interest rates to rise, borrowing would slow'')!","Untuk Type 3 negatif: pecah ''If we hadn''t acted'' menjadi ''Had + we + NOT + acted'' (jangan pernah menulis ''Hadn''t we acted...'' karena itu berubah jadi kalimat tanya biasa!)."],"breakdowns":[{"tokens":[{"jp":"Were","reading":"/wɜːr/","meaning":"seandainya (inversi Type 2 tanpa ''if'')","role":"particle"},{"jp":"the treaty","reading":"/ðə ˈtriːti/","meaning":"perjanjian tersebut","role":"subject"},{"jp":"to collapse,","reading":"/tə kəˈlæps/","meaning":"runtuh (wajib ''to + V1'' untuk aksi!),","role":"verb"},{"jp":"tariffs would surge.","reading":"/ˈtærɪfs wʊd sɜːrdʒ/","meaning":"tarif bea akan melonjak.","role":"predicate"}],"translation":"Seandainya perjanjian tersebut runtuh, tarif bea akan melonjak."},{"tokens":[{"jp":"Had it not been for","reading":"/hæd ɪt nɑːt bɪn fɔːr/","meaning":"seandainya dulu bukan karena (= Without)","role":"connector"},{"jp":"her fellowship,","reading":"/hɜːr ˈfɛloʊʃɪp/","meaning":"beasiswa risetnya,","role":"noun"},{"jp":"she could not have attended.","reading":"/ʃiː kʊd nɑːt hæv əˈtɛndɪd/","meaning":"dia tidak mungkin bisa kuliah di sana.","role":"predicate"}],"translation":"Seandainya dulu bukan karena beasiswa risetnya, dia tidak mungkin bisa kuliah di sana."}],"forms":[{"label":"Type 1 Eksekutif (Should)","jp":"Should the flight be canceled, the airline will rebook us.","reading":"/ʃʊd ðə flaɪt biː ˈkænsəld ði ˈɛrlaɪn wɪl riːˈbʊk ʌs/","id":"Apabila penerbangan dibatalkan, maskapai akan menjadwalkan ulang tiket kita."},{"label":"Type 2 Hipotesis (Were...to)","jp":"Were I in charge, I would prioritize debt reduction.","reading":"/wɜːr aɪ ɪn tʃɑːrdʒ aɪ wʊd praɪˈɔːrətaɪz dɛt rɪˈdʌkʃən/","id":"Andaikan saya yang memegang kendali, saya akan memprioritaskan pengurangan utang."},{"label":"Type 3 Lampau (Had...not)","jp":"Had the sensor triggered earlier, the spill would have been contained.","reading":"/hæd ðə ˈsɛnsər ˈtrɪɡərd ˈɜːrliər ðə spɪl wʊd hæv bɪn kənˈteɪnd/","id":"Andaikan sensor itu aktif lebih awal, tumpahannya pasti dapat dibendung."}],"mistakes":[{"wrong":"If had we known about the tax hike, we would have budgeted differently.","right":"Had we known about the tax hike, we would have budgeted differently.","why":"Inversi ''Had we...'' SUDAH menggantikan fungsi ''If''—memakai ''If'' dan inversi sekaligus adalah kesalahan fatal ganda!"},{"wrong":"Hadn''t the firewall blocked the packet, the server would have been breached.","right":"Had the firewall not blocked the packet, the server would have been breached.","why":"Dalam Inverted Conditional, negasi tidak boleh dikontraksi bersama kata bantu di depan; wajib ''Had + Subject + not + V3''!"}],"quiz":[{"question":"Soal level tertinggi TOEFL Structure: ''___ the Atlantic thermohaline circulation to weaken significantly, Northern Europe would face harsher winters.''","options":["If","Should","Were","Had"],"answer":2,"why":"Perhatikan adanya struktur ''to weaken'' (to + V1) dan hasil ''would face'' (Type 2)—satu-satunya kata pembuka yang berpasangan dengan ''Subject + to V1'' adalah ''Were''!"},{"question":"Pilih bentuk Inverted Type 3 negatif yang benar secara gramatikal:","options":["Hadn''t it been for the antibiotics, the infection would have spread.","Had it not been for the antibiotics, the infection would have spread.","If had it not been for the antibiotics, the infection would have spread.","Were it not been for the antibiotics, the infection would have spread."],"answer":1,"why":"''Had it not been for + Noun'' (= If it hadn''t been for...) meletakkan ''not'' sesudah subjek ''it'' tanpa kata ''If''."},{"question":"Lengkapi surat resmi berikut: ''___ any discrepancy arise during the audit, notify the compliance officer immediately.''","options":["Were","Had","Should","Would"],"answer":2,"why":"Karena diikuti V1 telanjang ''arise'' (tanpa ''to'') dan induk kalimat imperatif (Type 1), pembuka yang tepat adalah ''Should''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000052', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-002', 'tense', 'Be + To-Infinitive: Mandat Resmi, Protokol & Takdir (are to comply)', 'Mandat/Jadwal Resmi: am/is/are + (not) + to V1 • Syarat Tujuan: If + S + be + to V1 • Takdir Lampau: was/were + to V1', 'Menyatakan instruksi otoritatif, agenda kenegaraan/korporat, prasyarat kesuksesan, serta takdir sejarah (''future in the past'').', 2, '2026-11-26T00:00:00+00:00', '[{"jp":"All contractors are to sign the non-disclosure agreement prior to onboarding.","reading":"/ɔːl ˈkɑːntræktərz ɑːr tə saɪn ðə ˌnɑːndɪsˈkloʊʒər əˈɡriːmənt ˈpraɪər tu ˈɑːnbɔːrdɪŋ/","id":"Seluruh kontraktor diwajibkan menandatangani perjanjian kerahasiaan sebelum orientasi kerja."},{"jp":"If developing nations are to achieve net-zero targets, green financing must triple.","reading":"/ɪf dɪˈvɛləpɪŋ ˈneɪʃənz ɑːr tu əˈtʃiːv nɛt ˈzɪroʊ ˈtɑːrɡɪts ɡriːn faɪˈnænsɪŋ mʌst ˈtrɪpəl/","id":"Jika negara-negara berkembang ingin mencapai target nol emisi bersih, pembiayaan hijau harus meningkat tiga kali lipat."}]'::jsonb, 'All staff are to complete... • If we are to succeed... • was never to return', '{"analogy":"Struktur pendek ''be + to + V1'' menyimpan wibawa luar biasa yang sering luput dipahami pembelajar menengah! Ketika bandara atau CEO menulis ''Passengers are not to leave bags unattended'', artinya BUKAN ''sedang adalah untuk'', melainkan perintah mutlak setara ''must not''! Di koran berita, judul ''Prime Minister to visit Jakarta'' adalah bentuk ringkas dari ''is to visit'' (agenda resmi terjadwal). Dan di teks sejarah TOEFL Reading, ''Little did he know that this discovery WAS TO change physics forever'' menceritakan takdir masa depan dilihat dari titik masa lampau!","when_to_use":["Mengeluarkan protokol resmi, aturan keselamatan, atau instruksi dewan tanpa memakai kata ''must'' (''No files are to be removed'')","Membangun kalimat prasyarat strategis di TOEFL Writing dengan pola favorit C2: ''If [Subject] is/are to [achieve goal], [prerequisite must happen]''","Menceritakan kelanjutan nasib sejarah (''Future in the Past'') dalam biografi dan bacaan humaniora: ''was/were (never) to + V1'' vs rencana batal ''was/were to have + V3''"],"formula_parts":[{"role":"subject","text":"Subject","label":"Pelaku / Kebijakan"},{"role":"verb","text":"am/is/are/was/were + (not)","label":"Be Verb Penentu Waktu"},{"role":"verb","text":"to + V1 / to be + V3","label":"Mandat / Agenda / Takdir"}],"steps":["Gunakan ''is/are (not) to + V1'' (atau pasif ''is/are to be + V3'') untuk pengumuman resmi dan tata tertib institusi.","Hafalkan formula esai juara ''If + S + is/are to + V1'' yang artinya ''Jika [subjek] benar-benar ingin/hendak mencapai...''.","Bedakan di bacaan sejarah: ''was to become famous'' (takdir yang akhirnya BENAR terjadi kemudian), sedangkan ''The summit was to have taken place in May'' (''was to have + V3'' = tadinya dijadwalkan terjadi, tapi BATAL!)."],"breakdowns":[{"tokens":[{"jp":"Sensitive backups","reading":"/ˈsɛnsətɪv ˈbækʌps/","meaning":"cadangan data sensitif","role":"subject"},{"jp":"are not","reading":"/ɑːr nɑːt/","meaning":"dilarang keras (mandat negatif)","role":"verb"},{"jp":"to be stored","reading":"/tə biː stɔːrd/","meaning":"untuk disimpan (pasif)","role":"verb"},{"jp":"on personal drives.","reading":"/ɑːn ˈpɜːrsənəl draɪvz/","meaning":"di penyimpanan pribadi.","role":"place"}],"translation":"Cadangan data sensitif dilarang keras disimpan pada penyimpanan pribadi."},{"tokens":[{"jp":"The young inventor left Vienna in 1899,","reading":"/ðə jʌŋ ɪnˈvɛntər lɛft viˈɛnə/","meaning":"sang penemu muda meninggalkan Wina tahun 1899,","role":"predicate"},{"jp":"never to return.","reading":"/ˈnɛvər tə rɪˈtɜːrn/","meaning":"dan ditakdirkan tak pernah kembali lagi selamanya.","role":"ending"}],"translation":"Sang penemu muda meninggalkan Wina pada tahun 1899, dan tak pernah kembali lagi selamanya."}],"forms":[{"label":"Agenda Resmi Berita","jp":"The central bank is to announce interest rate decisions Wednesday.","reading":"/ðə ˈsɛntrəl bæŋk ɪz tu əˈnaʊns ˈɪntrəst reɪt dɪˈsɪʒənz/","id":"Bank sentral dijadwalkan mengumumkan keputusan suku bunga pada hari Rabu."},{"label":"Prasyarat Esai (If...are to)","jp":"If cities are to remain livable, transit investment is essential.","reading":"/ɪf ˈsɪtiz ɑːr tə rɪˈmeɪn ˈlɪvəbəl ˈtrænzɪt ɪnˈvɛstmənt/","id":"Jika kota-kota ingin tetap layak huni, investasi transportasi umum sangatlah mutlak."},{"label":"Rencana Lampau Batal (was to have V3)","jp":"The spacecraft was to have launched Tuesday, but winds delayed it.","reading":"/ðə ˈspeɪskræft wəz tə hæv lɔːntʃt ˈtuːzdeɪ/","id":"Wahana antariksa itu tadinya dijadwalkan meluncur Selasa, namun tertunda angin."}],"mistakes":[{"wrong":"If I am to miss the bus, I''ll walk (salah pakai untuk kebetulan sepele).","right":"If I miss the bus, I''ll walk. (Pakai ''If + be to V1'' khusus untuk TUJUAN/TARGET yang ingin dicapai!).","why":"''If + S + be to V1'' mengandung makna ''in order to / jika ingin berhasil mencapai tujuan'', bukan untuk kejadian kebetulan sehari-hari."},{"wrong":"Visitors are not leaving the marked trail (kurang tegas sebagai aturan tertulis).","right":"Visitors are not to leave the marked trail.","why":"Untuk larangan protokol resmi, gunakan ''are not to + V1'', bukan Present Continuous biasa."}],"quiz":[{"question":"Dalam bacaan biografi TOEFL Reading tertulis: ''In 1928, Fleming noticed mold on a petri dish—an observation that was to save millions of lives.'' Apa arti ''was to save''?","options":["Fleming batal menyelamatkan nyawa","Di kemudian hari dalam sejarah, pengamatan tersebut terbukti menyelamatkan jutaan nyawa (takdir masa depan dari sudut pandang 1928)","Fleming diwajibkan oleh atasannya mencuci cawan petri","Pengamatan itu sudah selesai sebelum 1928"],"answer":1,"why":"''Was/were to + V1'' dalam narasi sejarah menyatakan ''Future in the Past''—peristiwa yang kelak benar-benar terwujud sesudah titik waktu cerita."},{"question":"Apa makna tersirat dari kalimat ''The merger was to have been finalized in March''?","options":["Mergernya resmi selesai pada bulan Maret","Mergernya semula dijadwalkan rampung bulan Maret, tetapi kenyataannya BATAL atau TERTUNDA","Mergernya baru direncanakan untuk Maret tahun depan","Mergernya dilarang oleh hukum"],"answer":1,"why":"Bentuk lampau sempurna ''was/were + to have + V3'' secara spesifik menandakan rencana masa lalu yang TIDAK terwujud sesuai jadwal!"},{"question":"Pilih pembuka kalimat tesis C2 yang paling tepat: ''___ public trust in AI systems, transparency standards must be enforceable.''","options":["If developers are to earn","If developers were earn","Should developers earning","Are developers to earning"],"answer":0,"why":"''If [developers] are to [earn]...'' secara idiomatis berarti ''Jika para pengembang ingin berhasil meraih kepercayaan publik...''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000053', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-003', 'sentence_pattern', 'Absolute Constructions: Klausa Lepas Berkelas (The audit completed, ...)', '(With) + [Own Noun Subject] + [V-ing / V3 / Adj / Prep Phrase], + [Main Clause with DIFFERENT Subject]', 'Menambahkan klausa latar/sebab yang memiliki subjek sendiri tanpa kata kerja finit maupun konjungsi untuk kepadatan gaya prosa C2.', 3, '2026-11-26T00:00:00+00:00', '[{"jp":"The security audit completed, the engineering team proceeded with deployment.","reading":"/ðə sɪˈkjʊrəti ˈɔːdɪt kəmˈpliːtɪd ði ˌɛndʒɪˈnɪrɪŋ tiːm prəˈsiːdɪd wɪð dɪˈplɔɪmənt/","id":"Begitu audit keamanan tuntas, tim teknik melanjutkan proses penayangan sistem."},{"jp":"With enterprise demand surging, the startup doubled its server capacity.","reading":"/wɪð ˈɛntərpraɪz dɪˈmænd ˈsɜːrdʒɪŋ ðə ˈstɑːrtʌp ˈdʌbəld ɪts ˈsɜːrvər kəˈpæsəti/","id":"Seiring melonjaknya permintaan korporat, perusahaan rintisan itu menggandakan kapasitas servernya."}]'::jsonb, 'Weather permitting (/pərˈmɪtɪŋ/), ... • All things considered, ... • With inflation easing, ...', '{"analogy":"Ingat aturan Participial Phrase di B2 yang melarang dua subjek berbeda (''Having completed the audit, the team...''—subjek harus sama)? Nah, bagaimana kalau kita INGIN memakai dua subjek berbeda (''Auditnya selesai'' + ''Timnya lanjut'') secara super ringkas tanpa ''after/because''? Jawabannya adalah Nominative Absolute Construction! Caranya: cantumkan subjek milik frasa pertama (''The audit''), buang ''was/is''-nya sehingga tersisa partisip ''completed'', pisahkan dengan koma, lalu masuk ke kalimat utama! Ini bukan kesalahan Dangling Modifier, melainkan puncak gaya prosa C2!","when_to_use":["Memadatkan hubungan sebab-akibat atau urutan waktu di mana klausa pertama punya subjek tersendiri (''The vote having been cast, the session adjourned'')","Memakai versi modern yang sangat produktif di jurnalisme ekonomi & bisnis AS dengan awalan ''With'': ''With + [Noun] + [V-ing / V3 / Prep]''","Menggunakan ungkapan idiomatis baku C2: ''Weather permitting,'' (Jika cuaca mengizinkan), ''All things considered,'' (Mempertimbangkan segalanya), ''Other things being equal,'' (Ceteris paribus)"],"formula_parts":[{"role":"particle","text":"(With)","label":"Opsional Pengantar Kausal"},{"role":"subject","text":"Noun Phrase 1","label":"Subjek Milik Klausa Lepas"},{"role":"adjective","text":"V-ing / V3 / Adj / Prep,","label":"TANPA Verb Finit (is/was)!"},{"role":"predicate","text":"Subject 2 + Finite Verb","label":"Induk Kalimat Utama"}],"steps":["Pastikan di dalam Absolute Phrase TIDAK ADA kata kerja finit (''was, were, is, are'')! Jika kamu menulis ''The audit WAS completed, the team proceeded'' tanpa konjungsi, itu menjadi kesalahan Comma Splice ❌!","Pilih ''V-ing'' jika Noun 1 melakukan aksi aktif (''Time permitting,'', ''With costs rising,''), dan ''V3'' jika Noun 1 dikenai aksi pasif (''All seats taken,'', ''With the bug fixed,'').","Kenali struktur ini di soal TOEFL Structure supaya tidak terjebak memilih ''was/were'' ketika tidak ada konjungsi penghubung antar-klausa!"],"breakdowns":[{"tokens":[{"jp":"All other variables","reading":"/ɔːl ˈʌðər ˈvɛriəbəlz/","meaning":"semua variabel lainnya (Subjek 1)","role":"subject"},{"jp":"held constant,","reading":"/hɛld ˈkɑːnstənt/","meaning":"dijaga tetap konstan (V3 pasif tanpa ''are/were''!),","role":"adjective"},{"jp":"reaction rates","reading":"/riˈækʃən reɪts/","meaning":"laju reaksi (Subjek 2)","role":"subject"},{"jp":"double every 10°C.","reading":"/ˈdʌbəl ˈɛvri tɛn dɪˈɡriːz/","meaning":"berlipat ganda setiap kenaikan 10°C.","role":"predicate"}],"translation":"Dengan semua variabel lain dijaga konstan, laju reaksi berlipat ganda setiap kenaikan 10°C."},{"tokens":[{"jp":"Time permitting,","reading":"/taɪm pərˈmɪtɪŋ/","meaning":"jika waktu memungkinkan (Absolute aktif),","role":"time"},{"jp":"we''ll take","reading":"/wiːl teɪk/","meaning":"kita akan membuka","role":"verb"},{"jp":"live audience questions.","reading":"/laɪv ˈɔːdiəns ˈkwɛstʃənz/","meaning":"pertanyaan langsung dari hadirin.","role":"object"}],"translation":"Jika waktu memungkinkan, kita akan membuka sesi tanya jawab langsung dari hadirin."}],"forms":[{"label":"With + Noun + V-ing (Aktif)","jp":"With deadlines looming, the editors worked through the weekend.","reading":"/wɪð ˈdɛdlaɪnz ˈluːmɪŋ ði ˈɛdɪtərz wɜːrkt θruː/","id":"Dengan tenggat waktu yang kian membayangi, para editor bekerja sepanjang akhir pekan."},{"label":"Noun + V3 (Tanpa With)","jp":"Negotiations having stalled, both sides called in mediators.","reading":"/nɪˌɡoʊʃiˈeɪʃənz ˈhævɪŋ stɔːld boʊθ saɪdz kɔːld ɪn/","id":"Karena perundingan mengalami jalan buntu, kedua belah pihak memanggil mediator."},{"label":"Idiom Tetap C2","jp":"All things considered, the product launch exceeded expectations.","reading":"/ɔːl θɪŋz kənˈsɪdərd ðə ˈprɑːdʌkt lɔːntʃ ɪkˈsiːdɪd/","id":"Mempertimbangkan segala aspek, peluncuran produk tersebut melampaui ekspektasi."}],"mistakes":[{"wrong":"The contract was signed, both CEOs shook hands for the press.","right":"The contract signed, both CEOs shook hands. / Once the contract was signed, both CEOs...","why":"Dua klausa yang masing-masing punya kata kerja finit (''was signed'' dan ''shook'') tidak boleh cuma dipisah koma (Comma Splice)! Buang ''was'' (Absolute) atau tambahkan konjungsi ''Once/After''!"},{"wrong":"With interest rates are falling, tech stocks rallied.","right":"With interest rates falling, tech stocks rallied.","why":"''With'' adalah preposisi, bukan konjungsi! Di belakang ''With + Noun'', kata kerjanya wajib non-finit (''falling'' / ''cut''), dilarang memakai ''are/were''!"}],"quiz":[{"question":"Soal jebakan maut TOEFL Structure: ''___, the expedition team set up base camp before nightfall.''","options":["The supplies were unloaded","Their supplies unloaded","Unloaded their supplies","Because their supplies unloading"],"answer":1,"why":"Karena tidak ada konjungsi (''After/Once''), pilihan A menciptakan Comma Splice! Pilihan B (''Their supplies unloaded'') adalah Absolute Construction sah (= After their supplies had been unloaded)."},{"question":"Perbaiki kalimat laporan ekonomi ini: ''With semiconductor supply chains ___ across three continents, a single port closure can halt production.''","options":["spread","are spread","were spreading","to spreading"],"answer":0,"why":"Setelah preposisi ''With + Noun'', dibutuhkan Past Participle V3 pasif ''spread'' (V1-V2-V3: spread-spread-spread), bukan kata kerja finit ''are spread''."},{"question":"Apa arti dari frasa tetap ''Other things being equal'' dalam ekonomi dan sains?","options":["Semua hal di dunia ini tidak adil","Dengan asumsi faktor-faktor lainnya tetap sama / tidak berubah (ceteris paribus)","Hal lain jauh lebih penting","Kedua opsi gagal total"],"answer":1,"why":"''Other things being equal'' adalah konstruksi absolut idiomatis untuk menyatakan asumsi variabel lain tidak berubah."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000054', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-004', 'sentence_pattern', 'Concessive Inversion: Konsesi Emfatik (Much as I respect / Try as they might)', '[Adj / Adv] + as / though + [Subject + Verb] • [Base Verb] + as + [Subject + may/might] • Much as + [S + V]', 'Mengangkat kata sifat, kata kerja dasar, atau ''Much as'' ke awal klausa untuk menciptakan kontras konsesi bernilai sastra dan retoris tinggi.', 4, '2026-11-26T00:00:00+00:00', '[{"jp":"Impressive though the benchmark scores are, real-world latency remains an issue.","reading":"/ɪmˈprɛsɪv ðoʊ ðə ˈbɛntʃmɑːrk skɔːrz ɑːr ˈriːəlwɜːrld ˈleɪtənsi rɪˈmeɪnz ən ˈɪʃuː/","id":"Sekalipun skor tolok ukurnya begitu mengesankan, latensi di dunia nyata tetap menjadi kendala."},{"jp":"Much as I admire their bold vision, the unit economics simply don''t add up.","reading":"/mʌtʃ æz aɪ ədˈmaɪər ðɛr boʊld ˈvɪʒən ðə ˈjuːnɪt ˌɛkəˈnɑːmɪks ˈsɪmpli doʊnt æd ʌp/","id":"Betapapun besarnya kekaguman saya pada visi berani mereka, hitungan ekonomi per unitnya tetap tidak masuk akal."}]'::jsonb, 'Compelling though the theory is, ... • Try as she might, ... • Much as I admire...', '{"analogy":"Kalau semua orang menulis ''Although the theory is compelling'', tulisan C2 membalik urutannya dengan melempar kata sifatnya ke paling depan bak pukulan pembuka: ''Compelling though/as the theory is,...''! Berbeda dari Negative Inversion, di sini Subjek + Verb-nya tetap berurutan normal di ujung klausa konsesi. Dan untuk usaha maksimal yang tetap gagal menembus batas, ada pola legendaris C2: ''Try as they might,...'' (''Seberapapun kerasnya mereka mencoba,...'')!","when_to_use":["[Adjective / Adverb] + as / though + Subject + Verb: memberi penekanan kuat pada kualitas yang diakui sebelum membelokkan argumen ('' appealing as the idea sounds,...'')","Much as + Subject + Verb suka/hargai/ingin: membuka kritik atau penolakan secara sangat berkelas (''Much as I''d love to join,...'')","[V1] + as + Subject + may / might / will: menekankan usaha keras yang tetap tak membuahkan hasil (''Search as we might, we found no trace'')"],"formula_parts":[{"role":"adjective","text":"Adj / Adv / Base Verb","label":"Dilempar ke Paling Depan"},{"role":"connector","text":"as / though","label":"Bukan ''although''!"},{"role":"predicate","text":"Subject + Verb","label":"Tanpa ''but'' di Induk Kalimat"}],"steps":["Tarik kata sifat/keterangan ke awal kalimat, pasang ''as'' atau ''though'' (JANGAN ''although''! ''Although'' tidak pernah boleh dipakai di posisi kedua ini!), lalu lanjutkan dengan ''Subject + Verb''.","Jika yang dikedepankan adalah KATA BENDA tunggal terhitung untuk konsesi, artikel ''a/an'' wajib DIHAPUS ('' Skeptic though he was,...'' = Although he was a skeptic)!","Gunakan ''(As) much as + S + V'' di awal kalimat untuk arti ''Meskipun saya sangat...''—jangan tertukar dengan perbandingan kuantitas!"],"breakdowns":[{"tokens":[{"jp":"Skeptical","reading":"/ˈskɛptɪkəl/","meaning":"meski begitu skeptis (Adjective dikedepankan)","role":"adjective"},{"jp":"as","reading":"/æz/","meaning":"sekalipun (= although)","role":"connector"},{"jp":"reviewers initially were,","reading":"/rɪˈvjuːərz ɪˈnɪʃəli wɜːr/","meaning":"para peninjau pada awalnya,","role":"predicate"},{"jp":"the replication succeeded.","reading":"/ðə ˌrɛplɪˈkeɪʃən səkˈsiːdɪd/","meaning":"uji replikasi tersebut berhasil.","role":"predicate"}],"translation":"Sekalipun para peninjau awalnya begitu skeptis, uji replikasi tersebut berhasil."},{"tokens":[{"jp":"Try as","reading":"/traɪ æz/","meaning":"sekeras apa pun mencoba (V1 + as)","role":"verb"},{"jp":"competitors might,","reading":"/kəmˈpɛtɪtərz maɪt/","meaning":"para pesaing berusaha,","role":"subject"},{"jp":"they couldn''t match","reading":"/ðeɪ ˈkʊdənt mætʃ/","meaning":"mereka tak sanggup menandingi","role":"predicate"},{"jp":"its ecosystem.","reading":"/ɪts ˈiːkoʊˌsɪstəm/","meaning":"ekosistem produk tersebut.","role":"object"}],"translation":"Sekeras apa pun para pesaing mencoba, mereka tak sanggup menandingi ekosistem produk tersebut."}],"forms":[{"label":"Adjective + though/as","jp":"Counterintuitive though it sounds, adding lanes can worsen traffic.","reading":"/ˌkaʊntərɪnˈtuːɪtɪv ðoʊ ɪt saʊndz ˈædɪŋ leɪnz kən ˈwɜːrsən/","id":"Sekalipun terdengar berlawanan dengan intuisi, menambah lajur jalan justru dapat memperparah kemacetan."},{"label":"Much as + S + V","jp":"Much as we value speed, we never compromise on safety.","reading":"/mʌtʃ æz wiː ˈvæljuː spiːd wiː ˈnɛvər ˈkɑːmprəmaɪz ɑːn ˈseɪfti/","id":"Betapapun tingginya kami menghargai kecepatan, kami tak pernah berkompromi soal keselamatan."},{"label":"Be it A or B (Baik A maupun B)","jp":"Every dependency—be it internal or third-party—must be audited.","reading":"/ˈɛvri dɪˈpɛndənsi biː ɪt ɪnˈtɜːrnəl ɔːr ˈθɜːrdˌpɑːrti/","id":"Setiap pustaka ketergantungan—baik internal maupun pihak ketiga—wajib diaudit."}],"mistakes":[{"wrong":"Expensive although the equipment was, it paid for itself.","right":"Expensive though / as the equipment was, it paid for itself.","why":"Kata ''although'' HANYA boleh berdiri di paling awal klausa! Untuk pola kata sifat yang dikedepankan, wajib memakai ''though'' atau ''as''!"},{"wrong":"Brilliant though was the strategy, it failed.","right":"Brilliant though the strategy was, it failed.","why":"Dalam Concessive Fronting, kata sifatnya yang maju ke depan, sedangkan ''Subject + Verb'' (''the strategy was'') tetap dalam susunan normal!"}],"quiz":[{"question":"Soal C2 / TOEFL Reading & Structure: ''___ as the new compression algorithm appears on paper, it struggles with noisy audio.''","options":["Although promising","Promising","It is promising","Promisingly"],"answer":1,"why":"Struktur ''[Adjective] + as + Subject + Linking Verb (appears)'' membutuhkan kata sifat ''Promising'' (= Although the algorithm appears promising)."},{"question":"Apa makna kalimat ''Much as Dr. Sato respected her mentor''s legacy, she published data refuting his model''?","options":["Karena sangat menghormati mentornya, Dr. Sato membatalkan publikasi datanya","Walaupun sangat menghormati warisan ilmiah mentornya, Dr. Sato tetap menerbitkan data yang membantah model sang mentor","Dr. Sato menghormati mentornya persis sebanyak ia menyukai datanya","Dr. Sato tidak menghormati mentornya sama sekali"],"answer":1,"why":"''Much as + S + V'' di awal kalimat berfungsi sebagai klausa konsesi yang kuat (''Meskipun sangat...'')."},{"question":"Pilih pelengkap struktur konsesi klasik ini: ''Strange ___ it may seem, hot water can freeze faster than cold water under certain conditions.''","options":["although","despite","though","however"],"answer":2,"why":"Hanya ''though'' atau ''as'' yang sah menempati posisi setelah kata sifat yang dikedepankan (''Strange though/as it may seem'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000055', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-005', 'honorific', 'Distancing & Evidentiality: Kritik Riset Objektif (is alleged to have / purports to)', '[Subject] + is alleged / thought / rumored / claimed + to V1 (kini) / to have V3 (lampau) • purports to + V1', 'Menjaga jarak intelektual dan hukum dari klaim pihak lain menggunakan pasif pelaporan perfek dan penanda skeptisisme halus.', 5, '2026-11-26T00:00:00+00:00', '[{"jp":"The manuscript is thought to have been written in the twelfth century.","reading":"/ðə ˈmænjəskrɪpt ɪz θɔːt tə hæv bɪn ˈrɪtən ɪn ðə twɛlfθ ˈsɛntʃəri/","id":"Naskah kuno tersebut diperkirakan telah ditulis pada abad kedua belas."},{"jp":"The supplement purports to boost memory, yet double-blind trials show no effect.","reading":"/ðə ˈsʌplɪmənt pərˈpɔːrts tə buːst ˈmɛməri jɛt ˈdʌbəl blaɪnd ˈtraɪəlz ʃoʊ noʊ ɪˈfɛkt/","id":"Suplemen itu mengklaim mampu meningkatkan daya ingat, namun uji buta ganda tidak menunjukkan efek apa pun."}]'::jsonb, 'is thought to have originated • purports (/pərˈpɔːrts/) to solve • ostensibly (/ɑːˈstɛnsəbli/)', '{"analogy":"Dalam jurnalisme investigasi, hukum, dan tinjauan pustaka (literature review) TOEFL Integrated Writing, kamu tidak boleh menelan klaim orang lain mentah-mentah seolah itu faktamu sendiri! ''Distancing'' adalah sarung tangan steril akademik: ''is thought to have V3'' melaporkan konsensus pakar atas kejadian lampau secara netral; ''is alleged to have V3'' melindungi dari tuntutan pencemaran nama baik (''diduga telah...''); sedangkan kata tajam C2 ''purports to + V1'' dan ''ostensibly'' memberi sinyal cerdas kepada pembaca: ''Klaim luarnya sih begini, tapi penulis meragukan kebenarannya!''","when_to_use":["Reporting Passive + Perfect Infinitive (''is believed / estimated / rumored / alleged + to have V3''): melaporkan aksi yang terjadi LEBIH DULU dari waktu pelaporan","Menyampaikan skeptisisme akademik di TOEFL Integrated Writing (saat Lecture membantah Reading!) menggunakan ''purports to + V1'', ''supposedly'', atau ''ostensibly'' (''secara lahiriah diklaim untuk X, padahal...'')","Menggunakan ''It is widely held that...'' atau ''Proponents contend that...'' untuk memisahkan opini kubu tertentu dari suara objektif penulis"],"formula_parts":[{"role":"subject","text":"Subject","label":"Topik yang Diklaim"},{"role":"verb","text":"is said / thought / alleged","label":"Pasif Pelapor Netral/Hukum"},{"role":"verb","text":"to V1 (kini) | to have V3 (lampau)","label":"Infinitif Biasa vs Perfek"},{"role":"particle","text":"purports to / ostensibly","label":"Sinyal Skeptis C2"}],"steps":["Perhatikan perbedaan waktu pada Infinitive setelah pasif pelapor: jika aksi yang dilaporkan terjadi di MASA LALU (''fosil itu hidup jutaan tahun lalu''), wajib gunakan Perfect Infinitive ''is believed TO HAVE LIVED'' (atau pasif ''to have been built'')!","Gunakan ''purport to + V1'' (aktif, bukan pasif ''is purported'' untuk benda/studi!) ketika merangkum klaim bacaan yang akan segera kamu patahkan dengan bukti kuliah di TOEFL Writing!","Gunakan adverbia C2 ''ostensibly'' (''secara tampak luar / dengan dalih'') ketika motif asli berbeda dari alasan yang diumumkan."],"breakdowns":[{"tokens":[{"jp":"The breach","reading":"/ðə briːtʃ/","meaning":"kebocoran data tersebut","role":"subject"},{"jp":"is alleged","reading":"/ɪz əˈlɛdʒd/","meaning":"diduga (istilah hukum belum divonis)","role":"verb"},{"jp":"to have exposed","reading":"/tə hæv ɪkˈspoʊzd/","meaning":"telah membocorkan (Perfect Infinitive lampau!)","role":"verb"},{"jp":"two million records.","reading":"/tuː ˈmɪljən ˈrɛkərdz/","meaning":"dua juta data catatan.","role":"object"}],"translation":"Kebocoran data tersebut diduga telah mengekspos dua juta catatan pengguna."},{"tokens":[{"jp":"The fee was introduced","reading":"/ðə fiː wəz ˌɪntrəˈduːst/","meaning":"biaya itu diberlakukan","role":"verb"},{"jp":"ostensibly","reading":"/ɑːˈstɛnsəbli/","meaning":"dengan dalih / tampak luarnya demi","role":"particle"},{"jp":"to fund maintenance.","reading":"/tə fʌnd ˈmeɪntənəns/","meaning":"mendanai perawatan.","role":"verb"}],"translation":"Biaya tersebut diberlakukan dengan dalih untuk mendanai pemeliharaan."}],"forms":[{"label":"Kini vs Lampau (to V1 vs to have V3)","jp":"Polynesian navigators are known to have reached South America.","reading":"/ˌpɑːlɪˈniːʒən ˈnævɪɡeɪtərz ɑːr noʊn tə hæv riːtʃt/","id":"Para navigator Polinesia diketahui telah mencapai Amerika Selatan (di masa silam)."},{"label":"Perfect Passive Infinitive","jp":"The fresco is estimated to have been painted around 1490.","reading":"/ðə ˈfrɛskoʊ ɪz ˈɛstɪmeɪtɪd tə hæv bɪn ˈpeɪntɪd/","id":"Lukisan dinding itu diperkirakan telah dilukis sekitar tahun 1490."},{"label":"Skeptis TOEFL Integrated Writing","jp":"While the reading passage contends that..., the lecturer casts doubt on this claim.","reading":"/waɪl ðə ˈriːdɪŋ ˈpæsɪdʒ kənˈtɛndz ðæt/","id":"Sementara teks bacaan berpendapat bahwa..., dosen meragukan klaim tersebut."}],"mistakes":[{"wrong":"The ancient temple is believed to build in the 9th century.","right":"The ancient temple is believed to have been built in the 9th century.","why":"Ada dua kesalahan sekaligus: candi ''dibangun'' (pasif) DAN terjadi di masa lampau (abad ke-9), sehingga wajib memakai Perfect Passive Infinitive ''to have been built''!"},{"wrong":"According to me, the author''s claim is flawed.","right":"In my view / The evidence suggests that the author''s claim is flawed.","why":"''According to'' HANYA digunakan untuk mengutip sumber pihak lain (''According to the lecturer / Dr. Chen''), tidak pernah ''According to me''!"}],"quiz":[{"question":"Soal level atas TOEFL Structure: ''The crater in Yucatán is widely accepted by geologists ___ the extinction of non-avian dinosaurs 66 million years ago.''","options":["triggering","to trigger","to have triggered","that triggered"],"answer":2,"why":"Struktur pasif pelapor ''is accepted [to...]'' yang merujuk aksi 66 juta tahun silam menuntut Perfect Infinitive aktif: ''to have triggered''."},{"question":"Dalam soal TOEFL Reading Attitude/Inference, penulis menulis: ''The policy was ostensibly designed to protect small farmers.'' Apa sikap penulis?","options":["Penulis yakin 100% kebijakan itu tulus membantu petani kecil","Penulis menyiratkan keraguan bahwa di balik alasan resminya, kebijakan itu mungkin punya tujuan lain atau gagal melindungi petani kecil","Penulis belum membaca kebijakan tersebut","Penulis mendukung penghapusan pertanian"],"answer":1,"why":"Kata kunci C2 ''ostensibly'' selalu memberi sinyal bahwa alasan yang diklaim di permukaan berbeda dari kenyataan sesungguhnya!"},{"question":"Pilih bentuk pasif pelapor lampau yang tepat untuk benda: ''Several priceless scrolls are feared ___ in the library fire.''","options":["to destroy","to have destroyed","to have been destroyed","having destroyed"],"answer":2,"why":"Gulungan naskah ''hancur terbakar'' (pasif) sebelum kekhawatiran saat ini, sehingga rumusnya ''to have been + V3 (destroyed)''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000056', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-006', 'honorific', 'Formulaic Subjunctive: Ungkapan Klasik Eksekutif (Be that as it may / Suffice it to say)', 'Be that as it may, ... • Suffice it to say (that)... • Come what may, ... • Far be it from me to + V1', 'Menggunakan fosil struktur subjunctive klasik yang tetap hidup subur dalam pidato eksekutif, opini hukum, dan wacana akademik C2.', 6, '2026-11-26T00:00:00+00:00', '[{"jp":"The migration will be complex; be that as it may, we cannot stay on legacy servers.","reading":"/ðə maɪˈɡreɪʃən wɪl biː kəmˈplɛks biː ðæt æz ɪt meɪ wiː ˈkænɑːt steɪ ɑːn ˈlɛɡəsi ˈsɜːrvərz/","id":"Migrasinya memang akan rumit; sekalipun demikian adanya, kita tidak bisa terus bertahan di server lama."},{"jp":"Suffice it to say, the audit uncovered systemic governance gaps.","reading":"/səˈfaɪs ɪt tə seɪ ði ˈɔːdɪt ʌnˈkʌvərd sɪˈstɛmɪk ˈɡʌvərnəns ɡæps/","id":"Cukuplah dikatakan bahwa audit tersebut mengungkap celah tata kelola yang sistemik."}]'::jsonb, 'Be that as it may (/biː ðæt æz ɪt meɪ/) • Suffice (/səˈfaɪs/) it to say', '{"analogy":"Mengapa orang Amerika terpelajar masih mengatakan ''God bless you'' (bukan ''blesses'') atau ''Be that as it may'' (bukan ''Is that'')? Ini adalah ''permata warisan klasik'' (Formulaic Subjunctive)—ungkapan beku yang bentuk kata kerjanya tidak boleh diutak-atik sehuruf pun! Menggunakannya satu kali dengan tepat di rapat direksi, sidang tesis, atau TOEFL Speaking/Writing langsung memancarkan penguasaan idiomatis setara penutur asli berpendidikan tinggi.","when_to_use":["Be that as it may,: transisi elegan setara ''Nevertheless / Meskipun fakta tadi mungkin benar, pokok kesimpulannya tetap tidak berubah''","Suffice it to say (that)...: merangkum detail panjang yang tak perlu dirinci satu per satu (''Cukuplah dikatakan singkatnya bahwa...'')","Far be it from me to + V1 (kerendahan hati retoris saat hendak memberi kritik: ''Bukan kapasitas saya untuk menggurui, namun...'') & Come what may (''Apa pun yang terjadi nanti'')"],"formula_parts":[{"role":"connector","text":"Be that as it may,","label":"Transisi Konsesi Elegan"},{"role":"connector","text":"Suffice it to say (that)","label":"Ringkasan Tegas Eksekutif"},{"role":"connector","text":"Far be it from me to + V1","label":"Pembuka Kritik Santun"}],"steps":["Hafalkan setiap frasa secara utuh sebagai satu kesatuan tetap (fixed expression)—jangan pernah mengubah ''Suffice'' menjadi ''Suffices'' atau ''Be'' menjadi ''Is''!","Gunakan ''Be that as it may,'' tepat di awal kalimat baru (atau setelah titik koma) untuk mengakui argumen sebelumnya lalu berpindah tegas ke keputusan utama.","Kenali juga frasa subjunctive klasik yang sering muncul di bacaan sastra/hukum TOEFL: ''so be it'' (terjadilah demikian / kita terima konsekuensinya), ''as it were'' (ibaratnya / bisa dibilang begitu), dan ''if need be'' (jika memang diperlukan—perhatikan ''need'' dan ''be'' murni!)."],"breakdowns":[{"tokens":[{"jp":"We can hire external consultants","reading":"/wiː kən ˈhaɪər ɪkˈstɜːrnəl kənˈsʌltənts/","meaning":"kita bisa menyewa konsultan luar","role":"predicate"},{"jp":"if need be.","reading":"/ɪf niːd biː/","meaning":"jika memang diperlukan (idiom baku: bukan ''if needed is''!).","role":"connector"}],"translation":"Kita dapat menyewa konsultan eksternal jika memang diperlukan."},{"tokens":[{"jp":"Far be it from me","reading":"/fɑːr biː ɪt frʌm miː/","meaning":"jauh dari niat saya untuk lancang","role":"connector"},{"jp":"to question the board,","reading":"/tə ˈkwɛstʃən ðə bɔːrd/","meaning":"mempertanyakan dewan direksi,","role":"verb"},{"jp":"yet this forecast seems optimistic.","reading":"/jɛt ðɪs ˈfɔːrkæst siːmz ˌɑːptɪˈmɪstɪk/","meaning":"namun proyeksi ini tampak terlalu optimistis.","role":"predicate"}],"translation":"Bukan bermaksud lancang mempertanyakan dewan direksi, namun proyeksi ini tampak terlalu optimistis."}],"forms":[{"label":"Transisi Argumen (Be that as it may)","jp":"Competitors raised more capital. Be that as it may, our retention leads.","reading":"/biː ðæt æz ɪt meɪ ˈaʊər rɪˈtɛnʃən liːdz/","id":"Pesaing menggalang modal lebih besar. Kendati demikian, retensi kitalah yang memimpin."},{"label":"Metafora Akademik (as it were)","jp":"Mitochondria serve as the cell''s power plants, as it were.","reading":"/ˌmaɪtəˈkɑːndriə sɜːrv æz ðə sɛlz ˈpaʊər plænts æz ɪt wɜːr/","id":"Mitokondria berfungsi ibarat pembangkit listrik bagi sel."},{"label":"Ketegasan Sikap (so be it)","jp":"If upholding privacy costs us ad revenue, then so be it.","reading":"/ɪf ʌpˈhoʊldɪŋ ˈpraɪvəsi kɔːsts ʌs æd ˈrɛvənuː ðɛn soʊ biː ɪt/","id":"Jika menjaga privasi membuat kita kehilangan pendapatan iklan, biarlah risiko itu kita ambil."}],"mistakes":[{"wrong":"Suffices it to say, the launch went smoothly.","right":"Suffice it to say, the launch went smoothly.","why":"''Suffice it to say'' memakai bentuk subjunctive klasik tanpa ''-s'' (''Let it suffice to say'')—jangan pernah menambahkan ''-s''!"},{"wrong":"If needs be / if need is (pencampuran rancu di tulisan Amerika).","right":"if need be (bentuk paling baku di American English).","why":"Dalam American English standar, frasa idiomatis tetapnya adalah ''if need be'' (= if there should be a need)."}],"quiz":[{"question":"Dalam artikel opini tertulis: ''Critics note that electric vehicles still rely on grid electricity. Be that as it may, lifecycle emissions remain significantly lower.'' Apa fungsi ''Be that as it may''?","options":["Membantah bahwa mobil listrik memakai listrik","Mengakui poin kritik tadi memang ada benarnya, tetapi menegaskan bahwa kesimpulan utamanya tetap tidak goyah","Menyatakan sebab-akibat langsung seperti ''Therefore''","Memberikan contoh tambahan seperti ''For instance''"],"answer":1,"why":"''Be that as it may'' berarti ''Meskipun fakta itu memang demikian adanya, namun...'' (setara ''Nevertheless'')."},{"question":"Pilih ejaan ungkapan tetap C2 yang 100% tepat:","options":["Suffices to saying, we won.","Suffice it to say, the negotiations were tense.","Is that as it might, we proceed.","Far is it from I to judge."],"answer":1,"why":"Ungkapan idiomatis bakunya adalah ''Suffice it to say (that)...''."},{"question":"Apa arti sisipan '', as it were,'' dalam kalimat ilmiah atau pidato?","options":["Pada masa lampau dulu kala","Bisa diibaratkan demikian / secara kiasan (menandai penggunaan metafora)","Sebaliknya dari kenyataan","Wajib dilakukan segera"],"answer":1,"why":"'', as it were,'' dipakai untuk memperhalus ungkapan kiasan atau perumpamaan (''seolah-olah / ibarat kata'')."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000057', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-007', 'sentence_pattern', 'Appositives & Resumptive Modifiers: Ekspansi Kalimat (a flaw that...)', 'Intro Appositive: [A + Adj + Noun], [Proper Subject] + V • Resumptive/Summative: [Full Clause]—[a shift / Noun + that...]', 'Memperluas kalimat panjang tanpa menjadi kabur menggunakan aposisi pembuka dan pengulang kata kunci bernapas editorial (The Economist / New Yorker style).', 7, '2026-11-26T00:00:00+00:00', '[{"jp":"A pioneer in deep learning, Geoffrey Hinton warned early about alignment risks.","reading":"/ə ˌpaɪəˈnɪr ɪn diːp ˈlɜːrnɪŋ ˈdʒɛfri ˈhɪntən wɔːrnd ˈɜːrli əˈbaʊt əˈlaɪnmənt rɪsks/","id":"Sebagai pelopor dalam deep learning, Geoffrey Hinton sejak dini memperingatkan risiko penyelarasan AI."},{"jp":"Antibiotic discovery has stalled for decades—a drought that threatens modern surgery.","reading":"/ˌæntibaɪˈɑːtɪk dɪˈskʌvəri hæz stɔːld fɔːr ˈdɛkeɪdz ə draʊt ðæt ˈθrɛtənz ˈmɑːdərn ˈsɜːrdʒəri/","id":"Penemuan antibiotik telah mandek selama puluhan tahun—sebuah kemarau inovasi yang mengancam bedah modern."}]'::jsonb, 'A pioneer in AI, Dr. Hinton... • ...dropped 30%, a decline that alarmed...', '{"analogy":"Pernah bingung saat menulis kalimat panjang dengan '', which...'' karena tidak jelas kata ''which'' itu merujuk ke kata benda terakhir atau ke seluruh kalimat? Penulis esai level C2 punya jurus jauh lebih tajam bernama **Summative & Resumptive Modifier**! Caranya: selesaikan kalimat utamamu, pasang tanda koma atau *em-dash* (`—`), lalu rangkum seluruh ide tadi menjadi SATU KATA BENDA TAJAM + `that` (`—a bottleneck that...`, `—a paradox that...`), atau ulangi kata kunci terakhir untuk dikupas lebih dalam! Hasilnya: nol ambiguitas dan super berwibawa!","when_to_use":["Fronted Appositive (''[Noun Phrase], [Subject] + Verb''): cara paling favorit soal #1–5 TOEFL Structure membuka kalimat biografi atau definisi ilmiah tanpa kata kerja tambahan!","Summative Modifier ('', a [summary noun] that...''): menggantikan '', which...'' yang kabur dengan merangkum seluruh klausa sebelumnya ke dalam nomina evaluatif (''a phenomenon that'', ''a flaw that'', ''an achievement that'')","Resumptive Modifier (''—[repeated word] that...''): mengulang kata kunci penting di ujung klausa agar kalimat panjang tetap jernih dan dramatis"],"formula_parts":[{"role":"noun","text":"[Noun Phrase], [Matching Subject]","label":"Fronted Appositive (Tanpa Verb!)"},{"role":"predicate","text":"[Independent Clause], / —","label":"Pernyataan Utama Utuh"},{"role":"noun","text":"a [Summary Noun] + that + V","label":"Summative Modifier Tajam"}],"steps":["Waspadai pola nomor satu di TOEFL Structure: ''___, the peregrine falcon can reach speeds over 200 mph.'' Karena sudah ada koma + Subjek + Verb, bagian depan cukup diisi Noun Phrase Appositive (''The fastest bird on Earth''), JANGAN ditambah ''It is''!","Saat mengedit esai TOEFL, ubah '', which is bad because it...'' menjadi Summative Modifier: ''—a vulnerability that exposes...''.","Untuk Resumptive Modifier, ulangi kata benda/sifat kunci sesudah koma atau *em-dash* (''The system relies on trust—trust that takes years to earn'')."],"breakdowns":[{"tokens":[{"jp":"Once a niche hobby,","reading":"/wʌns ə niːʃ ˈhɑːbi/","meaning":"dulunya hanyalah hobi segelintir orang (Fronted Appositive),","role":"noun"},{"jp":"esports","reading":"/ˈiːspɔːrts/","meaning":"olahraga elektronik (tunggal tak terhitung!)","role":"subject"},{"jp":"now fills","reading":"/naʊ fɪlz/","meaning":"kini memenuhi","role":"verb"},{"jp":"olympic-sized stadiums.","reading":"/əˈlɪmpɪk saɪzd ˈsteɪdiəmz/","meaning":"stadion seukuran Olimpiade.","role":"object"}],"translation":"Dulunya hanyalah hobi segelintir orang, esports kini memenuhi stadion seukuran Olimpiade."},{"tokens":[{"jp":"Central banks raised rates aggressively—","reading":"/ˈsɛntrəl bæŋks reɪzd reɪts əˈɡrɛsɪvli/","meaning":"bank sentral menaikkan suku bunga secara agresif—","role":"predicate"},{"jp":"a move","reading":"/ə muːv/","meaning":"sebuah langkah (Summative Noun)","role":"noun"},{"jp":"that curbed inflation","reading":"/ðæt kɜːrbd ɪnˈfleɪʃən/","meaning":"yang meredam inflasi","role":"connector"},{"jp":"but cooled hiring.","reading":"/bʌt kuːld ˈhaɪrɪŋ/","meaning":"namun mendinginkan perekrutan kerja.","role":"predicate"}],"translation":"Bank sentral menaikkan suku bunga secara agresif—sebuah langkah yang meredam inflasi namun memperlambat perekrutan."}],"forms":[{"label":"Fronted Appositive (Gaya TOEFL)","jp":"An archipelago of over 17,000 islands, Indonesia boasts immense biodiversity.","reading":"/ən ˌɑːrkɪˈpɛləɡoʊ əv ˈoʊvər ˌsɛvənˈtiːn ˈθaʊzənd ˈaɪləndz/","id":"Sebagai negara kepulauan dengan lebih dari 17.000 pulau, Indonesia memiliki keanekaragaman hayati luar biasa."},{"label":"Summative Modifier (, a X that)","jp":"Only 12% of plastic is recycled, a statistic that underscores the need for redesign.","reading":"/ə stəˈtɪstɪk ðæt ˌʌndərˈskɔːrz ðə niːd/","id":"Hanya 12% plastik yang didaur ulang, sebuah statistik yang mempertegas perlunya desain ulang."},{"label":"Resumptive Modifier (Pengulangan)","jp":"Engineers need uninterrupted focus—focus that open-plan offices rarely allow.","reading":"/ˈfoʊkəs ðæt ˈoʊpən plæn ˈɔːfɪsɪz ˈrɛrli əˈlaʊ/","id":"Para insinyur membutuhkan fokus tanpa gangguan—fokus yang jarang dimungkinkan oleh kantor ruang terbuka."}],"mistakes":[{"wrong":"It is the largest planet in our solar system, Jupiter has dozens of moons.","right":"The largest planet in our solar system, Jupiter has dozens of moons.","why":"Jebakan klasik nomor #1 TOEFL Structure! Menaruh ''It is'' sebelum koma menciptakan dua kalimat utuh tanpa kata hubung (Comma Splice)—cukup gunakan Appositive Noun Phrase murni!"},{"wrong":"A bestselling novelist, her latest book won the Pulitzer Prize.","right":"A bestselling novelist, she won the Pulitzer Prize for her latest book.","why":"Sama seperti Participial Phrase, Fronted Appositive wajib sejajar identitas dengan subjek tepat setelah koma (''her latest book'' bukan seorang novelis—''she'' lah novelisnya)!"}],"quiz":[{"question":"Soal khas pembuka TOEFL Structure: ''___, graphene conducts electricity far more efficiently than copper.''","options":["It is a single layer of carbon atoms","A single layer of carbon atoms","Because a single layer of carbon atoms","Being it is a single layer of carbon atoms"],"answer":1,"why":"Induk kalimat setelah koma sudah memiliki Subjek (''graphene'') + Verb (''conducts''); maka di depan koma dibutuhkan Fronted Appositive Noun Phrase ''A single layer of carbon atoms''."},{"question":"Pilih Summative Modifier yang paling tajam dan bebas dari kesalahan Comma Splice: ''Venture funding fell by 40% last year, ___.''","options":["it forced startups to prioritize profitability","a contraction that forced startups to prioritize profitability","that forced startups to prioritize profitability","was a contraction forcing startups"],"answer":1,"why":"''a contraction that forced...'' merangkum seluruh klausa penurunan 40% menjadi satu aposisi benda evaluatif yang gramatikal dan elegan (perhatikan ''that'' sendirian tidak boleh dipakai setelah koma!)."},{"question":"Manakah kalimat yang SALAH karena Appositive tidak cocok dengan subjeknya?","options":["A former aerospace engineer, Budi founded a robotics startup.","A former aerospace engineer, Budi''s startup builds autonomous drones.","Budi, a former aerospace engineer, founded a robotics startup.","Once a small garage project, Budi''s startup now employs 300 people."],"answer":1,"why":"Dalam pilihan B, ''A former aerospace engineer'' merujuk ke ''Budi''s startup'' (perusahaan bukanlah mantan insinyur!)."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000058', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-008', 'particle', 'Nuanced Discourse Framing: Pembingkaian Presisi (Insofar as / Notwithstanding)', 'Insofar as + [Clause] (''sejauh mana/karena'') • Notwithstanding + [Noun] / [Noun] + notwithstanding • Vis-à-vis + [Noun]', 'Membatasi ruang lingkup argumen secara bedah presisi menggunakan penghubung tingkat C2 dalam teks hukum, kebijakan, dan akademik.', 8, '2026-11-26T00:00:00+00:00', '[{"jp":"Automation threatens jobs only insofar as workers lack retraining opportunities.","reading":"/ˌɔːtəˈmeɪʃən ˈθrɛtənz dʒɑːbz ˈoʊnli ˌɪnsoʊˈfɑːr æz ˈwɜːrkərz læk riːˈtreɪnɪŋ/","id":"Otomatisasi mengancam lapangan kerja hanya sejauh para pekerja tidak memiliki akses pelatihan ulang."},{"jp":"Short-term volatility notwithstanding, long-term fundamentals remain robust.","reading":"/ˈʃɔːrttɜːrm ˌvɑːləˈtɪləti ˌnɑːtwɪðˈstændɪŋ ˈlɔːŋtɜːrm ˌfʌndəˈmɛntəlz rɪˈmeɪn roʊˈbʌst/","id":"Terlepas dari gejolak jangka pendek, fundamental jangka panjangnya tetap kokoh."}]'::jsonb, 'insofar as (/ˌɪnsoʊˈfɑːr æz/) • notwithstanding (/ˌnɑːtwɪðˈstændɪŋ/) • vis-à-vis (/ˌviːzəˈviː/)', '{"analogy":"Di level C2, argumen tidak lagi hitam-putih (''benar'' vs ''salah''), melainkan dibingkai batas berlakunya! ''Insofar as'' (atau ''inasmuch as'') bekerja seperti pisau bedah yang membatasi: ''Pernyataan A benar HANYA SEJAUH / DALAM BATAS B terjadi''. ''Notwithstanding'' adalah kakak super-formal dari ''despite'' yang punya keunikan langka: ia bisa berdiri DI DEPAN kata benda (''Notwithstanding the delay,'') ATAU DI BELAKANG kata bendanya (''The delay notwithstanding,'')! Sedangkan ''vis-à-vis'' membandingkan posisi satu hal berhadapan langsung dengan hal lain.","when_to_use":["Insofar as + Subject + Verb: membatasi sejauh mana suatu klaim atau teori berlaku dalam esai analitis","Notwithstanding: sebagai preposisi sebelum/sesudah Noun Phrase (''terlepas dari''), atau adverbia transisi ''Notwithstanding,'' (''Namun demikian,'')","Vis-à-vis + Noun (''dibandingkan dengan / dalam kaitannya dengan'') & Whereby + Clause (''yang dengannya / melalui mekanisme mana'')"],"formula_parts":[{"role":"connector","text":"insofar as + S + V","label":"Sejauh Mana / Dalam Hal"},{"role":"particle","text":"(Noun) notwithstanding (Noun)","label":"Preposisi/Postposisi ''Despite''"},{"role":"particle","text":"vis-à-vis + Noun | whereby + S+V","label":"Relasi Banding & Mekanisme"}],"steps":["Gunakan ''insofar as'' (ditulis satu kata di American English modern!) diikuti klausa S + V lengkap untuk mempertajam batas argumenmu.","Kenali fleksibilitas posisi ''notwithstanding'' di TOEFL Reading: ''Notwithstanding its flaws,'' = ''Its flaws notwithstanding,'' = ''Despite its flaws,'' (tanpa kata ''of''!).","Gunakan ''whereby'' setelah kata benda sistem/kesepakatan (''a treaty whereby...'', ''an algorithm whereby...'') sebagai pengganti ringkas untuk ''by which / through which''."],"breakdowns":[{"tokens":[{"jp":"They devised a scheme","reading":"/ðeɪ dɪˈvaɪzd ə skiːm/","meaning":"mereka merancang sebuah skema","role":"predicate"},{"jp":"whereby","reading":"/wɛrˈbaɪ/","meaning":"yang melaluinya (= by which)","role":"connector"},{"jp":"unused solar power","reading":"/ʌnˈjuːzd ˈsoʊlər ˈpaʊər/","meaning":"listrik surya tak terpakai","role":"subject"},{"jp":"is sold back to the grid.","reading":"/ɪz soʊld bæk tə ðə ɡrɪd/","meaning":"dijual kembali ke jaringan listrik utama.","role":"predicate"}],"translation":"Mereka merancang sebuah skema yang dengannya listrik surya berlebih dijual kembali ke jaringan utama."},{"tokens":[{"jp":"The dollar weakened","reading":"/ðə ˈdɑːlər ˈwiːkənd/","meaning":"nilai tukar dolar melemah","role":"predicate"},{"jp":"vis-à-vis","reading":"/ˌviːzəˈviː/","meaning":"dibandingkan berhadapan dengan","role":"particle"},{"jp":"other major currencies.","reading":"/ˈʌðər ˈmeɪdʒər ˈkɜːrənsiz/","meaning":"mata uang utama lainnya.","role":"noun"}],"translation":"Nilai tukar dolar melemah dibandingkan terhadap mata uang utama lainnya."}],"forms":[{"label":"Batas Ruang Lingkup (insofar as)","jp":"Metrics are useful insofar as they guide real action.","reading":"/ˈmɛtrɪks ɑːr ˈjuːsfəl ˌɪnsoʊˈfɑːr æz ðeɪ ɡaɪd riːəl ˈækʃən/","id":"Metrik bermanfaat hanya sejauh metrik tersebut memandu tindakan nyata."},{"label":"Postposisi Elegan (notwithstanding)","jp":"Privacy concerns notwithstanding, adoption grew rapidly.","reading":"/ˈpraɪvəsi kənˈsɜːrnz ˌnɑːtwɪðˈstændɪŋ əˈdɑːpʃən ɡruː ˈræpɪdli/","id":"Terlepas dari kekhawatiran privasi, tingkat adopsi tumbuh pesat."},{"label":"Sebab Formal (inasmuch as)","jp":"Inasmuch as both parties breached the terms, the contract is void.","reading":"/ˌɪnæzˈmʌtʃ æz boʊθ ˈpɑːrtiz briːtʃt ðə tɜːrmz/","id":"Mengingat kedua belah pihak melanggar ketentuan, kontrak tersebut batal."}],"mistakes":[{"wrong":"Notwithstanding of the objections, the bill passed.","right":"Notwithstanding the objections, the bill passed. / The objections notwithstanding,...","why":"Sama persis seperti ''despite'', kata ''notwithstanding'' TIDAK PERNAH diikuti preposisi ''of''!"},{"wrong":"a person whereby I spoke yesterday","right":"a system whereby users verify identity (orang memakai ''with whom'', bukan ''whereby''!).","why":"''Whereby'' hanya merujuk pada proses, metode, rencana, atau perjanjian (''by means of which''), bukan manusia atau tempat!"}],"quiz":[{"question":"Soal kosa kata & struktur TOEFL Reading: ''His critique is valid insofar as it highlights sampling bias, yet it overlooks the longitudinal data.'' Kata ''insofar as'' paling dekat maknanya dengan:","options":["regardless of whether","to the extent that","in contrast to","long before"],"answer":1,"why":"''Insofar as'' secara presisi berarti ''to the extent/degree that'' (''sejauh mana / dalam batas bahwa'')."},{"question":"Pilih kalimat yang menggunakan ''notwithstanding'' secara benar:","options":["Notwithstanding of the embargo, trade continued.","Logistical hurdles notwithstanding, the relief supplies arrived on schedule.","The relief supplies arrived, logistical hurdles despite.","Notwithstanding they lacked funds, they succeeded."],"answer":1,"why":"Berbeda dari ''despite'' yang hanya boleh di depan benda, ''notwithstanding'' sah diletakkan tepat sesudah Noun Phrase (''Logistical hurdles notwithstanding,'') tanpa ''of''!"},{"question":"Lengkapi definisi mekanisme hukum berikut: ''Arbitration is a legal mechanism ___ disputes are resolved outside of court.''","options":["whom","whereby","vis-à-vis","albeit"],"answer":1,"why":"''Whereby'' (= by which / through which) menghubungkan kata benda metode (''a legal mechanism'') dengan klausa lengkap cara kerjanya."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000059', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-009', 'particle', 'Three-Word Phrasal-Prepositional Verbs: Idiom Eksekutif (come down to / live up to)', '[Verb + Adverb Particle + Preposition] + [Noun / Gerund V-ing] (TIDAK BISA dipisah oleh objek!)', 'Menguasai idiom kerja tiga kata tak terpisahkan yang mendominasi rapat kepemimpinan AS dan TOEFL Listening.', 9, '2026-11-26T00:00:00+00:00', '[{"jp":"Ultimately, startup survival comes down to solving a painful user problem.","reading":"/ˈʌltɪmətli ˈstɑːrtʌp sərˈvaɪvəl kʌmz daʊn tə ˈsɑːlvɪŋ ə ˈpeɪnfəl ˈjuːzər ˈprɑːbləm/","id":"Pada akhirnya, kelangsungan hidup perusahaan rintisan berujung pada kemampuan memecahkan masalah nyata pengguna."},{"jp":"The new chip lived up to the hype, cutting power draw by 40%.","reading":"/ðə nuː tʃɪp lɪvd ʌp tə ðə haɪp ˈkʌtɪŋ ˈpaʊər drɔː baɪ ˈfɔːrti pərˈsɛnt/","id":"Cip baru itu berhasil memenuhi ekspektasi tinggi, memangkas konsumsi daya sebesar 40%."}]'::jsonb, 'boils down to (/bɔɪlz daʊn tuː/) + N/V-ing • do away with • live up to', '{"analogy":"Penutur C2 bukan hanya menguasai kata Latin yang panjang, tetapi juga terdengar 100% alami saat berbicara dengan para eksekutif Amerika menggunakan **Three-Word Phrasal-Prepositional Verbs**! Ada dua aturan tata bahasa mutlak di sini: (1) Berbeda dari phrasal verb dua kata (''turn it off''), phrasal verb tiga kata TIDAK PERNAH BISA DIPISAH oleh objeknya (''do away it with'' ❌ → ''do away with it'' ✅)! (2) Karena kata ketiganya selalu PREPOSISI (to, with, on, for), maka jika diikuti kata kerja, WAJIB berbentuk Gerund `V-ing` (''comes down to EXECUTING'', bukan ''to execute'')!","when_to_use":["Merangkum inti persoalan di rapat (''come down to / boil down to'' = pada intinya berpulang pada...)","Membahas inovasi dan standar (''do away with'' = menghapuskan sistem usang; ''live up to'' = memenuhi ekspektasi/reputasi; ''keep up with'' = mengimbangi laju)","Mengelola dinamika kerja (''put up with'' = menoleransi hal buruk; ''make up for'' = menebus kekurangan; ''zero in on'' = membidik fokus tajam; ''follow through on/with'' = menuntaskan janji hingga selesai)"],"formula_parts":[{"role":"verb","text":"come down / do away / live up","label":"Verba + Partikel"},{"role":"particle","text":"to / with / on / for","label":"Preposisi Pengunci (Tak Terpisah)"},{"role":"object","text":"Noun / Pronoun / V-ing","label":"Wajib di Belakang Preposisi!"}],"steps":["Jangan pernah menyelipkan kata ganti (''it/them'') di tengah-tengahnya: selalu taruh di paling belakang (''put up with it'', ''make up for it'', ''zero in on them'').","Waspadai jebakan kata ''to'' di ujung ''come down to / boil down to / live up to / look forward to / get around to'': itu semua PREPOSISI, jadi wajib diikuti Noun atau `V-ing` (''get around to reviewing'' = akhirnya sempat meninjau)!","Kenali padanan formal satu katanya untuk berpindah mulus antara lisan eksekutif dan tulisan jurnal: do away with ↔ abolish, put up with ↔ tolerate, make up for ↔ compensate for."],"breakdowns":[{"tokens":[{"jp":"The company decided to","reading":"/ðə ˈkʌmpəni dɪˈsaɪdɪd tə/","meaning":"perusahaan memutuskan untuk","role":"verb"},{"jp":"do away with","reading":"/duː əˈweɪ wɪð/","meaning":"menghapuskan (= abolish)","role":"verb"},{"jp":"annual performance rankings.","reading":"/ˈænjuəl pərˈfɔːrməns ˈræŋkɪŋz/","meaning":"pemeringkatan kinerja tahunan.","role":"object"}],"translation":"Perusahaan memutuskan untuk menghapuskan sistem pemeringkatan kinerja tahunan."},{"tokens":[{"jp":"Sorry—I haven''t","reading":"/ˈsɑːri aɪ ˈhævənt/","meaning":"maaf—saya belum","role":"verb"},{"jp":"gotten around to","reading":"/ˈɡɑːtən əˈraʊnd tuː/","meaning":"sempat menyentuh/mengerjakan (US: gotten)","role":"verb"},{"jp":"reading","reading":"/ˈriːdɪŋ/","meaning":"membaca (wajib V-ing sesudah preposisi ''to''!)","role":"object"},{"jp":"your draft yet.","reading":"/jʊr dræft jɛt/","meaning":"draf Anda.","role":"object"}],"translation":"Maaf—saya belum sempat membaca draf Anda."}],"forms":[{"label":"Inti Masalah (+ V-ing!)","jp":"Winning the grant boils down to framing a clear hypothesis.","reading":"/ˈwɪnɪŋ ðə ɡrænt bɔɪlz daʊn tə ˈfreɪmɪŋ ə klɪr haɪˈpɑːθəsɪs/","id":"Memenangkan hibah itu pada intinya bergantung pada penyusunan hipotesis yang jernih."},{"label":"Menebus Kekurangan (make up for)","jp":"Strong execution can make up for a late market entry.","reading":"/strɔːŋ ˌɛksɪˈkjuːʃən kən meɪk ʌp fɔːr ə leɪt ˈmɑːrkɪt ˈɛntri/","id":"Eksekusi yang kuat dapat menebus keterlambatan masuk pasar."},{"label":"Menuntaskan Komitmen (follow through)","jp":"Great leaders follow through on their promises.","reading":"/ɡreɪt ˈliːdərz ˈfɑːloʊ θruː ɑːn ðɛr ˈprɑːmɪsɪz/","id":"Pemimpin hebat menuntaskan janji-janji mereka hingga tuntas."}],"mistakes":[{"wrong":"Success comes down to execute consistently.","right":"Success comes down to executing consistently.","why":"Kata ''to'' pada ''come down to'' adalah preposisi, bukan penanda infinitif—wajib diikuti kata benda atau Gerund ''executing''!"},{"wrong":"Legacy passwords are risky, so we did away them with.","right":"Legacy passwords are risky, so we did away with them.","why":"Three-word phrasal verbs bersifat inseparable (tak terpisahkan); kata ganti ''them'' wajib diletakkan setelah ''with''!"}],"quiz":[{"question":"Dalam TOEFL Listening percakapan kampus, mahasiswa berkata: ''I finally got around to ___ my advisor about the thesis.'' Bentuk yang benar adalah:","options":["email","emailed","emailing","have emailed"],"answer":2,"why":"''Get around to'' (= akhirnya punya waktu untuk melakukan sesuatu yang tertunda) berakhiran preposisi ''to'', sehingga wajib diikuti Gerund ''emailing''."},{"question":"Apa arti dari kalimat CEO: ''We can no longer put up with flaky deployment scripts; let''s do away with them''?","options":["Kita harus mempertahankan dan memuji skrip lama tersebut","Kita tidak bisa lagi menoleransi skrip deployment yang sering gagal; mari kita hapuskan/ganti skrip tersebut","Kita harus menunda perbaikan skrip tersebut","Kita harus memasang skrip itu di layar atas"],"answer":1,"why":"''Put up with'' = menoleransi hal buruk, sedangkan ''do away with'' = menghapuskan/menyingkirkan sesuatu yang tidak lagi berguna."},{"question":"Pilih kalimat dengan posisi pronoun yang benar:","options":["High expectations were set, and the team lived them up to.","High expectations were set, and the team lived up them to.","High expectations were set, and the team lived up to them.","High expectations were set, and the team lived to them up."],"answer":2,"why":"Seluruh kesatuan ''live up to'' tidak boleh dipecah; objek ''them'' selalu berada tepat setelah preposisi ''to''."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e2000001-0000-4000-8000-000000000060', 'e1000001-0000-4000-8000-000000000006', 'GP-EN-C2-010', 'sentence_pattern', 'Rhetorical Antithesis & Cadence: Ritme Keynote (not by..., but by...)', 'Antithesis: not [Form A], but [Form B] / less about X than about Y • Tricolon: A, B, and C (Rising Syllable Cadence)', 'Merancang kalimat puncak pidato eksekutif dan penutup esai TOEFL 120 dengan kontras simetris (antithesis) dan irama tiga serangkai (tricolon).', 10, '2026-11-26T00:00:00+00:00', '[{"jp":"Leadership is measured not by the authority we claim, but by the trust we inspire.","reading":"/ˈliːdərʃɪp ɪz ˈmɛʒərd nɑːt baɪ ði əˈθɔːrəti wiː kleɪm bʌt baɪ ðə trʌst wiː ɪnˈspaɪər/","id":"Kepemimpinan diukur bukan dari wewenang yang kita klaim, melainkan dari kepercayaan yang kita bangkitkan."},{"jp":"The bottleneck is less a question of raw compute than one of data quality.","reading":"/ðə ˈbɑːtəlnɛk ɪz lɛs ə ˈkwɛstʃən əv rɔː kəmˈpjuːt ðæn wʌn əv ˈdeɪtə ˈkwɑːləti/","id":"Hambatannya bukan terutama soal daya komputasi mentah, melainkan soal kualitas data."}]'::jsonb, 'less a technical hurdle than a cultural one • clarity, speed, and resilience', '{"analogy":"Mengapa pidato Steve Jobs, Barack Obama, atau penutup esai skor 30/30 TOEFL Writing terasa begitu merinding dan mudah diingat? Rahasianya adalah arsitektur ritme **Antithesis** dan **Tricolon**! Antithesis menyandingkan dua kutub berlawanan dalam cermin tata bahasa yang 100% simetris (''not by X, but by Y'' atau versi analitis C2 ''less about X than about Y''). Sementara Tricolon (Rule of Three) merangkai tiga elemen paralel dengan elemen ketiga sedikit lebih panjang sebagai ketukan penutup simfoni (Hukum Behaghel: pendek → sedang → panjang memuncak)!","when_to_use":["Menulis kalimat penutup (clincher sentence) pada esai beasiswa LPDP/Fulbright, TOEFL Writing, atau presentasi keynote","Membingkai ulang akar masalah secara elegan dengan ''is less (about) X than (about) Y'' (''bukan semata soal X, melainkan lebih soal Y''—lebih dewasa daripada menyangkal X 100%!)","Menggabungkan Tricolon paralel + pengulangan preposisi demi kejelasan ritme (''for our users, for our partners, and for the communities we serve'')"],"formula_parts":[{"role":"connector","text":"not [Prep + Noun], but [Prep + Noun]","label":"Cermin Antithesis Simetris"},{"role":"connector","text":"less (a/about) X than (a/about) Y","label":"Nuansa Prioritas Analitis"},{"role":"ending","text":"Item 1, Item 2, and [Longer Item 3]","label":"Tricolon & End-Weight Cadence"}],"steps":["Dalam Antithesis (''not..., but...''), ulangi preposisi pada KEDUA sisi agar irama ketukannya tegas dan sejajar (''not IN how fast we code, but IN how deeply we listen'')!","Gunakan ''less X than Y'' ketika X bukannya salah 100%, tetapi Y jauh lebih menentukan (''Success here is less technical than organizational'').","Terapkan prinsip *End-Weight* pada Tricolon: susun tiga frasa paralel dari yang paling ringkas menuju yang paling berbobot di urutan ketiga (plus gunakan *Oxford comma* sebelum ''and'' sesuai standar publikasi AS!)."],"breakdowns":[{"tokens":[{"jp":"Scientific progress advances","reading":"/ˌsaɪənˈtɪfɪk ˈprɑːɡrɛs ədˈvænsɪz/","meaning":"kemajuan ilmiah bergerak maju","role":"predicate"},{"jp":"not through blind consensus,","reading":"/nɑːt θruː blaɪnd kənˈsɛnsəs/","meaning":"bukan melalui konsensus buta (Prep + Adj + Noun),","role":"connector"},{"jp":"but through rigorous falsification.","reading":"/bʌt θruː ˈrɪɡərəs ˌfɔːlsɪfɪˈkeɪʃən/","meaning":"melainkan melalui pengujian sanggahan yang ketat (simetris!).","role":"connector"}],"translation":"Kemajuan ilmiah bergerak maju bukan melalui konsensus buta, melainkan melalui pengujian sanggahan yang ketat."},{"tokens":[{"jp":"Great software demands","reading":"/ɡreɪt ˈsɔːftwɛr dɪˈmændz/","meaning":"perangkat lunak hebat menuntut","role":"verb"},{"jp":"clean code,","reading":"/kliːn koʊd/","meaning":"kode yang bersih (2 suku kata),","role":"object"},{"jp":"clear ownership,","reading":"/klɪr ˈoʊnərʃɪp/","meaning":"kepemilikan tanggung jawab yang jelas (4 suku kata),","role":"object"},{"jp":"and relentless empathy for the user.","reading":"/ænd rɪˈlɛntləs ˈɛmpəθi fɔːr ðə ˈjuːzər/","meaning":"serta empati tiada henti bagi pengguna (puncak irama Tricolon).","role":"ending"}],"translation":"Perangkat lunak hebat menuntut kode yang bersih, tanggung jawab yang jelas, serta empati tiada henti bagi penggunanya."}],"forms":[{"label":"Antithesis Simetris","jp":"We hire not for pedigree, but for curiosity and grit.","reading":"/wiː ˈhaɪər nɑːt fɔːr ˈpɛdɪɡriː bʌt fɔːr ˌkjʊriˈɑːsəti ænd ɡrɪt/","id":"Kami merekrut bukan berdasarkan nama besar almamater, melainkan berdasarkan rasa ingin tahu dan kegigihan."},{"label":"Analitis C2 (less...than)","jp":"Urban congestion is less an engineering failure than a pricing failure.","reading":"/ˈɜːrbən kənˈdʒɛstʃən ɪz lɛs ən ˌɛndʒɪˈnɪrɪŋ ˈfeɪljər ðæn/","id":"Kemacetan kota bukan semata kegagalan rekayasa teknik, melainkan lebih merupakan kegagalan kebijakan tarif."},{"label":"Chiasmus / Pembalikan Tajam","jp":"Failing to plan is planning to fail.","reading":"/ˈfeɪlɪŋ tə plæn ɪz ˈplænɪŋ tə feɪl/","id":"Gagal merencanakan sama saja dengan merencanakan kegagalan."}],"mistakes":[{"wrong":"The reform is less about cutting budgets as it is about accountability.","right":"The reform is less about cutting budgets than (about) improving accountability.","why":"Kata komparatif ''less'' selalu wajib berpasangan dengan ''than'' (bukan ''as''—yang memakai ''as'' adalah ''not so much X as Y''!)."},{"wrong":"Innovation requires creativity, being bold, and we must collaborate.","right":"Innovation requires creative thinking, bold experimentation, and cross-functional collaboration.","why":"Tricolon kehilangan seluruh daya pukul retorisnya dan menjadi salah grammar apabila ketiga unsurnya berbeda kelas kata!"}],"quiz":[{"question":"Perhatikan pasangan idiom retoris C2 berikut: ''not so much X ___ Y'' vs ''less X ___ Y''. Pasangan kata penghubung yang benar berturut-turut adalah:","options":["than / as","as / than","but / than","that / as"],"answer":1,"why":"Pola baku keduanya adalah ''not so much X AS Y'' (''bukan semata X melainkan Y'') dan ''less X THAN Y''!"},{"question":"Pilih kalimat Antithesis yang paling simetris dan tepat untuk penutup esai TOEFL Writing:","options":["Education succeeds not by memorizing facts, but when students think critically.","Education succeeds not by rote memorization of isolated facts, but by the cultivation of critical inquiry.","Education not succeeds by memorizing, rather than critical inquiry.","Education succeeds less by memorizing facts as by thinking."],"answer":1,"why":"Pilihan B menjaga simetri struktural ''not by [Noun Phrase], but by [Noun Phrase]'' dengan irama naik (End-Weight) yang sangat berwibawa."},{"question":"Dalam standar publikasi akademik Amerika (APA / Chicago / TOEFL), manakah tanda baca Tricolon (Oxford/Serial Comma) yang dianjurkan?","options":["speed, security, and scalability","speed, security and, scalability","speed security, and scalability","speed; security, and scalability"],"answer":0,"why":"American English standar menggunakan Oxford comma (koma sebelum ''and'' pada item terakhir dalam daftar tiga unsur atau lebih) demi mencegah ambiguitas."}]}'::jsonb) ON CONFLICT ("id") DO UPDATE SET "level_id" = EXCLUDED."level_id", "code" = EXCLUDED."code", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "formula" = EXCLUDED."formula", "explanation" = EXCLUDED."explanation", "order_index" = EXCLUDED."order_index", "examples" = EXCLUDED."examples", "formula_reading" = EXCLUDED."formula_reading", "learning_guide" = EXCLUDED."learning_guide";
